                        let dateArr = dateparts[0].split("-");
                        let timeArr = dateparts[1].split(":");

                        let hour = timeArr[0];
                        if (parseInt(hour) < 12) {
                            if (dateparts[2] === 'PM' || dateparts[2] === 'م') {
                                hour = parseInt(hour) + 12;
                            }
                        }
                        else {//equal to 12
                            if (dateparts[2] !== 'PM' && dateparts[2] !== 'م') { // AM or Subah
                                hour = 0;
                            }
                        }

                        return dateArr[2] + "-" + dateArr[1] + "-" + dateArr[0] + "T" + (parseInt(hour) < 10 ? ('0' + parseInt(hour)) : hour) + ":" + timeArr[1] + ':00+04:00';
