            getScriptNextPageAuh: function () {
                return helperFunc(function () {
                    debugger;
                    function gotoNextPage() {

                        var totalFines = $("span[id*='ctl00_ContentPlaceHolder1_lblNoTickets'")[0].innerText.split("-")[0].split("e ")[1];
                        var totalPages = totalFines > 50 ? totalFines / 50 : 1;
                        totalPages = Math.ceil(totalPages);

                        chrome.storage.local.get(['newFines', 'processedPages'], function (result) {

                            let fines = result.newFines;
                            let processedPages = result.processedPages;

                            //wait 2secs then call...
                            let moveToNext = function () {

                                setTimeout(function () {
                                    let res = $('#ctl00_ContentPlaceHolder1_UpdateProgress1').attr('style');

                                    if (res === "display:none;" || res === "display: none;") {
                                        chrome.runtime.sendMessage({
                                            type: 'injectContentScript'
                                        });
                                    }
                                    else {
                                        setTimeout(moveToNext(), 2000);
                                    }
                                }, 2000);

                            };

                            let processNextPage = function () {
                                chrome.storage.local.set({ 'newFines': [] }, function (resutl) {
                                    //Move to next page and then parse data...
                                    if (!document.getElementsByClassName("gridViewPager") || !document.getElementsByClassName("gridViewPager").length)
                                        processedPages = totalPages + 1;

                                    if (totalPages > 1 && processedPages <= totalPages) {
                                        //Send info to background so this script could call for each page.
                                        debugger;
                                        let pagerElement = document.getElementsByClassName("gridViewPager")[0].getElementsByTagName('a')[0];
                                        let outerHtml = "javascript: __doPostBack('ctl00$ContentPlaceHolder1$gvTickets', 'Page$" + processedPages + "')";
                                        pagerElement.setAttribute('href', outerHtml);
                                        pagerElement.click();

                                        moveToNext();

                                    }
                                    else {
                                        //Downloading completed as there are no pages
                                        chrome.runtime.sendMessage({
                                            type: "reportProgressPerPageBackground", isComplated: true, trafficFileId: trafficFileId,
                                            progress: 100, error: ''
                                        }, function () {
                                            chrome.runtime.sendMessage({ type: "closeMainWindow" });
                                        });
                                    }

                                });
                            }

                            if (fines.length < 1) {
                                processNextPage();
                            }
                            else {
                                chrome.runtime.sendMessage({
                                    contentScriptQuery: "postData",
                                    data: JSON.stringify(fines),
                                    url: appHost + '/api/services/app/uaeFine/SaveFinesInBulk'
                                }, function (response) {
                                    if (response.error) {
                                        console.log(response.error);
                                        chrome.runtime.sendMessage({ type: "reportProgressPerPageBackground", isComplated: true, trafficFileId: trafficFileId, progress: 100, error: response.error.message });
                                    }
                                    else if (response.success) {
                                        processNextPage();
                                    }
                                    else {
                                        console.log(response);
                                        alert('error occured see console.');
                                    }
                                });
                            }
                        });

                    }

                    gotoNextPage();

                });
            },
