                                                    amount: row.children[6].innerText.trim().split('Q')[0],
                                                    plateNo: PlatNo,
                                                    plateInfo: PlatNo,
                                                    fineDescription: row.children[3].innerText.trim(),
                                                    location: row.children[4].innerText.trim(),
                                                    trafficFileId: trafficFile,
                                                    tenantId: tenantId,
