                        function pageNavigator(pageNumber) {
                            let src = document.createElement('script');
                            src.innerText = 'navigate(' + pageNumber + ');';
                            src.id = 'navPage';
                            document.body.appendChild(src);
                            src.parentElement.removeChild(src);
                        }

