(function () {
    appModule.factory('equipmentChargesCalculator', [
        'utilities', 'abp.services.app.holiday',
        function (utilities, holidayService) {
            var isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
            var weekendDay1 = parseInt(abp.setting.get("App.General.WeekEndDay1")); // 0 to 6 (week day)
            var weekendDay2 = parseInt(abp.setting.get("App.General.WeekEndDay2")); // 0 to 6 (week day)
            var mixWeekendWithNormalRental = utilities.parseBoolean(abp.setting.get("App.General.MixWeekendWithNormalRental"));
            var weekEndKMsLimit = parseInt(abp.setting.get("App.General.WeekEndKMsLimit"));
            var individualCustomerRentalDefaultInvoicingRule = parseInt(abp.setting.get("App.General.InvoicingRuleIndividual"));
            var corporateCustomerRentalDefaultInvoicingRule = parseInt(abp.setting.get("App.General.InvoicingRuleCorporate"));
            var individualCustomerLeaseDefaultInvoicingRule = parseInt(abp.setting.get("App.General.LeaseInvoicingRuleIndividual"));
            var corporateCustomerLeaseDefaultInvoicingRule = parseInt(abp.setting.get("App.General.LeaseInvoicingRuleCorporate"));
            var isUserWiseDiscountEnabled = abp.features.isEnabled("CRS.UserWiseDiscount");
            var gracePeriod = parseInt(abp.setting.get("App.General.RentalGracePeriodInMinutes"));
            var isFuelChargesInvoiceEnabled = utilities.parseBoolean(abp.setting.get("App.General.InvoiceFuelChargesOnReplacement"));
            var isTaxOnSalikOrFineForTaxExemptedCustomers = utilities.parseBoolean(abp.setting.get("App.General.TaxOnSalikOrFineForTaxExemptedCustomers"));
            var taxPercentSetting = parseFloat(abp.setting.get("App.General.TaxPercentage"));
            var weeklyAgreementChargedMinimumOneWeek = utilities.parseBoolean(abp.setting.get("App.General.WeeklyAgreementChargedMinimumOneWeek"));
            var invoicingRule = null;
            var holidays = [];
            holidayService.getHolidays().success(function (result) {
                holidays = result.items;
                angular.forEach(holidays, function (holiday) {
                    holiday.date = (utilities.jsonUtcDateToLocalMoment(holiday.date)).startOf('day');
                });
            });

            var rateTypes = {
                perDay: 1,
                perWeek: 2,
                perMonth: 3,
                oneTime: 6,
                perHour: 7,
                perHalfDay: 8,
                perKm: 5
            };

            var chargesTypes = {
                rent: 1,
                fuelCharges: 4,
                mileageCharges: 5,
                tolls: 7,
                fines: 8,
                tollsSurcharge: 33,
                finesSurcharge: 34,
                extraHoursCharges: 68,
            };

            var operationTypes = {
                opening: 1,
                closing: 2
            };

            var invoicingRules =
            {
                DateToDate: 1,
                CalendarMonth: 2,
                ThirtyDays: 3,
            };

            //where date is moment object
            function isHoliday(date) {
                for (var i = 0; i < holidays.length; i++) {
                    if (date.isSame(holidays[i].date, 'day'))
                        return true;
                }

                return false;
            }

            var calculateChargesPeriodWise = function (agreementChargesWithDays) {
                var unit = 0;
                var charges = 0;
                var totalDays = 0;
                var fromDate = angular.copy(agreementChargesWithDays.dateOut);
                if (invoicingRule == invoicingRules.DateToDate) {

                    // Calculate Charges of All Complete Months
                    while (fromDate <= agreementChargesWithDays.dateIn && ((agreementChargesWithDays.days - totalDays) >= moment(fromDate).daysInMonth())) {
                        var daysInMonth = moment(fromDate).daysInMonth();
                        totalDays = totalDays + daysInMonth;
                        var agreementChargesDateToDate = agreementChargesWithDays.charges.rate / 1;
                        charges = charges + agreementChargesDateToDate;
                        fromDate = moment(fromDate).add(1, 'months');
                        unit++;
                    }

                    // Calculate Charges of  Remaining partial Months 
                    if (agreementChargesWithDays.days > totalDays) {
                        var daysToCalculate = agreementChargesWithDays.days - totalDays;
                        var daysInMonth = moment(fromDate).daysInMonth();
                        var agreementChargesPartial = (agreementChargesWithDays.charges.rate / 30) * daysToCalculate; //calculate prorata based on 30 days //(agreementChargesWithDays.charges.rate / daysInMonth) * daysToCalculate;
                        var unitCalculated = daysToCalculate / daysInMonth;
                        charges += agreementChargesPartial;
                        unit += unitCalculated;
                    }

                    agreementChargesWithDays.charges.units = utilities.round(unit, 2);
                    agreementChargesWithDays.charges.charges = utilities.round(charges, 2);

                } else if (invoicingRule == invoicingRules.CalendarMonth) {

                    var monthEnd = moment(fromDate).endOf('month');
                    var numberOfDaysInMonth = moment(fromDate).daysInMonth();
                    //var numberOfDaysDifference = monthEnd.diff(fromDate, 'days');
                    var duration = moment.duration(monthEnd.diff(fromDate));
                    var hours = duration.asHours();
                    var days = utilities.round(duration.asDays(), 2);
                    var numberOfDaysDifference = utilities.round(duration.asDays(), 2);

                    if (agreementChargesWithDays.days >= days) {
                        //Caluclte charges First Month Complete/Partial depending on end date
                        var agreementCharges = (numberOfDaysDifference == numberOfDaysInMonth ? agreementChargesWithDays.charges.rate / 1 : (agreementChargesWithDays.charges.rate / 30) * numberOfDaysDifference);  // calculate prorata based on 30 days// (agreementChargesWithDays.charges.rate / numberOfDaysInMonth) * numberOfDaysDifference;
                        charges = charges + agreementCharges;
                        var unitCalculated = numberOfDaysDifference / numberOfDaysInMonth;
                        unit += unitCalculated;
                        fromDate = monthEnd.add(1, 'seconds');
                        totalDays = totalDays + numberOfDaysDifference;

                        // Caluclte Charges For All next complete months
                        while (fromDate <= agreementChargesWithDays.dateIn && ((agreementChargesWithDays.days - totalDays) >= moment(fromDate).daysInMonth())) {
                            var daysInMonth = moment(fromDate).daysInMonth();
                            totalDays = totalDays + daysInMonth;
                            var agreementCharges = agreementChargesWithDays.charges.rate / 1;
                            charges = charges + agreementCharges;
                            fromDate = moment(fromDate).add(1, 'months');
                            unit++;
                        }

                    }

                    // calculate Charges For Last partial month
                    if (agreementChargesWithDays.days > totalDays) {
                        var days = agreementChargesWithDays.days - totalDays;
                        var daysInMonth = moment(fromDate).daysInMonth();
                        var agreementCharges = (agreementChargesWithDays.charges.rate / 30) * days; //calcualte prorate based on 30 days //(agreementChargesWithDays.charges.rate / daysInMonth) * days
                        var unitCalculated = (days / daysInMonth);
                        charges += agreementCharges;
                        unit += unitCalculated;
                    }

                    agreementChargesWithDays.charges.units = utilities.round(unit, 2);
                    agreementChargesWithDays.charges.charges = utilities.round(charges, 2);

                }
            };

            var calculateAllowedDaysPeriodWise = function (agreementChargesWithDays) {
                var unit = 0;
                var charges = 0;
                var totalDays = 0;
                var fromDate = angular.copy(agreementChargesWithDays.dateOut);
                if (invoicingRule == invoicingRules.DateToDate) {

                    // Calculate Charges of All Complete Months
                    while (fromDate <= agreementChargesWithDays.dateIn && ((agreementChargesWithDays.days - totalDays) >= moment(fromDate).daysInMonth())) {
                        var daysInMonth = moment(fromDate).daysInMonth();
                        totalDays = totalDays + daysInMonth;
                        //var agreementChargesDateToDate = agreementChargesWithDays.charges.rate / 1;
                        //charges = charges + agreementChargesDateToDate;
                        fromDate = moment(fromDate).add(1, 'months');
                        unit++;
                    }

                    // Calculate Charges of  Remaining partial Months 
                    if (agreementChargesWithDays.days > totalDays) {
                        var daysToCalculate = agreementChargesWithDays.days - totalDays;
                        var daysInMonth = moment(fromDate).daysInMonth();
                        //var agreementChargesPartial = (agreementChargesWithDays.charges.rate / 30) * daysToCalculate; //calculate prorata based on 30 days //(agreementChargesWithDays.charges.rate / daysInMonth) * daysToCalculate;
                        var unitCalculated = daysToCalculate / daysInMonth;
                        // charges += agreementChargesPartial;
                        unit += unitCalculated;
                    }

                    //agreementChargesWithDays.charges.units = utilities.round(unit, 2);
                    //agreementChargesWithDays.charges.charges = utilities.round(charges, 2);

                } else if (invoicingRule == invoicingRules.CalendarMonth) {

                    var monthEnd = moment(fromDate).endOf('month');
                    var numberOfDaysInMonth = moment(fromDate).daysInMonth();
                    //var numberOfDaysDifference = monthEnd.diff(fromDate, 'days');
                    var duration = moment.duration(monthEnd.diff(fromDate));
                    var hours = duration.asHours();
                    var days = utilities.round(duration.asDays(), 2);
                    var numberOfDaysDifference = utilities.round(duration.asDays(), 2);

                    if (agreementChargesWithDays.days >= days) {
                        //Caluclte charges First Month Complete/Partial depending on end date
                        //var agreementCharges = (numberOfDaysDifference == numberOfDaysInMonth ? agreementChargesWithDays.charges.rate / 1 : (agreementChargesWithDays.charges.rate / 30) * numberOfDaysDifference);  // calculate prorata based on 30 days// (agreementChargesWithDays.charges.rate / numberOfDaysInMonth) * numberOfDaysDifference;
                        //charges = charges + agreementCharges;
                        var unitCalculated = numberOfDaysDifference / numberOfDaysInMonth;
                        unit += unitCalculated;
                        fromDate = monthEnd.add(1, 'seconds');
                        totalDays = totalDays + numberOfDaysDifference;

                        // Caluclte Charges For All next complete months
                        while (fromDate <= agreementChargesWithDays.dateIn && ((agreementChargesWithDays.days - totalDays) >= moment(fromDate).daysInMonth())) {
                            var daysInMonth = moment(fromDate).daysInMonth();
                            totalDays = totalDays + daysInMonth;
                            // var agreementCharges = agreementChargesWithDays.charges.rate / 1;
                            // charges = charges + agreementCharges;
                            fromDate = moment(fromDate).add(1, 'months');
                            unit++;
                        }

                    }

                    // calculate Charges For Last partial month
                    if (agreementChargesWithDays.days > totalDays) {
                        var days = agreementChargesWithDays.days - totalDays;
                        var daysInMonth = moment(fromDate).daysInMonth();
                        //var agreementCharges = (agreementChargesWithDays.charges.rate / 30) * days; //calcualte prorate based on 30 days //(agreementChargesWithDays.charges.rate / daysInMonth) * days
                        var unitCalculated = (days / daysInMonth);
                        //charges += agreementCharges;
                        unit += unitCalculated;
                    }

                    return utilities.round(unit, 2);
                }
            };

            var calculate = function (agreement) {

                if (agreement == null) return 0;

                if (agreement.movements == null) return 0; //if agreement & no movements
                if (agreement.movements.length == 0) return 0;  //if agreement & no movements
                if (agreement.customer != null)
                {
                    if (agreement.customer.contactCategory == 2)
                         gracePeriod = parseInt(abp.setting.get("App.General.RentalGracePeriodInMinutesForCompany"));
                    else
                        gracePeriod = parseInt(abp.setting.get("App.General.RentalGracePeriodInMinutes"));
                }
                var dateOut = null;
                var dateIn = null;
                var dateInLease = null;
                //get operation type if charges or being claculated for opening or closing
                var operationType = operationTypes.opening;

                if (agreement.movements[agreement.movements.length - 1].inDetail != null)
                    if (agreement.movements[agreement.movements.length - 1].inDetail.dateTime != null && agreement.movements[agreement.movements.length - 1].inDetail.fuelLevel != null && agreement.movements[agreement.movements.length - 1].inDetail.km != null)
                        operationType = operationTypes.closing;

                if (operationType == operationTypes.opening) {  //if opening (agreement or new booking) then don't calculate if return date is not set
                    if (agreement.endDate == null) return 0;
                    dateOut = moment(agreement.movements[0].outDetail.dateTime);
                    dateIn = moment(agreement.endDate);

                } else {
                    dateOut = utilities.jsonUtcDateToLocalMoment(agreement.movements[0].outDetail.dateTime);
                    dateIn = moment(agreement.movements[agreement.movements.length - 1].inDetail.dateTime);
                    if (agreement.agreementCategory == 8) {
                        dateInLease = angular.copy(dateIn);
                        dateInLease.hours(dateOut.hour()).minutes(dateOut.minutes()).seconds(dateOut.seconds()).milliseconds(dateOut.milliseconds());
                    }

                }

                var duration;
                if (agreement.agreementCategory == 8 && operationType == operationTypes.closing)
                    duration = moment.duration(dateInLease.diff(dateOut));
                else
                    duration = moment.duration(dateIn.diff(dateOut));
                var hours = duration.asHours();
                var days = 0;
                var weekEndOrHolidayDays = 0;

                days = Math.floor(hours / 24);

                if ((hours - days * 24) * 60 > gracePeriod && agreement.agreementCategory != 8) // if extra minutes are greater than grace period then calculate 1 day extra
                    days += 1;

                if (days < 1) // charge minimum for 1 day if daily rental
                    days = 1;

                var d = moment(dateOut);
                for (var di = 1; di <= days; di++) { //loop days equal to applicable no of days
                    if (d.day() == weekendDay1 || d.day() == weekendDay2)
                        weekEndOrHolidayDays += 1;

                    d = d.add(1, 'day');
                }

                var allowedExtraDayOrMonth = days - weekEndOrHolidayDays;
                if (agreement.agreementCategory == 8)
                    allowedExtraDayOrMonth = calculateAllowedDaysPeriodWise({ days: days, dateOut: dateOut, dateIn: dateIn });

                var totalCharges = 0.0;
                var totalTax = 0.0;

                if (agreement.customer && agreement.customer.isTaxExempted) {
                    agreement.taxPercent = 0;
                    agreement.isTaxExempted = true;
                }

                if (agreement.customer) {
                    if (agreement.agreementCategory == 7 || agreement.agreementCategory == 8)
                        invoicingRule = agreement.customer.invoicingRule != null ? agreement.customer.invoicingRule : (agreement.customer.contactCategory == 1 ? individualCustomerRentalDefaultInvoicingRule : corporateCustomerRentalDefaultInvoicingRule);
                    else if (operationType == operationTypes.opening)
                        invoicingRule = invoicingRules.DateToDate;
                    else //lease
                        invoicingRule = agreement.customer.leaseInvoicingRule != null ? agreement.customer.leaseInvoicingRule : (agreement.customer.contactCategory == 1 ? individualCustomerLeaseDefaultInvoicingRule : corporateCustomerLeaseDefaultInvoicingRule);
                }

                for (var i = 0; i < agreement.charges.length; i++) {
                    //reset to 0
                    if (agreement.charges[i].chargesTypeId != chargesTypes.tollsSurcharge && agreement.charges[i].chargesTypeId != chargesTypes.finesSurcharge) {
                        agreement.charges[i].units = 0;
                        agreement.charges[i].charges = 0;
                    }

                    if (!agreement.charges[i].accepted) continue;

                    if (agreement.charges[i].chargesTypeId == chargesTypes.rent) {
                        if (agreement.charges[i].rateTypeId == rateTypes.perDay) {
                            if (!mixWeekendWithNormalRental || true) { // only for running purpose
                                agreement.charges[i].units = days;
                                agreement.charges[i].charges = utilities.round(days * agreement.charges[i].rate, 2);
                            } else {
                                var normalRate = agreement.charges[i].limit;
                                var weekEndRate = agreement.charges[i].excessRate;

                                agreement.charges[i].units = days;

                                if (weekEndRate > 0) { //week end rate is available. then separate caculation for normal and weekend/holiday days
                                    agreement.charges[i].charges = utilities.round((days - weekEndOrHolidayDays) * normalRate + weekEndOrHolidayDays * weekEndRate, 2);
                                    agreement.charges[i].notes = ' ' + (days - weekEndOrHolidayDays) + ' x ' + normalRate + ' + ' + weekEndOrHolidayDays + ' x ' + weekEndRate;
                                } else {
                                    agreement.charges[i].charges = utilities.round(days * normalRate, 2);
                                }

                                if (days == weekEndOrHolidayDays && weekEndRate > 0)
                                    agreement.charges[i].rate = weekEndRate;
                                else
                                    agreement.charges[i].rate = normalRate;
                            }

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perWeek) {
                            agreement.charges[i].units = utilities.round(days / 7, 2);
                            agreement.charges[i].charges = utilities.round((agreement.charges[i].rate / 7) * days, 2);
                            if (weeklyAgreementChargedMinimumOneWeek
                                && agreement.charges[i].charges < agreement.charges[i].rate) {
                                agreement.charges[i].charges = agreement.charges[i].rate;
                                agreement.charges[i].units = 1;
                            }

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perMonth) {
                            if (invoicingRule != null && (invoicingRule == 1 || invoicingRule == 2)) {
                                calculateChargesPeriodWise({ charges: agreement.charges[i], days: days, dateOut: dateOut, dateIn: dateIn });
                                if (agreement.charges[i].charges < agreement.charges[i].rate && agreement.agreementCategory == 7) {
                                    agreement.charges[i].charges = agreement.charges[i].rate;
                                    agreement.charges[i].units = 1;
                                }
                            }
                            else {
                                agreement.charges[i].units = utilities.round(days / 30, 2);
                                agreement.charges[i].charges = utilities.round((agreement.charges[i].rate / 30) * days, 2);
                                if (agreement.charges[i].charges < agreement.charges[i].rate && agreement.agreementCategory == 7) {
                                    agreement.charges[i].charges = agreement.charges[i].rate;
                                    agreement.charges[i].units = 1;
                                }
                            }

                            ////not complete yet
                            //if (agreement.charges[i].units < 1) { //if period is less than one than charge min one month
                            //    agreement.charges[i].units = 1;
                            //    agreement.charges[i].charges = agreement.charges[i].rate;
                            //}

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perHalfDay) {
                            days = 0.5;
                            agreement.charges[i].units = 1;
                            agreement.charges[i].charges = agreement.charges[i].rate;

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perHour) {
                            hours = utilities.round(hours);
                            days = hours / 24;
                            agreement.charges[i].units = hours;
                            agreement.charges[i].charges = utilities.round(hours * agreement.charges[i].rate, 2);

                        } else if (agreement.charges[i].rateTypeId == rateTypes.oneTime) {
                            agreement.charges[i].charges = utilities.round(agreement.charges[i].rate, 2);

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perKm) {

                            var kmDiff = 0.0;
                            for (var r = 0; r < agreement.movements.length; r++) {
                                kmDiff += (utilities.round(agreement.movements[r].inDetail.km) - utilities.round(agreement.movements[r].outDetail.km));
                            }

                            //agreement.charges[i].units = kmDiff;
                            agreement.charges[i].charges = utilities.round(kmDiff * agreement.charges[i].rate, 2);

                        }

                        //if user wise discount (settings) is enabled then user can apply discount percentage for rent (only) and discount field at bottom is locked and calculated through this %age

                        if (isUserWiseDiscountEnabled) {
                            if (agreement.charges[i].discountPercent > 0)
                                agreement.discount = utilities.round(agreement.charges[i].charges * agreement.charges[i].discountPercent / 100, 2);
                            else
                                agreement.discount = 0;
                        }

                    } else {

                        if (agreement.charges[i].rateTypeId == rateTypes.perDay) {
                            agreement.charges[i].units = days;
                            agreement.charges[i].charges = utilities.round(days * agreement.charges[i].rate, 2);

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perWeek) {
                            agreement.charges[i].units = utilities.round(days / 7, 2);
                            agreement.charges[i].charges = utilities.round((agreement.charges[i].rate / 7) * days, 2);

                        } else if (agreement.charges[i].rateTypeId == rateTypes.perMonth) {
                            if (invoicingRule != null && (invoicingRule == 1 || invoicingRule == 2)) {
                                calculateChargesPeriodWise({ charges: agreement.charges[i], days: days, dateOut: dateOut, dateIn: dateIn });
                                if (agreement.charges[i].charges < agreement.charges[i].rate && agreement.agreementCategory == 7) {
                                    agreement.charges[i].charges = agreement.charges[i].rate;
                                    agreement.charges[i].units = 1;
                                }
                            }
                            else {
                                agreement.charges[i].units = utilities.round(days / 30, 2);
                                agreement.charges[i].charges = utilities.round((agreement.charges[i].rate / 30) * days, 2);
                                if (agreement.charges[i].charges < agreement.charges[i].rate && agreement.agreementCategory == 7) {
                                    agreement.charges[i].charges = agreement.charges[i].rate;
                                    agreement.charges[i].units = 1;
                                }
                            }
                            //agreement.charges[i].units = utilities.round(days / 30, 2);
                            //agreement.charges[i].charges = utilities.round((agreement.charges[i].rate / 30) * days, 2);
                        }

                        //Fuel charges for closing only
                        else if (operationType == operationTypes.closing && agreement.charges[i].chargesTypeId == chargesTypes.fuelCharges && agreement.charges[i].rate > 0) {
                            var comsumedLiters = 0;
                            if (!isFuelChargesInvoiceEnabled) { //calculate for all vehicles
                                for (var j = 0; j < agreement.movements.length; j++) {
                                    var levelDiff = agreement.movements[j].outDetail.fuelLevel - agreement.movements[j].inDetail.fuelLevel;
                                    if (levelDiff > 0) {
                                        var diffInLiters = levelDiff * agreement.movements[j].vehicle.fuelTankCapacity;
                                        comsumedLiters += diffInLiters;
                                    }
                                }
                            }
                            else { //calcualte for last vehicle based on first vehicle out level and last vehicle in level 
                                var levelDiff = agreement.movements[0].outDetail.fuelLevel - agreement.movements[agreement.movements.length - 1].inDetail.fuelLevel;
                                if (levelDiff > 0) {
                                    var diffInLiters = levelDiff * agreement.movements[agreement.movements.length - 1].vehicle.fuelTankCapacity;
                                    comsumedLiters += diffInLiters;
                                    agreement.charges[i].notes = app.localize('FuelLevelOut') + ": " + getFuelLevel(agreement.movements[0].outDetail.fuelLevel) + ", " + app.localize('FuelLevelIn') + ": " + getFuelLevel(agreement.movements[agreement.movements.length - 1].inDetail.fuelLevel) + ", " + "Liters Used: " + diffInLiters + ", " + "Rate: " + agreement.charges[i].rate + app.localize('/Liter');
                                }
                            }

                            if (comsumedLiters > 0) {
                                agreement.charges[i].units = comsumedLiters;
                                agreement.charges[i].charges = utilities.round(comsumedLiters * agreement.charges[i].rate, 2);
                            } else {
                                agreement.charges[i].units = 0;
                                agreement.charges[i].charges = 0;

                            }
                        }

                        //else if fixed and no other charges type mentioned in above and field is enabled for opening also then put rate as charges
                        else if (!agreement.charges[i].applyOnClosing && agreement.charges[i].rateTypeId == rateTypes.oneTime) {
                            agreement.charges[i].charges = agreement.charges[i].rate;
                        }
                        //Access mileage charges (additional to periodic charges)
                        if (operationType == operationTypes.closing
                            && agreement.charges[i].chargesTypeId == chargesTypes.extraHoursCharges
                            && agreement.totalHoursOnTimeSheet > 0) {
                            agreement.charges[i].notes = '';

                            var perDayOrPerMonthLimit = 0;
                            //var additionalMileage = 0.0;

                            //if (agreement.charges[i].rateTypeId == rateTypes.perWeek)
                            //    perDayLimit = agreement.charges[i].limit / 7;
                            //else if (agreement.charges[i].rateTypeId == rateTypes.perMonth)
                            //    perDayLimit = agreement.charges[i].limit / 30;
                            //else
                            //    perDayLimit = agreement.charges[i].limit;

                            perDayOrPerMonthLimit = agreement.charges[i].limit;

                            var allowedExtraHours = allowedExtraDayOrMonth * perDayOrPerMonthLimit;
                            //if (!mixWeekendWithNormalRental || weekEndKMsLimit <= 0) {
                            //    allowedExtraHours = perDayLimit * days;
                            //}
                            //else {
                            //    allowedExtraHours = perDayLimit * (days - weekEndOrHolidayDays) + weekEndKMsLimit * weekEndOrHolidayDays;
                            //}

                            var remainingExtraHours = agreement.totalHoursOnTimeSheet - allowedExtraHours;
                            agreement.charges[i].units = 0;

                            if (remainingExtraHours > 0) {

                                agreement.charges[i].units = remainingExtraHours;

                                agreement.charges[i].notes = app.localize('Hours') + ": " + utilities.round(agreement.totalHoursOnTimeSheet, 2) + "<br/>";
                                agreement.charges[i].notes += app.localize('Allowed') + ": " + utilities.round(allowedExtraHours, 2) + "<br/>";

                                agreement.charges[i].notes += app.localize('Extra') + ": " + utilities.round(remainingExtraHours, 2) + "<br/>";
                                agreement.charges[i].notes += app.localize('Charges') + " (" + utilities.round(remainingExtraHours, 2) + " x " + agreement.charges[i].rate + "): " + (utilities.round((parseFloat(remainingExtraHours) * parseFloat(agreement.charges[i].rate)), 2));

                                var extraHoursCharges = remainingExtraHours * agreement.charges[i].rate;
                                agreement.charges[i].charges = utilities.round((agreement.charges[i].charges + extraHoursCharges), 2); // add excess charges with normal mileage charges
                            }
                            agreement.charges[i].extraHours = remainingExtraHours > 0 ? utilities.round(remainingExtraHours, 2) : 0;
                        }
                    }

                    if (agreement.charges[i].charges > 0) {
                        var charges = parseFloat(agreement.charges[i].charges);

                        //if rent and discount is applied then minus discount from rental charges before calculating tax
                        if (agreement.charges[i].chargesTypeId == chargesTypes.rent && agreement.discount > 0) {
                            charges -= agreement.discount;
                        }

                        totalCharges += charges;
                        var taxPercent = agreement.taxPercent;
                        var applyTaxOnTaxExempted = agreement.isTaxExempted && isTaxOnSalikOrFineForTaxExemptedCustomers && (agreement.charges[i].chargesTypeId == chargesTypes.tollsSurcharge || agreement.charges[i].chargesTypeId == chargesTypes.finesSurcharge);
                        //calcualte tax if enabled & charges type is taxable
                        if (agreement.charges[i].taxable && (agreement.taxPercent > 0 || applyTaxOnTaxExempted)) {
                            var tax = 0.0;
                            if (applyTaxOnTaxExempted) //take tax percentage from global settings
                                taxPercent = taxPercentSetting;

                            if (isTaxInclusive) {   // prices are with tax. extract include tax amount which will not be added in 
                                //equation solved from following formula... 
                                //chargesWithoutTax + chargesWithoutTax * (taxPercent/100) = chargesWithTax
                                var chargesWithoutTax = (charges * 100) / (100 + taxPercent);
                                tax = utilities.round(charges - chargesWithoutTax, 2);

                            } else {    //prices are without tax. calculate tax and include in total
                                tax = utilities.round(charges * taxPercent / 100, 2);
                                totalCharges += tax;
                            }

                            agreement.charges[i].tax = tax;
                            totalTax += tax;
                        }
                    }
                }

                totalCharges = utilities.round(totalCharges, 2);
                agreement.tax = utilities.round(totalTax, 2);
                agreement.totalCharges = totalCharges;

                return totalCharges;
            };

            var sumCharges = function (agreement) {
                if (agreement == null) return 0;
                if (agreement.charges == null) return 0;
                if (agreement.charges.length == 0) return 0;



                var totalCharges = 0.0;
                var totalTax = 0.0;

                for (var i = 0; i < agreement.charges.length; i++) {
                    if (agreement.charges[i].charges > 0) {
                        var tax = 0;
                        var taxPercent = agreement.taxPercent;
                        var charges = parseFloat(agreement.charges[i].charges);

                        //if rent and discount is applied then minus discount from rental charges before calculating tax
                        if (agreement.charges[i].chargesTypeId == chargesTypes.rent && agreement.discount > 0) {
                            charges -= agreement.discount;
                        }

                        totalCharges += charges;

                        var applyTaxOnTaxExempted = agreement.isTaxExempted && isTaxOnSalikOrFineForTaxExemptedCustomers && (agreement.charges[i].chargesTypeId == chargesTypes.tollsSurcharge || agreement.charges[i].chargesTypeId == chargesTypes.finesSurcharge);
                        //calcualte tax if enabled & charges type is taxable
                        if (agreement.charges[i].taxable && (agreement.taxPercent > 0 || applyTaxOnTaxExempted)) {

                            if (applyTaxOnTaxExempted) //take tax percentage from global settings
                                taxPercent = taxPercentSetting;

                            if (isTaxInclusive) {   // prices are with tax. extract include tax amount which will not be added in 
                                //equation solved from following formula... 
                                //chargesWithoutTax + chargesWithoutTax * (taxPercent/100) = chargesWithTax
                                var chargesWithoutTax = (charges * 100) / (100 + taxPercent);
                                tax = utilities.round(charges - chargesWithoutTax, 2);

                            } else {    //prices are without tax. calculate tax and include in total
                                tax = utilities.round(charges * taxPercent / 100, 2);
                                totalCharges += tax;
                            }

                            agreement.charges[i].tax = tax;
                            totalTax += tax;
                        }
                    }
                }
                totalCharges = utilities.round(totalCharges, 2);
                agreement.tax = utilities.round(totalTax, 2);
                agreement.totalCharges = totalCharges;

                return totalCharges;
            };

            getFuelLevel = function (value) {
                if (value == null)
                    return "";

                if (value == 0) {
                    return "0/8";
                }
                else if (value > 0 && value <= 0.125) {
                    return "1/8";
                }
                else if (value > 0.125 && value <= 0.25) {
                    return "2/8";
                }
                else if (value > 0.25 && value <= 0.375) {
                    return "3/8";
                }
                else if (value > 0.375 && value <= 0.5) {
                    return "4/8";
                }
                else if (value > 0.5 && value <= 0.625) {
                    return "5/8";
                }
                else if (value > 0.625 && value <= 0.75) {
                    return "6/8";
                }
                else if (value > 0.75 && value <= 0.875) {
                    return "7/8";
                }
                else if (value > 0.875 && value <= 1) {
                    return "8/8";
                }
                else {
                    return "";
                }
            };
            return {
                calculate: calculate,
                sumCharges: sumCharges
            };
        }
    ]);
})();;
(function () {
    appModule.factory('fineDownloader', [
        '$uibModal', '$filter', 'appSession', 'abp.services.app.trafficFile', '$http',
        function ($uibModal, $filter, appSession, trafficFileService, $http) {

            var tarfficFiles = [];
            var tenantId = appSession.tenant.id;

            var firebaseConfig = null;
            var connectionName = "FinesDownloadApp";
            var finesFirebase = null;


            var baseUrl = "https://speedcloudfinesextensionfunctionapp.azurewebsites.net/api";

            //if (location.hostname == "localhost")
            //    baseUrl = 'http://localhost:7073/api'; //For Debugging only


            //////////////////////////////////////////////////////////
            ///// Download fines and report progress using Firebase //
            //////////////////////////////////////////////////////////

            var enqueuedTrafficFilesCount = 0;
            var downloadedTrafficFiles = 0;
            var skipTrafficFiles = 0;
            var enqueuedTrafficFilesDetail = [];

            var downloadAllFines = function (callbackFunc, errorCallbackFunc, req) {
                enqueuedTrafficFilesCount = 0;
                downloadedTrafficFiles = 0;
                enqueuedTrafficFilesDetail = [];
                skipTrafficFiles = 0;

                var onlyDubaiFilesDownloading = false;
                var reqHasTrafficFileIds = false;

                if (req) {

                    try {
                        onlyDubaiFilesDownloading = req.onlyDubaiFilesDownloading;
                    } catch (e) {
                        onlyDubaiFilesDownloading = false;
                    }

                    try {
                        reqHasTrafficFileIds = req.trafficFileIds.length > 0;
                    } catch (e) {
                        reqHasTrafficFileIds = false;
                    }
                }

                //if (location.hostname == "localhost") {
                //    if (!confirm("Want to Download?"))
                //        return true;
                //}

                //code is for FMS (Fines Management System)
                if (reqHasTrafficFileIds) {
                    tarfficFiles = req.trafficFileIds;
                    totalTrafficFilesCount = req.trafficFileIds.length;

                    angular.forEach(tarfficFiles, function (trafficFile) {

                        if (trafficFile.state === 'Dubai') {
                            downloadAndReportFinesProgress(trafficFile, null, callbackFunc, errorCallbackFunc);
                        } else if (!onlyDubaiFilesDownloading && (trafficFile.state === 'Qatar')) { //trafficFile.state === 'Abu Dhabi' || 
                            captchaHandlingAndEnqueueForDownloading(trafficFile, callbackFunc, errorCallbackFunc);
                        }
                        else {
                            skipTrafficFiles += 1; //skip files with unknown state.          

                            //Case when there is no dubai traffic files and contract closing call is given then no downloading will be initiated..
                            if (skipTrafficFiles === totalTrafficFilesCount) {
                                var isDownloading = false;
                                callbackFunc && callbackFunc(null, isDownloading);
                            }
                        }

                    });
                }
                else {
                    trafficFileService.getTrafficFiles()
                        .success(function (result) {
                            tarfficFiles = result.items;
                            totalTrafficFilesCount = tarfficFiles.length;

                            //if there are no traffic files found then stop downloading...
                            if (totalTrafficFilesCount === 0) {
                                var isDownloading = false;
                                callbackFunc && callbackFunc(null, isDownloading);
                                return;
                            }

                            angular.forEach(tarfficFiles, function (trafficFile) {

                                if (trafficFile.state === 'Dubai') { //dubai downloading is disabled for agreement closing as onlyDubaiFilesDownloading is for agreement
                                    downloadAndReportFinesProgress(trafficFile, null, callbackFunc, errorCallbackFunc);
                                } else if (!onlyDubaiFilesDownloading && trafficFile.state === 'Qatar') { //(trafficFile.state === 'Abu Dhabi' || 
                                    captchaHandlingAndEnqueueForDownloading(trafficFile, callbackFunc, errorCallbackFunc);
                                }
                                else {
                                    skipTrafficFiles += 1;// as downloading for Abu Dhabi is skipped due to slow downloading. i.e. contract closing case

                                    //Case when there is only dubai traffic files and contract closing call is given then no downloading will be initiated..
                                    if (skipTrafficFiles === totalTrafficFilesCount) {
                                        var isDownloading = false;
                                        callbackFunc && callbackFunc(null, isDownloading);
                                    }
                                }

                            });
                        })
                        .error(function (reason) {
                            console.log(reason);
                            alert(reason);
                        });
                }
            };

            function captchaHandlingAndEnqueueForDownloading(trafficFile, callbackFunc, errorCallbackFunc) {
                var azureGetCaptchaUrl = baseUrl + "/GetCaptcha";

                abp.ajax({
                    url: azureGetCaptchaUrl,
                    type: 'POST',
                    data: JSON.stringify({ 'state': trafficFile.state })
                })
                    .done(function (response) {
                        var captcha = response;

                        var modalInstance = $uibModal.open({
                            templateUrl: '~/App/tenant/views/crs/fines/inputCaptchaModal.cshtml',
                            controller: 'tenant.views.crs.fines.inputCaptchaModal as vm',
                            backdrop: 'static',
                            size: 'sm',
                            resolve: {
                                trafficFile: function () {
                                    return trafficFile;
                                },
                                captcha: function () {
                                    return captcha;
                                }
                            }
                        });

                        modalInstance.result.then(function (result) {

                            if (result.captcha.captchaCode) {
                                downloadAndReportFinesProgress(result.trafficFile, result.captcha, callbackFunc, errorCallbackFunc);
                            }
                            else {
                                //captcha canceled by user....
                                enqueuedTrafficFilesDetail.push(
                                    {
                                        trafficFile: trafficFile,
                                        progress: 100,
                                        downloadCount: 0,
                                        error: 'User not provided Captcha.',
                                        isComplete: true,
                                        path: ''
                                    });

                                downloadedTrafficFiles += 1;
                                initiateFirebaseAndTriggerCallback(callbackFunc, errorCallbackFunc, enqueuedTrafficFilesDetail);
                            }
                        });
                    }
                    ).fail(function (reason) {
                        console.log(reason);
                        alert(reason);
                    });
            }

            var downloadAndReportFinesProgress = function (trafficFile, captcha, callbackFunc, errorCallbackFunc) {

                var req = {
                    "TenantId": tenantId,
                    "State": trafficFile.state,
                    "FileIds": [trafficFile.fileId]
                };

                if (captcha !== null) {
                    //Abu Dhabi Traffic File
                    req = angular.extend({}, req, captcha);     //Merging two objects
                }

                var azureProcessAndDownloadFinesUrl = baseUrl + "/EnqueueDownloadFines";

                abp.ajax({
                    url: azureProcessAndDownloadFinesUrl,
                    type: 'POST',
                    timeout: 0,
                    data: JSON.stringify(req)
                }).done(function success(initialResponse) {

                    //var initialResponse = data.speedAzureResponse;
                    if (!firebaseConfig)
                        firebaseConfig = initialResponse.SpeedFirebaseConfig;

                    var error = '';
                    var isComplete = false;
                    var progress = 0;

                    if (initialResponse.TrafficFileErrors) {
                        error = initialResponse.TrafficFileErrors[0].ErrorMessage;
                        isComplete = true;
                        progress = 100;
                    }

                    enqueuedTrafficFilesDetail.push(
                        {
                            trafficFile: trafficFile,
                            progress: progress,
                            downloadCount: 0,
                            error: error,
                            isComplete: isComplete,
                            path: initialResponse.FirebaseChildPath
                        });

                    initiateFirebaseAndTriggerCallback(callbackFunc, errorCallbackFunc, enqueuedTrafficFilesDetail);

                });
            };

            //////////////////////////////////////////////////////////
            function initiateFirebaseAndTriggerCallback(callbackFunc, errorCallbackFunc, enqueuedTrafficFilesDetail) {

                enqueuedTrafficFilesCount += 1;
                if ((totalTrafficFilesCount - skipTrafficFiles) === enqueuedTrafficFilesCount) {

                    enqueuedTrafficFilesCount = 0;
                    totalTrafficFilesCount = 0;

                    finesFirebase = null;
                    var firebaseIsAlreadyInitialized = false;

                    try {

                        finesFirebase = firebase.app(connectionName);
                        if (finesFirebase)
                            firebaseIsAlreadyInitialized = true;

                    } catch (e) {
                        firebaseIsAlreadyInitialized = false;
                    }

                    if (!firebaseIsAlreadyInitialized) {

                        finesFirebase = firebase.initializeApp({
                            apiKey: firebaseConfig.ApiKey,
                            authDomain: firebaseConfig.AuthDomain,
                            databaseURL: firebaseConfig.DatabaseUrl,
                            projectId: firebaseConfig.ProjectId,
                            storageBucket: firebaseConfig.StorageBucket
                        }, connectionName);

                    }

                    var isFirebaseLoggedIn = false;
                    try {
                        if (firebase.app(connectionName).auth().currentUser) {

                            isFirebaseLoggedIn = true;
                        }
                    } catch (e) {
                        isFirebaseLoggedIn = false;
                    }


                    var registerFirebaseListener = function () {
                        callbackFunc && callbackFunc(enqueuedTrafficFilesDetail, true);

                        angular.forEach(enqueuedTrafficFilesDetail, function (trafficFileResponse) {

                            if (!trafficFileResponse.error) { // if user does not provide captch then a error response will be added so register only valild Traffic File responnse.
                                var firebaseProgressReporter = finesFirebase.database().ref().child(trafficFileResponse.path);

                                //Watch the value changing in status object in firbase for downloading...
                                firebaseProgressReporter.on('value', function (sanpshot) {
                                    if (!sanpshot) return;

                                    var obj = sanpshot.val();

                                    if (obj) {

                                        //Report any change in downloading status...
                                        trafficFileResponse.downloadedCount = obj.DownloadedCount;
                                        trafficFileResponse.progress = obj.ProgressPercentage;
                                        trafficFileResponse.isComplete = obj.IsComplete;
                                        trafficFileResponse.error = obj.Error;

                                        var isDownloading = true;
                                        if (trafficFileResponse.isComplete) {
                                            downloadedTrafficFiles += 1;
                                            if (enqueuedTrafficFilesDetail.length <= downloadedTrafficFiles) {
                                                isDownloading = false;
                                            }
                                        }

                                        callbackFunc && callbackFunc(enqueuedTrafficFilesDetail, isDownloading);
                                    }

                                });
                            }
                        });
                    };


                    try {

                        if (!isFirebaseLoggedIn) {
                            //Authentication user...
                            finesFirebase.auth().signInWithCustomToken(firebaseConfig.Token).then(function () {

                                registerFirebaseListener();
                            }, function errorFunc(error) {
                                errorCallbackFunc && errorCallbackFunc(error);
                            });
                        }
                        else {

                            registerFirebaseListener();
                        }
                    } catch (e) {
                        errorCallbackFunc && errorCallbackFunc(e);
                    }
                }
            }


            //------------------------------------------------------
            //-------------------------Exposing Funcs ------------------
            //------------------------------------------------------

            return {
                downloadAllFines: downloadAllFines
            };
        }
    ]);
})();


;
