            function getApplicableTariffLines(chargesTypeId, rateTypeId, weekEnd, duration) {
                if (tariffLines == null) return null;

                var applicableLines = [];

                for (var i = 0; i < tariffLines.length; i++) {
                    if (tariffLines[i].chargesTypeId == chargesTypeId && tariffLines[i].rateTypeId == rateTypeId && tariffLines[i].weekEnd == weekEnd) {
                        if (duration >= tariffLines[i].from && (duration <= tariffLines[i].to || tariffLines[i].to == 0)) {
                            applicableLines.push(tariffLines[i]);
                        }
                    }
                }

                return applicableLines;
            }

