                if (age == 0 && drivingExperience == 0) return false;

                var isYoungOrNew = false;

                //check if driver is new based configured dirving experience
                if (minDrivingExperience > 0 && drivingExperience > 0) {
                    if (drivingExperience < minDrivingExperience)
                        isYoungOrNew = true;
                }

                //check if driver is young based on configured age
