                baseUrl = 'http://localhost:7071/api'; //For Debugging only


            var connName = "SalikDownloadApp";
            var salikFirebase = null;

            //////////////////////////////////////////////////////////
            ///// Download tolls and report progress using Firebase //
            //////////////////////////////////////////////////////////

            var enqueueAndDownloadWithProgress = function (callbackfunc, requestData, error) {
                var salikFirebaseResponse = {
                    progress: 0,
                    downloadCount: 0,
                    isComplete: false,
                    error: ''
                };

                var callback = callbackfunc;
                var errorCallback = error;

                var azureUrl = baseUrl + '/EnqueueDownloadTolls'; //baseUrl + '/DownloadTolls_HttpStart';  //

                requestData = angular.extend({}, requestData, { tenantId: tenantId });

                //if (location.hostname == "localhost") {
                //    if (!confirm("Want to Download Tolls?"))
                //        return true;
                //}

                $http({
                    url: azureUrl,
                    method: "POST",
                    data: requestData
                }).then(
                    function success(result) {

                        //var initialResponse = result.data.speedAzureResponse;
                        var initialResponse = result.data;

                        if (!initialResponse) {
                            errorCallback('error occured while downloading in Azure.');
                            return;
                        }

                        //Connect to firebase using config from response...

                        var firbaseConfig = initialResponse.SpeedFirebaseConfig;

                        var firebaseIsAlreadyInitialized = false;


                        //If there is any created app which has same name but not disposed before then remove it from firebase
                        try {
                            salikFirebase = firebase.app(connName);
                            if (salikFirebase) //salikFirebase.delete().then(function (r) { salikFirebase = null; console.log(r); }, function (e) { console.log(e); })
                                firebaseIsAlreadyInitialized = true;
                        } catch (e) {
                            var exc = e;
                        }

                        if (!firebaseIsAlreadyInitialized) {

                            salikFirebase = firebase.initializeApp({
                                apiKey: firbaseConfig.ApiKey,
                                authDomain: firbaseConfig.AuthDomain,
                                databaseURL: firbaseConfig.DatabaseUrl,
                                projectId: firbaseConfig.ProjectId,
                                storageBucket: firbaseConfig.StorageBucket
                            }, connName);
                        }

                        var isFirebaseLoggedIn = false;
                        try {
                            if (salikFirebase.auth().currentUser) {

                                isFirebaseLoggedIn = true;
                            }
                        } catch (e) {
                            var exce = e;
                        }

                        var registerFirebaseListener = function () {
                            var firebaseProgressReporter = salikFirebase.database().ref().child(initialResponse.FirebaseChildPath);

                            //Watch the value changing in status object in firbase for downloading...
                            firebaseProgressReporter.on('value', function (sanpshot) {
                                if (!sanpshot) return;

                                var obj = sanpshot.val();

                                if (obj) {

                                    salikFirebaseResponse.progress = obj.ProgressPercentage;
                                    salikFirebaseResponse.downloadCount = obj.DownloadedCount;
                                    salikFirebaseResponse.isComplete = obj.IsComplete;
                                    salikFirebaseResponse.error = obj.Error;

                                    callback && callback(salikFirebaseResponse);
                                }
                            });

                            callback && callback(salikFirebaseResponse);
                        };

                        try {
                            if (!isFirebaseLoggedIn) {
                                salikFirebase.auth().signInWithCustomToken(firbaseConfig.Token).then(function () {

                                    registerFirebaseListener();

                                }, function error(reason) {
                                    console.log(reason);
                                    errorCallback && errorCallback('error occured while signing in to Firebase..');
                                    return false;
                                });
                            }
                            else {

                                registerFirebaseListener();

                            }
                        } catch (e) {
                            errorCallback && errorCallback(e);
                        }

                    },
                    function error(reason) {
                        console.log(reason);
                    });
            };

            //Get local or online URL 
            var getTollsCount = function (requestData, successCallback, errorCallback) {

                requestData.tenantId = tenantId;

                $http({
                    url: baseUrl + '/GetTollsCount',
                    method: "POST",
                    data: requestData
                }).then(
                    function success(result) {
                        successCallback && successCallback(result);
                    },
                    function error(e) {
                        errorCallback && errorCallback(e);
                    }
                );

            };

            //This function is not completed and under development, Azure func size is also in-complete
            //var getTollsCountWithFb = function (request, callback, error) {

            //    var azureUrl = baseUrl + '/EnqueueTollsCount';
            //    $http({
            //        url: azureUrl,
            //        method: "POST",
            //        data: request
            //    }).then(
            //        function success(result) {

            //            //var initialResponse = result.data.speedAzureResponse;
            //            var initialResponse = result.data;

            //            if (!initialResponse) {
            //                error && error('error occured while downloading in Azure.');
            //                return;
            //            }

            //            //Connect to firebase using config from response...

            //            var firbaseConfig = initialResponse.SpeedFirebaseConfig;

            //            var firebaseIsAlreadyInitialized = false;


            //            //If there is any created app which has same name but not disposed before then remove it from firebase
            //            try {
            //                salikFirebase = firebase.app(connName);
            //                if (salikFirebase) //salikFirebase.delete().then(function (r) { salikFirebase = null; console.log(r); }, function (e) { console.log(e); })
            //                    firebaseIsAlreadyInitialized = true;
            //            } catch (e) {
            //                var exc = e;
            //            }

            //            if (!firebaseIsAlreadyInitialized) {

            //                salikFirebase = firebase.initializeApp({
            //                    apiKey: firbaseConfig.ApiKey,
            //                    authDomain: firbaseConfig.AuthDomain,
            //                    databaseURL: firbaseConfig.DatabaseUrl,
            //                    projectId: firbaseConfig.ProjectId,
            //                    storageBucket: firbaseConfig.StorageBucket
            //                }, connName);
            //            }

            //            var isFirebaseLoggedIn = false;
            //            try {
            //                if (salikFirebase.auth().currentUser) {

            //                    isFirebaseLoggedIn = true;
            //                }
            //            } catch (e) {
