			var toWords = function (s, currencyName, decimalName) {

				vm.currencyName = currencyName || abp.setting.get("App.General.CurrencyName");
				vm.decimalCurrencyName = decimalName || abp.setting.get("App.General.DecimalCurrencyName");
				// American Numbering System
				var th = ['', 'thousand', 'million', 'billion', 'trillion'];
				// uncomment this line for English Number System
				// var th = ['','thousand','million','milliard','billion'];
				var dg = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];
				var tn = ['ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
				var tw = ['twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
				s = (abp.session.tenantId == 3461 ? Number(s).toFixed(3) : Number(s).toFixed(vm.currencyDecimals)) + '';
				s = s.replace(/[\, ]/g, '');
				if (s != parseFloat(s)) return 'not a number';
				var x = s.indexOf('.');
				if (x == -1) x = s.length;
				if (x > 15) return 'too big';
				var n = s.split('');
				var str = '';
				var sk = 0;

				for (var i = 0; i < x; i++) {
					if ((x - i) % 3 == 2) {
						if (n[i] == '1') {
							str += tn[Number(n[i + 1])] + ' ';
							i++;
							sk = 1;
						} else if (n[i] != 0) {
							str += tw[n[i] - 2] + ' ';
							sk = 1;
						}
					} else if (n[i] != 0) {
						str += dg[n[i]] + ' ';
						if ((x - i) % 3 == 0) str += 'hundred ';
						sk = 1;
					}
					if ((x - i) % 3 == 1) {
						if (sk) str += th[(x - i - 1) / 3] + ' ';
						sk = 0;
					}
				}
				if (str != '')
					str += vm.currencyName;
				if (x != s.length) {
					var y = s.length;
					var z = s.split('.')

					if (parseFloat(z[1]) != 0) {
						if (str != '')
							str += ' And ';
						//for (var i = x + 1; i < y; i++) str += dg[n[i]] + ' ';
						for (var i = x + 1; i < y; i++) {
							if ((y - i) % 3 == 2) {
								if (n[i] == '1') {
									str += tn[Number(n[i + 1])] + ' ';
									i++;
									sk = 1;
								} else if (n[i] != 0) {
									str += tw[n[i] - 2] + ' ';
									sk = 1;
								}
							} else if (n[i] != 0) {
								str += dg[n[i]] + ' ';
								if ((y - i) % 3 == 0) str += 'hundred ';
								sk = 1;
							}
							if ((y - i) % 3 == 1) {
								if (sk) str += th[(y - i - 1) / 3] + ' ';
								sk = 0;
							}
						}
						str += vm.decimalCurrencyName;
					}
				}

				return str.replace(/\s+/g, ' ') + ' only';
			};

			var getVehicleSubStatuses = function (subStatus) {
				if (!subStatus) return '';
				if (subStatus == 1) return app.localize('Available');
				else if (subStatus == 2) return app.localize('NotReady');
				else if (subStatus == 3) return app.localize('ForSale');
				else if (subStatus == 4) return app.localize('TotalLoss');
				else if (subStatus == 5) return app.localize('PendingCustomerDelivery');
				else if (subStatus == 6) return app.localize('PendingWorkshopDelivery');
				else if (subStatus == 7) return app.localize('ReadyToGo');
				return '';
			};

