			var getTaxRules = () => {
				var rules = [
					{ id: 1, name: app.localize('StandardRated') },
					{ id: 2, name: app.localize('ZeroRated') },
					{ id: 3, name: app.localize('Exempted') },
					// { id: 4, name: app.localize('OutsideScope') },
				];
				if (isGroupTRNEnabled) {
					rules.push({ id: 5, name: app.localize('GroupTRN') });
				}

				return rules;
			};
			var getZeroRatedOrExemptedTaxRules = () => {
				var rules = [
					/*{ id: 2, name: app.localize('Exempted') },*/
					{ id: 3, name: app.localize('ZeroRated') },
				];
				if (isGroupTRNEnabled) {
					rules.push({ id: 5, name: app.localize('GroupTRN') });
				}
				if (vm.isTaxCategoryInRentalOrLeaseModule) {
					rules.push({ id: 4, name: app.localize('OutofScope') });
				}
				if (!vm.isTaxCategoryInRentalOrLeaseModule) {
					rules.push({ id: 2, name: app.localize('Exempted') });
				}
				return rules;
			};
