			var checkNegativeDueAmounts = function (allocations) {

				if (canOverAllocateAllocation)
					return false;

				var anyNegativeDueAmount = allocations.some(allocation =>
					round(allocation.amount - allocation.alreadyAllocated - allocation.allocatedNow, 2) < 0
				);
				return anyNegativeDueAmount;
			};

