			var multilineStringToHTML = function (input) {
				if (!input) return input;
				var output = input
					//replace possible line breaks.
					.replace(/(\r\n|\r|\n)/g, '<br/>')
					//replace tabs
					.replace(/\t/g, '&nbsp;&nbsp;&nbsp;')
					//replace spaces.
					.replace(/ /g, '&nbsp;');

				return output;
			};

			var multilineStringToHTMLWordBreak = function (input) {
				if (!input) return input;
				var output = input
					//replace possible line breaks.
					.replace(/(\r\n|\r|\n)/g, '<br/>')
					//replace tabs
					.replace(/\t/g, '&nbsp;&nbsp;&nbsp;')
				//replace spaces.
				//.replace(/ /g, '&nbsp;');
				return output;
			};


			var findInNestedListById = function (list, value) {
				if (value !== null) {
					return list.reduce(function f(acc, val) {
						return (val.id === value) ? val :
							(val.children && val.children.length) ? val.children.reduce(f, acc) : acc;
					});
				} else {
					return null;
				}
			};

