                            x.showPlannedDate = plannedDate.isValid() && releaseDate.isValid() && !releaseDate.isSame(plannedDate, 'day');

                            vm.totalActiveReleaseTaskCount += x.taskCount;
                            vm.totalInCompletedTaskCount += x.completedTask;
