(function () {
    appModule.controller('host.views.cbs.projects.uploadDocumentsModal', [
        '$scope', 'appSession', '$uibModalInstance', 'FileUploader', 'tenantId',
        function ($scope, appSession, $uibModalInstance, fileUploader, tenantId) {

            var vm = this;
            vm.loading = false;
            vm.uploadedFileName = null;
            vm.uploadedFileUrl = null;

            vm.uploadHeader = function () {
                return app.localize("Document")
            };

            function guid() {
                function _p8(s) {
                    var p = (Math.random().toString(16) + "000000000").substr(2, 8);
                    return s ? "-" + p.substr(0, 4) + "-" + p.substr(4, 4) : p;
                }
                return _p8() + _p8(true) + _p8(true) + _p8();
            }
            var getGUID = guid();

            vm.uploader = new fileUploader({
                url: abp.appPath + 'Document/UploadDocumentFromHost?id=' + getGUID + '&tenantId=' + tenantId,
                queueLimit: 1,
                autoUpload: true,
                removeAfterUpload: true,
                filters: [{
                    name: 'filter',
                    fn: function (item, options) {
                        //File type check
                        //var type = '|' + item.type.slice(item.type.lastIndexOf('/') + 1) + '|';
                        //if ('|jpg|jpeg|png|'.indexOf(type) === -1) {
                        //    abp.message.warn(app.localize('ProfilePicture_Warn_FileType'));
                        //    return false;
                        //}

                        //File size check
                        if (item.size > 5242880 * 5) //5MB
                        {
                            abp.message.warn(app.localize('Document_Warn_SizeLimit'));
                            return false;
                        }

                        return true;
                    }
                }]
            });

            vm.uploader.onSuccessItem = function (fileItem, response, status, headers) {
                vm.loading = true;
                if (response.success) {
                    vm.uploadedFileName = response.result.fileName;
                    vm.uploadedFileUrl = response.result.url;
                    vm.loading = false;
                    $uibModalInstance.close({ guid: getGUID, name: response.result.fileName, url: response.result.url, urlWithToken: response.result.url + response.result.token });

                } else {
                    abp.message.error(response.error.message);
                }

            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
        }
    ]);
})();;
(function () {
    appModule.controller('host.views.cbs.projects.viewModal', [
        '$uibModalInstance', 'projectId', 'abp.services.app.project',
        function ($uibModalInstance, projectId, projectService) {
            var vm = this;
            vm.teamMembers = [];
            vm.getProjectStatus = function (status) {
                if (!status)
                    return '';
                if (status == 1)
                    return 'Open';
                if (status == 2)
                    return 'Closed';
                if (status == 3)
                    return 'On Hold';
                if (status == 4)
                    return 'Cancelled';
                if (status == 5)
                    return 'Completed';
            };
            vm.getProjectType = function (type) {
                if (!type || type == 0)
                    return 'Not Set';
                if (type == 1)
                    return 'Domestic';
                if (type == 2)
                    return 'International';
                if (type == 3)
                    return 'Internal';

            };
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };


            
            function init() {
                vm.loading = true;
                projectService.getProjectForView({
                    id: projectId
                }).success(function (result) {
                    vm.project = result;
                    vm.teamMembers = result.teamMembers;
                    vm.additionalTenants = "";
                    angular.forEach(vm.project.additionalTenants, function (value) {
                        vm.additionalTenants += value.tenancyName + " " + value.name + ", ";
                    });
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();;
