                vm.getStatus = function (id) {
                    if (id == 1)
                        return app.localize("New");
                    else if (id == 2)
                        return app.localize("Closed");
                    else if (id == 3)
                        return app.localize("Cancelled");
                    else if (id == 4)
                        return app.localize("OnHold");
                    else if (id == 5)
                        return "Estimation Pending";
                    else if (id == 6)
                        return "Estimated, Customer Confirmation Pending";
                    else if (id == 7)
                        return "Customer Confirmed, Finance Approval Pending";
                    else if (id == 8)
                        return "Finance Approved";
                    else if (id == 9)
                        return "In-Progress";
                    else if (id == 10)
                        return "Scope Sent";
                    else if (id == 11)
                        return "Scope Approved";
                    else if (id == 12)
                        return "Quotation Sent";
                    else if (id == 13)
                        return "Quotation Approved";
                    else if (id == 14)
                        return "On Approval";
                    else if (id == 15)
                        return "Delivered";
                    else return '';
                };

