(function () {
    appModule.controller('host.views.crm.productVariants.productVariantSettingModal', [
        '$scope', '$filter', '$uibModalInstance', 'abp.services.app.productVariant', 'productVariant',
        function ($scope, $filter, $uibModalInstance, productVariantService, productVariant) {
            var vm = this;

            vm.saving = false;
            vm.variant = productVariant;
            vm.variant.checkCardTypes = [];

            vm.checkCardTypes = [
                { id: 1, name: "Agreement"},
                { id: 2, name: "NRM"},
                { id: 3, name: "Repair & Maintenance"},
                { id: 4, name: "Estimation/Job"},
                { id: 5, name: "Customer Vehicle"},
                { id: 6, name: "Replacement Vehicle"},
                { id: 7, name: "Workshop"},
                { id: 8, name: "Inspection"}
            ];

            vm.movementTypes = [
                { id: 1, name: "Agreement" },
                { id: 2, name: "NRM" },
                { id: 3, name: "Garage" },
                { id: 4, name: "Delivery" },
                { id: 5, name: "Collection" },
                { id: 6, name: "Total Loss" },
                { id: 7, name: "Due for Sale" },
                { id: 8, name: "Status Change" },
                { id: 9, name: "Mileage Update" },
                { id: 10, name: "Garage Job" }
            ];

            vm.steps = [
                {id: 1, name: 'One Step'},
                {id: 2, name: 'Two Step'}
            ]

            vm.stepCheckTypes = [
                { id: 1, name: 'Check-out' },
                { id: 2, name: 'Check-in' }
            ]

            vm.additionalFieldsList = [
                { id: 1, name: "Vehicle" },
                { id: 2, name: "Customer" },
                { id: 3, name: "Driver" },
                { id: 4, name: "Workshop" },
                { id: 5, name: "AgreementNo" },
                { id: 6, name: "Branch" },
                { id: 7, name: "Notes" },
                { id: 8, name: "Custom Field 1" },
                { id: 9, name: "Custom Field 2" },
                { id: 10, name: "Custom Field 3" },
                { id: 11, name: "Documents" }
            ];

            vm.ducumentsList = [
                { id: 1, name: "Passport" },
                { id: 2, name: "National ID" },
                { id: 3, name: "Driving License" }
            ];

            vm.getCheckCardTypeName = function (type) {
                if (type == 1)
                    return "Agreement";
                if (type == 2)
                    return "NRM";
                if (type == 3)
                    return "Repair & Maintenance";
                if (type == 4)
                    return "Estimation/Job";
                if (type == 5)
                    return "Customer Vehicle";
                if (type == 6)
                    return "Replacement Vehicle";
                if (type == 7)
                    return "Workshop";
                if (type == 8)
                    return "Inspection";
            }

            vm.sortOfCCTypeSettingsChanged = function (event, ui) {
                vm.loading = true;
                var obj = JSON.parse(ui.item.attr('data-id'));
                var updatedIndex = ui.item.index();

                var row = obj.row;


                if (updatedIndex === 0) {

                    row.order = (vm.variant.checkCardTypes[0].order) / 2;
                    var element = row;
                    vm.variant.checkCardTypes.splice(obj.rowIndex, 1);
                    vm.variant.checkCardTypes.splice(updatedIndex, 0, element);
                }
                else if (updatedIndex === (vm.variant.checkCardTypes.length - 1)) {
                    row.order = (vm.variant.checkCardTypes[updatedIndex].order + vm.variant.checkCardTypes[updatedIndex].order + 1) / 2;
                    element = row;
                    vm.variant.checkCardTypes.splice(obj.rowIndex, 1);
                    vm.variant.checkCardTypes.splice(updatedIndex, 0, element);
                }
                else {
                    if (updatedIndex > obj.rowIndex)
                        row.order = (vm.variant.checkCardTypes[updatedIndex + 1].order + vm.variant.checkCardTypes[updatedIndex].order) / 2;
                    else if (updatedIndex < obj.rowIndex)
                        row.order = (vm.variant.checkCardTypes[updatedIndex - 1].order + vm.variant.checkCardTypes[updatedIndex].order) / 2;
                    element = row;
                    vm.variant.checkCardTypes.splice(obj.rowIndex, 1);
                    vm.variant.checkCardTypes.splice(updatedIndex, 0, element);
                }
                vm.loading = false;
                $scope.$apply();
            };

            vm.sortOfSettingsChanged = function (event, ui) {
                vm.loading = true;
                var obj = JSON.parse(ui.item.attr('fieldData-id'));
                var updatedIndex = ui.item.index();
                var row = obj.row;
                var ccType = vm.variant.checkCardTypes[obj.ccTypeIndex];

                if (updatedIndex === 0) {

                    row.order = (ccType.fields[0].order) / 2;
                    var element = row;
                    ccType.fields.splice(obj.rowIndex, 1);
                    ccType.fields.splice(updatedIndex, 0, element);
                }
                else if (updatedIndex === (ccType.fields.length - 1)) {
                    row.order = (ccType.fields[updatedIndex].order + ccType.fields[updatedIndex].order + 1) / 2;
                    element = row;
                    ccType.fields.splice(obj.rowIndex, 1);
                    ccType.fields.splice(updatedIndex, 0, element);
                }
                else {
                    if (updatedIndex > obj.rowIndex)
                        row.order = (ccType.fields[updatedIndex + 1].order + ccType.fields[updatedIndex].order) / 2;
                    else if (updatedIndex < obj.rowIndex)
                        row.order = (ccType.fields[updatedIndex - 1].order + ccType.fields[updatedIndex].order) / 2;
                    element = row;
                    ccType.fields.splice(obj.rowIndex, 1);
                    ccType.fields.splice(updatedIndex, 0, element);
                }
                vm.loading = false;
                $scope.$apply();
            };

            vm.addCheckCardType = function () {
                var order = vm.variant.checkCardTypes.length < 1 ? 1 :
                    vm.variant.checkCardTypes[vm.variant.checkCardTypes.length - 1].order + 1;
                var ccType = {
                    type: null, name: null, productVariantId: productVariant.id, order: order, stepType: null, step1CheckType: null, step1CheckTypeLabel: null, step2CheckType: null, step2CheckTypeLabel: null,
                    fields: []
                };
                vm.variant.checkCardTypes.push(ccType);
            }

            vm.removeRow = function (obj) {
                var index = vm.variant.checkCardTypes.indexOf(obj);
                vm.variant.checkCardTypes.splice(index, 1);
            };

            vm.addAdditionalField = function (row) {
                var order = row.fields.length < 1 ? 1 :
                    row.fields[row.fields.length - 1].order + 1;
                row.fields.push({ order: order});
            }

            vm.removeAdditionalFieldRow = function (obj, row) {
                var index = row.fields.indexOf(obj);
                row.fields.splice(index, 1);
            }

            vm.save = function () {
                vm.saving = true;
                productVariantService.saveVariantSetting({ checkCardTypes: vm.variant.checkCardTypes, productVariantId: productVariant.id }).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function() {
                    vm.saving = false;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.loading = true;
                productVariantService.getProductVariantForEdit({ id: productVariant.id }).success(function (result) {
                    vm.variant = result;
                    if (!vm.variant.checkCardTypes)
                        vm.variant.checkCardTypes = [];

                    vm.variant.checkCardTypes = $filter('orderBy')(vm.variant.checkCardTypes, 'order');
                    for (var i = 0; i < vm.variant.checkCardTypes.length; i++) {
                        vm.variant.checkCardTypes[i].fields = $filter('orderBy')(vm.variant.checkCardTypes[i].fields, 'order');
                    }

                }).finally(function () {
                    vm.loading = false;
                });
            }
            init();
        }
    ]);
})();;
(function () {
    appModule.controller('host.views.crm.proposal.createOrEditProposalModal', [
        '$scope', '$uibModalInstance', 'proposalId', 'abp.services.app.proposal', 'abp.services.app.directory', 'abp.services.app.edition',
        function ($scope, $uibModalInstance, proposalId, proposalService, directoryService, editionService) {

            var vm = this;
            vm.saving = false;
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.editionFeaturesvalues = [];
            vm.featureData = null;
            vm.isOldSpeedRadioEnabled = true;
            vm.proposal = {
                customizationbuffer: 1,
                dataMigrationRadio: 1,
                proposalDetail: {
                    customization:
                    {
                        customizationRadio: 1,
                        customizationBufferHours: null,
                        customizationDescriptionList: [],
                    },
                    dataMigration:
                    {
                        dataMigrationRadio: 1,
                        migrationFeatures: [],
                    },
                    featureData: null,
                }
            };

            var featureKeys = [
                'Core.Companies',
                'Core.Contacts',
                'Core.Staff',
                'Core.Suppliers',
                'Core.Vehicles',
                'CRS.Accounts.OpeningBalances',
                'CRS.Rental.Agreements.Open',
                'CRS.Rental.Agreements.Close'
            ];


            vm.searchsupportPlan = function ($select) {
                vm.supports = [
                    { id: 1, name: 'Support Plan A' },
                    { id: 2, name: 'Support Plan B' },
                    { id: 3, name: 'Support Plan C' },
                    { id: 4, name: 'Support Plan D' }
                ];
            };


            vm.searchLicencePlan = function ($select) {
                vm.licence = [
                    { id: 1, name: 'Perpetual' },
                    { id: 2, name: 'Subscription' }
                ];
            };
            vm.searchCompany = function ($select) {
                return directoryService.search({ keyword: $select.search, contactCategory: 2 }).then(function (response) {
                    vm.companies = response.data.items;
                });
            };


            vm.getEditionValue = function (item) {
                return parseInt(item.value);
            };

            vm.setActiveTabIndex = function (index) {
                if (index == 4)
                    vm.dataMigrationTabSelected();
            };


            vm.dataMigrationTabSelected = function () {
               
                if (vm.isEditMod == false) {
                    vm.proposal.proposalDetail.dataMigration.migrationFeatures = [];
                    featureKeys.forEach(function (value) {
                        var matchedValues = vm.proposal.proposalDetail.featureData.featureValues.filter(e => e.name == value && e.value == 'true');
                        if (matchedValues.length > 0) {
                            var featureDisplyName = '';
                            var matchedName = vm.proposal.proposalDetail.featureData.features.filter(e => e.name == matchedValues[0].name);
                            if (matchedName.length > 0) {
                                featureDisplyName = matchedName[0].displayName;
                            }
                            vm.proposal.proposalDetail.dataMigration.migrationFeatures.push({ featureName: matchedValues[0].name, selected: false, displayName: featureDisplyName });
                        }
                    });
                }
                else {
                    featureKeys.forEach(function (value) {
                        var matchedValues = vm.proposal.proposalDetail.featureData.featureValues.filter(e => e.name == value && e.value == 'true');
                        if (matchedValues.length > 0) {
                            var ValueToAdd = vm.proposal.proposalDetail.dataMigration.migrationFeatures.filter(r => r.featureName == value);
                            if (ValueToAdd.length == 0) {
                                var featureDisplyName = '';
                                var matchedName = vm.proposal.proposalDetail.featureData.features.filter(e => e.name == matchedValues[0].name);
                                if (matchedName.length > 0) {
                                    featureDisplyName = matchedName[0].displayName;
                                }
                                vm.proposal.proposalDetail.dataMigration.migrationFeatures.push({ featureName: matchedValues[0].name, selected: false, displayName: featureDisplyName });
                            }
                        }
                        else {
                            var valueToRemove = vm.proposal.proposalDetail.dataMigration.migrationFeatures.filter(r => r.featureName == value);
                            if (valueToRemove.length > 0) {
                                vm.proposal.proposalDetail.dataMigration.migrationFeatures = vm.proposal.proposalDetail.dataMigration.migrationFeatures.filter(r => r.featureName != valueToRemove[0].featureName);
                            }
                        }
                    });
                }

                //Old speed radio check on the basis of CRS=true
                var oldSpeedCheck = vm.proposal.proposalDetail.featureData.featureValues.filter(e => e.name == "CRS" && e.value == "true");
                vm.isOldSpeedRadioEnabled = oldSpeedCheck.length == 0 ? false : true;
            };


            vm.getEditions = function (editionId) {
                vm.proposal.proposalDetail.dataMigration.migrationFeatures = [];
                proposalService.getEditionForProposalEdit({
                    id: editionId
                }).success(function (result) {
                    vm.edition = result.edition;
                    vm.proposal.proposalDetail.featureData = {
                        features: result.features,
                        featureValues: result.featureValues
                    };
                    vm.editionFeaturesvalues = result.featureValues;
                });
            }

            vm.save = function () {
                if (!vm.proposal.proposalDetail.featureData.isValid()) {
                    abp.message.warn(app.localize('InvalidFeaturesWarning'));
                    return;
                }
                debugger;
                vm.saving = true;
                if (vm.proposal.proposalDetail.licenceType != null) {
                    vm.proposal.proposalDetail.licenceType = vm.proposal.proposalDetail.licenceType.id;
                }
                if (vm.proposal.edition != null) {
                    vm.proposal.editionId = vm.proposal.edition.id;
                }
                proposalService.createOrUpdateProposal({
                    proposal: vm.proposal,
                }).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });
            };



            vm.addRow = function (line) {
                if (line == undefined)
                    line = customizationListLineObject();
                vm.proposal.proposalDetail.customization.customizationDescriptionList.push(line);
            };

            function customizationListLineObject() {
                var line = new Object();
                line.description = '';
                return line;
            }

            vm.removeRow = function (obj) {
                var index = vm.proposal.proposalDetail.customization.customizationDescriptionList.indexOf(obj);
                vm.proposal.proposalDetail.customization.customizationDescriptionList.splice(index, 1);
            };

            vm.featureDataForViewOnly = function () {

                var parentFeatureValues = [];
                var childFeatureValues = [];
                var parentFeature = [];
                var childFeature = [];

                featureKeys.forEach(function (value) {
                    var enabledFeatureValue = vm.proposal.proposalDetail.featureData.featureValues.filter(e => e.name == value && e.value == 'true');
                    if (enabledFeatureValue.length > 0)
                        childFeatureValues.push(enabledFeatureValue[0]);

                });

                featureKeys.forEach(function (value) {
                    var featureToAdd = vm.proposal.proposalDetail.featureData.features.filter(r => r.name == value)[0];
                    var parentNameNull = false;
                    var featureToAddParent = featureToAdd;
                    childFeature.push(featureToAdd);
                    while (!parentNameNull) {
                        featureToAddParent = vm.proposal.proposalDetail.featureData.features.filter(r => r.name == featureToAddParent.parentName)[0];
                        if (featureToAddParent != null) {
                            if (!childFeature.filter(r => r.name == featureToAddParent.name).length > 0)
                                childFeature.push(featureToAddParent);
                        }
                        else {
                            parentNameNull = true;
                        }
                    }
                }

                );
                vm.featureData = {
                    features: childFeature,
                    featureValues: childFeatureValues
                };


            };

            function getEditions() {
                editionService.getEditions().success(function (result) {
                    vm.editions = result.items;
                });
            }

            function init() {
                vm.loading = true;
                proposalService.getProposalForEdit({ id: proposalId }).success(function (result) {
                    getEditions();
                    vm.proposal = result;
                    if (proposalId > 0) {
                        vm.isEditMod = true;
                        vm.searchLicencePlan(null);
                        vm.searchsupportPlan(null);
                        vm.proposal.proposalDetail.licenceType = vm.licence.filter(r => r.id == result.proposalDetail.licenceType)[0];
                        if (vm.proposal.proposalDetail.customization.customizationDescriptionList == null) {
                            vm.proposal.proposalDetail.customization.customizationDescriptionList = [];
                            vm.addRow();
                        }
                    }
                    else {
                        vm.isEditMod = false;
                        vm.addRow();
                    }
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('host.views.crm.proposal.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.proposal','abp.services.app.commonLookup', 'abp.services.app.directory',
        function ($scope, $uibModal, uiGridConstants, proposalService, commonLookupService, directoryService) {
            var vm = this;
            vm.loading = false;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeModel = {
                startDate: moment(moment().format('YYYY-MM-DD')).utc(),
                endDate: moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc()
            };

            vm.filters = {
                enableDateRange:true,
                proposalNo: '',
                editionId: null,
                companyId: null,
                firstDateSearch: false,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
            };


            vm.permissions = {
                view: abp.auth.hasPermission('Pages.CRM.Proposal.TechnicalPuposal'),
                create: abp.auth.hasPermission('Pages.CRM.Proposal.TechnicalPuposal.AddNew'),
                edit: abp.auth.hasPermission('Pages.CRM.Proposal.TechnicalPuposal.Edit'),
                'delete': abp.auth.hasPermission('Pages.CRM.Proposal.TechnicalPuposal.Delete')
            };


            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.createProposal = function () {
                openCreateOrEditProposalModal(null);
            };





            function openCreateOrEditProposalModal(proposalId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/crm/proposal/createOrEditProposalModal.cshtml',
                    controller: 'host.views.crm.proposal.createOrEditProposalModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        proposalId: function () {
                            return proposalId;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getProposals();
                });
            }

            vm.searchCompanies = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                return directoryService.search({ keyword: $select.search, contactType: 2, contactCategory: 2 }).then(function (response) {
                    vm.companies = response.data.items;
                });
            };



            vm.clearCompany = function () {
                vm.filters.companyId = null;
                vm.filters.company = null;
            };


            vm.getEditionValue = function (item) {
                return parseInt(item.value);
            };

            function getEditions() {
                vm.loading = true;
                commonLookupService.getEditionsForCombobox({}).success(function (result) {
                    vm.editions = result.items;
                }).finally(function () {
                    vm.loading = false;
                });
            }

            vm.getLocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('DD-MMM-YY');
                }
                else {
                    return "";
                }
            };
            vm.dateRangeCheck = function () {

                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
            };
            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: 120,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.view" ng-click="grid.appScope.viewProposal(row.entity)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.edit" ng-click="grid.appScope.editProposal(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.delete" ng-click="grid.appScope.deleteProposal(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.view" target="_blank" href="/Report#/host/printModalProposal/{{row.entity.id}}" >' + app.localize('Print') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: 'Proposal No',
                        field: 'proposalNo'
                    },
                    {
                        name: 'Date',
                        field: 'proposalDate',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getLocalDate(row.entity.proposalDate)}}</div>' +
                            '</div>'
                    },
                    {
                        name: 'Company',
                        field: 'company.name'
                    },
                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = null;
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }
                        vm.getProposals();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;
                        vm.getProposals();
                    });
                },
                data: []
            };

            vm.editProposal = function (proposal) {
                openCreateOrEditProposalModal(proposal.id);
            };
            vm.viewProposal = function (proposal) {
                openViewProposalModal(proposal.id);
            };



            function openViewProposalModal(proposalId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/crm/proposal/viewModel.cshtml',
                    controller: 'host.views.crm.proposal.viewModel as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        proposalId: function () {
                            return proposalId;
                        }
                    }
                });
            }
            vm.dateRangeModelChange = function () {
                vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };
            vm.deleteProposal = function (proposal) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            proposalService.deleteproposal({ id: proposal.id }).success(function () {
                                vm.getProposals();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };



            vm.getProposals = function () {
                vm.loading = true;
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
                proposalService.getProposals(vm.filters).success(function (data) {
                    vm.gridOptions.totalItems = data.totalCount;
                    vm.gridOptions.data = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };
            function init() {
                getEditions();
                vm.getProposals();
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('host.views.crm.proposal.printModal', ['$stateParams', '$sce', 'appSession', 'abp.services.app.proposal', 'abp.services.app.commonLookup', 'utilities',
        function ($stateParams, sce, appSession, proposalService, commonLookupService, utilities) {
            var vm = this;
            var proposalId = 0;
           

            //no Qatar police
            var featureKeys = ['CRS.Rental', 'CRS.Lease', 'CRS.Accounts', 'MCC', 'CRS.Tolls.Salik', 'CRS.Fines.AbuDhabiPolice', 'CRS.Fines.DubaiPolice','CRS.Fines.Qatar', 'CRS.Transportation','CRS.Limo'];
            vm.proposalPrintFeatureData = null;
            vm.inScopeTrueValue = [];
            if (!isNaN($stateParams.query)) {
                proposalId = $stateParams.query;
            }
            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };
            vm.getlocalDateTime = function (date, format) {
                if (date != null) {
                    if (format == null) format = vm.dateFormat;

                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(format);
                }
                else {
                    return "";
                }
            };

            vm.getLocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('DD-MMM-YY');
                }
                else {
                    return "";
                }
            };


            vm.getUserName = function (userId) {
                commonLookupService.getUser({
                    id: userId
                }).success(function (result) {
                    vm.userName = result.name;
                });
            };

            vm.featureDataForViewOnly = function () {
                var featureValues = [];
                var features = [];
                featureValues = vm.proposal.proposalDetail.featureData.featureValues.filter(e => e.value == 'true')
                featureValues.forEach(function (value) {
                    features.push(vm.proposal.proposalDetail.featureData.features.filter(r => r.name == value.name)[0]);
                });
                vm.proposalPrintFeatureData = {
                    features: features,
                    featureValues: featureValues
                };
            };


            vm.getlocalDateTimeForEngAr = function (date, format) {
                if (date != null) {
                    if (format == null) format = vm.dateFormat;

                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(format);
                }
                else {
                    return "";
                }
            };



            vm.licenceName = function (id) {
                var licenceArr = [
                    { id: 1, name: 'Perpetual' },
                    { id: 2, name: 'Monthly Subscription' }
                ];

                var result = licenceArr.filter(r => r.id == id);

                if (result.length == 0) {
                    return null;
                }
                else {
                    return result[0].name;
                }
            };


            vm.getTrueInScopeValues = function () {

                featureKeys.forEach(function (value) {
                    var matchedValues = vm.proposal.proposalDetail.featureData.featureValues.filter(e => e.name == value && e.value == 'true');
                   
                    if (matchedValues.length > 0) {
                        vm.inScopeTrueValue.push(matchedValues[0]);
                    }
                   
                });
                //only once data must be there about below three
               // 'CRS.Fines.AbuDhabiPolice', 'CRS.Fines.DubaiPolice', 'CRS.Fines.Qatar'

                var isDubaiPoliceExist = vm.inScopeTrueValue.filter(r => r.name == "CRS.Fines.DubaiPolice");
                var isAbuDhabiPoliceExist = vm.inScopeTrueValue.filter(r => r.name == "CRS.Fines.AbuDhabiPolice");
                var isQatarExist = vm.inScopeTrueValue.filter(r => r.name == "CRS.Fines.Qatar");
                if (isDubaiPoliceExist.length > 0) {
                    vm.inScopeTrueValue = vm.inScopeTrueValue.filter(r => r.name != 'CRS.Fines.AbuDhabiPolice');
                    vm.inScopeTrueValue = vm.inScopeTrueValue.filter(r => r.name != 'CRS.Fines.Qatar');
                }
                else if (isAbuDhabiPoliceExist.length > 0) {
                    vm.inScopeTrueValue = vm.inScopeTrueValue.filter(r => r.name != 'CRS.Fines.Qatar');
                    vm.inScopeTrueValue = vm.inScopeTrueValue.filter(r => r.name != 'CRS.Fines.DubaiPolice');
                }
                else if (isQatarExist.length > 0) {
                    vm.inScopeTrueValue = vm.inScopeTrueValue.filter(r => r.name != 'CRS.Fines.AbuDhabiPolice');
                    vm.inScopeTrueValue = vm.inScopeTrueValue.filter(r => r.name != 'CRS.Fines.DubaiPolice');
                }

            };


            function init() {
                {
                    debugger;
                    vm.loading = true;
                    proposalService.getProposalForPrint({
                        id: proposalId
                    }).success(function (result) {
                        vm.proposal = result;
                        vm.getTrueInScopeValues();
                        vm.featureDataForViewOnly();
                    }).finally(function () {
                        vm.loading = false;
                    });
                }
            }
            init();
        }
    ])

})();;
