(function () {
    appModule.controller('host.views.hr.keysStore.createOrEditModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.secretKey', 'secretKeyId', 'abp.services.app.user',
        function ($scope, $uibModal, $uibModalInstance, secretKeyService, secretKeyId, userService) {
            var vm = this;
            vm.keyStore = {};
            vm.saving = false;

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            var passwordEncripted = '';
            var passwordNormal = '';
            vm.passwordShown = false;

            function setPassword() {
                if (!vm.passwordShown) {
                    vm.keyStore.password = passwordNormal;
                    document.getElementById('keyPassword').type = "text";
                    vm.passwordShown = true;
                }
                else {
                    vm.keyStore.password = passwordEncripted;
                    document.getElementById('keyPassword').type = "password";
                    vm.passwordShown = false;
                }
            }

            vm.showPassword = function (keyStoreId) {
                if (!passwordNormal)
                    secretKeyService.getForView({ id: keyStoreId })
                        .success(function (r) {
                            passwordNormal = r.password;
                            setPassword();
                        });
                else
                    setPassword();


            };

            vm.save = function () {
                vm.saving = true;

                if (vm.keyStore.assignedToUser)
                    vm.keyStore.assignedToUserId = vm.keyStore.assignedToUser.id;

                //if (vm.keyStore.id && !vm.passwordShown)
                //vm.keyStore.password = passwordEncripted;

                secretKeyService.createOrUpdateSecretKey({ secretKey: vm.keyStore })
                    .success(function () {
                        abp.notify.info('Saved Successfully');
                        $uibModalInstance.close();
                    })
                    .finally(function () {
                        vm.saving = false;
                        vm.loading = false;
                    });
            };

            vm.twoFactorAuthenticationTypes = [
                { id: 1, value: 'SMS' },
                { id: 2, value: 'Email' },
                { id: 3, value: 'Google Authenticator' },
                { id: 4, value: 'Other' }
            ];

            vm.refresh = function () {
                secretKeyService.getSecretKeyForEdit({ id: secretKeyId })
                    .success(function (r) {
                        vm.keyStore = r;
                        passwordEncripted = vm.keyStore.password;

                        if (!r)
                            vm.keyStore.securityQuestions = [{ question: '', answer: '' }];
                    });
            };

            function init() {
                vm.refresh();
            }

            vm.keyStore.assignedToUser = null;
            vm.clearUser = function () {
                vm.keyStore.assignedToUser = null;
                vm.keyStore.assignedToUserId = null;
            };

            vm.users = [];
            vm.searchUsers = function ($select) {
                if ($select.search === "")
                    return null;
                userService.searchUsers({ keyword: $select.search })
                    .then(function (response) {
                        vm.users = response.data.items;
                    });
            };

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.hr.keysStore.index', [
        '$scope', '$uibModal', 'abp.services.app.secretKey',
        function ($scope, $uibModal, secretKeyService) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.loading = false;
            vm.secretKeyItems = [];

            vm.filters = {
                title: ''
            };

            vm.permissions = {
                view: abp.auth.hasPermission('Page.HR.KeysStore'),
                create: abp.auth.hasPermission('Page.HR.KeysStore.Add'),
                edit: abp.auth.hasPermission('Page.HR.KeysStore.Edit'),
                'delete': abp.auth.hasPermission('Page.HR.KeysStore.Delete'),
                canViewAllKeys: abp.auth.hasPermission('Page.HR.KeysStore.CanViewAllKeys')
            };

            vm.createKeysStore = function () {
                openCreateOrEditKeysStoreModal(null);
            };

            function openCreateOrEditKeysStoreModal(secretKeyId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/hr/keysStore/createOrEditModal.cshtml',
                    controller: 'host.views.hr.keysStore.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        secretKeyId: function () {
                            return secretKeyId;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.refresh();
                });
            }

            vm.refresh = function () {
                secretKeyService.getAll(vm.filters)
                    .success(function (r) {
                        vm.secretKeyItems = r.items;
                    });
            };

            vm.validate = function (row) {
                return vm.permissions.canViewAllKeys || row.assignedToUserId === abp.session.userId;
            };

            vm.viewKeyStore = function (id) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/hr/keysStore/viewModal.cshtml',
                    controller: 'host.views.hr.keysStore.viewModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        secretKeyId: function () {
                            return id;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                });
            };

            vm.updateKeyStore = function (id) {
                openCreateOrEditKeysStoreModal(id);
            };

            vm.delete = function (key) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', ''),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            secretKeyService.delete({ id: key.id }).success(function () {
                                abp.notify.info('Deleted Successfully');
                            }).finally(function () {
                                vm.refresh();
                            });
                        }
                    }
                );
            };

            function init() {
                vm.refresh();
            }

            init();
        }
    ]);
})();;
