(function () {

    appModule.controller('host.views.marketing.leads.report', [
        '$scope', 'abp.services.app.lead', 'utilities', 'abp.services.app.user',
        function ($scope, leadService, utilities, userService) {

            var vm = this;
            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.loading = false;
            vm.filters = null;

            if ($scope.$parent !== null) {
                if ($scope.$parent.vmMain !== null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            

            vm.allStatuses = [{ id: 1, name: 'Due' },
            { id: 2, name: 'Processed' },
            { id: 3, name: 'Converted' },
            { id: 4, name: 'Not Suitable' },
            { id: 10, name: 'New' },
            { id: 11, name: 'Suitable' },
            { id: 12, name: 'Not Suitable' },
            { id: 20, name: 'New' },
            { id: 21, name: 'Dull' },
            { id: 22, name: 'Rejected' },
            { id: 23, name: 'Not Suitable' },
            //{ id: 30, name: 'New' },
            { id: 31, name: 'Active' },
            { id: 32, name: 'Hot' },
            { id: 33, name: 'Final' },
            { id: 34, name: 'Closed' }];
            vm.statuses = [];

            vm.stages = [{ id: 1, name: 'Prospect' },
            { id: 2, name: 'Lead' },
            { id: 3, name: 'Deal' }];

            function getStatuses(row) {
                var stage = row.stage;

                if (stage === 0 || stage === null || stage === undefined) {
                    row.statuses = null;
                }
                else if (stage === 1) {
                    row.statuses = vm.allStatuses.filter(f => f.id >= 10 && f.id < 20);//prospect
                }
                else if (stage === 2) {
                    row.statuses = vm.allStatuses.filter(f => f.id >= 20 && f.id < 30);//Lead
                }
                else if (stage === 3) {
                    row.statuses = vm.allStatuses.filter(f => f.id >= 30 && f.id < 40);//Deal
                }
            }
            vm.stageChange = function (row) {
                getStatuses(row);
            };

            vm.totalValueChange = function (row) {
                row.totalValue = (parseFloat(vm.calculatedValue(row)) * 12) + parseFloat(row.setupCharges);
            };

            vm.calculatedValue = function (row) {
                if (row.subscriptionType == 2) {
                    return row.subscriptionCharges;
                }
                else {
                    return 0;
                }
            };

            if (vm.filters === null)
                vm.filters = $stateParams.filters;

            vm.getStageName = function (stage) {
                if (stage === 1) {
                    return 'Prospect';
                }
                else if (stage === 2) {
                    return 'Lead';
                }
                else if (stage === 3) {
                    return 'Deal';
                }
                else {
                    return '';
                }
            };
            vm.getStageNameForGroupBy = function (stage) {
                if (stage === 3) {
                    return 'Deals';
                }
                else if (stage === 2) {
                    return 'Leads';
                }
                else if (stage === 1) {
                    return 'Prospects';
                }
                else {
                    return '';
                }
            };
            vm.getStatusName = function (id) {
                if (id === 1) {
                    return "Due";
                }
                else if (id === 2) {
                    return "Processed";
                }
                else if (id === 3) {
                    return "Converted";
                }
                else if (id === 4) {
                    return "Not Suitable";
                }
                else if (id === 10) {
                    return "New";
                }
                else if (id === 11) {
                    return "Suitable";
                }
                else if (id === 12) {
                    return "Not Suitable";
                }
                else if (id === 20) {
                    return "New";
                }
                else if (id === 21) {
                    return "Dull Deal";
                }
                else if (id === 22) {
                    return "Rejected Sale";
                }
                else if (id === 23) {
                    return "Not Suitable";
                }
                else if (id === 30) {
                    return "New";
                }
                else if (id === 31) {
                    return "Active";
                }
                else if (id === 32) {
                    return "Hot";
                }
                else if (id === 33) {
                    return "Final";
                }
                else if (id === 34) {
                    return "Closed";
                }

            };
            vm.getVerifyStatusesName = function (value) {
                if (value == false) {
                    return "No";
                }
                else if (value == true) {
                    return "Yes";
                } else {
                    return null;
                }
            };

            vm.rowSaved = function (row, list) {
                
                if (row.salesPersonUser)
                    row.salesPersonUserId = row.salesPersonUser.id;
                const input = {
                    lead: row
                };
                leadService.updateLeadInline(input).success(function (result) {
                    if (row.status != 0 && list != undefined) {
                        var index = list.statusList.findIndex(function (obj) {
                            return obj.id === row.id;
                        });

                        // If the object is found, remove it from the array
                        if (index !== -1) {
                            list.statusList.splice(index, 1);
                        }
                        var specificStage =vm.leads.find(function (obj) {
                            return obj.stage === row.stage;
                        });
                        if (specificStage == undefined) {
                            vm.leads.push({ stage: row.stage, stageList: [{ status: row.status, statusList: [row], totalSetupCharges: row.setupCharges, totalSubscriptionCharges: row.subscriptionCharges, subscriptionType: row.subscriptionType }]});
                        }
                        else {

                            var specificStatus = specificStage.stageList.find(function (obj) {
                                return obj.status === row.status;
                            });
                            if (specificStatus == undefined) {
                                specificStage.stageList.push({ status: row.status, statusList: [row], totalSetupCharges: row.setupCharges, totalSubscriptionCharges: row.subscriptionCharges, subscriptionType: row.subscriptionType });
                            }
                            else {

                                specificStatus.statusList.push(row);
                                vm.totalSetupPerStatusValue(specificStatus);
                                vm.totalSubscriptionPerStatusValue(specificStatus);
                            }
                        }
                        vm.totalSetupPerStatusValue(list);
                        vm.totalSubscriptionPerStatusValue(list);
                        row.isEnabledStatus = false;
                    }

                });
            };

            vm.saveAssigned = function (task) {
                clearInterval(myInterval);
                    task.salesPerson = task.salesPersonUser.name;
                    task.isEnabled = false;
                vm.rowSaved(task);
                    
            };

            var myInterval = null;

            var tempRow = {};
            vm.assignUser = function (task) {

                task.isEnabled = true;
                setTimeout(function () {
                    $("#uiSelect_" + task.id + " span")[0].click();
                    tempRow = task;
                }, 100);
                    myInterval = setInterval(vm.focsOut,1);
            }

            vm.focsOut = function () {
                // Focus logic here
                $("#uiSelect_" + tempRow.id ).focusout(function () {
                    clearInterval(myInterval);
                    setTimeout(function () {
                        tempRow.isEnabled = false;
                    }, 225);

                });
            };

            vm.focusStage = function (task) {

                setTimeout(function () {
                    $("#uiSelectStage_" + task.id).focus().click();
                }, 100);
            }

            vm.focusStatus = function (task) {

                setTimeout(function () {
                    $("#uiSelectStatus_" + task.id).focus().click();
                }, 100);
            }
           



            
            

            vm.getLeadForReport = function () {
                vm.loading = true;
                leadService.getLeadsForReport(vm.filters).success(function (result) {
                    vm.leads = result;
                    
                }).finally(function () {
                    vm.loading = false;
                });
            };
           
            vm.totalPerStatusValue = function (List) {
                var totalPerStatusValue = 0;
                for (var i in List) {
                    totalPerStatusValue += List[i].totalValue;
                    }
                return totalPerStatusValue;
            }

            vm.totalSetupPerStatusValue = function (List) {
                var totalSetupPerStatusValue = 0;
                for (var i in List.statusList) {
                        totalSetupPerStatusValue += parseFloat(List.statusList[i].setupCharges);
                }
                List.totalSetupCharges = parseFloat(totalSetupPerStatusValue);
                //$scope.$apply();
            }

            vm.totalSubscriptionPerStatusValue = function (List) {
                var totalSubscriptionPerStatusValue = 0;
                for (var i in List.statusList) {
                    totalSubscriptionPerStatusValue += parseFloat(List.statusList[i].subscriptionCharges);
                }
                List.totalSubscriptionCharges = parseFloat(totalSubscriptionPerStatusValue);
            }

            vm.totalStatusCount = function (List) {
                var totalCount = 0;
                for (var i in List) {
                    totalCount += List[i].statusList.length;
                }
                return totalCount;
            }

            vm.totalSetupCharges = function (List) {
                var totalSetupCharges = 0;
                for (var i in List) {
                    totalSetupCharges += List[i].totalSetupCharges;
                }
                return totalSetupCharges;
            }

            vm.totalSubscriptionCharges = function (List) {
                var totalSubscriptionCharges = 0;
                for (var i in List) {
                    totalSubscriptionCharges += List[i].totalSubscriptionCharges;
                }
                return totalSubscriptionCharges;
            }


            vm.searchUsers = function ($select) {
                if ($select.search == "")
                    return null;
                userService.searchUsers({ keyword: $select.search }).then(function (response) {
                    vm.users = response.data.items;
                });
            };

            vm.totalValue = function (List) {
                var totalValue = 0;
                for (var i in List) {
                    for (var j in List[i].statusList) {
                        totalValue += List[i].statusList[j].totalValue;
                    }
                }
                return totalValue;
            }
          
            function init() {
                vm.getLeadForReport();
            }
            init();
        }
    ]);
})();;
(function () {
    appModule.controller('common.views.mergeContacts.importMergeContactsModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'fileName', '$filter', 'abp.services.app.mergeContact',
    function ($scope, $uibModal, $uibModalInstance, fileName, $filter, mergeContactService) {

        var vm = this;
        vm.saving = false;
        vm.totalCount = 0;
        var lastGroupId = 0;
        var currentGroupId = 0;
        vm.contactsMerged = 0;
        vm.hideMergeButton = false;
        vm.cancel = function () {
            if (vm.importedOpeningBalances)
                $uibModalInstance.close();
            else
                $uibModalInstance.dismiss();
        };

        vm.mergeImportedContacts = function () {
            
            vm.saving = true;
            var foundLines = $filter('filter')(vm.data, {
                groupId: currentGroupId,
            }, true);

            if (foundLines.length < 2) {
                currentGroupId++;

                if (currentGroupId <= lastGroupId)
                    vm.mergeImportedContacts();
                else {
                    vm.saving = false;
                    vm.hideMergeButton = true;
                }

            } else {
                var nameOfContacts = foundLines.map(function (line) {
                    return line.name;
                });
                mergeContactService.mergeContactsByName({ contacts: nameOfContacts })
                    .success(function (result) {
                        currentGroupId++;
                        vm.contactsMerged++;
                        if (currentGroupId <= lastGroupId)
                            vm.mergeImportedContacts();
                        else {
                            vm.saving = false;
                            vm.hideMergeButton = true;
                        }
                    }).error(function (response) {
                        vm.errorContactGroupId = currentGroupId;
                        vm.hideMergeButton = true;
                        vm.saving = false;
                        //abp.message.error(response.error);
                    });
            }

        };

        function init() {
            vm.loading = true;
            mergeContactService.importContactsFromExcel(fileName)
            .success(function (result) {
                vm.data = result;
                vm.totalCount = vm.data.length;
                currentGroupId = vm.data[0].groupId;
                lastGroupId = vm.data[vm.data.length - 1].groupId;
            })
            .error(function (response) {
                abp.message.error(response.error);
            })
            .finally(function () {
                vm.importing = false;
                vm.loading = false;
            });
        }
        init();


    }
    ]);
})();;
(function () {

    appModule.controller('common.views.mergeContacts.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.mergeContact', '$filter', 'FileUploader', 'appSession', 'abp.services.app.directory',
        function ($scope, $uibModal, uiGridConstants, mergeContactService, $filter, fileUploader, appSession, directoryService) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
            vm.mergeContactData = [];
            vm.loading = false;
            //vm.contactCategory = null;

           // vm.importPermission = appSession.tenant.tenancyName.toLowerCase() == 'carleaserentacar';
           // vm.importPermission = true;

            vm.permissions = {
               // merge: abp.auth.hasPermission('Pages.Administration.MergeContacts'),
                merge: true,
            };
            vm.contactCategories = [
                { id: 2, name: 'Company' },
                { id: 1, name: 'Person' },

            ];
            //vm.contactCategory = vm.contactCategory == null ? 2 : vm.contactCategory

            vm.removeRow = function (row) {
                var index = vm.mergeContactData.indexOf(row);
                vm.mergeContactData.splice(index, 1);
            };
            vm.filters = {
                keyword: '',
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                contactCategory: 2
            };

            vm.clearTable = function () {
                vm.mergeContactData = []
            }
            vm.getSelectedContactCategoryName = function () {
                var selectedCategory = vm.contactCategories.find(cat => cat.id === vm.filters.contactCategory);
                return selectedCategory ? selectedCategory.name : '';
            };

            function openCreateOrEditExpenseTypeModal() {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/mergeContacts/searchAddContacts.cshtml',
                    controller: 'common.views.mergeContacts.searchAddContacts as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        contactCategory: function () {
                            return vm.filters.contactCategory;
                        },
                        selectedId: function () {
                        return vm.lead ? vm.lead.company.id : "";
                    },

                    }
                });

                modalInstance.result.then(function (result) {
                    if (result.length > 0) {
                        result.forEach(function (value) {
                            var foundLines = $filter('filter')(vm.mergeContactData, {
                                id: value.id,
                            }, true);
                            if (foundLines.length == 0) {
                                vm.mergeContactData.push(value);
                            }
                        });
                    }
                    //vm.getExpenseTypes();
                });
            }

            vm.searchAddContacts = function () {
                if (vm.mergeContactData.length > 0) {
                    vm.contactCategory = vm.mergeContactData[0].contactCategory;
                }
                openCreateOrEditExpenseTypeModal();
            };

            vm.mergeContacts = function () {
                
                vm.saving = true;
                var listofIds = [];
                listofIds.push({ id: vm.lead.company.id });
                vm.mergeContactData.forEach(function (value) {
                    listofIds.push({ id: value.id });
                });
                mergeContactService.mergeContactsHost({ contacts: listofIds }).success(function () {
                    vm.mergeContactData = [];
                    //vm.contactCategory = null;
                    abp.notify.info(app.localize('SavedSuccessfully'));
                }).finally(function () {
                    vm.saving = false;
                });

            };

            // Import openingBalance Code
            vm.uploader = new fileUploader({
                url: abp.appPath + 'Document/UploadTempFile',
                queueLimit: 1,
                autoUpload: true,
                removeAfterUpload: true,
                filters: [{
                    name: 'filter',
                    fn: function (item, options) {
                        //File type check
                        var type = '|' + item.type.slice(item.type.lastIndexOf('/') + 1) + '|';
                        if ('|vnd.openxmlformats-officedocument.spreadsheetml.sheet|'.indexOf(type) === -1) {
                            abp.message.warn(app.localize('UploadFile_Warn_FileType'));
                            return false;
                        }

                        ////File size check
                        //if (item.size > 5242880 * 5) //5MB
                        //{
                        //    abp.message.warn(app.localize('Document_Warn_SizeLimit'));
                        //    return false;
                        //}

                        return true;
                    }
                }]
            });

            vm.uploader.onSuccessItem = function (fileItem, response, status, headers) {
                vm.importing = true;
                if (response) {
                    var fileName = response.result.fileName;
                    vm.importing = false;
                    openImportMergeContactsModal(fileName);
                }
                else {
                    abp.message.error(response.error.message);
                }
            };
            vm.uploader.onErrorItem = function (response, error, errorMessage) {
                vm.loading = true;
                if (response.isError) {
                    abp.message.error("Error in File Uploading");
                }
            };
            //For Car Rental Changes
            vm.searchContacts = function () {
                if (!vm.filters.keyword) return;
                vm.loading = true;
                return directoryService.searchContactsForMerging(vm.filters)
                    .then(function (response) {
                        vm.data = response.data.items;
                        var result = $filter('filter')(vm.data, true);

                        vm.data.forEach(function (value) {
                            var foundLines = $filter('filter')(vm.mergeContactData, {
                                id: value.id,
                            }, true);
                            if (foundLines.length == 0) {
                                vm.mergeContactData.push(value);
                            }
                        });

                    })
                    .finally(function () {
                        vm.loading = false;
                    });
            };
            vm.searchCompanies = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                return directoryService.search({ keyword: $select.search, contactCategory: vm.filters.contactCategory}).then(function (response) {
                    vm.companies = response.data.items;
                });
            };

            function openImportMergeContactsModal(fileName) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/mergeContacts/importMergeContactsModal.cshtml',
                    controller: 'common.views.mergeContacts.importMergeContactsModal as vm',
                    backdrop: 'static',
                    size: 'xl',
                    resolve: {
                        fileName: function () {
                            return fileName;
                        },

                    }
                });
                modalInstance.result.then(function () {
                    if (appSession.tenant.tenancyName.toLowerCase() != 'carleaserentacar')
                        initCustomerOpeningBalance();
                    vm.importing = false;
                });
            };

        }
    ]);
})();;
(function () {
    appModule.controller('common.views.mergeContacts.searchAddContacts',
        ['$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.directory', 'abp.services.app.tariffGroup', 'uiGridConstants', '$filter', 'contactCategory', 'selectedId', 'abp.services.app.person',
            function ($scope, $uibModal, $uibModalInstance, directoryService, tariffGroupService, uiGridConstants, $filter, contactCategory, selectedId, personService) {

                var vm = this;
                vm.data = [];
                vm.contactCategory = contactCategory;
                vm.selectedId = selectedId;
                vm.filters = {
                    keyword: '',
                    skipCount: 0,
                    maxResultCount: app.consts.grid.defaultPageSize,
                    contactCategory: contactCategory 
                };

                vm.contactCategories = [
                    { id: 2, name: 'Company' },
                    { id: 1, name: 'Person' },

                ];
                vm.searchContacts = function () {
                    if (!vm.filters.keyword) return;
                    vm.loading = true;
                    return directoryService.searchContactsForMerging(vm.filters)
                        .then(function (response) {
                            if (selectedId != "") {
                                vm.data = response.data.items.filter(function (item) {
                                    return item.id !== selectedId;
                                });
                            } else {
                                vm.data = response.data.items;
                            }
                        })
                        .finally(function () {
                            vm.loading = false;
                        });
                };

                vm.cancel = function () {
                    $uibModalInstance.dismiss();
                };
                vm.save = function () {
                    if (vm.data.length == 0) return;
                    var foundLines = $filter('filter')(vm.data, {
                        selected: true,
                    }, true);
                    $uibModalInstance.close(foundLines);
                };

            }]);
})();;
