(function () {
    appModule.controller('host.views.regions.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.directory', 'abp.services.app.regions',
        function ($scope, $uibModal, uiGridConstants, directoryService, regionsAppService) {
            var vm = this;
            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
            vm.permissions = {
                create: abp.auth.hasPermission('Pages.CarRental.Dashboard.CreateCompany'),
                edit: abp.auth.hasPermission('Pages.CarRental.Dashboard.EditCompany'),
                delete: abp.auth.hasPermission('Pages.CarRental.Dashboard.DeleteCompany'),
            };
            var requestParams = {
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                sorting: "name asc"
            };
            vm.tenantGridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                enableColumnResizing: true,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                useExternalSorting: true,
                appScopeProvider: vm,
                rowTemplate: '<div ng-repeat="(colRenderIndex, col) in colContainer.renderedColumns track by col.colDef.name" class="ui-grid-cell" ng-class="{ \'ui-grid-row-header-cell\': col.isRowHeader}"  ui-grid-cell></div>',
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: 115,
                        enableColumnResizing: false,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.edit" ng-click="grid.appScope.editRegion(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.delete" ng-click="grid.appScope.DeleteRegion(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Name'),
                        width: 400,
                        field: 'name'
                    },
                    {
                        name: app.localize('Countries'),
                        width: 400,
                        field: 'countries'
                    },
                    {
                        name: app.localize('SalesStaff'),
                        width: 400,
                        field: 'salesStaff'
                    }
                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            requestParams.sorting = null;
                            console.log(sortColumns);
                        } else {
                            requestParams.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                            console.log("Else Condition Sort :" + sortColumns[0].field + "Direction  :" + sortColumns[0].sort.direction + "Sort Length :" + sortColumns[0].length);
                            console.log("Sorting params :" + requestParams.sorting);
                        }
                        vm.getRegion();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        requestParams.skipCount = (pageNumber - 1) * pageSize;
                        requestParams.maxResultCount = pageSize;
                        if (vm.filters != null) {
                            vm.searchItems(requestParams.skipCount, requestParams.maxResultCount);
                        }
                    });
                },
                data: []
            };
            vm.searchButtonCLick = function () {
                requestParams.skipCount = 0;
                requestParams.maxResultCount = 10;
                vm.tenantGridOptions.paginationCurrentPage = 1;
                vm.tenantGridOptions.paginationPageSize = 10;
                vm.searchItems();
            }
            vm.searchItems = function () {
                vm.loading = true;
                if (vm.filters == null) {
                    vm.filters = { isFeatured: false };
                }
                if (requestParams.sorting == null || requestParams.sorting == []) {
                    requestParams.sorting = "name asc"
                }
                regionsAppService.searchRegions({
                    Name: vm.filters.name, Countries: vm.filters.countries, SalesStaff: vm.filters.salesStaff, skipCount: requestParams.skipCount, maxResultCount: requestParams.maxResultCount, sorting: requestParams.sorting
                })
                    .then(function (data) {
                        if (data.data != null) {
                            vm.tenantGridOptions.totalItems = data.data.totalCount;
                            let allData = data.data.items;
                            let modifiedData = [];
                            for (let i = 0; i < allData.length; i++) {
                                modifiedData.push(allData[i]);
                            }
                            vm.tenantGridOptions.data = modifiedData;
                        }
                        else {
                            vm.tenantGridOptions.data = [];
                        }

                    }).finally(function () {
                        vm.loading = false;
                    });
            };
            vm.getRegion = function () {
                vm.loading = true;
                if (requestParams.sorting == null || requestParams.sorting == []) {
                    requestParams.sorting = "name asc"
                }
                vm.tenantGridOptions.data = [];
                regionsAppService.searchRegions({ skipCount: requestParams.skipCount, maxResultCount: requestParams.maxResultCount, sorting: requestParams.sorting }).then(function (data) {
                    vm.tenantGridOptions.totalItems = data.data.totalCount;
                    let allData = data.data.items;
                    let modifiedData = [];
                    for (let i = 0; i < allData.length; i++) {
                        modifiedData.push(allData[i]);
                    }
                    vm.tenantGridOptions.data = modifiedData;
                }).finally(function () {
                    vm.loading = false;
                }).catch(function (err) {
                    console.log(err);
                });
            };
            vm.addRegion = function (region) {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/regions/createOrEditModal.cshtml',
                    controller: 'host.views.regions.createOrEditModal as vm',
                    backdrop: 'static',
                    resolve: {
                        regionId: function () {
                            return null;
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getRegion();
                });
            };
            vm.editRegion = function (region) {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/regions/createOrEditModal.cshtml',
                    controller: 'host.views.regions.createOrEditModal as vm',
                    backdrop: 'static',
                    resolve: {
                        regionId: function () {
                            return region.id;
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getRegion();
                });
            };
            vm.DeleteRegion = function (region) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', ''),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            vm.loading = true;
                            regionsAppService.deleteRegion(region.id)
                                .then(function (data) {
                                    if (data.data[0].speedId) {
                                        directoryService.updatePublishedEntity(data.data[0].speedId, "".toString())
                                        abp.notify.info(app.localize('RecordDeleted.'));
                                    }
                                }).finally(function () {
                                    vm.loading = false;
                                    vm.getRegion();
                                });
                        }
                    }
                );
            };
            function init() {
                vm.getRegion();
            }
            init();
        }
    ]);
})();;
(function () {
    appModule.controller('host.views.reports.crs.index', [
        '$scope', '$uibModal','utilities', 'abp.services.app.currency', 'abp.services.app.businessDivision', 'abp.services.app.tenant', 'abp.services.app.customizationHost',
        function ($scope, $uibModal, utilities, currencyService, businessDivisionService, tenantAppService, customizationService) {
            var vm = this;


            vm.loading = false;
            vm.report = [];
            vm.dateRangeModel = {};

            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));

            vm.applyFilter = function () {
                vm.filters.pendingInvoice = false;
                vm.filters.deliveredPendingInvoice = false;

                if (vm.filters.invoiceFilter === "PendingInvoice") {
                    vm.filters.pendingInvoice = true;
                } else if (vm.filters.invoiceFilter === "DeliveredPendingInvoice") {
                    vm.filters.deliveredPendingInvoice = true;
                }
            }

            vm.filters = {
                fromDate: null,
                toDate: null,
                enableDateRange: true
            };

            vm.getStatus = function (id) {
                if (id == 1)
                    return app.localize("New");
                else if (id == 2)
                    return app.localize("Closed");
                else if (id == 3)
                    return app.localize("Cancelled");
                else if (id == 4)
                    return app.localize("OnHold");
                else if (id == 5)
                    return "Estimation Pending";
                else if (id == 6)
                    return "Estimated, Customer Confirmation Pending";
                else if (id == 7)
                    return "Customer Confirmed, Finance Approval Pending";
                else if (id == 8)
                    return "Finance Approved";
                else if (id == 9)
                    return "In-Progress";
                else if (id == 10)
                    return "Scope Sent";
                else if (id == 11)
                    return "Scope Approved";
                else if (id == 12)
                    return "Quotation Sent";
                else if (id == 13)
                    return "Quotation Approved";
                else if (id == 14)
                    return "On Approval";
                else if (id == 15)
                    return "Delivered";
                else return '';
            };
            vm.getInvoiced = function (row) {
                row.invoicedAmount = 0;
                row.milestones.forEach(x => {
                    if (x.invoiceStatus == 2)
                        row.invoicedAmount += x.amount;
                });
                return row.invoicedAmount.toFixed(2);
            }


            vm.getbusinessDivisions = function () {
                vm.loading = true;
                businessDivisionService.getBusinessDivisions().success(function (data) {
                    vm.businessDivisions = data.items
                }).finally(function () {
                    vm.loading = false;
                });
            }
            vm.dateRangeCheck = function () {

                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                else {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
            };

            vm.dateRangeModelChange = function () {
                vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };
           


            
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getlocalDateTime = function (date) {

                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('DD-MMM-YY');
                }
                else {
                    return "";
                }
            };

            
           
            vm.searchTenants = function ($select) {
                if ($select.search == "")
                    return null;
                tenantAppService.searchTenants({ filter: $select.search }).then(function (response) {
                    vm.tenants = response.data.items;
                });
            };
            setTimeout(function () {
                var startDateModel = moment().add(-29, 'days').startOf('day');
                var endDateModel = moment().endOf('day')
                vm.dateRangeModel = {
                    startDate: startDateModel,
                    endDate: endDateModel
                };
            }, 200);

            vm.crsReport = function () {
                vm.loading = true;
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                else {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
                customizationService.getCRsReport(vm.filters).success(function (result) {
                    vm.report = result;
                    var groupedData = vm.report.reduce(function (acc, report) {
                        if (report.customCurrency != null) {

                            var currencyCode = report.customCurrency.code;
                            if (!acc[currencyCode]) {
                                acc[currencyCode] = { currencyCode: currencyCode, totalAmount: 0, invoicedAmount: 0, unInvoicedAmount: 0 };
                            }
                            acc[currencyCode].totalAmount += ((vm.convertCurrency(report) * report.vatPercent / 100) + vm.convertCurrency(report));
                            report.milestones.forEach(x => {
                                if (x.invoiceStatus == 1) {

                                    acc[currencyCode].unInvoicedAmount += x.amount;
                                }
                                else if (x.invoiceStatus == 2) {
                                    acc[currencyCode].invoicedAmount += x.amount;

                                }
                            });
                            return acc;
                        }
                        return acc;
                    }, {});

                    vm.groupAmount = Object.values(groupedData);
                    vm.loading = false;

                });
            }
            vm.UpdateChangeRequest = function (id) {
                openCreateOrUpdateHostChangeRequestModal(id);
            };
            function openCreateOrUpdateHostChangeRequestModal(id) {

                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/customization/createOrUpdateChangeRequestModal.cshtml',
                    controller: 'host.views.customization.createOrUpdateChangeRequestModal as vm',
                    backdrop: 'static',
                    size: 'xl',
                    resolve: {
                        changeRequestId: function () {
                            return id;
                        },
                        project: function () {
                            return null;
                        },
                        tasksToMove: function () {
                            return null;
                        },
                        isCRFromProjectDashboard: function () {
                            return false;
                        },
                        isCRFromNewPoints: function () {
                            return false;
                        },
                        isGapFromScope: function () {
                            return false;
                        },
                        gapTaskFromScope: function () {
                            return null;
                        },
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.crsReport();
                });
            }
            
            vm.convertCurrency = function (row) {
                if (row.customCurrencyId > 0)
                    return (row.cost * vm.currencies.find(obj => obj.id === row.customCurrencyId).currencyToBaseRate) - row.discount;
                else
                    return 0;
            };
            vm.getCurrencies = function () {
                vm.loading = true;
                currencyService.getCurrencies().success(function (data) {
                    vm.currencies = data.items;

                }).finally(function () {
                    vm.loading = false;
                });
            }
            vm.getCurrencies();
            vm.getbusinessDivisions();
            //vm.crsReport();
        }
    ]);
})();;

appModule.controller('host.views.reports.debtCases.addLogModal', [
    '$scope', '$uibModalInstance', '$uibModal','caseObj', 'abp.services.app.case', 'abp.services.app.user',
    function ($scope, $uibModalInstance, $uibModal, caseObj, caseService, userService) {
        var vm = this;
        vm.case = angular.copy(caseObj);
        vm.filters = {};
        vm.documents = [];

        vm.searchAssignedUsers = function ($select) {
            if (!$select.search)
                return null;
            userService.searchAssignedToUsers({ keyword: $select.search }).then(function (response) {
                vm.assignedToUserNames = response.data.items;
            });
        };
        vm.getOriginalName = function (doc) {
            var originalName = doc.name.replace("_" + doc.guid, "");
            return originalName;
        };
        vm.uploadDocument = function () {
            var modalInstance = $uibModal.open({
                templateUrl: '~/App/host/views/reports/debtCases/uploadDocumentsModal.cshtml',
                controller: 'host.views.reports.debtCases.uploadDocumentsModal as vm',
                backdrop: 'static',
                resolve: {
                    tenantId: function () {
                        return 0;
                    }
                }

            });
            modalInstance.result.then(function (result) {
                vm.documents.push(result);

            });
        };

        vm.save = function () {
            caseService.saveCaseLog({
                caseId: caseObj.id,
                detail: vm.case.detail,
                assignedToUserId: vm.case.assignedToUserId,
                dueDate: vm.case.dueDate,
                documents: vm.documents
            }).success(function () {
                $uibModalInstance.close();
            });
        };

        vm.cancel = function () {
            $uibModalInstance.dismiss();
        };
    }
]);
;
(function () {
    appModule.controller('host.views.reports.debtCases.caseDetailLogModal', [
        '$scope', '$uibModalInstance', 'abp.services.app.case', 'caseObj', '$uibModal',
        function ($scope, $uibModalInstance, caseService, caseObj , $uibModal) {

            var vm = this;
            vm.saving = false;
            vm.case = caseObj;
            vm.documents = [];

            vm.getStatus = function (status) {
                if (!status)
                    return '';
                if (status == 1)
                    return 'Open';
                if (status == 2)
                    return 'Closed';
                /*if (status == 3)
                    return 'On Hold';
                if (status == 4)
                    return 'Cancelled';*/
            };

            vm.cancel = function () {
                $uibModalInstance.close();;
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM-DD HH:mm');
                }
                else {
                    return "";
                }
            };

            vm.getOriginalName = function (doc) {
                var originalName = doc.name.replace("_" + doc.guid, "");
                return originalName;
            };


            vm.openLogDocumentsModal = function (row) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/reports/debtCases/showLogDocumentsModal.cshtml',
                    controller: 'host.views.reports.debtCases.showLogDocumentsModal as vm',
                    backdrop: 'static',
                    resolve: {
                        caseLog: function () {
                            return row;
                        }
                    }
                });
            };

            vm.addLogs = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/reports/debtCases/addLogModal.cshtml',
                    controller: 'host.views.reports.debtCases.addLogModal as vm',
                    backdrop: 'static',
                    resolve: {
                        caseObj: function () {
                            return vm.case;
                        }
                    }
                });

                modalInstance.result.then(function () {
                    vm.getCaseLogs();
                });
            };

            vm.save = function () {
                vm.loading = true;
                caseService.saveCaseLog({
                    caseId: caseObj.id,
                    detail: vm.case.detail,
                    assignedToUserId: vm.case.assignedToUser,
                    dueDate: vm.case.dueDate,
                    documents: vm.case.documents
                }).success(function (data) {
                    vm.getCaseLogs();
                    vm.case.detail = "";
                    assignedToUserId: vm.case.assignedToUserId;
                    dueDate: vm.case.dueDate;
                    vm.documents = [];
                }).finally(function () {
                    vm.loading = false;
                });
            }

            vm.getCaseLogs = function () {
                vm.loading = true;
                caseService.getCaseLogs({
                    id: caseObj.id
                }).success(function (data) {
                    vm.case.logs = data;

                }).finally(function () {
                    vm.loading = false;
                });
            }

            vm.getCaseLogs();
        }
    ]);
})();;
