(function () {
    appModule.controller('host.views.reports.sales.createOrEditSaleModal', [
        '$scope', 'utilities', '$uibModal', '$uibModalInstance', 'saleId', 'abp.services.app.businessDivision', 'abp.services.app.hostProduct', 'abp.services.app.productVariant', 'abp.services.app.productModule', 'abp.services.app.packages', 'abp.services.app.user', 'abp.services.app.directory', 'abp.services.app.salesHost',
        function ($scope, utilities, $uibModal, $uibModalInstance, saleId, businessDivisionService, productService, productVariantService, productModuleService, packagesAppService, userService, directoryService, salesService) {

            var vm = this;
            vm.loading = false;
            vm.saving = false;

            vm.saleId = saleId;

            // Subscription variables

            vm.subscription = {
                type: 2,
                subscriptionPackages: [],
               
            };

            vm.products = [];
            vm.subscriptionsTypes = [
                { id: 2, name: "Monthly" },
                { id: 1, name: "Yearly" },
                { id: 3, name: "Quarterly" },
                //{ id: 4, name: "6 Monthly" }
            ];

            // Scope variable 

            vm.documents = [];
            vm.selectedProductVariants = [];
            vm.groupedVariants = {};
            vm.customModules = [];
            vm.gapPoints = [];
            vm.totalEstimatedHours = null;
            vm.multilineStringToHTMLWordBreak = (s) => utilities.multilineStringToHTMLWordBreak(s);

            // Milestone

            vm.milestones = [];


            vm.searchUsers = function ($select) {
                if ($select.search == "")
                    return null;
                userService.searchUsers({ keyword: $select.search }).then(function (response) {
                    vm.users = response.data.items;
                });
            };

            vm.searchCompanies = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                return directoryService.search({ keyword: $select.search, contactType: 2, contactCategory: 2 }).then(function (response) {
                    vm.companies = response.data.items;
                });
            };

            vm.clearCompany = function () {
                vm.filters.companyId = null;
                vm.filters.company = null;
            };

            // Product variant for subscription 

            vm.getProducts = function () {
                productService.getProductsForVariants({}).then(function (response) {
                    vm.products = [];
                    vm.products = response.data;
                }).finally(function () {
                });
            };

            vm.filterRowProductId = function (productId, row) {
                row.seletedProductId = productId;
                vm.loading = true;
                productVariantService.getProductVariants({ id: productId }).success(function (result) {
                    row.productVariants = [];
                    row.productVariants = result;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.filterRowVariantId = function (variantId, row) {
                row.packages = [];
                row.seletedVariantId = variantId;
                vm.loading = true;
                packagesAppService.getPackages({ ProductId: row.seletedProductId, ProductVariantId: row.seletedVariantId, sorting: "title asc" }).success(function (result) {
                    row.packages = result.items.filter(obj => obj.currencyId === vm.currencyId);
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.addRow = function () {
                vm.subscription.subscriptionPackages.push(
                    {
                        oneTimeCharges: 0,
                        subscriptionCharges: 0,
                        packageId: null,
                        package: { productId: 0, variantId: 0 }
                    });
                vm.getCharges();
            };

            vm.removeSubscriptionPackageRow = function (row) {
                var index = vm.subscription.subscriptionPackages.indexOf(row);
                vm.subscription.subscriptionPackages.splice(index, 1);
                vm.getCharges();
            };

            vm.getCharges = function () {
                vm.totalOTC = 0;
                vm.totalSubscriptionCharges = 0;
                vm.subscription.subscriptionPackages.forEach(x => {
                    vm.totalOTC += x.oneTimeCharges;
                    vm.totalSubscriptionCharges += x.subscriptionCharges;
                });
                vm.subscription.amount = vm.totalSubscriptionCharges;
                vm.subscription.SetupCharges = vm.totalOTC;
            };

            vm.adjustCharges = function (row) {
                if (row) {
                    var package = row.packages.filter(obj => obj.id === row.packageId)[0];
                    if (!package) return;

                    row.oneTimeCharges = package.oneTimeCharges;

                    if (vm.subscription.type == 1) {
                        row.subscriptionCharges = package.rate * 12;
                    }
                    else if (vm.subscription.type == 2) {
                        row.subscriptionCharges = package.rate;
                    }
                    else if (vm.subscription.type == 3) {
                        row.subscriptionCharges = package.rate * 3;
                    }
                    /*else if (vm.sale.type == 4) {
                        row.saleCharges = package.rate * 6;
                    }*/
                }
                else {
                    angular.forEach(vm.subscription.subscriptionPackages, function (r) {
                        vm.adjustCharges(r);
                    });
                }

                vm.getCharges();
                vm.calculateAmountVat();
            };


            vm.calculateAmountVat = function () {
                //debugger
                if (vm.subscription.amount !== "" && vm.subscription.vatPercent !== "" && vm.subscription.amount !== undefined && vm.subscription.vatPercent !== undefined) {
                    var amount = parseFloat(vm.subscription.amount);
                    var vatPercent = parseFloat(vm.subscription.vatPercent);
                    vm.subscription.amountVat = amount + (amount * vatPercent / 100);
                } else {
                    vm.subscription.amountVat = 0;
                }
            };

            // Product variant for subscription end



            // Scope start

            // Document of Scope

            vm.uploadDocument = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/cbs/projects/uploadDocumentsModal.cshtml',
                    controller: 'host.views.cbs.projects.uploadDocumentsModal as vm',
                    backdrop: 'static',
                    resolve: {
                        tenantId: function () {
                            return 0;
                        }
                    }

                });
                modalInstance.result.then(function (result) {
                    result.isNew = true;
                    result.isDeleted = false;
                    vm.documents.push(result);
                });
            };

            vm.getOriginalName = function (doc) {
                return doc.name.replace("_" + doc.guid, "");
            };

            vm.removeDocument = function (document) {
                if (document.id) {
                    document.isDeleted = true;
                }
                else {
                    var index = vm.documents.indexOf(document);
                    if (index > -1) {
                        vm.documents.splice(index, 1);
                    }
                }
            };

            // Standard Module

            vm.openAddProductModal = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/cbs/projects/addProductModal.cshtml',
                    controller: 'host.views.cbs.projects.addProductModal as vm',
                    backdrop: 'static',
                });

                modalInstance.result.then(function (item) {
                    if (item) {
                        vm.onVariantSelectedFromPopup(item.product, item.variant);
                    }
                });
            };

            vm.onVariantSelectedFromPopup = function (product, variant) {
                if (!product) return;

                productModuleService.getModulesForProduct({
                    ProductId: product.id,
                    VariantId: variant ? variant.id : null
                }).then(function (response) {
                    const modules = response.data.map(function (module) {
                        module.checked = module.category === 1;
                        return module;
                    });

                    const item = {
                        productId: product.id,
                        productName: product.name,
                        productCode: product.code,
                        variantId: variant ? variant.id : null,
                        variantName: variant ? variant.name : '',
                        modules: modules,
                        showModules: false
                    };

                    var exists = vm.selectedProductVariants.some(function (p) {
                        return p.productId === product.id && p.variantId === (variant ? variant.id : null);
                    });

                    if (exists) {
                        abp.message.warn("This product-variant is already added.");
                        return;
                    }

                    vm.selectedProductVariants.push(item);

                    if (!vm.groupedVariants[product.code]) {
                        vm.groupedVariants[product.code] = {
                            productName: product.name,
                            variants: [],
                            showVariants: true
                        };
                    }

                    vm.groupedVariants[product.code].variants.push(item);
                });
            };

            vm.getModuleCategory = function (category) {
                return category === 2 ? 'Add On' : '';
            };

            vm.removeProductVariant = function (item) {
                var index = vm.selectedProductVariants.indexOf(item);
                if (index > -1) {
                    vm.selectedProductVariants.splice(index, 1);
                }
            };

            // custom modules

            vm.addCustomModuleRow = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/cbs/projects/addCustomModuleModal.cshtml',
                    controller: 'host.views.cbs.projects.addCustomModuleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        isFromCustomModule: true,
                        esistingGapPoint: function () {
                            return null;
                        },
                        existingModule: function () {
                            return null;
                        },
                        isEdit: false
                    }
                });

                modalInstance.result.then(function (result) {
                    if (result) {
                        vm.customModules.push({
                            name: result.name,
                            detail: result.detail
                        });
                    }
                });
            };

            vm.editCustomModuleRow = function (module) {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/cbs/projects/addCustomModuleModal.cshtml',
                    controller: 'host.views.cbs.projects.addCustomModuleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        isFromCustomModule: true,
                        esistingGapPoint: function () {
                            return null;
                        },
                        existingModule: function () {
                            return angular.copy(module);
                        },
                        isEdit: true
                    }
                });

                modalInstance.result.then(function (result) {
                    if (result) {
                        angular.extend(module, result);
                    }
                });
            };

            vm.removeCustomModuleRow = function (row) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            var idx = vm.customModules.indexOf(row);
                            if (idx !== -1) {
                                vm.customModules.splice(idx, 1);
                            }
                            $scope.$applyAsync();
                        }
                    }
                );
            };

            // GAP POINT


            vm.addGapPointModal = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/cbs/projects/addCustomModuleModal.cshtml',
                    controller: 'host.views.cbs.projects.addCustomModuleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        isFromCustomModule: false,
                        esistingGapPoint: function () {
                            return null;
                        },
                        existingModule: function () {
                            return null;
                        },
                        isEdit: false
                    }
                });

                modalInstance.result.then(function (result) {
                    if (result) {
                        vm.gapPoints.push({
                            description: result.description || '',
                            scope: result.scope || '',
                            estimatedHours: parseFloat(result.estimatedHours || 0),
                        });
                        vm.calculateHours();
                    }
                });
            };

            vm.editGapPoint = function (row) {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/cbs/projects/addCustomModuleModal.cshtml',
                    controller: 'host.views.cbs.projects.addCustomModuleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        isFromCustomModule: false,
                        esistingGapPoint: function () {
                            return angular.copy(row);
                        },
                        existingModule: function () {
                            return null;
                        },
                        isEdit: true
                    }
                });
                modalInstance.result.then(function (result) {
                    if (result) {
                        angular.extend(row, result);
                        vm.calculateHours();
                    }
                });
            };

            vm.removeGapPoint = function (row) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            $scope.$applyAsync(function () {
                                var index = vm.gapPoints.indexOf(row);
                                if (index > -1) {
                                    vm.gapPoints.splice(index, 1);
                                }
                                vm.calculateHours();
                            });
                        }
                    }
                );
            };

            vm.importGapPointData = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '/App/host/views/customization/importCustomizationTaskModal.cshtml',
                    controller: 'host.views.customization.importCustomizationTaskModal as vm',
                    backdrop: 'static',
                    resolve: {}
                });

                modalInstance.result.then(function (excelData) {
                    if (excelData && excelData.length > 0) {
                        excelData.forEach(function (item) {
                            vm.gapPoints.push({
                                description: item.description || '',
                                scope: item.scope || '',
                                estimatedHours: parseFloat(item.estimatedHours || 0),
                            });
                        });
                        vm.calculateHours();
                    }
                });
            };

            vm.calculateHours = function () {
                vm.totalHours = 0.0;
                vm.gapPoints.forEach(function (item) {
                    if (item.estimatedHours !== undefined) {
                        vm.totalHours += item.estimatedHours;
                    }
                });
                vm.gapPoints.totalEstimatedHours = vm.totalHours;
            };

            // Scope End




            // Milestone

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('DD-MMM-YY');
                }
                else {
                    return "";
                }
            };

            vm.createMilestone = function () {
                openCreateOrEditMilestoneModal(null, false);
            };

            vm.editMilestone = function (row) {
                openCreateOrEditMilestoneModal(row, true);
            };


            function openCreateOrEditMilestoneModal(existingMilestone, isEdit) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/reports/sales/createOrEditMilestoneModal.cshtml',
                    controller: 'host.views.reports.sales.createOrEditMilestoneModal as vm',
                    backdrop: 'static',
                    resolve: {
                        milestone: function () {
                            return angular.copy(existingMilestone || {});
                        },
                        isEdit: function () {
                            return isEdit;
                        }
                    }
                });

                modalInstance.result.then(function (milestoneData) {
                    if (isEdit) {
                        var idx = vm.milestones.indexOf(existingMilestone);
                        if (idx !== -1) {
                            vm.milestones[idx] = milestoneData;
                        }
                    } else {
                        vm.milestones.push(milestoneData);
                    }
                });
            }
           
            vm.deleteMilestone = function (row) {
                abp.message.confirm(
                    app.localize('YesDelete'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            var idx = vm.milestones.indexOf(row);
                            if (idx !== -1) {
                                vm.milestones.splice(idx, 1);
                            }
                            $scope.$applyAsync();
                        }
                    }
                );
            };

            // Get functions 

            vm.getbusinessDivisions = function () {
                businessDivisionService.getBusinessDivisionsWithCurrency().success(function (data) {
                    vm.businessDivisions = data.items;
                    if (vm.sale && vm.sale.businessDivisionId) {
                        setBusinessDivision();
                    }
                });
            };
            function setBusinessDivision() {
                var selected = vm.businessDivisions.find(function (b) {
                    return b.id === vm.sale.businessDivisionId;
                });
                if (selected) {
                    vm.sale.businessDivision = selected;
                    vm.currencyId = vm.sale.businessDivision.currencyId;
                }
            }

            vm.getSaleById = function () {
                vm.loading = true;


                salesService.getSaleById({ id: saleId }).success(function (result) {
                    vm.sale = result.sale;

                    vm.scope = result.scope ? JSON.parse(result.scope) : {};
                    vm.documents = (result.documents || []).map(function (doc) {
                        doc.isNew = false;
                        doc.isDeleted = false;
                        return doc;
                    });
                    vm.detail = result.detail ? JSON.parse(result.detail) : {};

                    vm.selectedProductVariants = vm.scope.selectedProductVariants || [];
                    vm.customModules = vm.scope.customModules || [];
                    vm.gapPoints = vm.scope.gapPoints || [];

                    vm.milestones = vm.detail.milestones || [];
                    vm.subscription = vm.detail.subscription || {};

                    if (vm.businessDivisions && vm.businessDivisions.length > 0) {
                        setBusinessDivision();
                    }

                }).finally(function () {
                    vm.getCharges();
                    vm.calculateHours();
                    vm.loading = false;
                });
            };
            

            vm.save = function () {
                vm.saving = true;

                const requestData = {
                    id: vm.sale ? vm.sale.id : 0,
                    documents: vm.documents,
                    scope: JSON.stringify({
                        selectedProductVariants: vm.selectedProductVariants,
                        customModules: vm.customModules,
                        gapPoints: vm.gapPoints,
                    }),
                    salesPersons: vm.sale.salesPersons,
                    businessDivisionId: vm.sale.businessDivisionId,
                    detail: JSON.stringify({
                        milestones: vm.milestones,
                        subscription: vm.subscription,
                    }),
                    companyId: vm.sale.companyId,
                    notes: vm.sale.notes,
                    saleDate: vm.sale.saleDate,
                };

                salesService.createOrUpdateSale(requestData)
                    .success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    })
                    .finally(function () {
                        vm.saving = false;
                    });
            }


            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.getProducts();
                if (saleId != null) {
                    vm.getSaleById();
                }
                vm.getbusinessDivisions();
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('host.views.reports.sales.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.salesHost', 'abp.services.app.directory', 'abp.services.app.businessDivision',
        function ($scope, $uibModal, uiGridConstants, salesService, directoryService, businessDivisionService) {

            var vm = this;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.permissions = {
                addSale: abp.auth.hasPermission('Pages.Tenants.HostReports.Sales.AddNew'),
                editSale: abp.auth.hasPermission('Pages.Tenants.HostReports.Sales.Edit'),
                deleteSale: abp.auth.hasPermission('Pages.Tenants.HostReports.Sales.Delete'),
                viewSale: abp.auth.hasPermission('Pages.Tenants.HostReports.Sales.View'),
            };

            vm.filters = {
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                businessDivisionId: null,
                companyId: null,
                creatorUserId: null,
                enableCreationDateRange: false,
                enableSaleDateRange: false,
                creationFromDate: null,
                creationToDate: null,
                saleFromDate: null,
                saleToDate: null
            };


            function initDate() {
                vm.dateRangeModel = {
                    startDate: moment(moment().format('YYYY-MM-DD')).utc(),
                    endDate: moment(moment().format('YYYY-MM-DD')).utc()
                    //endDate: moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc()
                };
            }

            vm.creationDateRangeChanged = function () {
                vm.filters.creationFromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().startOf('day');
                vm.filters.creationToDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            vm.saleDateRangeChanged = function () {
                vm.filters.saleFromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().startOf('day');
                vm.filters.saleToDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            vm.creationDateRangeCheck = function () {
                if (vm.filters.enableCreationDateRange) {
                    vm.filters.creationFromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().startOf('day');
                    vm.filters.creationToDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
                } else {
                    vm.filters.creationFromDate = null;
                    vm.filters.creationToDate = null;
                }
            };

            vm.saleDateRangeCheck = function () {
                if (vm.filters.enableSaleDateRange) {
                    vm.filters.saleFromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().startOf('day');
                    vm.filters.saleToDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
                } else {
                    vm.filters.saleFromDate = null;
                    vm.filters.saleToDate = null;
                }
            };

            vm.getbusinessDivisions = function () {
                vm.loading = true;
                businessDivisionService.getBusinessDivisions().success(function (data) {
                    vm.businessDivisions = data.items
                }).finally(function () {
                    vm.loading = false;
                });
            }

            vm.searchCompanies = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                return directoryService.search({ keyword: $select.search, contactType: 2, contactCategory: 2 }).then(function (response) {
                    vm.companies = response.data.items;
                });
            };

            vm.clearCompany = function () {
                vm.filters.companyId = null;
                vm.filters.company = null;
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {

                    return date.replace('Z', '');

                }
                else {
                    return "";
                }
            };

            vm.createSale = function () {
                openCreateOrEditSaleModal(null);
            };

            vm.viewSale = function (sale) {
                openViewSaleModal(sale.id);
            };

            vm.editSale = function (sale) {
                openCreateOrEditSaleModal(sale.id);
            };

            function openCreateOrEditSaleModal(saleId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/reports/sales/createOrEditSaleModal.cshtml',
                    controller: 'host.views.reports.sales.createOrEditSaleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        saleId: function () {
                            return saleId;
                        }
                    },
                    size: 'xl',

                });
                modalInstance.result.then(function (result) {
                    vm.getSales();
                })
            };

            function openViewSaleModal(saleId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/host/views/reports/sales/viewSaleModal.cshtml',
                    controller: 'host.views.reports.sales.viewSaleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        saleId: function () {
                            return saleId;
                        }
                    },
                    size: 'xl',

                });
                /*modalInstance.result.then(function (result) {
                    vm.getSales();
                })*/
            };

            vm.deleteSale = function (row) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            salesService.deleteSale({
                                id: row.id
                            }).success(function () {
                                vm.getSales();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };

            vm.getSales = function () {
                vm.loading = true;
                if (vm.filters.enableCreationDateRange) {
                    vm.filters.creationFromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().startOf('day');
                    vm.filters.creationToDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
                }
                if (vm.filters.enableSaleDateRange) {
                    vm.filters.saleFromDate == vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().startOf('day');
                    vm.filters.saleToDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
                }
                if (!vm.filters.enableCreationDateRange) {
                    vm.filters.creationFromDate = null;
                    vm.filters.creationToDate = null;
                }
                if (!vm.filters.enableSaleDateRange) {
                    vm.filters.saleFromDate = null;
                    vm.filters.saleToDate = null;
                }
                salesService.getSales(vm.filters ).success(function (data) {
                    vm.gridOptions.totalItems = data.totalCount;
                    vm.gridOptions.data = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize(' '),
                        enableSorting: false,
                        width: 60,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.viewSale" ng-click="grid.appScope.viewSale(row.entity)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.editSale" ng-click="grid.appScope.editSale(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.deleteSale" ng-click="grid.appScope.deleteSale(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: 'Sale Date',
                        field: 'saleDate',
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <span>{{grid.appScope.getlocalDateTime(row.entity.saleDate) | date:"dd-MMM-yy"}}</span>' +
                            '</div>',
                    },
                    {
                        name: 'Division',
                        field: 'businessDivision.name',
                    },
                    {
                        name: 'Company',
                        field: 'company.companyName',
                    },
                    {
                        name: 'Created By',
                        field: 'creatorUserName',
                    },
                    {
                        name: 'Creation Date',
                        field: 'creationDate',
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <span>{{grid.appScope.getlocalDateTime(row.entity.creationDate) | date:"dd-MMM-yy"}}</span>' +
                            '</div>',
                    },
                   
                      
                ],

                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = null;
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }

                        vm.getSales();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getSales();
                    });
                },


                data: []
            };

            function init() {
                initDate();
                vm.getSales();
                vm.getbusinessDivisions();
            }
            init();
        }
    ]);
})();;
(function () {
    appModule.controller('host.views.reports.sales.viewSaleModal', [
        '$scope', 'utilities', '$uibModalInstance', 'saleId', 'abp.services.app.hostProduct', 'abp.services.app.salesHost',
        function ($scope, utilities, $uibModalInstance, saleId, productService, salesService) {

            var vm = this;
            vm.loading = false;

            vm.saleId = saleId;

            vm.products = [];
            vm.getSubscriptionType = function(type){
                if(type == 1)
                {
                    return "Yearly";
                }
                if (type == 2)
                {
                    return "Monthly";
                }
                if (type == 3)
                {
                    return "Quarterly";
                }
            };

            vm.documents = [];
            vm.selectedProductVariants = [];
            vm.groupedVariants = {};
            vm.customModules = [];
            vm.gapPoints = [];
            vm.totalEstimatedHours = null;
            vm.multilineStringToHTMLWordBreak = (s) => utilities.multilineStringToHTMLWordBreak(s);
            vm.milestones = [];


            vm.getProducts = function () {
                productService.getProductsForVariants({}).then(function (response) {
                    vm.products = [];
                    vm.products = response.data;
                });
            };

            vm.getCharges = function () {
                vm.totalOTC = 0;
                vm.totalSubscriptionCharges = 0;
                vm.subscription.subscriptionPackages.forEach(x => {
                    vm.totalOTC += x.oneTimeCharges;
                    vm.totalSubscriptionCharges += x.subscriptionCharges;
                });
                vm.subscription.amount = vm.totalSubscriptionCharges;
                vm.subscription.SetupCharges = vm.totalOTC;
            };

            vm.getOriginalName = function (doc) {
                return doc.name.replace("_" + doc.guid, "");
            };

            vm.getModuleCategory = function (category) {
                return category === 2 ? 'Add On' : '';
            };

            vm.calculateHours = function () {
                vm.totalHours = 0.0;
                vm.gapPoints.forEach(function (item) {
                    if (item.estimatedHours !== undefined) {
                        vm.totalHours += item.estimatedHours;
                    }
                });
                vm.gapPoints.totalEstimatedHours = vm.totalHours;
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('DD-MMM-YY');
                }
                else {
                    return "";
                }
            };
     

            // Get functions     

            vm.getSaleById = function () {
                vm.loading = true;

                salesService.getSaleById({ id: saleId }).success(function (result) {
                    vm.sale = result.sale;

                    vm.scope = result.scope ? JSON.parse(result.scope) : {};
                    vm.documents = result.documents || [];
                   
                    vm.detail = result.detail ? JSON.parse(result.detail) : {};

                    vm.selectedProductVariants = vm.scope.selectedProductVariants || [];
                    vm.customModules = vm.scope.customModules || [];
                    vm.gapPoints = vm.scope.gapPoints || [];

                    vm.milestones = vm.detail.milestones || [];
                    vm.subscription = vm.detail.subscription || {};

                }).finally(function () {
                    vm.getCharges();
                    vm.calculateHours();
                    vm.loading = false;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.getProducts();
                vm.getSaleById();
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('host.views.reports.statementOfAccounts.index', [
        '$scope', '$uibModal', 'abp.services.app.tenantStatementOfAccounts', 'utilities', '$stateParams', 'abp.services.app.tenant',
        function ($scope, $uibModal, tenantStatementOfAccountsService, utilities, $stateParams, tenantAppService) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
            vm.agreementDashboardFilters = null;
            if ($stateParams.filters) {
                vm.agreementDashboardFilters = $stateParams.filters;
            }
            vm.loading = false;
            vm.statementOfAccount = null;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.tenants = [];
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.rounding = function (number) {
                return utilities.round(number, 2);
            };
            vm.formatBalance = function (balance) {
                if (balance != 0) {
                    return balance > 0 ? 'Dr ' + vm.CurrencyFormate(balance) : 'Cr ' + (vm.CurrencyFormate(-balance));
                }
                return balance;
            };
            vm.filters = {
                tenantId: null,
                fromDate: null,
                toDate: null,
                statementOfAccountSearchFilter: 1,
                enableDateRange: true
            };
            vm.searchTenants = function ($select) {
                if ($select.search == "")
                    return null;
                tenantAppService.searchTenants({ filter: $select.search }).then(function (response) {
                    vm.tenants = response.data.items;
                });
            };
            vm.dateRangeModel = {
                startDate: null,
                endDate: null,
            };

            vm.permissions = {

                viewStatementOfAccount: abp.auth.hasPermission('Pages.Tenants.Report.TenantStatementOfAccounts'),
            };

            vm.dateRangeModelChanged = function () {
                vm.filters.startDate = vm.dateRangeModel.startDate;
                vm.filters.endDate = vm.dateRangeModel.endDate;
            };

            vm.radioButtonValueChanged = function () {
                if (vm.filters.statementOfAccountSearchFilter == 2) {
                    vm.filters.enableDateRange = false;
                    vm.getStatementOfAccounts();
                }
                    
                else if (vm.filters.statementOfAccountSearchFilter == 1) {
                    vm.filters.enableDateRange = true;
                    vm.getStatementOfAccounts();
                }
                
            };

            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalDateNew = function (date) {
                if (date != null) {
                    return moment.utc(date).format('DD-MM-YYYY');
                } else {
                    return "";
                }
            };

            vm.getVoucherType = function (type){
                if (type == 1) {
                    return "Invoice";
                }
                else if (type == 2) {
                    return "Receipt";
                };
            };


            vm.CurrencyFormate = function (amount) {
                if (amount == null) return null;
                return amount.toLocaleString('en');
            }

            vm.formatBalanceAsDrCr = function (balance) {
                if (balance > 0)
                    return 'Dr ' + vm.CurrencyFormate(utilities.round(balance, 2));
                else if (balance < 0)
                    return 'Cr ' + vm.CurrencyFormate(utilities.round(-balance, 2));
                else
                    return "0";
            };
            vm.getdebitAndCredit = function () {

                vm.debitSum = 0;
                vm.creditSum = 0;
                if (vm.statementOfAccount.statement) {
                    angular.forEach(vm.statementOfAccount.statement, function (value) {
                        if (value.debit > 0)
                            vm.debitSum += value.debit;
                        if (value.credit > 0)
                            vm.creditSum += value.credit;
                    });
                }
            };

            vm.getStatementOfAccounts = function () {

                vm.loading = true;
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                else {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
                if (vm.filters.statementOfAccountSearchFilter == 2) {

                    tenantStatementOfAccountsService.getTenantOutStandingInvoices(vm.filters).success(function (result) {
                        vm.statementOfAccount = result;
                        vm.getdebitAndCredit();

                    }).finally(function () {
                        vm.loading = false;
                    });
                }
              
                else {
                    tenantStatementOfAccountsService.getTenantStatementOfAccounts(vm.filters).success(function (result) {
                        vm.statementOfAccount = result;
                        vm.getdebitAndCredit();

                    }).finally(function () {
                        vm.loading = false;
                    });
                }

            };
          
            vm.localize = function (input) {
                if (input == null)
                    return "";

                return app.localize(input);
            };

          
            vm.StatementOfAccountPrintModal = function () {

                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate !== null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate !== null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                else {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }

                $uibModal.open({
                    templateUrl: '~/App/host/views/reports/statementOfAccounts/printtemplates/printPreview.cshtml',
                    controller: 'host.views.reports.statementOfAccounts.printtemplates.printPreview as vmMain',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        filters: function () {
                            return vm.filters;
                        }
                    }
                });

            };

            function init() {
                if (vm.agreementDashboardFilters) {
                    vm.filters.tenant = vm.agreementDashboardFilters.tenant;
                    if (vm.filters.enableDateRange) {
                        vm.dateRangeModel.startDate = moment(moment().format('YYYY-MM-DD')).utc();
                        vm.dateRangeModel.endDate = moment(moment().format('YYYY-MM-DD')).add(1, 'month').add(-1, 'milliseconds').utc();
                    }

                    vm.dateRangeModelChanged()
                    vm.getStatementOfAccounts();
                }
            }

            init();
        }
    ]);

})();;
