(function () {
    appModule.controller('tenant.views.common.contactGroups.viewModal', [
        '$scope', '$uibModalInstance', 'abp.services.app.contactGroup', 'contactGroupId', 'abp.services.app.costCenter',
        function ($scope, $uibModalInstance, contactGroupService, contactGroupId, costCenterService) {

            var vm = this;
            vm.saving = false;
            vm.contactGroup = null;
            vm.loading = false;
            vm.isCostCenterEnabled = abp.features.isEnabled("Core.CostCenters");

            function getContactType(type) {

                if (type == 2)
                    return 'Customer';
                else if (type == 3)
                    return 'Supplier';
                else if (type == 6)
                    return 'CorporateDriver';
                else if (type == 7)
                    return 'CompanyContact';
                return '';
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getCostCenters = function () {
                costCenterService.getCostCenters({}).success(function (data) {
                    vm.costCenters = data.items;
                });
            };

            function init() {
                vm.loading = true;
                contactGroupService.getContactGroupForEdit({
                    id: contactGroupId
                }).success(function (result) {
                    vm.contactGroup = result;
                    vm.contactGroup.contactTypeName = getContactType(vm.contactGroup.contactType);
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.common.correctVehicleStatus.index', [
        '$scope', 'abp.services.app.vehicle', 'abp.services.app.vehicleStatus', 
        function ($scope, vehicleService, vehicleStatusService) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.loading = false;
            vm.saving = false;

            vm.vehicles = [];

            vm.dateFormat = abp.setting.get("App.General.DateFormat");

            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
            
            vm.searchVehicles = function ($select) {
                if ($select.search == "") { vm.vehicles = null; return null; }
                return vehicleService.searchVehicles({ plateNo: $select.search }).then(function (response) {
                    vm.vehicles = response.data.items;
                });
            };

            vm.vehicleChanged = function (id) {
                vm.loading = true;
                vehicleStatusService.getLastMovementAndSuggestedStatus({ id: id }).success
                    (function (result) {
                        vm.movementstatus = result;
                        
                    }).finally(function () {
                        vm.loading = false;
                       
                    });;
            };

            vm.convertVehicleStatus = function () {
                vm.loading = true;
                vm.saving = true;
               vehicleStatusService.convertStatus({ vehicleId: vm.vehicle.id, suggestedStatus: vm.movementstatus.suggestedStatus }).success
                   (function () {                      
                        vm.loading = false;
                        vm.saving = false;
                        abp.notify.info(app.localize('SavedSuccessfully'));
                    }).finally(function () {
                        vm.loading = false;
                        vm.saving = false;
                    });
            };

        }
    ]);
})();;
