(function () {
    appModule.controller('tenant.views.common.hrm.deduction.deductionPayrollLineModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.directory', 'abp.services.app.deduction', 'deductionId',
        function ($scope, $uibModal, $uibModalInstance, directoryService, deductionService, deductionId) {

            var vm = this;

            vm.deductionId = deductionId;

            vm.voucherNo = null;
            vm.amount = null;
            vm.voucherDate = null;

            vm.voucherFound = false;

            vm.isSearching = false;
            vm.isSaving = false;


            // ---------------------------------------------------------
            // Search Receipt Voucher
            // ---------------------------------------------------------

            vm.searchReceiptVoucher = function () {

                if (!vm.voucherNo ||
                    vm.voucherNo.trim() === '') {

                    abp.message.warn("PleaseEnterReceiptVoucherNo");

                    return;
                }

                vm.isSearching = true;

                vm.voucherFound = false;
                vm.amount = null;
                vm.voucherDate = null;

                deductionService.getReceiptVoucherForDeduction({
                    receiptVoucherNo: vm.voucherNo.trim(),
                    deductionId: vm.deductionId
                }).then(function (result) {

                    if (result.data) {

                        vm.voucherFound = true;
                        vm.voucherNo = result.data.voucherNo;
                        vm.amount = result.data.amount;
                        vm.voucherDate = result.data.voucherDate;
                        vm.voucherId = result.data.voucherId;

                    }
                    else {

                        abp.message.warn("ReceiptVoucherNotFound");

                    }

                }).finally(function () {

                    vm.isSearching = false;

                });
            };


            // ---------------------------------------------------------
            // Enter key
            // ---------------------------------------------------------

            vm.onVoucherKeyPress = function (event) {

                if (event.which === 13) {

                    event.preventDefault();

                    vm.searchReceiptVoucher();
                }
            };

            vm.getlocalDate = function (date) {
                if (date) {
                    return moment(date).format("YYYY-MM-DD");
                }
                return "";
            };
            // ---------------------------------------------------------
            // OK
            // ---------------------------------------------------------

            vm.save = function () {

                if (!vm.voucherFound) {

                    abp.message.warn(
                        vm.l("PleaseSearchReceiptVoucher")
                    );

                    return;
                }

                vm.isSaving = true;

                deductionService.addCashDeductionPayrollLine({

                    deductionId: vm.deductionId,
                    receiptVoucherNo: vm.voucherNo,
                    amount: vm.amount,
                    voucherId: vm.voucherId

                }).then(function (result) {

                    abp.notify.success("CashEMIAddedSuccessfully");

                    /*
                     * Backend has now:
                     *
                     * 1. Validated receipt voucher
                     * 2. Found current payroll
                     * 3. Created PayrollLine
                     * 4. Updated deduction information
                     *
                     * Close modal and return updated data.
                     */

                    $uibModalInstance.close(
                        result.data
                    );

                }).finally(function () {

                    vm.isSaving = false;

                });
            };


            // ---------------------------------------------------------
            // Cancel
            // ---------------------------------------------------------

            vm.cancel = function () {

                $uibModalInstance.dismiss(
                    'cancel'
                );
            };

        }
    ]
    );

})();;
(function () {
    appModule.controller('tenant.views.common.hrm.deduction.importDeductions', [
        '$scope', 'abp.services.app.directory', 'abp.services.app.deduction', 'utilities', '$uibModalInstance',
        function ($scope, directoryService, deductionService, utilities, $uibModalInstance) {

            var vm = this;

            vm.loading = false;
            vm.processing = false;
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.selectedFile = null;
            vm.recordCountInBatch = 1000;
            vm.allowImport = false;
            vm.totalRecordsCount = 0;
            vm.successRecordsCount = 0;
            vm.failRecordsCount = 0;

            vm.hasError = false;
            vm.isSuccessFound = false;

            $scope.loadFile = function (files) {
                vm.allowImport = false;
                if (files.length > 0) {
                    $scope.$apply(function () {
                        vm.selectedFile = files[0];
                        readFileData();
                    });
                } else {
                    vm.refresh();
                    $scope.$apply();
                }
            };
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            vm.refresh = function () {
                vm.fileDataList = [];
                angular.element('#dataFile').val(null);
                vm.selectedFile = null;
                vm.allowImport = false;

                vm.totalRecordsCount = 0;
                vm.successRecordsCount = 0;
                vm.failRecordsCount = 0;
                vm.errorRecords = null;
                vm.showCount = false;
                vm.hasError = false;
                vm.isSuccessFound = false;
            };


            vm.getlocalDate = function (date) {
                if (date) {
                    let localDate = moment.utc(date); // First, treat it as UTC

                    localDate.add(12, 'seconds');
                    localDate.local();

                    return localDate.format(vm.dateFormat);
                } else {
                    return "";
                }
            };



            //vm.getlocalDate = function (date) {
            //    console.log(date);
            //    if (date) {
            //        return moment(date).utc().local().format(vm.dateFormat);
            //    }
            //    else {
            //        return "";
            //    }
            //};

            function correctData(date) {
                if (date) {
                    return moment(date).add(12, 'seconds');
                }
                else {
                    return "";
                }
            }

            vm.getTypeOfDeduction = function (type) {
                type = parseInt(type);
                if (type === 1) return app.localize("AdvanceDeduction");
                if (type === 2) return app.localize("LoanDeduction");
                if (type === 3) return app.localize("FinesDeduction");
                if (type === 4) return app.localize("ExtraDeduction");
                return "";
            };

            vm.importFromExcelSample = function () {
                vm.loading = true;


                agreementAppService.openAgreementSampleFile()
                    .success(function (result) {
                        app.downloadTempFile(result);
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            function readFileData() {

                vm.fileDataList = [];
                var file = vm.selectedFile;

                if (file && ['xlsx', 'xls'].indexOf(file.name.split('.').pop().toLowerCase()) > -1) {

                    var reader = new FileReader();
                    vm.loading = true;
                    vm.saving = true;
                    reader.onload = function (e) {

                        var data = e.target.result;
                        var workbook = XLSX.read(data, { type: 'binary', cellDates: true, cellNF: false, cellText: false });
                        var first_sheet_name = workbook.SheetNames[0];

                        var dataObjects = XLSX.utils.sheet_to_json(workbook.Sheets[first_sheet_name], { raw: true, dateNF: 'MM-DD-YYYY HH:mm:ss' });

                        if (dataObjects.length > 0) {

                            for (var i = 0; i < dataObjects.length; i++) {

                                var value = dataObjects[i];

                                var record = {
                                    error: '',
                                    importStatus: 'new',

                                    employeeCode: value['Employee_Code'] ? value['Employee_Code'].toString().trim() : '',
                                    name: value['Name'] ? value['Name'].toString().trim() : '',
                                    date: value['Date'] ? correctData(value['Date']) : null,
                                    type: value['Type'] ? value['Type'].toString().trim() : '',
                                    amount: value['Amount'] ? parseFloat(value['Amount']) : 0,
                                    remarks: value['Remarks'] ? value['Remarks'].toString().trim() : ''
                                    //salaryItemId: value['Salary_Item_Id'] ? parseInt(value['Salary_Item_Id']) : ''

                                };

                                vm.fileDataList.push(record);
                            }

                            if (vm.fileDataList.length > 0)
                                vm.allowImport = true;

                        } else {
                            abp.message.error("Something Wrong Or File is empty !", "Error");
                        }

                        vm.loading = false;
                        vm.saving = false;
                        $scope.$apply();
                    };

                    reader.onerror = function (ex) {
                        vm.loading = false;
                        abp.message.warn(
                            app.localize(ex),
                            'Unknown File'
                        );
                    };

                    reader.readAsBinaryString(file);

                } else {
                    abp.message.error("Please select Valid file to upload !", "Unknown File");
                    vm.loading = false;
                    vm.saving = false;
                }

            }

            vm.importData = function () {

                vm.allowImport = false;
                vm.loading = true;
                vm.saving = true;

                if (vm.fileDataList) {
                    sendDataInBatches();
                }
                else
                    abp.message.error("Something Wrong Or File is empty !", "Error");
            };


            function sendDataInBatches() {
                vm.saving = true;
                vm.loading = true;

                var recordsToSend = [];
                angular.forEach(vm.fileDataList, function (dataItem) {
                    if (dataItem.importStatus === 'new' && recordsToSend.length < vm.recordCountInBatch) {
                        recordsToSend.push(dataItem);
                    }
                });

                //return condition
                if (recordsToSend.length < 1) {
                    vm.loading = false;
                    vm.showCount = true;
                    vm.totalRecordsCount = vm.fileDataList.length;
                    vm.successRecordsCount = vm.fileDataList.filter(e => e.status == "success").length;
                    vm.failRecordsCount = vm.fileDataList.filter(e => e.status == "fail").length;
                    vm.failRecords = vm.fileDataList.filter(e => e.status == "fail");

                    var fieldsRecordsIndex = [];
                    vm.failRecords.forEach(e => {
                        fieldsRecordsIndex.push(vm.failRecords.indexOf(e) + 1);
                    });
                    vm.errorRecords = fieldsRecordsIndex.join();
                    return;
                }

                deductionService.importDeductions({ deductions: recordsToSend })
                    .success(function (data) {

                        if (data) {

                            angular.forEach(data.deductions, function (dataItem) {
                                if (dataItem.error) {
                                    vm.hasError = true;
                                }

                                angular.forEach(vm.fileDataList, function (fileDataItem) {
                                    if (fileDataItem.employeeCode === dataItem.employeeCode) {
                                        fileDataItem.importStatus = dataItem.importStatus;
                                        fileDataItem.error = dataItem.error;

                                        if (fileDataItem.importStatus === 'success') {
                                            vm.isSuccessFound = true;
                                        }

                                    }
                                });
                            });

                            if (vm.hasError) {
                                angular.forEach(vm.fileDataList, function (fileDataItem) {
                                    if (fileDataItem.importStatus === 'success') {
                                        fileDataItem.importStatus = 'new';
                                    }
                                });
                            }

                        }

                    }).finally(function () {
                        vm.loading = false;
                        vm.saving = false;
                    });
            }


            //function sendDataInBatches() {

            //    vm.loading = true;

            //    //get records that dont saved yet
            //    var recordsToSend = [];
            //    angular.forEach(vm.fileDataList, function (dataItem) {
            //        if (dataItem.importStatus === 'new' && recordsToSend.length < vm.recordCountInBatch) {
            //            recordsToSend.push(dataItem);
            //        }
            //    });

            //    //return condition
            //    if (recordsToSend.length < 1) {
            //        vm.loading = false;
            //        vm.showCount = true;
            //        vm.totalRecordsCount = vm.fileDataList.length;
            //        vm.successRecordsCount = vm.fileDataList.filter(e => e.status == "success").length;
            //        vm.failRecordsCount = vm.fileDataList.filter(e => e.status == "fail").length;
            //        vm.failRecords = vm.fileDataList.filter(e => e.status == "fail");

            //        var fieldsRecordsIndex = [];
            //        vm.failRecords.forEach(e => {
            //            fieldsRecordsIndex.push(vm.failRecords.indexOf(e) + 1);
            //        });
            //        vm.errorRecords = fieldsRecordsIndex.join();
            //        return;
            //    }

            //    deductionService.importDeductions({ deductions: recordsToSend })
            //        .success(function (data) {

            //            if (data) {
            //                angular.forEach(data.deductions, function (dataItem) {
            //                    angular.forEach(vm.fileDataList, function (fileDataItem) {
            //                        if (fileDataItem.employeeCode === dataItem.employeeCode) {
            //                            fileDataItem.importStatus = dataItem.importStatus;
            //                            fileDataItem.error = dataItem.error;
            //                        }
            //                    });
            //                });
            //            }
            //            vm.loading = false;
            //            //sendDataInBatches();

            //        }).finally(function (data) {
            //            vm.loading = false;
            //        });

            //}

            vm.resolveBoolValue = function (value) {
                return value === 0 ? 'NO' : 'YES';
            };
        }
    ]);

})();;
(function () {
    appModule.controller('tenant.views.common.hrm.deduction.index', [
        '$scope', '$uibModal', 'abp.services.app.directory', 'uiGridConstants', 'abp.services.app.deductionSearch', 'abp.services.app.deduction', 'abp.services.app.salaryItemsSetting',
        function ($scope, $uibModal, directoryService, uiGridConstants, deductionSearchService, deductionService, salaryItemsSettingService) {

            var vm = this;

            vm.loading = false;

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));

            vm.permissions = {
                view: abp.auth.hasPermission('Pages.HRM.Deduction.View'),
                create: abp.auth.hasPermission('Pages.HRM.Deduction.AddNew'),
                edit: abp.auth.hasPermission('Pages.HRM.Deduction.Edit'),
                delete: abp.auth.hasPermission('Pages.HRM.Deduction.Delete')
            };

            vm.filters = {
                enableDateRange: true,
                status: null,
                startDate: null,
                endDate: null,
                staffId: null,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                type: null,
            };

            vm.statuses = [
                { id: 0, name: app.localize("Pending") },
                { id: 1, name: app.localize("Deducted") },
                { id: 2, name: app.localize("WaivedOff") }
            ];

            vm.types = null;
            vm.staffs = [];

            //functions
            vm.getDeductions = function () {
                vm.loading = true;

                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }

                if (vm.filters.staff != null) {
                    vm.filters.staffId = vm.filters.staff.id;
                }

                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }

                deductionSearchService.getDeductions(vm.filters).success(function (data) {

                    vm.gridOptions.totalItems = data.totalCount;
                    vm.gridOptions.data = data.items;

                }).finally(function () {
                    vm.loading = false;
                });

            };

            function getDeductionTypes() {
                vm.types = [
                    { id: 1, name: app.localize("Loan Deduction") }
                ];
            };

            //function getStatusTypes() {
            //    vm.statuses = [
            //        { id: 0, name: app.localize("Pending") },
            //        { id: 1, name: app.localize("Deducted") },
            //        { id: 1, name: app.localize("WaivedOff") }
            //    ];
            //};

            vm.dateRangeModelChanged = function () {
                vm.filters.startDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                vm.filters.endDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            function initDate() {
                vm.dateRangeModel = {
                    startDate: moment().add(-29, 'days').startOf('day'),
                    endDate: moment().endOf('day')
                };
            }

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM-DD');
                }
                else {
                    return "";
                }
            };

            vm.clearStaff = function () {
                vm.filters.staff = null;
                vm.filters.staffId = null;
            };

            vm.searchStaff = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customers). get customers
                return directoryService.search({ keyword: $select.search, contactType: 1, activeOnly: true }).then(function (response) {
                    vm.staffs = response.data.items;
                });
            };

            vm.exportToExcel = function () {
                vm.loading = true;

                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                    vm.filters.startDate = null;
                    vm.filters.endDate = null;
                }

                vm.filters.fromDate = vm.filters.startDate;
                vm.filters.toDate = vm.filters.endDate;

                deductionSearchService.exportToExcel(vm.filters)
                    .success(function (result) {
                        app.downloadTempFile(result);
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            vm.searchStaffPopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return 1;
                        }
                    }
                }).result.then(function (staff) {
                    if (staff != null) {
                        vm.filters.staff = staff;
                    }
                });
            };

            vm.createDeduction = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/common/hrm/deduction/createOrEditModal.cshtml',
                    controller: 'tenant.views.common.hrm.deduction.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return {
                                id: null
                            }
                        },
                        amount: function () {
                            return 0;
                        },
                        staff: function () {
                            return {
                                staff: null
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getDeductions();
                });
            };

            vm.editDeduction = function (deduction) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/common/hrm/deduction/createOrEditModal.cshtml',
                    controller: 'tenant.views.common.hrm.deduction.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return {
                                id: deduction.id
                            }
                        },
                        amount: function () {
                            return 0;
                        },
                        staff: function () {
                            return {
                                staff: null
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getDeductions();
                });
            };

            vm.viewDeduction = function (deduction) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/common/hrm/deduction/viewModal.cshtml',
                    controller: 'tenant.views.common.hrm.deduction.viewModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return {
                                id: deduction.id
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getDeductions();
                });
            };

            vm.deleteDeduction = function (deduction) {
                abp.message.confirm(
                    app.localize('DeleteDeductionMessage'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            deductionService.deleteDeduction({
                                id: deduction.id
                            }).success(function () {
                                vm.getDeductions();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };

            vm.deductionLog = function (deduction) {
                opendeductionLogModal(deduction);
            };

            function opendeductionLogModal(deduction) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/common/hrm/deduction/deductionLogModal.cshtml',
                    controller: 'tenant.views.common.hrm.deduction.deductionLogModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        options: function () {
                            return {
                                deductionId: deduction.id,
                            };
                        }
                    }
                });

            }

            vm.getStatusTypes = function (status) {
                if (status == 0) {
                    return app.localize("Pending");
                } else if (status == 1) {
                    return app.localize("Deducted");
                } else if (status == 1) {
                    return app.localize("WaivedOff");
                } else {
                    return "";
                }
            };

            vm.getTypeOfDeduction = function (type) {
                if (type == 51) {
                    return app.localize("AdvanceDeduction");
                } else if (type == 52)
                    return app.localize("LoanDeduction");
                else if (type == 55)
                    return app.localize("FinesDeduction");
                else if (type == 65)
                    return app.localize("ExtraDeduction");

                else {
                    return "";
                }
            };


            // Import deductions

            vm.openImportDeductionModal = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/common/hrm/deduction/importDeductions.cshtml',
                    controller: 'tenant.views.common.hrm.deduction.importDeductions as vm',
                    backdrop: 'static',
                    size: 'full',


                });
            };

            //vm.getTypeOfDeduction = function (salaryItemId) {             
            //    if (salaryItemId != null && vm.salaryTypes != null) {
            //        var salaryType = vm.salaryTypes.find(salaryType => salaryType.id === salaryItemId);

            //        if (salaryType != null) {
            //            return abp.localization.localize(salaryType.type || '');
            //        }
            //    }
            //    // Handle the case when salaryItemId is null or vm.salaryTypes is null
            //    return ''; // or any other default value or behavior you want
            //};

            //init
            function init() {
                initDate();
                vm.getStatusTypes();
                getDeductionTypes();
                vm.getDeductions();
            }


            //grid 
            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize(' '),
                        enableSorting: false,
                        width: 55,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown " uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize(' ') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.view" ng-click="grid.appScope.viewDeduction(row.entity)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.delete && row.entity.statusType == 0 && row.entity.numberOfPaidInstallments == 0" ng-click="grid.appScope.deleteDeduction(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.edit && row.entity.statusType == 0" ng-hide="row.entity.status == 8" ng-click="grid.appScope.editDeduction(row.entity)">' + app.localize('ReviseInstallments') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.view" ng-click="grid.appScope.deductionLog(row.entity)">' + app.localize('Log') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('StartDate'),
                        field: 'startDate',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.startDate)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Type'),
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getTypeOfDeduction(row.entity.salaryItemId)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Staff'),
                        field: 'staff.name',
                    },
                    {
                        name: app.localize('Amount'),
                        field: 'totalAmount',
                        type: 'totalAmount',
                    },
                    {
                        name: app.localize('NumberOfInstallments'),
                        type: 'number',
                        field: 'numberOfDeductions',

                    },
                    {
                        name: app.localize('NumberOfPaidInstallments'),
                        type: 'number',
                        field: 'numberOfPaidInstallments',

                    },
                    {
                        name: app.localize('Status'),
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getStatusTypes(row.entity.statusType)}}</div>' +
                            '</div>'
                    }
                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getDeductions();
                    });
                },
                data: []
            };
            function getSalaryItemTypes() {
                vm.loading = true;
                salaryItemsSettingService.getSalaryItemTypes().success(function (data) {
                    vm.salaryTypes = data.map(function (item) {
                        item.type = vm.getLocalize(item.type);
                        return item;
                    });
                    init();

                }).finally(function () {
                    vm.loading = false;
                });
            }
            getSalaryItemTypes();

            vm.getLocalize = (name) => {
                if (name === "OtherDeduction1")
                    return "Extra Deduction";

                return abp.localization.localize(name);
            }
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.common.hrm.deduction.viewModal', [
        '$uibModalInstance', 'abp.services.app.directory', 'abp.services.app.deduction', 'utilities', 'options', 'abp.services.app.salaryItemsSetting',
        function ($uibModalInstance, directoryService, deductionService, utilities, options, salaryItemsSettingService) {

            var vm = this;
            vm.loading = false;
            vm.totalPaidAmount = 0;
            var deductionId = options.id;

            //functions
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };

            vm.getTypeOfDeduction = function (salaryItemId) {

                if (salaryItemId != null && vm.salaryTypes != null) {
                    var salaryType = vm.salaryTypes.find(salaryType => salaryType.id === salaryItemId);

                    if (salaryType != null) {

                        if (salaryType.id == 65)
                            return abp.localization.localize("Extra Deduction" || '');

                        return abp.localization.localize(salaryType.type || '');
                    }
                }
                return '';
            };

            vm.getStatusTypes = function (status) {
                if (status == 0) {
                    return app.localize("Pending");
                } else if (status == 1) {
                    return app.localize("Deducted");
                } else if (status == 1) {
                    return app.localize("WaivedOff");
                } else {
                    return "";
                }
            };
            vm.getDeductionEmiStatus = function (status) {
                if (status == 1) {
                    return app.localize("Payroll");
                } else if (status == 2) {
                    return app.localize("Cash");
                } else {
                    return "";
                }
            };
            //vm.getTypeOfDeduction = function (type) {
            //    if (type == 1) {
            //        return app.localize("LoanDeduction");
            //    } else if (type == 2)
            //        return app.localize("AdvanceDeduction");
            //    else if (type == 3)
            //        return app.localize("FinesDeduction");
            //    else if (type == 4)
            //        return app.localize("ExtraDeduction");
            //    else {
            //        return "";
            //    }
            //};
            function init() {
                vm.loading = true;
                deductionService.getDeductionForView({ id: deductionId }).success(
                    function (result) {
                        vm.deduction = result;
                        if (vm.deduction.deductionDetails && vm.deduction.deductionDetails.length > 0) {
                            vm.totalPaidAmount = vm.deduction.deductionDetails.reduce(function (sum, deduction) {
                                return sum + deduction.amount;
                            }, 0);
                        }

                        /* vm.deduction.type = vm.getTypeOfDeduction(vm.deduction.type);*/

                    }).finally(function () {
                        vm.loading = false;
                    });
            }
            function getSalaryItemTypes() {
                vm.loading = true;
                salaryItemsSettingService.getSalaryItemTypes().success(function (data) {

                    vm.salaryTypes = data;
                    init();
                }).finally(function () {
                    vm.loading = false;
                });
            }
            getSalaryItemTypes();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.common.hrm.finalSettlement.index', [
        '$scope', '$uibModal', 'abp.services.app.directory', 'abp.services.app.leaveSalaryPayroll', 'abp.services.app.payroll', 'abp.services.app.staff', 'abp.services.app.designation', 'abp.services.app.businessUnit',
        function ($scope, $uibModal, directoryService, leaveSalaryPayrollService, payrollService, staffService, designationService, businessUnitService) {

            var vm = this;
            vm.isBusinessUnitWisePayrollProcess = abp.setting.getBoolean("App.Speed.Hrm.IsBusinessUnitsWisePayrollProcess");

            vm.loading = false;
            vm.isPayFullTicketPriceAndAdjustInSalary = false
            vm.leaveDetails = null;
            vm.lastWorkingDay = null;
            vm.firstWorkingDay = null;
            vm.serviceTenureDescription = '';
            vm.totalPayable = 0;
            vm.additional = 0;
            vm.airTicketPrice = 0;
            vm.leaveSalaryPayroll = {
                /*ticketPrice: 0,*/
                eligible: 0,
                payableValue: 0
            };
            //vm.startDate = new Date(date);
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.isGranted = (permission) => {
                return abp.auth.isGranted(permission);
            }
            var designationDetails = function () {
                designationService.getDesignations().success(function (result) {
                    vm.designationDetails = result.items;
                    //console.log(test);
                });
            };
            vm.clearStaff = function () {
                vm.staff = null;
                vm.staffId = null;
                vm.leave = null;
                vm.payroll = null;
                vm.lastWorkingDay = null;

            };
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                } else {
                    return "";
                }
            };
            vm.calculateTotal = (pd, ticketPrize) => {
                if (!pd) return 0;
                vm.totalPayable = (parseFloat(pd.netPay) || 0) + (parseFloat(ticketPrize) || 0) + (parseFloat(pd.leaveSalary) || 0) + (parseFloat(pd.gratuity) || 0);
                return vm.totalPayable;
            };
            vm.calculateTicket = (count, prize) => {

                const countValue = parseFloat(count);
                const prizeValue = parseFloat(prize);

                if (isNaN(countValue) || isNaN(prizeValue)) return 0;

                return countValue * prizeValue;
            };

            vm.searchStaff = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customers). get customers
                return directoryService.searchStaffForHrm({ keyword: $select.search, contactType: 1, activeOnly: true }).then(function (response) {
                    vm.staffs = response.data.items;
                });
            };

            vm.searchStaffPopoup = async function () {
                try {
                    vm.loading = true;
                    vm.isProcess = true;
                    if (vm.staff) {
                        vm.businessUnitId = vm.staff.businessUnitId;
                    }
                    vm.filters.isCalculateGratuity = true; // Calculate gratuity
                    // Fetch staff details
                    const staffResponse = await staffService.getStaffForEdit({ id: vm.staff.id });
                    vm.staffs = staffResponse.data.items;
                    vm.staff = staffResponse.data;
                    // First working day
                    if (vm.staff != null && vm.staff.dateOfJoining != null) {
                        vm.firstWorkingDay = vm.staff.dateOfJoining;
                    }
                    vm.airTicket = vm.staff.staffWiseEligibilities.find(x => x.salaryItemTypeId == 41);

                    // Fetch recent leave details
                    await vm.getStaffRecentLeaveDetails(vm.staff.id, vm.filters.isCalculateGratuity);

                    // Fetch recent ticket details
                    await vm.getStaffRecentTicketDetails(vm.staff.id);
                    vm.processReferesh();
                } catch (error) {
                    vm.isProcess = false;
                    return;
                }
                finally {
                    vm.loading = false;
                    /*vm.isProcess = false;*/
                }
            };


            vm.getStaffRecentLeaveDetails = async function (staffId, isCalculateGratuity) {
                try {
                    const response = await leaveSalaryPayrollService.getStaffRecentLeaveDetails(staffId, isCalculateGratuity);
                    vm.leave = response.data;
                    vm.leaveDetails = vm.leave;
                    //vm.leaveTicketStartDate = vm.leave?.leaveType?.leaveStartFrom;
                    if (vm.leave && vm.leave.leaveType) {
                        vm.leaveTicketStartDate = vm.leave.leaveType.leaveStartFrom;
                    }

                    if (vm.leave && vm.leave.fromDate && vm.leave.toDate) {
                        let startDate = moment(vm.leave.fromDate);
                        let endDate = moment(vm.leave.toDate);

                        if (startDate.isValid() && endDate.isValid()) {
                            vm.filters.approvedAnnualLeaves = endDate.diff(startDate, 'days') + 1;
                        } else {

                            vm.filters.approvedAnnualLeaves = 0;
                        }
                    } else {

                        vm.filters.approvedAnnualLeaves = 0;
                    }
                } catch (error) {
                    vm.isProcess = false;
                    $scope.$apply();
                    throw error;
                }
                finally {
                    vm.loading = false;
                    /* vm.isProcess = false;*/
                }
            };

            vm.getStaffRecentTicketDetails = async function (staffId) {
                try {
                    const response = await leaveSalaryPayrollService.getStaffRecentTicketDetails(staffId);
                    vm.lastTicketPayrollDetails = response.data;

                    if (vm.lastTicketPayrollDetails && vm.lastTicketPayrollDetails.ticketIssuanceDate /*!== vm.leave.fromDate*/) { // check coment for final settlement
                        // Check for same date in case of cancel reprocess
                        /*if (vm.lastTicketPayrollDetails.ticketIssuanceDate !== vm.leave.fromDate)*/
                        vm.lastTicketDate = vm.lastTicketPayrollDetails.ticketIssuanceDate;
                    } else if (vm.staff != null && vm.staff.dateOfJoining != null) {
                        let date;
                        date = vm.staff.dateOfJoining;
                        //if (vm.leave.leaveType.leaveStartFrom == 1) {
                        //    date = vm.staff.dateOfJoining;
                        //} else if (vm.leave.leaveType.leaveStartFrom == 2) {
                        //    date = vm.staff.dateOfConfirmation;
                        //}
                        vm.lastTicketDate = new Date(date);
                        /*vm.lastTicketDate = new Date('2024-01-22T00:00:00Z');*/

                    }
                    $scope.$apply();
                } catch (error) {
                    console.error('Error in getStaffRecentTicketDetails:', error);
                }
            };
            //vm.calculateEligibleValue = function () {

            //    //vm.calculateEligibleValue = function () {
            //    var currentDate = new Date();
            //    var startDate;
            //    if (vm.lastTicketPayrollDetails) {
            //        startDate = new Date(vm.lastTicketPayrollDetails.toDate);
            //    }
            //    else {
            //        var date;
            //        if (vm.leave.leaveType.leaveStartFrom == 1) {
            //            date = vm.staff.dateOfJoining
            //        }
            //        else if (vm.leave.leaveType.leaveStartFrom == 2) {
            //            date = vm.staff.dateOfConfirmation
            //        }
            //        startDate = new Date(date);
            //    }

            //    // Calculate the difference in milliseconds
            //    var dateDifference = currentDate - startDate;

            //    // Convert milliseconds to years
            //    var yearsDifference = dateDifference / (365.25 * 24 * 60 * 60 * 1000);

            //    // Round the result to get the whole years
            //    //var roundedYearsDifference = Math.floor(yearsDifference);

            //    if (yearsDifference >= 1) {
            //        if (yearsDifference >= vm.airTicket.afterYears) {
            //            vm.leaveSalaryPayroll.eligibleValue = vm.leaveSalaryPayroll.fullTicketValue * vm.airTicket.eligibleFor
            //        }
            //        else {
            //            vm.leaveSalaryPayroll.eligibleValue = Math.floor(((vm.leaveSalaryPayroll.fullTicketValue * (yearsDifference / vm.airTicket.afterYears)) * vm.airTicket.eligibleFor));
            //        }
            //        vm.leaveSalaryPayroll.approvedValue = vm.leaveSalaryPayroll.eligibleValue
            //        vm.leaveSalaryPayroll.receivableFromEmployee = vm.leaveSalaryPayroll.approvedValue - vm.leaveSalaryPayroll.eligibleValue
            //    }
            //    else {
            //        vm.leaveSalaryPayroll.eligibleValue = 0;
            //        vm.leaveSalaryPayroll.approvedValue = 0;
            //        vm.leaveSalaryPayroll.receivableFromEmployee = 0;
            //    }
            //}




            vm.calculateEligibleValue = function () {
                if (!vm.lastTicketDate || !moment(vm.lastTicketDate).isValid()) {
                    console.error('Invalid last ticket date');
                    return;
                }

                if (vm.leaveSalaryPayroll.ticketPrice <= 0 || vm.airTicket.eligibleFor <= 0) {
                    console.error('Invalid ticket price or eligibility');
                    return;
                }

                // Change this line to calculate ticket price in final settlement dont take current date

                var ticketDate = vm.lastWorkingDay;
                var dateDifference = ticketDate.diff(moment(vm.lastTicketDate), 'days') + 1; // Include both dates
                // replace below line with above one
                //var currentDate = moment(new Date());
                //var dateDifference = currentDate.diff(moment(vm.lastTicketDate), 'days') + 1; // Include both dates

                // Define the thresholds
                var oneYearInDays = 365.25;
                /*var eligibleDays = Math.floor(dateDifference);*/
                var eligibleDays = Math.floor(Math.abs(dateDifference)); // take positive value


                if (eligibleDays > oneYearInDays) {
                    var eligibleYears = Math.floor(eligibleDays / oneYearInDays);
                    var remainingDays = eligibleDays % oneYearInDays;

                    vm.leaveSalaryPayroll.payableValue = eligibleYears * vm.airTicket.eligibleFor * vm.leaveSalaryPayroll.ticketPrice;

                    if (remainingDays > 0) {
                        var additionalMonths = remainingDays / 30; // Approximate to months
                        var proRatedValue = (additionalMonths / 12) * vm.airTicket.eligibleFor * vm.leaveSalaryPayroll.ticketPrice;
                        vm.leaveSalaryPayroll.payableValue += Math.floor(proRatedValue);
                    }

                    vm.leaveSalaryPayroll.eligible = 100; // Eligible for full amount
                } else {
                    vm.isTicketForFirstTime = vm.checkAirTicketForFirstTime();// Check get air ticket for first time
                    if (!vm.isTicketForFirstTime) {
                        vm.leaveSalaryPayroll.payableValue = Math.floor((eligibleDays / oneYearInDays) * vm.airTicket.eligibleFor * vm.leaveSalaryPayroll.ticketPrice);
                        vm.leaveSalaryPayroll.eligible = (eligibleDays / oneYearInDays) * 100;
                    }
                    else {
                        vm.leaveSalaryPayroll.payableValue = 0;
                        vm.leaveSalaryPayroll.eligible = 0;
                    }
                }

                vm.leaveSalaryPayroll.ticketQuota = vm.airTicket.eligibleFor;
                vm.leaveSalaryPayroll.receivableFromEmployee = vm.leaveSalaryPayroll.payableValue - vm.leaveSalaryPayroll.ticketQuota;

                // Dont show advanve amount option in air tick for gratuity
                //if (vm.leaveSalaryPayroll.payableValue < vm.leaveSalaryPayroll.ticketPrice && !vm.isTicketForFirstTime) {
                //    vm.isAdvanceTicketAmount = true;
                //    vm.leaveSalaryPayroll.ticketPayable = vm.leaveSalaryPayroll.ticketPrice;
                //    vm.leaveSalaryPayroll.amountAsAdvance = vm.leaveSalaryPayroll.ticketPrice - vm.leaveSalaryPayroll.payableValue;
                //} else {
                //    vm.isAdvanceTicketAmount = false;
                //}
            };

            // Check air ticket for first time
            vm.checkAirTicketForFirstTime = function () {

                if (vm.staff != null && vm.staff.dateOfJoining != null && vm.staff.dateOfConfirmation != null) {
                    if (vm.lastTicketDate != null) {
                        if (moment(vm.lastTicketDate).isSame(moment(vm.staff.dateOfJoining)) ||
                            moment(vm.lastTicketDate).isSame(moment(vm.staff.dateOfConfirmation))) {
                            return true;
                        }
                    }
                }
                return false;
            }

            vm.ontTicketPriceChange = function () {
                vm.leaveSalaryPayroll.receivableFromEmployee = vm.leaveSalaryPayroll.ticketQuota - vm.leaveSalaryPayroll.payableValue;
            }


            vm.process = () => {
                vm.filters.staffId = vm.staff.id;
                // check here for exception on receivableFromEmployee
                /*vm.filters.receivableFromEmployee = vm.leaveSalaryPayroll.receivableFromEmployee;*/
                vm.filters.payableValue = vm.leaveSalaryPayroll.payableValue;

                vm.filters.skipCount = vm.skipCount;
                vm.filters.annualLeavesStartDate = moment(vm.leave.fromDate);
                /*vm.filters.noOfAnnualLeaves = vm.leave.leaveType?.noOfLeaves;*/
                /*vm.filters.noOfAnnualLeaves = vm.leave?.fullPaidDays;*/ // Get no of paid days 
                vm.filters.noOfAnnualLeaves = vm.leave?.fullPaidDays || 0;

                /*vm.filters.isCalculateAsLeaveSalary = vm.leave?.leaveType?.calculateAsLeaveSalary;*/
                vm.loading = false;
                //Get Re-joining Date
                if (vm.staff != null) {
                    leaveSalaryPayrollService.getReJoiningDate(vm.staff.id).then(function (response) {
                        vm.lastReJoiningDate = response.data;
                        vm.leaveDuration = vm.filters.approvedAnnualLeaves;
                        vm.noOfAnnualLeaves = vm.filters.noOfAnnualLeaves;
                    });
                }
                // Calculate staff service days for gratuity
                var result = vm.calculateTenureAndCompletedYears();

                // Assign values to vm.filters
                vm.filters.serviceYearsForGratuity = result.completedYearsDecimal; // Number of completed years
                vm.serviceTenureDescription = result.tenure;

                payrollService.processLeaveTicket(vm.filters)
                    .success((r) => {
                        let payroll = r.payroll;
                        vm.totalCount = r.totalCount;
                        payroll.payrollDetails.forEach(pd => {
                            pd.payrollLines.forEach(pl => {
                                if (pl.type === 1 && !vm.additionHeaders.find(ah => ah.name === pl.name)) {
                                    vm.additionHeaders.push({ name: pl.name, order: pl.order });
                                }
                                else if (pl.type === 2 && !vm.deductionHeaders.find(dh => dh.name === pl.name)) {
                                    vm.deductionHeaders.push({ name: pl.name, order: pl.order });
                                }
                            });

                            additionAndDeductionValues(pd);
                            //payrollCalculation(pd);

                            pd.getSalaryItemAmount = (name) => {
                                let salaryItem = pd.payrollLines.find(pl => pl.name === name);
                                return salaryItem ? salaryItem.amount : 0;
                            }
                        });

                        if (!vm.payroll) {
                            vm.payroll = payroll;
                            // Get Ticket Value In Case Of Cancel Re-Process
                            /*vm.airTicketPrice = vm.payroll.payrollDetails[0].airTicket || 0;*/
                            vm.airTicketPrice = (vm.payroll && vm.payroll.payrollDetails && vm.payroll.payrollDetails.length > 0 && vm.payroll.payrollDetails[0].airTicket) || 0;

                            if (vm.airTicketPrice > 0) {
                                vm.leaveSalaryPayroll.payableValue = vm.airTicketPrice;
                                vm.leaveSalaryPayroll.ticketPrice = vm.payroll.payrollDetails[0].oneTicketPrice;
                                vm.leaveSalaryPayroll.eligible = vm.payroll.payrollDetails[0].eligibilityPercentage;
                                vm.isPayFullTicketPriceAndAdjustInSalary = vm.payroll.payrollDetails[0].isPayFullTicketPrice;
                            }
                            else {
                                vm.leaveSalaryPayroll.payableValue = 0;
                                /*vm.leaveSalaryPayroll.ticketPrice = 0;*/
                                vm.leaveSalaryPayroll.eligible = 0;
                                vm.isPayFullTicketPriceAndAdjustInSalary = false;
                            }
                        }
                        else {
                            payroll.payrollDetails.forEach(pd => {
                                vm.payroll.payrollDetails.push(pd);
                            });
                        }
                        vm.payroll.payrollDetails.sort((pd1, pd2) => pd1.netPay < pd2.netPay ? 1 : -1);

                        // Comment batchwise processing work 
                        //vm.skipCount = vm.skipCount + vm.batchSize;
                        //if (vm.skipCount < vm.totalCount)
                        //    vm.process();
                        //else {
                        //    vm.isProcess = false;
                        //    if (vm.state === 2 && !vm.filters.isReprocess) {
                        //        vm.isPayrollForSave = false;
                        //        vm.isPayrollForApprove = true;
                        //    }
                        //    else if (vm.state === 2 && vm.filters.isReprocess) {
                        //        vm.isPayrollForSave = true;
                        //        vm.isPayrollForApprove = false;
                        //        vm.isSaved = false;
                        //    }
                        //    else {
                        //        vm.isPayrollForSave = true;

                        //    }
                        //    vm.isProcessEnabled = false;
                        //}

                        vm.isProcess = false;
                        if (vm.state === 2 && !vm.filters.isReprocess) {
                            vm.isPayrollForSave = false;
                            vm.isPayrollForApprove = true;
                        }
                        else if (vm.state === 2 && vm.filters.isReprocess) {
                            vm.isPayrollForSave = true;
                            vm.isPayrollForApprove = false;
                            vm.isSaved = false;
                        }
                        else {
                            vm.isPayrollForSave = true;

                        }
                        vm.isProcessEnabled = false;
                    })
                    .finally(() => {
                        vm.isProcess = false;
                    });
            }
            function additionAndDeductionValues(pd) {
                pd.additionValues = [];
                pd.deductionValues = [];
                vm.additionHeaders.forEach(h => {
                    let v = pd.additionValues.find(x => x.name === h.name);
                    if (!v) {
                        let pl = pd.payrollLines.find(x => x.name === h.name);
                        pd.additionValues.push({ name: h.name, order: h.order, amount: pl ? pl.amount : 0 });
                    }

                });
                vm.deductionHeaders.forEach(h => {
                    let v = pd.deductionValues.find(x => x.name === h.name);
                    if (!v) {
                        let pl = pd.payrollLines.find(x => x.name === h.name);
                        pd.deductionValues.push({ name: h.name, order: h.order, amount: pl ? pl.amount : 0 });
                    }
                });
            }

            vm.processReferesh = () => {

                // Set default values if vm.leave is null
                const fromDate1 = vm.leave ? vm.leave.fromDate : new Date(); // Use current date as default
                const toDate1 = vm.leave ? vm.leave.toDate : new Date(); // Use current date as default

                vm.payroll = null;
                vm.skipCount = 0;

                /*vm.filters.fromDate = moment(vm.leave.fromDate).startOf('month').startOf('day');*/
                vm.filters.fromDate = moment(vm.lastWorkingDay).startOf('month').startOf('day');
                //vm.filters.toDate = moment(vm.leave.toDate);
                // Assuming vm.leave.toDate is a date string or a date object
                vm.filters.toDate = moment(vm.lastWorkingDay)/*.subtract(1, 'days')*/; // month duration include last working day
                /* vm.filters.toDate = moment(vm.leave.fromDate).subtract(1, 'days');*/
                vm.filters.staffId = vm.staff.id;
                vm.filters.businessUnitId = vm.businessUnitId; // Setting base payroll processing
                //var fromDateMoment = moment(vm.leave.fromDate);
                //vm.filters.toDate = fromDateMoment.subtract(1, 'day');
                //vm.filters.toDate = moment(vm.filters.monthYear).endOf('month').endOf('day').subtract(1, 'milliseconds');


                vm.isProcess = true;
                payrollService.leaveProcessState(vm.filters)
                    .success((s) => {
                        vm.state = s;
                        if (s === 3) {
                            abp.message.warn('Unable to reprocess this month ,final settlement for this staff is already Processed and Approved.');
                            vm.isProcess = false;
                        }
                        else if (s === 2) {
                            vm.isProcess = true;
                            vm.isPayrollForSave = false;

                            abp.message.confirm(
                                'You want to Reprocess the final settlement? Previously saved final settlement for this month will be discarded',
                                'Are you sure?',
                                function (isConfirmed) {
                                    if (isConfirmed) {
                                        vm.filters.isReprocess = true;
                                        vm.leaveSalaryPayroll.ticketPrice = 0; //In Re-Processing
                                        vm.leaveSalaryPayroll.eligible = 0; //In Re-Processing
                                        vm.process();
                                    }
                                    else {
                                        vm.filters.isReprocess = false;
                                        vm.process();
                                    }
                                }
                            );
                        }
                        else {
                            vm.isProcess = true;
                            vm.isPayrollForSave = false;
                            vm.filters.isReprocess = false;

                            vm.process();
                        }
                    })
            }

            vm.approved = () => {
                vm.isApproving = true;

                payrollService.approved(vm.payroll.id)
                    .success(() => {
                        abp.notify.success("Successfully approved payroll.");
                    })
                    .finally(() => {
                        vm.isApproving = false;
                        vm.isPayrollForApprove = false;
                        vm.isApproved = true;
                    });
            }

            vm.rounding = (value) => {
                if (value === null) return null;

                return value.toLocaleString('en', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
            }


            vm.calculateTenureAndCompletedYears = function () {
                if (vm.lastWorkingDay != null && vm.firstWorkingDay != null) {
                    var lastWorkingDay = new Date(vm.lastWorkingDay);
                    var dateOfJoining = new Date(vm.firstWorkingDay);

                    if (lastWorkingDay.getTime() === dateOfJoining.getTime()) {
                        return {
                            tenure: "0 years, 0 months, 0 days",
                            completedYears: 0,
                            completedYearsDecimal: 0
                        };
                    }

                    // Check if the anniversary date is after the last working day
                    if (dateOfJoining > lastWorkingDay) {
                        return {
                            tenure: "Tenure information is not available.",
                            completedYears: 0,
                            completedYearsDecimal: 0
                        };
                    }

                    var years = lastWorkingDay.getFullYear() - dateOfJoining.getFullYear();
                    var months = lastWorkingDay.getMonth() - dateOfJoining.getMonth();
                    var days = lastWorkingDay.getDate() - dateOfJoining.getDate();

                    if (days < 0) {
                        months--;
                        var prevMonth = new Date(lastWorkingDay.getFullYear(), lastWorkingDay.getMonth(), 0);
                        days += prevMonth.getDate();
                    }

                    if (months < 0) {
                        years--;
                        months += 12;
                    }

                    var completedYears = years >= 0 ? years : 0; // Ensure no negative years

                    // Calculate completed years in decimal
                    var totalMonths = completedYears * 12 + months + (days / 30.44); // Average days in a month
                    var completedYearsDecimal = totalMonths / 12;

                    return {
                        tenure: `${years} years, ${months} months, ${days} days`,
                        completedYears: completedYears,
                        completedYearsDecimal: completedYearsDecimal.toFixed(3) // Format to 3 decimal places
                    };
                } else {
                    return {
                        tenure: "Tenure information is not available.",
                        completedYears: 0,
                        completedYearsDecimal: 0
                    };
                }
            };


            //vm.calculateTenureAndCompletedYears = function () {
            //    if (vm.lastWorkingDay != null && vm.firstWorkingDay != null) {
            //        var lastWorkingDay = new Date(vm.lastWorkingDay);
            //        var dateOfJoining = new Date(vm.firstWorkingDay);
            //        if (lastWorkingDay.getTime() === dateOfJoining.getTime()) {
            //            return {
            //                tenure: "0 years, 0 months, 0 days",
            //                completedYears: 0
            //            };
            //        }

            //        // Check if the anniversary date is after the last working day
            //        if (dateOfJoining > lastWorkingDay) {
            //            return {
            //                tenure: "Tenure information is not available.",
            //                completedYears: 0
            //            };
            //        }

            //        var years = lastWorkingDay.getFullYear() - dateOfJoining.getFullYear();
            //        var months = lastWorkingDay.getMonth() - dateOfJoining.getMonth();
            //        var days = lastWorkingDay.getDate() - dateOfJoining.getDate();

            //        if (days < 0) {
            //            months--;
            //            var prevMonth = new Date(lastWorkingDay.getFullYear(), lastWorkingDay.getMonth(), 0);
            //            days += prevMonth.getDate();
            //        }

            //        if (months < 0) {
            //            years--;
            //            months += 12;
            //        }

            //        var completedYears = years >= 0 ? years : 0; // Ensure no negative years

            //        return {
            //            tenure: `${years} years, ${months} months, ${days} days`,
            //            completedYears: completedYears
            //        };
            //    } else {
            //        return {
            //            tenure: "Tenure information is not available.",
            //            completedYears: 0
            //        };
            //    }
            //};

            vm.save = () => {
                vm.isSaving = true;

                // Update Ticket Value 
                if (vm.payroll && vm.payroll.payrollDetails) {
                    vm.payroll.payrollDetails.forEach(detail => {
                        if (vm.totalPayable > 0 && vm.leaveSalaryPayroll.ticketPrice > 0) {
                            // Perform updates on payrollDetail
                            detail.totalPayable = vm.totalPayable;
                            detail.oneTicketPrice = vm.leaveSalaryPayroll.ticketPrice;
                            detail.eligibilityPercentage = vm.leaveSalaryPayroll.eligible;
                            detail.isPayFullTicketPrice = vm.isPayFullTicketPriceAndAdjustInSalary;

                            //if (vm.leave && vm.leave.fromDate) {
                            //    detail.ticketIssuanceDate = vm.leave.fromDate;
                            //}
                            detail.ticketIssuanceDate = vm.lastWorkingDay; // Service end date is ticket issueance date

                            const ticketAmount = vm.isAdvanceTicketAmount && vm.isPayFullTicketPriceAndAdjustInSalary
                                ? vm.leaveSalaryPayroll.ticketPayable
                                : vm.leaveSalaryPayroll.payableValue;

                            detail.airTicket = ticketAmount;
                            detail.netSalary = detail.netSalary + ticketAmount; // Add ticket amount in net salary

                            // Check if ticket payrollLine exist and update the relevant line
                            if (detail.payrollLines) {
                                detail.payrollLines.forEach(line => {
                                    if (line.salaryItemId === 41) {
                                        line.amount = ticketAmount;
                                    }
                                    // Add advance loan in payroll line
                                    if (vm.isAdvanceTicketAmount && vm.isPayFullTicketPriceAndAdjustInSalary) {
                                        if (line.salaryItemId === 51) {
                                            line.amount = vm.leaveSalaryPayroll.amountAsAdvance;
                                        }
                                    }
                                });
                            }
                        }
                        detail.lastWorkingDay = vm.lastWorkingDay; // Save last working day
                    });
                }
                payrollService.save({
                    fromDate: vm.filters.fromDate,
                    toDate: vm.filters.toDate,
                    payroll: vm.payroll
                })
                    .success((id) => {
                        vm.payroll.id = id;
                        vm.isPayrollForApprove = true;
                        vm.isSaved = true;
                        abp.notify.success("Successfully saved payroll.");
                    })
                    .finally(() => {
                        vm.isSaving = false;
                        vm.isPayrollForSave = false;
                    });
            }

            vm.getAllBusinessUnits = () => {
                vm.loading = true;
                businessUnitService.getBusinessUnits({}).success(function (data) {
                    vm.businessUnits = data;
                }).finally(function () {

                });
            }

            init();

            function init() {
                // Get business units if setting is enabled
                if (vm.isBusinessUnitWisePayrollProcess)
                    vm.getAllBusinessUnits();

                designationDetails();
                vm.additionHeaders = [];
                vm.deductionHeaders = [];
                vm.isProcessEnabled = false;
                vm.isProcess = false;
                vm.isAdvanceTicketAmount = false;
                vm.isPayrollForSave = false;
                vm.isSaving = false;
                vm.isPayrollForApprove = false;
                vm.isApproving = false;
                vm.skipCount = 0;
                vm.batchSize = 1000;
                vm.totalCount = 0;
                vm.isSaved = false;
                vm.isApproved = false;
                vm.state = 1;
                vm.filters = {
                    skipCount: 0,
                    maxResultCount: vm.batchSize,
                    approvedAnnualLeaves: 0,
                    isCalculateGratuity: false
                    /*  isCalculateAsLeaveSalary: false,*/
                };
            }
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.common.hrm.leaveOpeningBalance.index', [
        '$scope', 'abp.services.app.leaveOpeningBalance', 'abp.services.app.leaveType',
        function ($scope, leaveOpeningBalanceService, leaveTypeService) {
            var vm = this;
            vm.loading = false;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.leaveTypeId = null;
            vm.modifiedLeaveRecordRows = [];

            vm.save = function () {
                vm.saving = true;

                var rawData = vm.modifiedLeaveRecordRows.length > 0 ? vm.modifiedLeaveRecordRows : vm.leaveOpeningBalanceList;
                var dataToSend = rawData.map(function (row) {
                    return {
                        leaveTypeId: row.leaveTypeId,
                        staffId: row.staff.id,
                        openingBalance: row.openingBalance,
                        lastRejoiningDate: row.lastRejoiningDate,
                        lastTicketIssuanceDate: row.lastTicketIssuanceDate,
                        cutOfDate: row.cutOfDate
                    };
                });

                leaveOpeningBalanceService.createOrUpdateLeaveOpeningBalance({
                    LeaveTypeId: vm.leaveTypeId,
                    LeaveOpeningBalance: dataToSend
                })
                    .success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        vm.getLeaveOpeningBalanceList();
                    })
                    .finally(function () {
                        vm.saving = false;
                        vm.modifiedLeaveRecordRows = [];
                    });
            };

            async function getLeaveTypes() {
                try {
                    const response = await leaveTypeService.getLeaveType({});
                    vm.leaveTypes = response.data.items;
                } catch (error) {

                }
            }

            vm.getLeaveOpeningBalanceList = () => {
                vm.loading = true;
                leaveOpeningBalanceService.getLeaveOpeningBalancesForEdit(vm.leaveTypeId)
                    .then((response) => {
                        if (response && response.data.items) {
                            vm.leaveOpeningBalanceList = response.data.items;
                        } else {
                            vm.leaveOpeningBalanceList = [];
                        }
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            vm.getAllLeaveOpeningBalance = () => {
                vm.loading = true;

                vm.selectedLeaveType = vm.leaveTypes.find(function (leaveType) {
                    return leaveType.id === vm.leaveTypeId;
                });

                leaveOpeningBalanceService.createOrUpdateLeaveOpeningBalance({
                    LeaveTypeId: vm.leaveTypeId,
                })
                    .then(function (response) {
                        vm.leaveOpeningBalanceList = response.data.items;
                    })
                    .finally(function () {
                        vm.loading = false;
                    });
            };

            vm.removeLeaveOpeningBalanceRow = function (row) {
                var index = vm.leaveOpeningBalanceList.indexOf(row);
                vm.leaveOpeningBalanceList.splice(index, 1);
            };

            vm.addLeaveOpeningBalanceRow = function (row) {
                if (vm.leaveOpeningBalanceList == undefined) {
                    vm.leaveOpeningBalanceList = [];
                }
                vm.leaveOpeningBalanceList.push(
                    {
                        staffId: null,
                        openingBalance: 0,
                        lastRejoiningDate: null,
                        lastTicketIssuanceDate: null,
                        cutOfDate: null,
                    });
            };

            function init() {
                getLeaveTypes();
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.common.hrm.leaveSalaryPayroll.index', [
        '$scope', '$uibModal', 'abp.services.app.directory', 'abp.services.app.leaveSalaryPayroll', 'abp.services.app.payroll', 'abp.services.app.staff', 'abp.services.app.designation', 'abp.services.app.businessUnit',
        function ($scope, $uibModal, directoryService, leaveSalaryPayrollService, payrollService, staffService, designationService, businessUnitService) {

            var vm = this;
            vm.isBusinessUnitWisePayrollProcess = abp.setting.getBoolean("App.Speed.Hrm.IsBusinessUnitsWisePayrollProcess");

            vm.loading = false;
            vm.isPayFullTicketPriceAndAdjustInSalary = false
            vm.leaveDetails = null;
            vm.totalPayable = 0;
            vm.additional = 0;
            vm.airTicketPrice = 0;
            vm.leaveSalaryPayroll = {
                /*ticketPrice: 0,*/
                eligible: 0,
                payableValue: 0
            };
            //vm.startDate = new Date(date);
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.isGranted = (permission) => {
                return abp.auth.isGranted(permission);
            }
            var designationDetails = function () {
                designationService.getDesignations().success(function (result) {
                    vm.designationDetails = result.items;
                    //console.log(test);
                });
            };
            vm.clearStaff = function () {
                vm.staff = null;
                vm.staffId = null;
                vm.leave = null;
                vm.payroll = null;

            };
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                } else {
                    return "";
                }
            };
            vm.calculateTotal = (pd, ticketPrize) => {
                if (!pd) return 0;
                vm.totalPayable = (parseFloat(pd.netPay) || 0) + (parseFloat(ticketPrize) || 0) + (parseFloat(pd.leaveSalary) || 0);
                return vm.totalPayable;
            };
            vm.calculateTicket = (count, prize) => {

                const countValue = parseFloat(count);
                const prizeValue = parseFloat(prize);

                if (isNaN(countValue) || isNaN(prizeValue)) return 0;

                return countValue * prizeValue;
            };

            vm.searchStaff = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customers). get customers
                return directoryService.searchStaffForHrm({ keyword: $select.search, contactType: 1, activeOnly: true }).then(function (response) {
                    vm.staffs = response.data.items;
                });
            };

            vm.searchStaffPopoup = async function () {
                try {
                    vm.loading = true;
                    vm.isProcess = true;
                    if (vm.staff) {
                        vm.businessUnitId = vm.staff.businessUnitId;
                    }
                    // Fetch staff details
                    const staffResponse = await staffService.getStaffForEdit({ id: vm.staff.id });
                    vm.staffs = staffResponse.data.items;
                    vm.staff = staffResponse.data;
                    vm.airTicket = vm.staff.staffWiseEligibilities.find(x => x.salaryItemTypeId == 41);

                    // Fetch recent leave details
                    await vm.getStaffRecentLeaveDetails(vm.staff.id, vm.filters.isCalculateGratuity);

                    // Fetch recent ticket details
                    await vm.getStaffRecentTicketDetails(vm.staff.id);
                    vm.processReferesh();
                } catch (error) {
                    vm.isProcess = false;
                    return;
                }
                finally {
                    vm.loading = false;
                    /*vm.isProcess = false;*/
                }
            };


            vm.getStaffRecentLeaveDetails = async function (staffId, isCalculateGratuity) {
                try {
                    const response = await leaveSalaryPayrollService.getStaffRecentLeaveDetails(staffId, isCalculateGratuity);
                    vm.leave = response.data;
                    vm.leaveDetails = vm.leave;
                    vm.leaveTicketStartDate = vm.leave.leaveType.leaveStartFrom;


                    if (vm.leave && vm.leave.fromDate && vm.leave.toDate) {
                        let startDate = moment(vm.leave.fromDate);
                        let endDate = moment(vm.leave.toDate);

                        if (startDate.isValid() && endDate.isValid()) {
                            vm.filters.approvedAnnualLeaves = endDate.diff(startDate, 'days') + 1;
                        } else {

                            vm.filters.approvedAnnualLeaves = 0;
                        }
                    } else {

                        vm.filters.approvedAnnualLeaves = 0;
                    }
                } catch (error) {
                    vm.isProcess = false;
                    $scope.$apply();
                    throw error;
                }
                finally {
                    vm.loading = false;
                    /* vm.isProcess = false;*/
                }
            };

            vm.getStaffRecentTicketDetails = async function (staffId) {
                try {
                    const response = await leaveSalaryPayrollService.getStaffRecentTicketDetails(staffId);
                    vm.lastTicketPayrollDetails = response.data;

                    if (vm.lastTicketPayrollDetails && vm.lastTicketPayrollDetails.ticketIssuanceDate !== vm.leave.fromDate) {
                        // Check for same date in case of cancel reprocess
                        /*if (vm.lastTicketPayrollDetails.ticketIssuanceDate !== vm.leave.fromDate)*/
                        vm.lastTicketDate = vm.lastTicketPayrollDetails.ticketIssuanceDate;
                    } else if (vm.leave && vm.leave.leaveType) {
                        let date;
                        if (vm.leave.leaveType.leaveStartFrom == 1) {
                            date = vm.staff.dateOfJoining;
                        } else if (vm.leave.leaveType.leaveStartFrom == 2) {
                            date = vm.staff.dateOfConfirmation;
                        }
                        vm.lastTicketDate = new Date(date);
                        /*vm.lastTicketDate = new Date('2024-01-22T00:00:00Z');*/

                    }
                    $scope.$apply();
                } catch (error) {
                    console.error('Error in getStaffRecentTicketDetails:', error);
                }
            };

            vm.calculateEligibleValue = function () {
                if (!vm.lastTicketDate || !moment(vm.lastTicketDate).isValid()) {
                    console.error('Invalid last ticket date');
                    return;
                }

                if (vm.leaveSalaryPayroll.ticketPrice <= 0 || vm.airTicket.eligibleFor <= 0) {
                    console.error('Invalid ticket price or eligibility');
                    return;
                }


                // Extra section that should replace with below line 

                var ticketDate = moment(vm.leave.fromDate);
                var dateDifference = ticketDate.diff(moment(vm.lastTicketDate), 'days'); // Not include leave start day 
                //
                //var currentDate = moment(new Date());
                //var dateDifference = currentDate.diff(moment(vm.lastTicketDate), 'days') + 1; // Include both dates

                // Define the thresholds
                var oneYearInDays = 365.25;
                var eligibleDays = Math.floor(dateDifference);

                if (eligibleDays > oneYearInDays) {
                    var eligibleYears = Math.floor(eligibleDays / oneYearInDays);
                    var remainingDays = eligibleDays % oneYearInDays;

                    vm.leaveSalaryPayroll.payableValue = eligibleYears * vm.airTicket.eligibleFor * vm.leaveSalaryPayroll.ticketPrice;

                    if (remainingDays > 0) {
                        var additionalMonths = remainingDays / 30; // Approximate to months
                        var proRatedValue = (additionalMonths / 12) * vm.airTicket.eligibleFor * vm.leaveSalaryPayroll.ticketPrice;
                        vm.leaveSalaryPayroll.payableValue += Math.floor(proRatedValue);
                    }

                    vm.leaveSalaryPayroll.eligible = 100; // Eligible for full amount
                } else {
                    vm.isTicketForFirstTime = vm.checkAirTicketForFirstTime();// Check get air ticket for first time
                    if (!vm.isTicketForFirstTime) {
                        vm.leaveSalaryPayroll.payableValue = Math.floor((eligibleDays / oneYearInDays) * vm.airTicket.eligibleFor * vm.leaveSalaryPayroll.ticketPrice);
                        vm.leaveSalaryPayroll.eligible = (eligibleDays / oneYearInDays) * 100;
                    }
                    else {
                        vm.leaveSalaryPayroll.payableValue = 0;
                        vm.leaveSalaryPayroll.eligible = 0;
                    }
                }

                vm.leaveSalaryPayroll.ticketQuota = vm.airTicket.eligibleFor;
                vm.leaveSalaryPayroll.receivableFromEmployee = vm.leaveSalaryPayroll.payableValue - vm.leaveSalaryPayroll.ticketQuota;

                if (vm.leaveSalaryPayroll.payableValue < vm.leaveSalaryPayroll.ticketPrice && !vm.isTicketForFirstTime) {
                    vm.isAdvanceTicketAmount = true;
                    vm.leaveSalaryPayroll.ticketPayable = vm.leaveSalaryPayroll.ticketPrice;
                    vm.leaveSalaryPayroll.amountAsAdvance = vm.leaveSalaryPayroll.ticketPrice - vm.leaveSalaryPayroll.payableValue;
                } else {
                    vm.isAdvanceTicketAmount = false;
                }
            };

            // Check air ticket for first time
            vm.checkAirTicketForFirstTime = function () {

                if (vm.staff != null && vm.staff.dateOfJoining != null && vm.staff.dateOfConfirmation != null) {
                    if (vm.lastTicketDate != null) {
                        if (moment(vm.lastTicketDate).isSame(moment(vm.staff.dateOfJoining)) ||
                            moment(vm.lastTicketDate).isSame(moment(vm.staff.dateOfConfirmation))) {
                            return true;
                        }
                    }
                }
                return false;
            }

            // Previous code
            //vm.calculateEligibleValue = function () {


            //    var currentDate = moment(new Date());

            //    var dateDifference = currentDate - vm.lastTicketDate;


            //    // Convert milliseconds to years
            //    var yearsDifference = dateDifference / (365.25 * 24 * 60 * 60 * 1000);
            //    // Round the result to get the whole years
            //    //var roundedYearsDifference = Math.floor(yearsDifference);

            //    /*if (yearsDifference >= 1) {*/ // remove check for minimum one year eligiblity
            //        if (yearsDifference >= vm.airTicket.afterYears) {
            //            //vm.leaveSalaryPayroll.payableValue = vm.airTicket.eligibleFor;
            //            vm.leaveSalaryPayroll.payableValue = vm.airTicket.eligibleFor * (vm.leaveSalaryPayroll.ticketPrice);
            //            vm.leaveSalaryPayroll.eligible = 100;
            //        }
            //        else {
            //           //vm.leaveSalaryPayroll.payableValue = Math.floor(((yearsDifference / vm.airTicket.afterYears)) * vm.airTicket.eligibleFor);
            //            vm.leaveSalaryPayroll.payableValue = Math.floor(((yearsDifference / vm.airTicket.afterYears)) * vm.leaveSalaryPayroll.ticketPrice * vm.airTicket.eligibleFor);
            //            vm.leaveSalaryPayroll.eligible = (yearsDifference / vm.airTicket.afterYears) * 100;
            //        }
            //        vm.leaveSalaryPayroll.ticketQuota = vm.airTicket.eligibleFor
            //        vm.leaveSalaryPayroll.receivableFromEmployee = vm.leaveSalaryPayroll.payableValue - vm.leaveSalaryPayroll.ticketQuota
            //        if (vm.leaveSalaryPayroll.payableValue < vm.leaveSalaryPayroll.ticketPrice)
            //        {
            //            vm.isAdvanceTicketAmount = true;
            //            vm.leaveSalaryPayroll.ticketPayable = vm.leaveSalaryPayroll.ticketPrice;
            //            vm.leaveSalaryPayroll.amountAsAdvance = vm.leaveSalaryPayroll.ticketPrice - vm.leaveSalaryPayroll.payableValue;
            //        }
            //        else
            //        {
            //            vm.isAdvanceTicketAmount = false;
            //        }
            //    //}
            //    //else {
            //    //    vm.leaveSalaryPayroll.ticketQuota = 0;
            //    //    vm.leaveSalaryPayroll.payableValue = 0;
            //    //    vm.leaveSalaryPayroll.receivableFromEmployee = 0;
            //    //    vm.leaveSalaryPayroll.eligible = 0;
            //    //}
            //}

            vm.ontTicketPriceChange = function () {
                vm.leaveSalaryPayroll.receivableFromEmployee = vm.leaveSalaryPayroll.ticketQuota - vm.leaveSalaryPayroll.payableValue;
            }


            vm.process = () => {
                vm.filters.staffId = vm.staff.id;
                // check here for exception on receivableFromEmployee
                /*vm.filters.receivableFromEmployee = vm.leaveSalaryPayroll.receivableFromEmployee;*/
                vm.filters.payableValue = vm.leaveSalaryPayroll.payableValue;

                vm.filters.skipCount = vm.skipCount;
                vm.filters.annualLeavesStartDate = moment(vm.leave.fromDate);
                /*vm.filters.noOfAnnualLeaves = vm.leave.leaveType?.noOfLeaves;*/
                vm.filters.noOfAnnualLeaves = vm.leave.fullPaidDays; // Get no of paid days 

                /*vm.filters.isCalculateAsLeaveSalary = vm.leave?.leaveType?.calculateAsLeaveSalary;*/
                vm.loading = false;
                //Get Re-joining Date
                if (vm.leaveDetails != null && vm.staff != null) {
                    leaveSalaryPayrollService.getReJoiningDate(vm.staff.id, vm.leaveDetails.leaveTypeId).then(function (response) {
                        vm.lastReJoiningDate = response.data;
                        vm.leaveDuration = vm.filters.approvedAnnualLeaves;
                        vm.noOfAnnualLeaves = vm.filters.noOfAnnualLeaves;
                    });
                }

                payrollService.processLeaveTicket(vm.filters)
                    .success((r) => {
                        let payroll = r.payroll;
                        vm.totalCount = r.totalCount;
                        payroll.payrollDetails.forEach(pd => {
                            pd.payrollLines.forEach(pl => {
                                if (pl.type === 1 && !vm.additionHeaders.find(ah => ah.name === pl.name)) {
                                    vm.additionHeaders.push({ name: pl.name, order: pl.order });
                                }
                                else if (pl.type === 2 && !vm.deductionHeaders.find(dh => dh.name === pl.name)) {
                                    vm.deductionHeaders.push({ name: pl.name, order: pl.order });
                                }
                            });

                            additionAndDeductionValues(pd);
                            //payrollCalculation(pd);

                            pd.getSalaryItemAmount = (name) => {
                                let salaryItem = pd.payrollLines.find(pl => pl.name === name);
                                return salaryItem ? salaryItem.amount : 0;
                            }
                        });

                        if (!vm.payroll) {
                            vm.payroll = payroll;
                            // Get Ticket Value In Case Of Cancel Re-Process
                            if (vm.payroll && vm.payroll.payrollDetails && vm.payroll.payrollDetails.length > 0) // Add check for payrollDetails not empty
                            {
                                vm.airTicketPrice = vm.payroll.payrollDetails[0].airTicket;
                                if (vm.airTicketPrice > 0) {
                                    vm.leaveSalaryPayroll.payableValue = vm.airTicketPrice;
                                    vm.leaveSalaryPayroll.ticketPrice = vm.payroll.payrollDetails[0].oneTicketPrice;
                                    vm.leaveSalaryPayroll.eligible = vm.payroll.payrollDetails[0].eligibilityPercentage;
                                    vm.isPayFullTicketPriceAndAdjustInSalary = vm.payroll.payrollDetails[0].isPayFullTicketPrice;
                                }
                                else {
                                    vm.leaveSalaryPayroll.payableValue = 0;
                                    /*vm.leaveSalaryPayroll.ticketPrice = 0;*/
                                    vm.leaveSalaryPayroll.eligible = 0;
                                    vm.isPayFullTicketPriceAndAdjustInSalary = false;
                                }
                            }

                        }
                        else {
                            payroll.payrollDetails.forEach(pd => {
                                vm.payroll.payrollDetails.push(pd);
                            });
                        }
                        vm.payroll.payrollDetails.sort((pd1, pd2) => pd1.netPay < pd2.netPay ? 1 : -1);

                        // Comment batchwaise processing work
                        //vm.skipCount = vm.skipCount + vm.batchSize;
                        //if (vm.skipCount < vm.totalCount)
                        //    vm.process();
                        //else
                        //{
                        //    vm.isProcess = false;
                        //    if (vm.state === 2 && !vm.filters.isReprocess)
                        //    {
                        //        vm.isPayrollForSave = false;
                        //        vm.isPayrollForApprove = true;
                        //    }
                        //    else if (vm.state === 2 && vm.filters.isReprocess)
                        //    {
                        //        vm.isPayrollForSave = true;
                        //        vm.isPayrollForApprove = false;
                        //        vm.isSaved = false;
                        //    }
                        //    else {
                        //        vm.isPayrollForSave = true;

                        //    }
                        //    vm.isProcessEnabled = false;
                        //}

                        vm.isProcess = false;
                        if (vm.state === 2 && !vm.filters.isReprocess) {
                            vm.isPayrollForSave = false;
                            vm.isPayrollForApprove = true;
                        }
                        else if (vm.state === 2 && vm.filters.isReprocess) {
                            vm.isPayrollForSave = true;
                            vm.isPayrollForApprove = false;
                            vm.isSaved = false;
                        }
                        else {
                            vm.isPayrollForSave = true;

                        }
                        vm.isProcessEnabled = false;
                    })
                    .finally(() => {
                        vm.isProcess = false;
                    });
            }
            function additionAndDeductionValues(pd) {
                pd.additionValues = [];
                pd.deductionValues = [];
                vm.additionHeaders.forEach(h => {
                    let v = pd.additionValues.find(x => x.name === h.name);
                    if (!v) {
                        let pl = pd.payrollLines.find(x => x.name === h.name);
                        pd.additionValues.push({ name: h.name, order: h.order, amount: pl ? pl.amount : 0 });
                    }

                });
                vm.deductionHeaders.forEach(h => {
                    let v = pd.deductionValues.find(x => x.name === h.name);
                    if (!v) {
                        let pl = pd.payrollLines.find(x => x.name === h.name);
                        pd.deductionValues.push({ name: h.name, order: h.order, amount: pl ? pl.amount : 0 });
                    }
                });
            }

            vm.processReferesh = () => {
                vm.payroll = null;
                vm.skipCount = 0;
                vm.filters.fromDate = moment(vm.leave.fromDate).startOf('month').startOf('day');
                //vm.filters.toDate = moment(vm.leave.toDate);
                // Assuming vm.leave.toDate is a date string or a date object
                vm.filters.toDate = moment(vm.leave.fromDate).subtract(1, 'days');
                vm.filters.staffId = vm.staff.id;
                vm.filters.businessUnitId = vm.businessUnitId; // Setting base payroll processing
                //var fromDateMoment = moment(vm.leave.fromDate);
                //vm.filters.toDate = fromDateMoment.subtract(1, 'day');
                //vm.filters.toDate = moment(vm.filters.monthYear).endOf('month').endOf('day').subtract(1, 'milliseconds');


                vm.isProcess = true;
                payrollService.leaveProcessState(vm.filters)
                    .success((s) => {
                        vm.state = s;
                        if (s === 3) {
                            abp.message.warn('Unable to reprocess this month ,Payroll for this month is already Processed and Approved.');
                            vm.isProcess = false;
                        }
                        else if (s === 2) {
                            vm.isProcess = true;
                            vm.isPayrollForSave = false;

                            abp.message.confirm(
                                'You want to Reprocess the payroll? Previously saved payroll for this month will be discarded',
                                'Are you sure?',
                                function (isConfirmed) {
                                    if (isConfirmed) {
                                        vm.filters.isReprocess = true;
                                        vm.leaveSalaryPayroll.ticketPrice = 0; //In Re-Processing
                                        vm.leaveSalaryPayroll.eligible = 0; //In Re-Processing
                                        vm.process();
                                    }
                                    else {
                                        vm.filters.isReprocess = false;
                                        vm.process();
                                    }
                                }
                            );
                        }
                        else {
                            vm.isProcess = true;
                            vm.isPayrollForSave = false;
                            vm.filters.isReprocess = false;

                            vm.process();
                        }
                    })
            }

            vm.approved = () => {
                vm.isApproving = true;

                payrollService.approved(vm.payroll.id)
                    .success(() => {
                        abp.notify.success("Successfully approved payroll.");
                    })
                    .finally(() => {
                        vm.isApproving = false;
                        vm.isPayrollForApprove = false;
                        vm.isApproved = true;
                    });
            }

            vm.rounding = (value) => {
                if (value === null) return null;

                return value.toLocaleString('en', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
            }

            vm.save = () => {
                vm.isSaving = true;

                // Update Ticket Value 
                if (vm.totalPayable > 0 && vm.leaveSalaryPayroll.ticketPrice > 0) {
                    if (vm.payroll && vm.payroll.payrollDetails) {
                        vm.payroll.payrollDetails.forEach(detail => {
                            // Perform updates on payrollDetail
                            detail.totalPayable = vm.totalPayable;
                            detail.oneTicketPrice = vm.leaveSalaryPayroll.ticketPrice;
                            detail.eligibilityPercentage = vm.leaveSalaryPayroll.eligible;
                            detail.isPayFullTicketPrice = vm.isPayFullTicketPriceAndAdjustInSalary;
                            if (vm.leave && vm.leave.fromDate) {
                                detail.ticketIssuanceDate = vm.leave.fromDate;
                            }

                            const ticketAmount = vm.isAdvanceTicketAmount && vm.isPayFullTicketPriceAndAdjustInSalary
                                ? vm.leaveSalaryPayroll.ticketPayable
                                : vm.leaveSalaryPayroll.payableValue;

                            detail.airTicket = ticketAmount;
                            detail.netSalary = detail.netSalary + ticketAmount; // Add ticket amount in net salary
                            // Check if ticket payrollLine exist and update the relevant line
                            if (detail.payrollLines) {
                                detail.payrollLines.forEach(line => {
                                    if (line.salaryItemId === 41) {
                                        line.amount = ticketAmount;
                                    }
                                    // Add advance loan in payroll line
                                    if (vm.isAdvanceTicketAmount && vm.isPayFullTicketPriceAndAdjustInSalary) {
                                        if (line.salaryItemId === 51) {
                                            line.amount = vm.leaveSalaryPayroll.amountAsAdvance;
                                        }
                                    }
                                });
                            }
                        });
                    }
                }
                payrollService.save({
                    fromDate: vm.filters.fromDate,
                    toDate: vm.filters.toDate,
                    payroll: vm.payroll
                })
                    .success((id) => {
                        vm.payroll.id = id;
                        vm.isPayrollForApprove = true;
                        vm.isSaved = true;
                        abp.notify.success("Successfully saved payroll.");
                    })
                    .finally(() => {
                        vm.isSaving = false;
                        vm.isPayrollForSave = false;
                    });
            }

            vm.getAllBusinessUnits = () => {
                vm.loading = true;
                businessUnitService.getBusinessUnits({}).success(function (data) {
                    vm.businessUnits = data;
                }).finally(function () {

                });
            }

            init();

            function init() {
                // Get business units if setting is enabled
                if (vm.isBusinessUnitWisePayrollProcess)
                    vm.getAllBusinessUnits();

                designationDetails();
                vm.additionHeaders = [];
                vm.deductionHeaders = [];
                vm.isProcessEnabled = false;
                vm.isProcess = false;
                vm.isAdvanceTicketAmount = false;
                vm.isPayrollForSave = false;
                vm.isSaving = false;
                vm.isPayrollForApprove = false;
                vm.isApproving = false;
                vm.skipCount = 0;
                vm.batchSize = 1000;
                vm.totalCount = 0;
                vm.isSaved = false;
                vm.isApproved = false;
                vm.state = 1;
                vm.filters = {
                    skipCount: 0,
                    maxResultCount: vm.batchSize,
                    approvedAnnualLeaves: 0,
                    isCalculateGratuity: false
                    /*  isCalculateAsLeaveSalary: false,*/
                };
            }
        }
    ]);
})();;
