            vm.amortization.Date =
            vm.accural = {
                accrualMonth: moment(vm.filters.monthYear).endOf('month').startOf('day').utc(),
                detail: vm.data
            }
            accrualService.createOrUpdateAccrual(vm.accural).success(function () {
                abp.notify.info(app.localize('SavedSuccessfully'));

            }).finally(function () {
                vm.saving = false;
            });
