(function () {
    appModule.controller('tenant.views.crs.accounting.cashFlowStatement.cashFlowSettingsModal', [
        '$uibModal', '$uibModalInstance', 'abp.services.app.cashFlowStatement', 'abp.services.app.account',
        function ($uibModal, $uibModalInstance, cashFlowStatementService, accountService) {

            var vm = this;
            var accounts = [];
            //vm.creditCard = contactCreditCard;

            //vm.creditCardTypes = [{ id: 1, name: 'MasterCard' }, { id: 2, name: 'Visa' }, { id: 3, name: 'AmericanExpress' }];



            vm.selectAccount = (data) => {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/accounting/cashFlowStatement/selectAccountModal.cshtml',
                    controller: 'tenant.views.crs.accounting.cashFlowStatement.selectAccountModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        accountCategory: function () {
                            return data.accountCategory;
                        },
                        selectedAccountIds: function () {
                            return data.accountIds;
                        }

                    }

                }).result.then(function (result) {
                    data.accountIds = result;
                    fillAccounts();
                });

            }

            function fillAccounts() {
                vm.settingTemplate.operatingActivities.forEach((row) => {
                    row.accountNames = accounts
                        .filter(e => row.accountIds.includes(e.id))
                        .map(e => e.accountCode + "-" + e.name)
                        .join(", ");
                });

                vm.settingTemplate.investingActivities.forEach((row) => {
                    row.accountNames = accounts
                        .filter(e => row.accountIds.includes(e.id))
                        .map(e => e.accountCode + "-" + e.name)
                        .join(", ");
                });

                vm.settingTemplate.financingActivities.forEach((row) => {
                    row.accountNames = accounts
                        .filter(e => row.accountIds.includes(e.id))
                        .map(e => e.accountCode + "-" + e.name)
                        .join(", ");
                });
            }

            function getCashFlowStatementTemplate() {
                cashFlowStatementService.getTemplate().success(function (data) {
                    vm.settingTemplate = data;
                    vm.loading = false;
                    fillAccounts();
                });
            }

            function getAccounts() {
                vm.loading = true;
                accountService.getAccounts().success(function (data) {
                    accounts = data.items.filter(e => e.isLeaf);
                    getCashFlowStatementTemplate();
                })
            }

            vm.save = function () {
                vm.saving = true;
                cashFlowStatementService.saveCashFlowTemplate(vm.settingTemplate).success(function () {
                    vm.saving = false;
                    $uibModalInstance.close(vm.creditCard);
                })
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                getAccounts();
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.crs.accounting.cashFlowStatement.index', [
        '$scope', '$uibModal', 'abp.services.app.fiscalYear', 'abp.services.app.fiscalMonth',  'utilities', 'abp.services.app.cashFlowStatement',
        function ($scope, $uibModal, fiscalYearService, fiscalMonthsService, utilities, cashFlowStatementService) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
            vm.filters = {
                fiscalYearId: null,
                fiscalMonthId: null,
                isFascalMonthActive: false,
                

            };
            vm.loading = false;

            vm.dateFormat = abp.setting.get("App.General.DateFormat");

            vm.cashFlowSettingPermission = abp.auth.hasPermission('Pages.Administration.Tenant.Settings');
            vm.currencyAndRoundingWithThree = function (value) {
                if (value == null) return null;

                return value.toLocaleString('en', { minimumFractionDigits: 3, maximumFractionDigits: 3 })
            };


            vm.roundingforView = function (value) {
                var roundedValue = utilities.roundforView(value, 2);
                return roundedValue.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            };
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.getFiscalYears = function () {
                vm.loading = true;
                fiscalYearService.getFiscalYearsDesc().success(function (data) {
                    vm.fiscalYears = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };
            vm.getMonthYear = function (date) { return date.add(1, 'days').format('MMM-YYYY'); };
            vm.getMonths = function () {
                
                
                
                //input.startDate = moment(moment(vm.fiscalYear.startDate).format('YYYY-MM-DD')).utc();
                //input.endDate = moment(moment(vm.fiscalYear.endDate).format('YYYY-MM-DD')).utc();
                if (vm.filters.fiscalYear)
                {
                    

                    vm.filters.fiscalYearId = vm.filters.fiscalYear.id;
                    vm.filters.startDate = vm.filters.fiscalYear.startDate;
                    vm.filters.endDate = vm.filters.fiscalYear.endDate;
                        fiscalMonthsService.getFiscalMonths(vm.filters).success(function (data) {


                            vm.fiscalMonths = data.items;

                        }).finally(function () {
                            vm.loading = false;
                        });
                    
                }
                    
                //input.id = null;
                

                

            };
            
            vm.rounding = function (value) {
                var result = utilities.round(value, 2);
                if (result % 1 != 0) {
                    return result;
                }
                else {
                    return result.toFixed(2);
                }
            };

            vm.formatNumber = function (amount) {
                if (amount == null) return null;
                var roundedAmount = vm.roundingforView(amount);
                return roundedAmount.toLocaleString('en');
            };

            vm.openSettingModal = () => {
                 $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/accounting/cashFlowStatement/cashFlowSettingsModal.cshtml',
                    controller: 'tenant.views.crs.accounting.cashFlowStatement.cashFlowSettingsModal as vm',
                     backdrop: 'static',
                    size:'lg'
                    //resolve: {
                    //    contactCreditCard: function () {
                    //        return {};
                    //    }

                    //}

                });

            }


            vm.exportToExcel = function (tableId) {

                var tab_text = "<table border='1px'><tr>";
                var textRange;
                var j = 0;
                var tab1 = document.getElementById(tableId); // id of table
                for (j = 0; j < tab1.rows.length; j++) {

                    tab_text = tab_text;
                    tab_text = tab_text + tab1.rows[j].innerHTML.toUpperCase() + "</tr>";
                }
                tab_text = tab_text + "</table>";

                var blob = b64toBlob(btoa(unescape(encodeURIComponent(tab_text))), "application/vnd.ms-excel");
                var blobUrl = URL.createObjectURL(blob);

                var a = document.createElement('a');
                a.href = blobUrl;
                a.download = 'CashFlowStatement.xls';
                a.click();
            };

            function b64toBlob(b64Data, contentType, sliceSize) {
                contentType = contentType || '';
                sliceSize = sliceSize || 512;

                var byteCharacters = atob(b64Data);
                var byteArrays = [];

                for (var offset = 0; offset < byteCharacters.length; offset += sliceSize) {
                    var slice = byteCharacters.slice(offset, offset + sliceSize);

                    var byteNumbers = new Array(slice.length);
                    for (var i = 0; i < slice.length; i++) {
                        byteNumbers[i] = slice.charCodeAt(i);
                    }

                    var byteArray = new Uint8Array(byteNumbers);

                    byteArrays.push(byteArray);
                }

                var blob = new Blob(byteArrays, { type: contentType });
                return blob;
            }

            function formatFields() {
                vm.data.income = vm.formatNumber(vm.data.income);
                vm.data.operatingActivitiesCashFlow = vm.formatNumber(vm.data.operatingActivitiesCashFlow);
                vm.data.investingActivitiesCashFlow = vm.formatNumber(vm.data.investingActivitiesCashFlow);
                vm.data.financingActivitiesCashFlow = vm.formatNumber(vm.data.financingActivitiesCashFlow);
                vm.data.cashFlow = vm.formatNumber(vm.data.cashFlow);
                vm.data.operatingActivities.forEach(e => e.value = vm.formatNumber(e.value));
                vm.data.investingActivities.forEach(e => e.value = vm.formatNumber(e.value));
                vm.data.financingActivities.forEach(e => e.value = vm.formatNumber(e.value));
            }

            vm.getcashFlowStatements = function () {
                vm.loading = true;
                if (vm.filters.fiscalMonth) {
                    vm.filters.fiscalMonthId = vm.filters.fiscalMonth.id;
                }
                    
                else {
                    vm.filters.fiscalMonthId = null;
                }
                if (vm.filters.fiscalYear)
                    vm.filters.fiscalYearId = vm.filters.fiscalYear.id;
                //vm.filters.fiscalYear = null;
                //vm.filters.fiscalMonth = null;
                cashFlowStatementService.getCashFlowStatement(vm.filters).success(function (data) {
                    vm.data = data;
                    formatFields();
                }).finally(() => vm.loading = false);
            }

            function init() {
                vm.getFiscalYears();
            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.crs.accounting.cashFlowStatement.selectAccountModal', [
        '$scope', 'abp.services.app.account', 'accountCategory', 'selectedAccountIds','$uibModalInstance',
        function ($scope, accountService, accountCategory, selectedAccountIds, $uibModalInstance) {

            var vm = this;
            vm.accounts = [];

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.loading = false;

            vm.accountCheckedOrUnchecked = function (account) {
                    vm.accounts.filter(e => e.parentId == account.id)
                        .forEach((row) => row.isChecked = account.isChecked);
            }

            vm.getAccounts = function () {
                vm.loading = true;
                accountService.getAccountsOnCategory({ id: accountCategory}).success(function (data) {
                    vm.accounts = data.items;
                    vm.accounts.filter(e => selectedAccountIds.includes(e.id)).forEach(e => e.isChecked = true);

                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.getAccounts();

            vm.save = function () {
                var accountIdsToReturn = vm.accounts.filter(e => e.isChecked).map(r => r.id);
                $uibModalInstance.close(accountIdsToReturn);
            }

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

        }
    ]);
})();;
