(function () {
    appModule.controller('tenant.views.crs.agreementsDashboard2.viewReceivedDetails', ['$scope', '$stateParams', 'abp.services.app.commonAgreement',
        '$stateParams', 'abp.services.app.commonLookup', 'utilities',
        function ($scope, $stateParams, commonAgreementService, $stateParams, commonLookupService, utilities) {

            var vm = this;
            vm.enableManualAgreementNo = utilities.parseBoolean(abp.setting.get("App.General.EnableManualAgreementNo"));
            vm.oneReceiptOnMultipleAgreement = abp.features.isEnabled("CRS.CustomFeatures.OneReceiptOnMultipleAgreement");
            vm.filters = null;

            if ($scope.$parent !== null) {
                if ($scope.$parent.vmMain !== null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters === null)
                vm.filters = $stateParams.filters;
            vm.getType = function (type) {
                if (type == 2) {
                    return app.localize("Receipt");
                } else if (type == 3) {
                    return app.localize("Payment");
                } else if (type == 7) {
                    return app.localize("OpeningBalance");
                } else {
                    return "";
                }

            };
            var vm = this;
            vm.saving = false;
            vm.total = 0;
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.agreementDetail = vm.filters.agreementForReceviced;
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            vm.getlocalDate = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };
            vm.getType = function (type) {
                if (type == 2) {
                    return app.localize("Receipt");
                } else if (type == 3) {
                    return app.localize("Payment");
                } else if (type == 7) {
                    return app.localize("OpeningBalance");
                } else if (type == 20) {
                    return app.localize("UsedDeposit");
                } else {
                    return "";
                }

            };


            function init() {
                vm.loading = true;
                commonAgreementService.getReceiptsByAgreementId({
                    id: vm.filters.agreementForReceviced.id

                }).success(function (result) {
                    vm.loading = false;
                    vm.receipts = result.items;

                    angular.forEach(vm.receipts, function (receipt) {
                        //if (receipt.type == 2 || receipt.type == 7)
                        //{
                        //    vm.total = vm.total + receipt.amount;
                        //}
                        //if (receipt.type == 3) {
                        //    vm.total = vm.total - receipt.amount;

                        //}
                        if (receipt.status != 5)
                            vm.total = vm.total + receipt.amountOnAgreement;
                        
                    });


                });
            }

            init();
        }]);
})();;
(function () {
    appModule.controller('tenant.views.crs.assets.assets.createOrEditModal', [
        '$uibModal', '$uibModalInstance', 'abp.services.app.asset', 'utilities', 'assetId', 'fiscalYear', 'abp.services.app.costCenter', 'abp.services.app.directory', 'abp.services.app.commonLookup',
        function ($uibModal, $uibModalInstance, assetService, utilities, assetId, fiscalYear, costCenterService, directoryService,lookupService) {

            var vm = this;
            vm.assets = {};
            vm.saving = false;
            vm.isEditMod = false;
            vm.totalOfChildAssetsPrice = 0;
            vm.minResidualValue = 1;
            vm.childAssetToRemove = {};
            vm.showOpeningDepr = false;
            vm.saveAndPrint = false;
            vm.isCostCenterEnabled = abp.features.isEnabled("Core.CostCenters");
            vm.isDealershipDiscountEnabled = abp.features.isEnabled("CRS.CustomFeatures.DiscountOnAssetFromDealership");
            vm.isCostCenter2Enabled = utilities.parseBoolean(abp.setting.get("App.Speed.Common.IsCostCenterGroup2Enabled"));
            vm.getCostCenterGroup = function (id) {
                if (id == 1)
                    return app.localize("CostCenterGroup1");
                else if (id == 2)
                    return app.localize("CostCenterGroup2");

            };

            vm.zerofyMinValue = function () {
                if (vm.asset.discount == null)
                    vm.asset.discount = 0;
            };
            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };

            vm.deprPercentageSum = 0.0;


            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.depreciationMethodChanged = function () {
                vm.minResidualValue = 1;
                if (vm.asset.depreciationMethodId == 1)
                    vm.minResidualValue = 0;
                vm.asset.annualDeprPercentage = null;
                if (vm.asset.depreciationMethodId == 1 || vm.asset.depreciationMethodId == 100)
                    return;
                //else if (vm.asset.depreciationMethodId == 8) {
                //    prepareCustomDepreciationTable();
                //    return;
                //}
                var perAnum = (vm.asset.purchseCost - vm.asset.residualValue) / vm.asset.assetLifeInYears;
                var percentageValue = 0;
                if (vm.asset.depreciationMethodId == 2)
                    percentageValue = 100;
                else if (vm.asset.depreciationMethodId == 3)
                    percentageValue = 125;
                else if (vm.asset.depreciationMethodId == 4)
                    percentageValue = 150;
                else if (vm.asset.depreciationMethodId == 5)
                    percentageValue = 175;
                else if (vm.asset.depreciationMethodId == 6)
                    percentageValue = 200;
                vm.asset.annualDeprPercentage = perAnum / (vm.asset.purchseCost - vm.asset.residualValue) * percentageValue;
            };
            vm.removeRow = function (row) {
                var index = vm.asset.childAssets.indexOf(row);

                //  assetService.setParentIdAsNullForDeletedRow({ id: vm.asset.childAssets[index].id, });
                assetService.setParentIdAsNullForDeletedRow({
                    id: vm.asset.childAssets[index].id
                }).success(function (result) {
                    vm.asset.childAssets.splice(index, 1);
                    vm.calculateTotalAttachmentCost();
                }).finally(function () {
                    vm.loading = false;
                });


            };
            vm.changeAsset = function (row) {

                row.title = row.asset.title;
                row.purchaseDate = row.asset.purchaseDate;
                row.purchseCost = row.asset.purchseCost;
                row.assetType = row.asset.assetType;
                row.id = row.asset.id;

            }
            vm.calculateTotalAttachmentCost = function () {

                if (vm.asset.childAssets) {
                    vm.asset.extraCost = 0;
                    vm.asset.childAssets.forEach(e => {
                        if (e.isPermanentAttachment)
                            vm.asset.extraCost += e.purchseCost;
                    });
                    if (typeof vm.asset.purchasePrice === 'undefined') {
                        vm.asset.purchseCost = vm.asset.extraCost;
                    } else {
                        vm.asset.purchseCost = vm.asset.extraCost + vm.asset.purchasePrice;
                    }
                }

            };


            vm.prepareCustomDepreciationTable = function () {
                vm.asset.anualDeprRates = [];
                if (vm.asset.depreciationMethodId == 8) {
                    var depStartDate = angular.copy(vm.asset.deprStartDate);

                    for (var i = 1; i <= vm.asset.assetLifeInYears; i++) {
                        var obj = {};
                        obj.year = i;
                        obj.fromDate = angular.copy(depStartDate);
                        obj.toDate = angular.copy(depStartDate.add(1, 'years'));
                        obj.percentage = null;

                        vm.asset.anualDeprRates.push(obj);
                        depStartDate.add({ days: 1 });
                    }
                    vm.sumCustomYearDepreciation();
                }
            }

            vm.sumCustomYearDepreciation = function (row) {
                var sum = 0.0;
                vm.asset.anualDeprRates.forEach(e => {
                    sum += e.percentage / 1;
                });
                if (sum > 100) {
                    abp.message.info("Percentage sum cannot be greater than 100");
                    if (row)
                        row.percentage = null;
                    vm.deprPercentageSum = 0;
                    vm.asset.anualDeprRates.forEach(e => {
                        vm.deprPercentageSum += e.percentage / 1;
                    });
                    return;
                }
                vm.deprPercentageSum = sum;
            };

            vm.addRow = function () {
                vm.asset.childAssets.push(childAccountObject());
            };
            vm.addRowPermanent = function () {
                debugger;
                vm.asset.childAssets.push(childAccountObjectPermanent());
            };

            function childAccountObjectPermanent() {

                var childAccount = new Object();
                childAccount.assetTypeId = null;
                childAccount.parentAssetId = null;
                childAccount.isPermanentAttachment = true;


                return childAccount;
            }
            function getLocations() {
                lookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                });
            };
            function childAccountObject() {

                var childAccount = new Object();
                childAccount.assetTypeId = null;
                childAccount.parentAssetId = null;



                return childAccount;
            }

            vm.searchAssetsWithNullParentId = function ($select) {
                if (!$select.search) return;

                assetService.searchAssetsWithNullParentId({ keyword: $select.search, category: 2, parentAssetId: vm.asset.parentAssetId }).success(function (data) {
                    vm.assetsWithNullParentId = data.items;

                });
            };

            vm.searchAssetsWithNullParentIdR = function ($select) {
                if (!$select.search) return;

                assetService.searchAssetsWithNullParentId({ keyword: $select.search, category: 2, parentAssetId: vm.asset.parentAssetId }).success(function (data) {
                    vm.assetsWithNullParentIdR = data.items;

                });
            };

            vm.deprStartDateChange = function () {
                if (!vm.asset.deprStartDate) return;
                if (vm.asset.deprStartDate < moment.utc(fiscalYear.startDate).toDate())
                    return vm.showOpeningDepr = true;
                else {
                    //vm.asset.openingDepr = 0;
                    return vm.showOpeningDepr = false;
                }
            };

            var getCostCenters = function () {
                costCenterService.searchCostCenters({ includeInActive: false }).success(function (data) {
                    vm.costCenters = data.items;
                    vm.costCentersGroup1 = vm.costCenters.filter(e => e.group != 2);
                    vm.costCentersGroup2 = vm.costCenters.filter(e => e.group == 2);
                });
            };

            var purchaseDateLoaded = false;
            vm.purchaseDateChange = function () {
                if (purchaseDateLoaded || !vm.isEditMod) {
                    vm.asset.inServiceDate = vm.asset.purchaseDate.toJSON();
                    vm.asset.deprStartDate = vm.asset.purchaseDate.toJSON();
                }
                else purchaseDateLoaded = true;
            };

            var inServiceDateLoaded = false;
            vm.inServiceDateChange = function () {
                if (inServiceDateLoaded || !vm.isEditMod)
                    vm.asset.deprStartDate = vm.asset.inServiceDate.toJSON();
                else
                    inServiceDateLoaded = true;
            };

            function getAssetType() {

                vm.loading = true;
                assetService.getAssetType({}).success(function (data) {
                    vm.assetTypes = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            function getDepreciationMethod() {
                vm.loading = true;
                assetService.getDepreciationMethod({}).success(function (data) {
                    vm.depreciationMethods = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };


            vm.searchSupplier = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers

                return directoryService.search({ keyword: $select.search, contactType: 3 }).then(function (response) {
                    vm.suppliers = response.data.items;
                });
            };

            // extended search using search contact popup
            vm.searchSupplierPopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return 3;
                        }
                    }
                }).result.then(function (supplier) {
                    if (supplier != null) {
                        vm.asset.dealer = supplier;
                        vm.asset.dealerId = supplier.id;
                    }
                });
            };

            vm.searchAssets = function ($select) {
                if (!$select.search) return;

                assetService.search({ keyword: $select.search, category: 1 }).success(function (data) {
                    vm.assets = data.items;
                });
            };

            vm.clearParentAsset = function () {
                vm.asset.parentAssetId = null;
                vm.asset.parentAsset = null;
            };

            vm.checkDuplicationOfAttachments = function () {

                const idSet = new Set();
                vm.hasDuplication = false;
                if (vm.asset.childAssets != null) {
                    if (vm.asset.childAssets.length > 0) {
                        for (let i = 0; i < vm.asset.childAssets.length; i++) {
                            const assetId = vm.asset.childAssets[i].id;
                            if (idSet.has(assetId)) {
                                vm.hasDuplication = true;
                                if (vm.hasDuplication) {
                                    abp.message.info("There is same asset in Removable and Permanent Attachments");
                                }
                                break;
                            }
                            idSet.add(assetId);
                        }
                    }
                }

                if (!vm.hasDuplication) {
                    vm.save();
                }

            };

            vm.save = function () {
                vm.saving = true;
                vm.asset.purchaseDate = vm.asset.purchaseDate.startOf('day');
                vm.asset.inServiceDate = vm.asset.inServiceDate.startOf('day');
                vm.asset.deprStartDate = vm.asset.deprStartDate.startOf('day');

                assetService.createOrUpdateAsset({
                    asset: vm.asset,
                }).success(function (asset) {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    if (vm.saveAndPrint)
                        saveAndPrint(asset);
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });

            };

            vm.setDepreciationMethods = function (asset) {
                vm.asset.depreciationMethodId = asset.depreciationMethodId;
            }

            vm.setResidualValue = function (residualValue) {
                vm.asset.residualValue = residualValue;
            }

            vm.setAssetLife = function (assetType) {
                vm.asset.assetLifeInYears = assetType.assetLifeInYears;
            }

            vm.setAnnualDeprPercentage = function (assetType) {
                vm.asset.annualDeprPercentage = assetType.annualDeprPercentage;
            }

            vm.setOpeningDepr = function (assetType) {
                vm.asset.openingDepr = assetType.openingDepr;
            }

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            var saveAndPrint = function (id) {
                window.open('/Report#/tenant/printAsset/' + id);
            };
            function init() {
                vm.loading = true;
                getLocations();
                if (vm.isCostCenterEnabled)
                    getCostCenters();
                assetService.getAssetForEdit({
                    id: assetId
                }).success(function (result) {

                    vm.asset = result;
                    if (vm.asset) {
                        if (vm.asset.childAssets) {
                            vm.asset.childAssets.forEach(e => {
                                e.asset = {

                                    assetNo: e.assetNo,
                                    title: e.title,

                                };
                            });
                        }
                    }

                    vm.calculateTotalAttachmentCost();

                    if (!assetId) {
                        vm.asset.childAssets = [];
                    }
                    if (moment.utc(vm.asset.deprStartDate).toDate() < moment.utc(fiscalYear.startDate).toDate())
                        vm.showOpeningDepr = true;
                    getAssetType();
                    getDepreciationMethod();
                    if (assetId > 0) {
                        vm.isEditMod = true;
                        vm.asset.assetLifeInYears = vm.rounding(assetLifeInYears);
                        if (vm.asset.depreciationMethodId == 1)
                            vm.minResidualValue = 0;
                        if (vm.asset.depreciationMethodId == 8)
                            vm.sumCustomYearDepreciation();


                    } else {
                        vm.isEditMod = false;
                    }
                }).finally(function () {
                    vm.loading = false;
                });

            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.assets.assets.depreciationDetailModal', [
        '$scope', 'abp.services.app.depreciationDetail', 'utilities', '$uibModalInstance', 'options',
        function ($scope, depreciationDetailService, utilities, $uibModalInstance, options) {
            var vm = this;
            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
            vm.loading = false;
            vm.grandTotal = 0;

            vm.openingDep = options.openingDepreciation;

            vm.CurrencyFormate = function (amount) {
                if (amount == null) return null;
                return amount.toLocaleString('en');
            };

            vm.ConvertToNumFormate = function (number) {
                var val = vm.CurrencyFormate(parseFloat(number));
                return val;
            };
           
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getlocalDateTimeShort = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM');
                }
                else {
                    return "";
                }
            };

            function init() {
                vm.loading = true;
                depreciationDetailService.getDepreciationDetailByAssetId({ id: options.assetId}).success(function (result) {
                    vm.report = result;
                    vm.grandTotal = vm.report.depreciation + vm.openingDep;
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.assets.assets.disposalApprovalModal', [
        '$uibModalInstance', 'abp.services.app.asset', 'abp.services.app.profile', 'abp.services.app.user', 'abp.services.app.approval', 'assetId', 'disposeLimited', 'approvalId', 'form', 'options', 'appSession', 'utilities', '$uibModal',
        function ($uibModalInstance, assetService, profileService, userService, approvalAppService, assetId, disposeLimited, approvalId, form, options, appSession, utilities, $uibModal) {

            var vm = this;
            vm.locationName = '';
            vm.documents = [];
            vm.disposeLimited = disposeLimited;
            vm.form = form;
            vm.approvalId = approvalId;
            vm.roles = [];
            vm.currentRoles = [];
            vm.currentUserId = appSession.user.id;
            vm.documentsForAssetsDisposalEnabled = abp.features.isEnabled("CRS.CustomFeatures.DocumentsForAssetsDisposal");
            vm.aseetIdForDepreciation = assetId;
            vm.isCostCenterEnabled = abp.features.isEnabled("Core.CostCenters");
            vm.isCostCenter2Enabled = utilities.parseBoolean(abp.setting.get("App.Speed.Common.IsCostCenterGroup2Enabled"));
            vm.salePriceSettingEnabled = utilities.parseBoolean(abp.setting.get("App.General.EstimateOrSetAssetPrice")) || (parseFloat(abp.setting.get("App.General.ProfitMarginOnBookValue")) > 0);
            vm.canChangeSalePrice = utilities.parseBoolean(abp.setting.get("App.General.EstimateOrSetAssetPrice")) && abp.features.isEnabled("Pages.Tenant.Assets.CanSetAssetSalePrice");
            vm.isDealershipDiscountEnabled = abp.features.isEnabled("CRS.CustomFeatures.DiscountOnAssetFromDealership");
            vm.isTransactionPasswordEnabled = abp.features.isEnabled("CRS.CustomFeatures.TransactionPassword");
            vm.discountOnAssetForDisposal = abp.features.isEnabled("CRS.CustomFeatures.DiscountOnAssetForDisposal");
            vm.isAssetDisposalApprovalEnabled = abp.features.isEnabled("CRS.Approval.AssetDisposals");

            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };
            vm.deprPercentageSum = 0.0;
            vm.assetDisposalDocs = [];
            vm.assetDisposalImages = [];

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };


            vm.isDocument = function (i) {
                return i && i.name &&
                    (['jpg', 'jpeg', 'png'].indexOf(i.name.split('.')[1].toLowerCase()) == -1);
            };

            vm.getDisposalType = function (id) {
                if (id == 1)
                    return app.localize("Selling");
                else if (id == 2)
                    return app.localize("TotalLoss");

            };
            vm.disposalTypes = [
                {
                    id: 1,
                    name: 'Selling'
                },
                {
                    id: 2,
                    name: 'Total Loss'
                }];

            vm.getOriginalName = function (doc) {
                var originalName = doc.name.replace("_" + doc.guid, "");
                return originalName;
            };
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.depreciationPopUp = function () {
                var obj = {
                    assetId: vm.aseetIdForDepreciation,
                    openingDepreciation: vm.asset.openingDepr,
                };

                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/assets/assets/depreciationDetailModal.cshtml',
                    controller: 'tenant.views.crs.assets.assets.depreciationDetailModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return obj;
                        }
                    }
                });
            };

            vm.changeSalePriceByUser = function () {
                vm.loading = true;
                assetService.changeSalePriceByUser({
                    id: assetId,
                    salePrice: vm.asset.salePrice
                }).success(function (result) {
                    vm.isSetSalePrice = false;
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    init();
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.getRoleByUserId = function () {
                return userService.getRoleByUserId({ id: vm.currentUserId })
                    .success(function (data) {
                        vm.currentRoles = data;
                    }).finally(function () {
                        vm.canApproveOrRejectColumnWise();
                    });
            };

            vm.getRoles = function (id) {
                id = id ? id : null;
                return userService.getRole({ id: id }).then(function (response) {
                    vm.roles = response.data;
                });
            };

            vm.getRole = function (id) {
                var result = vm.roles.filter(x => x.id == id);
                return result[0] ? result[0].displayName : '';
            };


            vm.canApproveOrRejectColumnWise = function () {
                vm.approvalLines.forEach(function (e, i) {
                    e.approvable = vm.canApproveOrReject(e, i);
                });
                if (vm.approvalLines.some(e => e.approvable == true))
                    return true;
                else return false;
            };

            vm.canApproveOrReject = function (row, index) {
                var canApproveOrReject = true;
                if ((vm.currentRoles.some(x => x.id == row.roleId) || vm.currentUserId == row.userId) && row.status == 1) {
                    if (index != 0) {
                        for (var i = 0; i < index; i++) {
                            var current = vm.approvalLines[i];
                            if (current.status != 2)
                                canApproveOrReject = false;
                        }
                    }
                }
                else {
                    canApproveOrReject = false;
                }

                return canApproveOrReject;
            };
            vm.approveRow = function (row) {

                abp.message.confirm(
                    'Do you really want to approve?',
                    function (isConfirmed) {

                        if (isConfirmed) {

                            vm.loading = true;
                            approvalAppService.approvalBySpecificUser({ approvalId: row.approvalId, recordId: assetId, form: vm.form, id: row.id })
                                .success(function (data) {
                                    abp.notify.info(app.localize('Approved.'));
                                    vm.approvalLines = data && data.length > 0 ? data : vm.approvalLines;
                                    var isAllApprovedLinesApproved = false;
                                    if (data.length > 0) {
                                        isAllApprovedLinesApproved = data.every(function (element) {
                                            return element.status == 2;
                                        });
                                        if (isAllApprovedLinesApproved) {
                                            $uibModalInstance.close(vm.approvalLines);
                                        }
                                    }
                                    //vm.approvalLines.find(x => x.id == row.id).status = 2;
                                    vm.canApproveOrRejectColumnWise();
                                }).finally(function () {
                                    vm.loading = false;
                                });
                        }

                    }
                );

            };


            vm.save = function () {
                vm.saving = true;
                if (vm.isTransactionPasswordEnabled) {
                    profileService.verifyTransactionPassword({ id: vm.transactionPassword })
                        .success(function () {
                            abp.notify.info(app.localize('PasswordVerifiedSuccessfully'));
                            disposeApprovedAsset();
                            $uibModalInstance.close();
                        }).finally(function () {
                            vm.saving = false;
                        });
                }
                else {
                    disposeApprovedAsset();
                    $uibModalInstance.close();
                }
            };

            function disposeApprovedAsset() {
                vm.loading = true;
                assetService.approveDisposal({ id: vm.asset.id }).success(function (data) {

                }).finally(function () {
                    vm.loading = false;
                    vm.saving = false;
                    abp.notify.info('Asset Disposed Successfully');
                });
            }

            function approvalForm() {

                vm.loading = true;
                vm.approvalLines = [];
                debugger;
                approvalAppService.getApprovals({ id: vm.approvalId })
                    .success(function (data) {
                        if (data)
                            vm.approvalLines = data.approvalLines;
                    })
                    .finally(function () {
                        vm.loading = false;
                    });
            }

            if (vm.isAssetDisposalApprovalEnabled) {
                vm.getRoles();
                vm.getRoleByUserId();
            }
            
            function init() {
                vm.loading = true;
                if (vm.isAssetDisposalApprovalEnabled)
                    approvalForm();

                assetService.getAssetForView({
                    id: assetId
                }).success(function (result) {
                    vm.asset = result;

                    vm.documents = vm.asset.documents;
                    if (vm.asset.documents) {
                        vm.asset.documents.forEach(doc => {
                            doc.thumb = doc.url;
                            doc.img = doc.url;

                            if (vm.isDocument(doc))
                                vm.assetDisposalDocs.push(doc);
                            else
                                vm.assetDisposalImages.push(doc);

                        });
                    }
                    if (vm.asset.anualDeprRates != null) {
                        vm.asset.anualDeprRates.forEach(e => {
                            vm.deprPercentageSum += e.percentage / 1;
                        });
                    }

                    vm.asset.disposalType = app.localize(vm.asset.disposalType);
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();;
