(function () {

    appModule.controller('tenant.views.crs.banking.reconciledReport.report', [
        '$scope','appSession', 'abp.services.app.bankReconciliation', 'utilities', 'abp.services.app.commonLookup', '$stateParams',
        function ($scope, appSession, bankReconciliationAppService, utilities, commonLookupService, $stateParams) {

            var vm = this;
            vm.fileName = appSession.tenant.tenancyName.toLowerCase() + '-' + 'header.png';

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };

            vm.loading = false;
            vm.filters = $stateParams.filters;

            var reportId = 0;
            //if pop-up print
            if ($scope.$parent) {
                if ($scope.$parent.vmMain && $scope.$parent.vmMain.reportId)
                    reportId = $scope.$parent.vmMain.reportId;
            }

            //if through url print
            if (reportId == 0 && !isNaN($stateParams.query)) {
                reportId = $stateParams.query;
            }

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM-DD');
                }
                else {
                    return "";
                }
            };


            vm.getBankAccounts = function getBankAccounts() {
                commonLookupService.getBankAccountsForSelection().success(function (data) {
                    vm.bankAccounts = data.items;
                });
            };


            //Location related code Start ------------
            vm.locationPermission = function (row) {
                if (row.locationId) {
                    if (!vm.permissions.allActionsOnOtherBranch && row.locationId != appSession.user.locationId)
                        return false;
                }
                return true;
            };

            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    vm.LocationsForAgreement = data.items;

                });
            };

            //Location related code END ---------------

            vm.getBankReconciledReport = function () {
                vm.loading = true;
                bankReconciliationAppService.getReconciledReportForPrint({ id: reportId }).success(function (data) {
                    vm.bankReconciledData = data.bankReconciliations.items;
                    vm.bankName = data.bankName;
                    vm.reconciledBalance = data.reconciledBalance;
                    vm.reconciliationDate = data.reconciliationDate;
                    vm.pendingEntriesBalance = data.pendingEntriesBalance;
                    vm.ledgerBalance = data.ledgerBalance;

                    var sumReconciledDebit = 0.0;
                    var sumReconciledCredit = 0.0;
                    vm.bankReconciledData.forEach(function (value, key) {
                        // in case of Debit
                        sumReconciledDebit = sumReconciledDebit + value.debit;
                        // in case of Credit
                        sumReconciledCredit = sumReconciledCredit + value.credit;
                    });
                    vm.sumReconciledDebit = utilities.round(sumReconciledDebit, 2);
                    vm.sumReconciledCredit = utilities.round(sumReconciledCredit, 2);
                }).finally(function () {
                    vm.loading = false;
                });
            };

            function init() {
                //vm.getBankAccounts();
                //getLocations();
                vm.getBankReconciledReport();
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.billing.index',
        ['$scope', 'abp.services.app.billing', 'abp.services.app.customerCareTenant', '$uibModal',
            function ($scope, billingService, customerCareTenantService, $uibModal) {

                var vm = this;
                vm.loading = false;
                vm.openInvoicesTotalAmount = 0;
                vm.outstandingInvoices = [];
                vm.filters = {
                    invoiceType: null
                };
                vm.filteredOutstandingInvoices = function () {
                    vm.outstandingInvoices = vm.openInvoices;
                    if (vm.invoiceType==1)
                        vm.outstandingInvoices = vm.openInvoices.filter(f => f.subscriptionId>0);
                    else if (vm.invoiceType == 2)
                        vm.outstandingInvoices = vm.openInvoices.filter(f => f.changeRequestId>0);
                    else if (vm.invoiceType == 3)
                        vm.outstandingInvoices = vm.openInvoices.filter(f => f.projectId>0);
                    vm.openInvoicesTotalAmount = 0;
                    vm.outstandingInvoices.forEach(e => {
                        vm.openInvoicesTotalAmount += e.totalAmount;
                    });
                };
                
                vm.getOpenInvoices = function () {
                    vm.loading = true;
                    customerCareTenantService.openInvoices(vm.filters).success(function (result) {
                        vm.openInvoices = result;
                        vm.outstandingInvoices = vm.openInvoices;
                        if (vm.invoiceType == 1)
                            vm.outstandingInvoices = vm.openInvoices.filter(f => f.subscriptionId > 0);
                        else if (vm.invoiceType == 2)
                            vm.outstandingInvoices = vm.openInvoices.filter(f => f.changeRequestId > 0);
                        else if (vm.invoiceType == 3)
                            vm.outstandingInvoices = vm.openInvoices.filter(f => f.projectId > 0);
                        vm.openInvoicesTotalAmount = 0;
                        vm.outstandingInvoices.forEach(e => {
                            vm.openInvoicesTotalAmount += e.totalAmount;
                        });
                    }).finally(function () {
                        vm.loading = false;
                    });
                };

                vm.invoiceTypes = [
                    { id: 1, name: "Subscription" },
                    { id: 2, name: "Change Request" },
                    { id: 3, name: "Project" }
                ];

                vm.getCloseInvoices = function () {
                    vm.loading = true;
                    customerCareTenantService.closeInvoices().success(function (result) {
                        vm.closeInvoices = result;
                        
                    }).finally(function () {
                        vm.loading = false;
                    });
                };

                vm.print = function (row) {

                    var modalInstance = $uibModal.open({
                        templateUrl: '~/App/tenant/views/crs/billing/invoicePrintTemplate.cshtml',
                        controller: 'tenant.views.crs.billing.invoicePrintTemplate as vm',
                        backdrop: 'static',
                        size: 'lg',
                        resolve: {
                            filters: function () {
                                return row.id;
                            }
                        }
                    });

                    modalInstance.result.then(function (result) {
                        init();
                    });
                };

                vm.invoiceStatus = function (code) {
                    if (code === 1)
                        return "Open";
                    else if (code === 2)
                        return "Cleared";
                    else
                        return "None";
                    
                };

                vm.paymentDetail = function (row) {

                    var modalInstance = $uibModal.open({
                        templateUrl: '~/App/tenant/views/crs/billing/paymentDetailModal.cshtml',
                        controller: 'tenant.views.crs.billing.paymentDetailModal as vm',
                        backdrop: 'static',
                        size: 'lg',
                        resolve: {
                            voucherId: function () {
                                return row.id;
                            },
                            invoiceDetail: function () {
                                    return row.voucherNo;
                            },
                        }
                    });
                };

                function init() {
                    vm.getOpenInvoices();
                    vm.getCloseInvoices();
                }
                init();
            }
        ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.billing.invoicePaymentModal', [
        '$scope', '$uibModalInstance', '$uibModal', 'invoice', 'abp.services.app.billing', 'abp.services.app.customerCareTenant',
        function ($scope, $uibModalInstance, $uibModal, invoice, billingService, customerCareTenantService) {
            var vm = this;
            vm.isSaving = false
            vm.invoice = invoice;
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.payment = {
                type: 1,
                card:null
            };

            if (vm.invoice.tenant.hasCard)
                vm.payment.card = 1;

            vm.save = function () {
                if (vm.payment.card == 1) {
                    vm.saving = true;
                    customerCareTenantService.invoiceSilentPayment({
                        id: vm.invoice.id

                    }).success(function (result) {
                        if (result == 'succeeded') {
                            abp.message.success('Paid successfully');
                            $uibModalInstance.close();
                        }
                        else {
                            abp.message.error(result);
                            $uibModalInstance.close();
                        }
                    }).finally(function () {
                        vm.saving = false;
                    });
                }
                else  {
                    let url = `/StripePayment/CheckoutSession?id=${vm.invoice.id}&type=${vm.payment.type}`;

                    // Redirect to the constructed URL
                    window.location.href = url;
                }
            };

            vm.cardType = function (type) {
                if (type == 1) {
                    return 'Master Card';
                } else if (type == 2) {
                    return 'Visa';
                } else if (type == 3) {
                    return 'American Express';
                } else if (type == 4) {
                    return 'Union Pay';
                } else if (type == 225) {
                    return 'Unknown';
                }
            };
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('MM/YYYY');
                }
                else {
                    return "";
                }
            };
            vm.init = function () {
                vm.loading = true;
                customerCareTenantService.getTenantCardById({
                    id: vm.invoice.tenant.id
                }).success(function (result) {
                    vm.tenantCard = result;
                }).finally(function () {
                    vm.loading = false;
                });

            };
            if (vm.invoice.tenant.hasCard)
                vm.init();
            
        }
    ]);
})();;
