(function () {
    appModule.controller('tenant.views.crs.coupons.allocationForCoupon', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.directory', 'abp.services.app.billingMethod', 'utilities', 'abp.services.app.commonLookup', 'appSession', 'abp.services.app.allocation', 'abp.services.app.coupon',
        function ($scope, $uibModal, $uibModalInstance, directoryService, billingMethodService, utilities, commonLookupService, appSession, allocationService, couponService) {

            var vm = this;
            var depositId = 0;
            vm.saving = false;
            vm.couponsData = [];
            vm.coupons = [];
            vm.allocationForCouponRedeem = {};
            vm.autoCalculateAmountInWords = abp.setting.get("App.General.AutoCalculateAmountInWords");
            vm.manualReceiptNo = utilities.parseBoolean(abp.setting.get("App.General.ManualReceiptNo"));
            vm.allocationForDepositPostAllocation = utilities.parseBoolean(abp.setting.get("App.General.ReceiptPostAllocation"));
            vm.isAccountsEnabled = abp.features.isEnabled("CRS.Accounts");
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm:ss';
            vm.allocationData = null;
            vm.amountChanged = function () {
                if (vm.allocationForCouponRedeem.amount == 0 || angular.isUndefined(vm.allocationForCouponRedeem.amount)) {
                    if (vm.autoCalculateAmountInWords == "true")
                        vm.allocationForCouponRedeem.amountInWords = '';
                    return;
                }
                if (vm.autoCalculateAmountInWords == "true")
                    vm.allocationForCouponRedeem.amountInWords = utilities.toWords(vm.amount);

            };


            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };


            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };
            vm.searchCustomers = function ($select) {
                //any contact (staff, customer, supplier)
                return directoryService.search({ keyword: $select.search }).then(function (response) {
                    vm.customers = response.data.items;
                });
            };



            vm.onCustomerSelect = function (customer) {

                vm.allocationForCouponRedeem.customerId = customer.id;
                vm.allocationForCouponRedeem.customer = customer;

                getCouponsData();
                getAllocatedToDeposit();
            };

            vm.sumAmount = function () {
                if (vm.allocationData == null)
                    return 0;

                if (vm.allocationData.allocations.length == 0)
                    return 0;

                vm.amount = 0;
                angular.forEach(vm.allocationData.allocations, function (value, key) {
                    if (value.allocatedNow > 0)
                        vm.amount = vm.amount + value.allocatedNow;
                });

                return vm.rounding(vm.amount);
            };
            vm.sumCouponsAmount = function () {
                if (vm.couponsData == null)
                    return 0;

                if (vm.couponsData.length == 0)
                    return 0;

                vm.couponsAmount = 0;
                angular.forEach(vm.couponsData, function (value, key) {
                    if (value.redeemNow > 0)
                        vm.couponsAmount = vm.couponsAmount + value.redeemNow;
                });

                return vm.rounding(vm.couponsAmount);
            };

            function getCouponsData() {
                vm.couponsData = [];
                couponService.getCouponsByCustomerId({
                    id: vm.allocationForCouponRedeem.customerId
                }).success(
                    function (data) {
                        // vm.couponsData = data;
                        vm.allocationForCouponRedeem.agreement = data[0].agreement;
                        vm.allocationForCouponRedeem.agreementId = data[0].agreementId;
                        angular.forEach(data, function (value, key) {
                            if (value) {
                                vm.coupon = value;
                                vm.coupon.redeemAmount = value.alreadyRedeemed;
                                vm.coupon.dueToRedeem = 0;
                                vm.coupon.redeemNowChecked = false;
                                vm.couponsData.push(vm.coupon)
                            }
                        });
                    });
            }

            vm.redeemNowChanged = function (row) {
                if (!row.redeemNowChecked)
                    row.redeemNow = 0;
            }
            //all contacts customers, suppliers, staff
            vm.searchCustomerPopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return null;
                        }
                    }
                }).result.then(function (result) {
                    if (result != null) {

                        vm.onCustomerSelect(result);
                    }
                });
            };
            vm.searchContacts = function ($select) {
                return directoryService.search({ keyword: $select.search, activeOnly: true }).then(function (response) {
                    vm.contacts = response.data.items;
                });
            };
            vm.customerChanged = function () {
                vm.allocationForCouponRedeem.customerId = vm.allocationForCouponRedeem.customer.id
                getCouponsData();
                getAllocatedToDeposit();
            }

            function getSettledAmount() {
                vm.loading = true;

                depositService.getAllocatedAmountOnDeposit(depositId)
                    .success(function (result) {
                        vm.previousSettledAmount = result;
                        vm.totalAmount = vm.allocationForCouponRedeem.amount;
                        vm.availableAmount = vm.rounding(vm.allocationForCouponRedeem.amount - vm.previousSettledAmount);
                        vm.allocationForCouponRedeem.amount = vm.availableAmount;
                    }).finally(function () {
                        vm.loading = false;
                    });
            }

            function init() {
            }
            vm.save = function () {
                debugger;

                if (vm.couponsData.some(e => (e.alreadyRedeemed + e.redeemNow) > e.amount)) {
                    abp.message.info("Redeem Now value should be less than or equal to Amount");
                    return;
                }
                vm.saving = true;
                vm.loading = true;
                vm.coupons = {
                    customer: vm.allocationForCouponRedeem.customer,
                    redeemVouchers: vm.couponsData.filter(x => x.redeemNowChecked).map(e => {
                        return {
                            couponId: e.id,
                            amount: e.redeemNow
                        }
                    })
                }

                var invoicesToBeAllocated = vm.allocationData.allocations.filter(e => e.allocatedNow > 0);
                couponService.allocateInvoicesToCouponRedeemedInvoice({ allocations: invoicesToBeAllocated, allocatingVoucherAmount: vm.amount, coupons: vm.coupons })
                    .success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                        vm.loading = false;
                    });
            };
            function getBankAccounts() {
                commonLookupService.getBankAccountsForSelection().success(function (data) {
                    vm.bankAccounts = data.items;
                });
            };
            function getAllocatedToDeposit() {
                vm.allocationData = null;
                allocationService.getAllocationsForEdit({ contactId: vm.allocationForCouponRedeem.customerId, voucherCategory: 'Creditor' }).success(
                    function (data) {
                        vm.allocationData = data;
                    });
            }
            function initializeFilters() {
                //getBillingMethods();
                //getLocations();
                //getBankAccounts();
            }

            init();
            initializeFilters();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.coupons.couponsImport', [
        '$scope', '$uibModalInstance', 'abp.services.app.coupon', 'abp.services.app.luckyDraw',
        function ($scope, $uibModalInstance, couponAppService, luckyDrawAppService) {

            var vm = this;

            vm.loading = false;
            vm.processing = false;
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.selectedFile = null;
            vm.recordCountInBatch = 20;
            vm.allowImport = false;

            vm.totalRecordsCount = 0;
            vm.successRecordsCount = 0;
            vm.failRecordsCount = 0;

            $scope.loadFile = function (files) {

                vm.allowImport = false;

                if (files.length > 0) {
                    $scope.$apply(function () {
                        vm.selectedFile = files[0];
                        readFileData();
                    });
                } else {
                    $scope.$apply();
                    vm.refresh();
                }
            };

            vm.refresh = function () {
                vm.luckyDrawId = null;
                vm.fileDataList = [];
                angular.element('#dataFile').val(null);
                vm.selectedFile = null;
                vm.allowImport = false;

                vm.totalRecordsCount = 0;
                vm.successRecordsCount = 0;
                vm.failRecordsCount = 0;
                vm.errorRecords = null;
                vm.showCount = false;
            };

            vm.getlocalDate = function (date) {
                if (date) {
                    return moment(date).utc().local().format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
            vm.getDateLuckyDraw = function (row) {
                if (!row.startDate)
                    return "";
                else
                    return '(' + vm.getlocalDate(row.startDate) + " - " + vm.getlocalDate(row.endDate) + ')';
            };
            function correctData(date) {
                if (date) {
                    return moment(date, ["DD/MM/YYYY h:mm A"]);
                }
                else {
                    return "";
                }
            }

            vm.cancel = function () {
                $uibModalInstance.close();
            };

            function readFileData() {

                vm.fileDataList = [];
                var file = vm.selectedFile;

                if (file && ['xlsx', 'xls'].indexOf(file.name.split('.').pop().toLowerCase()) > -1) {

                    var reader = new FileReader();
                    vm.loading = true;

                    reader.onload = function (e) {

                        var data = e.target.result;
                        var workbook = XLSX.read(data, { type: 'binary', cellDates: true, cellNF: false, cellText: false });
                        var first_sheet_name = workbook.SheetNames[0];

                        var dataObjects = XLSX.utils.sheet_to_json(workbook.Sheets[first_sheet_name], { raw: true, dateNF: 'MM-DD-YYYY HH:mm:ss' });
                        console.log(dataObjects);
                        if (dataObjects.length > 0) {

                            var checkForDuplication = true;

                            for (var i = 0; i < dataObjects.length; i++) {
                                var value = dataObjects[i];

                                var orderId = value['Order ID'];
                                if (!orderId) {
                                    abp.message.error("Order Id feild is missing at line " + (i + 2) + ".", "Error");
                                    checkForDuplication = false;
                                    vm.fileDataList = [];
                                    break;
                                }

                                var orderReference = value['Order Reference'];
                                if (!orderReference) {
                                    abp.message.error("Order Reference feild is missing at line " + (i + 2) + ".", "Error");
                                    checkForDuplication = false;
                                    vm.fileDataList = [];
                                    break;
                                }
                                var dateTimeNow = moment();

                                var item = {
                                    error: '',
                                    status: 'new',
                                    type: 1,
                                    luckyDrawId: vm.luckyDrawId,
                                    refId: value['Order ID'],
                                    refNo: value['Order Reference'],
                                    amount: value['Order Value'],
                                    couponDate: value['Created Date'] ? correctData(value['Created Date'].toString().trim()) : '',
                                    customerName: value['Customer Name'],
                                    customerMobile: value['Customer Mobile'],
                                    customerEmail: value['Customer Email'],
                                    couponVoucher: {
                                        date: dateTimeNow,
                                        billingDetail: {
                                            creditCard: {
                                                cardNoLastDigits: value['Card Number'] ? value['Card Number'].substr(value['Card Number'].length - 4) : '',
                                                transactionNo: value['Payment ID'] ? value['Payment ID'].toString().trim() : '',
                                                expiryDate: dateTimeNow
                                            }
                                        }
                                    }
                                };

                                vm.fileDataList.push(item);
                            }
                            console.log(vm.fileDataList);

                            if (checkForDuplication && vm.fileDataList.length > 0) {
                                vm.allowImport = !hasDuplicateCodes();
                            }
                            if (!vm.luckyDrawId)
                                vm.allowImport = false;
                        } else {
                            abp.message.error("Something Wrong Or File is empty !", "Error");
                        }

                        vm.loading = false;
                        $scope.$apply();
                    };

                    reader.onerror = function (ex) {
                        vm.loading = false;
                        abp.message.warn(
                            app.localize(ex),
                            'Unknown File'
                        );
                    };

                    reader.readAsBinaryString(file);

                } else {
                    abp.message.error("Please select Valid file to upload !", "Unknown File");
                    vm.loading = false;
                }

            }
            vm.luckyDrawChange = function () {
                if (!vm.luckyDrawId)
                    vm.allowImport = false;
                else
                    vm.allowImport = true;
            }
            vm.importData = function () {
                vm.allowImport = false;
                vm.loading = true;

                if (!vm.fileDataList || vm.fileDataList.length == 0) {
                    abp.message.error("Something Wrong Or File is empty !", "Error");
                    return;
                }
                sendDataInBatches();
            };

            function sendDataInBatches() {
                vm.loading = true;

                //get records that dont saved yet
                var recordsToSend = [];
                angular.forEach(vm.fileDataList, function (dataItem) {
                    if (dataItem.status === 'new' && recordsToSend.length < vm.recordCountInBatch) {
                        dataItem.luckyDrawId = vm.luckyDrawId;
                        recordsToSend.push(dataItem);
                    }
                });

                //return condition
                if (recordsToSend.length < 1) {
                    vm.loading = false;
                    vm.showCount = true;
                    vm.totalRecordsCount = vm.fileDataList.length;
                    vm.successRecordsCount = vm.fileDataList.filter(e => e.status == "success").length;
                    vm.failRecordsCount = vm.fileDataList.filter(e => e.status == "fail").length;
                    vm.failRecords = vm.fileDataList.filter(e => e.status == "fail");

                    var fieldsRecordsIndex = [];
                    vm.failRecords.forEach(e => {
                        fieldsRecordsIndex.push(vm.failRecords.indexOf(e) + 1);
                    });
                    vm.errorRecords = fieldsRecordsIndex.join();

                    return;
                }

                couponAppService.importCouponsData({ coupons: recordsToSend })
                    .success(function (data) {

                        if (data) {
                            angular.forEach(data.coupons, function (dataItem) {
                                angular.forEach(vm.fileDataList, function (fileDataItem) {
                                    if (fileDataItem.refId === dataItem.refId) {
                                        fileDataItem.status = dataItem.status;
                                        fileDataItem.couponNo = dataItem.couponNo;
                                        fileDataItem.error = dataItem.error;
                                    }
                                });
                            });
                        }

                        sendDataInBatches();
                    })
                    .finally(function (data) {
                        //   vm.loading = false;
                    });
            }

            function hasDuplicateCodes() {
                var result = false;

                //check for code duplication
                for (var a = 0; a < vm.fileDataList.length; a++) {
                    for (var j = a + 1; j < vm.fileDataList.length; j++) {
                        if (vm.fileDataList[a].refId === vm.fileDataList[j].refId) {
                            abp.message.error("Duplicate Order Id values at records " + (a + 1) + " and " + (j + 1) + ".", "Error");
                            result = true;
                            a = j = vm.fileDataList.length;
                            break;
                        }
                    }
                }

                return result;
            }


            function getActiveLuckyDraws() {
                luckyDrawAppService.getActiveLuckyDraws({}).success(function (data) {
                    vm.luckyDraws = data;
                    console.log(vm.luckyDraws);
                });
            }
            function init() {
                getActiveLuckyDraws();
            }
            init();
        }
    ]);

})();;
(function () {
    appModule.controller('tenant.views.crs.coupons.couponViewModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.coupon', 'couponId',
        function ($scope, $uibModal, $uibModalInstance, couponService, couponId) {

            var vm = this;
            vm.saving = false;
            vm.policeReportDocs = [];
            vm.canChangeCharges = false;
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            vm.getlocalDate = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getDateLuckyDraw = function (row) {
                if (!row.startDate)
                    return "";
                else
                    return '(' + vm.getlocalDate(row.startDate) + " - " + vm.getlocalDate(row.endDate) + ')';
            };
            vm.couponTypes = [{ id: 1, name: 'Prepaid' }, { id: 2, name: 'Shopping' }];
            vm.getCouponType = function (id) {
                if (id == 1) {
                    return 'Prepaid'
                } else if (id == 2) {
                    return 'Shopping'
                }
                else {
                    return null;
                }
            };
            function init() {
                vm.loading = true;
                couponService.getCouponForEdit({
                    id: couponId

                }).success(function (result) {
                    vm.loading = false;
                    vm.coupons = result;
                    vm.isShopping = vm.coupons.type;
                    vm.coupons.type = vm.getCouponType(vm.coupons.type);
                    vm.coupons.couponDate = vm.getlocalDate(vm.coupons.couponDate);
                    vm.coupons.winningDate = vm.getlocalDate(vm.coupons.winningDate);
                    vm.coupons.luckyDraw.name = vm.coupons.luckyDraw.name + ' ' + vm.getDateLuckyDraw(vm.coupons.luckyDraw);
                });
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.coupons.createOrEditCouponModel', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.directory', 'abp.services.app.agreement', 'abp.services.app.luckyDraw', 'abp.services.app.coupon', 'agreementId',
        function ($scope, $uibModal, $uibModalInstance, directoryService, agreementService, luckyDrawAppService, couponAppService, agreementId) {

            var vm = this;
            vm.saving = false;
            vm.filters = {
                coupon: { type: agreementId ? 2 : 1, agreementId: agreementId }
            };
            if (agreementId) {
                vm.isAddNewCoupon = false;
            } else
            {
                vm.isAddNewCoupon = true;

            }
            


            //vm.shoppingCouponId = shoppingCouponId;
            vm.save = function () {
                vm.saving = true;

                debugger;
                if (agreementId) {
                    couponAppService.createOrUpdateCoupon(vm.filters).success(function () {
                        abp.notify.info(app.localize('CouponSavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                    });
                } else {
                    vm.filters.noOfCoupons = 1;
                    couponAppService.createOrUpdateCoupon(vm.filters).success(function () {
                        abp.notify.info(app.localize('CouponSavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                    });


                }
            };

            vm.isCouponDateEmpty = function () {
                if (vm.filters.coupon.couponDate) {
                    return true;
                } else {
                    return false;
                }
            };

            vm.searchContacts = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers

                //return directoryService.search({ keyword: $select.search, contactType: 2 }).then(function (response) {
                //    vm.contacts = response.data.items;
                //});
                return directoryService.search({ keyword: $select.search, activeOnly: true }).then(function (response) {
                    vm.contacts = response.data.items;
                });
            };
            vm.searchContactsPopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return 2;
                        }
                    }
                }).result.then(function (supplier) {
                    if (supplier != null) {
                        vm.filters.coupon.customer = supplier;
                        vm.filters.coupon.customerId = supplier.id;
                    }
                });
            };
            vm.cancel = function () {
                $uibModalInstance.close();
            };

            vm.searchLuckyDraws = function ($select) {
                return luckyDrawAppService.search({ keyword: $select.search, activeOnly: true }).then(function (response) {
                    vm.luckyDraws = response.data;
                });
            };

            vm.clearLuckyDraw = function () {
                vm.filters.coupon.luckyDrawId = null;
                vm.filters.coupon.luckyDraw = null;
            };

            vm.getCouponForEdit = function (couponId) {
                vm.loading = true;
                

                couponAppService.getCouponForEdit({ id: couponId }).success(function (data) {

                    vm.coupon = data.totalCount;
                    vm.filters.coupon = data;
                    
                }).finally(function () {
                    vm.loading = false;
                });
            };
            function init() {
                vm.loading = true;
                vm.searchLuckyDraws('');
                if (!agreementId)
                {
                    vm.getCouponForEdit(agreementId);
                }
               
                agreementService.getAgreementWithAdvanceAndDepositForEdit({
                    id: agreementId
                }).success(function (result) {
                    vm.filters.coupon.agreement = result.agreement;
                    if (vm.filters.coupon.agreement) {
                        vm.filters.coupon.charges = result.agreement.totalCharges - result.agreement.tax;
                    }
                }).finally(function () {
                    vm.loading = false;
                });
            }
            init();
        }
    ]);
})();;
