                    { id: 3, taskNumber: 'T003', dateTime: '2025-06-28 13:00', task: 'Team Meeting', resourceId: 'R003', assignedTo: 'User 1', assignedBy: 'Admin', startDateTime: '2025-06-28 14:00', finishDateTime: '2025-06-28 16:00', status: 'Finished' }
