            vm.tollSurcharge = parseFloat(abp.setting.get("App.General.TollsSurCharge"));
            vm.fineSurchargeType = abp.setting.get("App.General.FineSurchargeType");
            vm.tollsSurCharge = abp.setting.get("App.General.TollsSurCharge");
