(function () {

    appModule.controller('tenant.views.crs.lease.smsToLeaseCustomer.index', [
        '$scope', '$uibModal', 'uiGridConstants', '$filter', 'abp.services.app.sMSToLeaseCustomer',
        function ($scope, $uibModal, uiGridConstants, $filter, promotionSMSservice) {

            var vm = this;
            vm.loading = false;
            vm.filters = {
                code: '',
                name: '',
                skipCount: 0,
                customersHavingOpenAgreement: true
                //maxResultCount: app.consts.grid.defaultPageSize,
            };
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';

            vm.sending = false;

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.allBoxTicked = function () {
                if (vm.allPersons === null) return;
                angular.forEach(vm.allPersons, function (row) {
                    if (row.mobileNo && !row.smsStatus)
                        row.generate = vm.tickAllBox;
                });
            };

            vm.checkCheckeditems = function () {
                if (vm.allPersons === null) return false;
                var foundLines = $filter('filter')(vm.allPersons, {
                    generate: true
                }, true);
                if (foundLines && foundLines.length >= 1)
                    return true;
            };

            vm.getAllPersons = function () {
                vm.loading = true;
                //alert(vm.filters.fromDate);
                //set filter dates to date range picker date only if selected dates are not null. by default range picker selects today but does not give values in filters
                //if null then get as following
                //fromDate: get local date with time 00:00:00 and then convert to utc
                //toDate: get local date of max time of night and then convert to utc

                promotionSMSservice.getAllPersons(vm.filters).success(function (data) {
                    vm.allPersons = data;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.getSmsBalance = function () {
                promotionSMSservice.getSmsBalance().success(function (data) {
                    vm.smsBalance = data.marketingSMS;
                    vm.transactionSmsBalance = data.transactionSMS;
                }).finally(function () {
                   // vm.loading = false;
                });
            };

            vm.NoOfSmsInBatch = 10;
            vm.AllPersonForSms = [];

            vm.SelectedPeopleCount = function () {
                if (vm.allPersons)
                    return vm.allPersons.filter(e => e.mobileNo && e.generate && !e.smsStatus).length;
                else
                    return 0;

            };
           
            vm.loadTemplate = function () {
                vm.loading = true;

                promotionSMSservice.getSmsTemplate()
                    .then(function (result) {
                        vm.messageBody = result.data.template; // Adjust this based on your API response
                    })
                    .finally(function () {
                        vm.loading = false;
                    });
            };

            vm.sendPromotions = function () {
                vm.sending = true;
                var sendSmsTo = [];

                //get people with mobile numbers
                angular.forEach(vm.allPersons, function (person) {
                    if (person.mobileNo && person.generate === true && person.smsStatus !== true) {
                        vm.AllPersonForSms.push(person);
                    }
                });

                //condition for return
                if (vm.AllPersonForSms.length < 1) {
                    vm.sending = false;
                    vm.AllPersonForSms = [];
                    vm.tickAllBox = false;

                    vm.getSmsBalance();

                    return;
                }

                //people to send message
                if (vm.AllPersonForSms.length > vm.NoOfSmsInBatch) {
                    for (var i = 0; i < vm.NoOfSmsInBatch; i++) {
                        sendSmsTo.push(vm.AllPersonForSms[i]);
                    }
                } else {
                    for (var k = 0; k < vm.AllPersonForSms.length; k++) {
                        sendSmsTo.push(vm.AllPersonForSms[k]);
                    }
                }

                var promotionSms = {};
                promotionSms.messageBody = vm.messageBody;
                promotionSms.to_Numbers = [];
                for (var j = 0; j < sendSmsTo.length; j++) {
                    if (sendSmsTo[j].mobileNo) {
                        promotionSms.to_Numbers.push(sendSmsTo[j].mobileNo);
                    }
                }

                promotionSMSservice.sendPromotions(promotionSms).success(function (result) {

                    if (result) {
                        var smsStatusDic = result.sendStatus;

                        angular.forEach(sendSmsTo, function (notifiedPerson) {
                            var person = vm.allPersons.filter(x => x.id === notifiedPerson.id);

                            if (smsStatusDic[person[0].mobileNo] === true) {
                                person[0].smsStatus = true;
                                person[0].generate = false;
                            }
                            else {
                                person[0].smsStatus = false;
                                person[0].generate = false;
                            }
                        });
                    }
                    else {
                        angular.forEach(sendSmsTo, function (notifiedPerson) {
                            var person = vm.allPersons.filter(x => x.id === notifiedPerson.id);
                            person[0].smsStatus = false;
                            person[0].generate = false;
                        });
                    }

                    vm.AllPersonForSms = [];
                    vm.sendPromotions();

                }).error(function () {
                    abp.message.error(response.error);

                }).finally(function () {
                    vm.sending = false;
                });
            };

            function init() {
                vm.getAllPersons();
                vm.getSmsBalance();
                vm.loadTemplate();
            }
            init();

        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.lease.tariff.createOrEditModal', [
        '$scope', '$filter', 'utilities', '$uibModal', '$uibModalInstance', 'abp.services.app.tariff', 'tariffGroup', 'tariffGroupId',
        function ($scope, $filter, utilities, $uibModal, $uibModalInstance, tariffService, tariffGroup, tariffGroupId) {

            var vm = this;

            vm.isWeeklyMonthlyEnabled = utilities.parseBoolean(abp.setting.get("App.General.WeeklyMonthlyRental"));

            vm.tariffGroup = tariffGroup;
            vm.saving = false;
            vm.isEditMod = false;
            vm.halfDayLineAdded = false;
            vm.inActive = false;
            vm.filters = {
                tariffGroupId: tariffGroupId,
                agreementCategory: 2
            };
            
            //vm.agreementTypes = [
            //   { type: "Daily", id: 1 },
            //   { type: "Weekly", id: 2 },
            //   { type: "Monthly", id: 3 }
            //];
            
            vm.agreementType = 3; // for monthly agreement by default

            var chargesTypes = {
                rent: 1
            };
            
            var rateTypes = {
                perDay: 1,
                perHour: 7,
                PerHalfDay: 8,
            };
            
            vm.localize = function (input) {
                return app.localize(input);
            };

            vm.agreementTypeChanged = function () {
                
            };

            

            //add rental tariff line
            vm.addTariffLine = function (chargesTypeId, rateTypeId, weekEnd) {
                

                var foundLines = $filter('filter')(vm.tariffLines, {
                    chargesTypeId: chargesTypeId,
                    rateTypeId: rateTypeId,
                    weekEnd: weekEnd
                }, true);

                var order = 1.0;
                var subOrder = 1;
                var chargesType = null;
                var rateType = null;

                if (foundLines.length > 0) {
                    order = foundLines[0].order;
                    subOrder = foundLines.length + 1;
                    chargesType = angular.copy(foundLines[0].chargesType);
                    rateType = angular.copy(foundLines[0].rateType);
                }

                vm.tariffLines.push(
                    {
                        chargesTypeId: chargesTypeId,
                        chargesType: chargesType,
                        order: order,
                        subOrder: subOrder,
                        rateTypeId: rateTypeId,
                        rateType: rateType,
                        tariffGroupId: tariffGroupId,
                        from: 0,
                        to: 0,
                        weekEnd: weekEnd,
                        rate: 0,
                        rateNewDriver: 0,
                        included: false,
                        limit: 0,
                        excessRate: 0,
                        maxUnits: 0
                    });

                if (chargesTypeId == chargesTypes.rent && rateTypeId == rateTypes.PerHalfDay)
                    vm.halfDayLineAdded = true;
            };

            vm.removeTariffLine = function (tariffLine) {
                var chargesTypeId = tariffLine.chargesTypeId;
                var rateTypeId = tariffLine.rateTypeId;
                var weekEnd = tariffLine.weekEnd;

                var index = vm.tariffLines.indexOf(tariffLine);
                vm.tariffLines.splice(index, 1);

                var otherSimilarLines = $filter('filter')(vm.tariffLines, {
                    chargesTypeId: chargesTypeId,
                    rateTypeId: rateTypeId,
                    weekEnd: weekEnd
                }, true);

                var subOrder = 1;
                for (var i = 0; i < otherSimilarLines.length; i++) {
                    otherSimilarLines[i].subOrder = subOrder;
                    subOrder += 1;
                }
                
                if (chargesTypeId == chargesTypes.rent && rateTypeId == rateTypes.PerHalfDay)
                    vm.halfDayLineAdded = false;
            };

            vm.save = function () {
                vm.saving = true;
                tariffService.createOrUpdateTariff({ tariffGroupId: tariffGroupId, inActive: vm.inActive, tariffLines: vm.tariffLines, agreementCategory: 2 }).success(function (result) { // 2 is for lease
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.loading = true;


                tariffService.getTariffForEdit(vm.filters).success(function (result) {
                    vm.tariffLines = result.tariffLines.items;
                    vm.inActive = result.inActive;
                    //check if half day price line is already added. then disable adding new row
                    var foundLines = $filter('filter')(vm.tariffLines, {
                        chargesTypeId: chargesTypes.rent,
                        rateTypeId: rateTypes.PerHalfDay
                    }, true);

                    if (foundLines.length > 0)
                        vm.halfDayLineAdded = true;

                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();

        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.limo.dashboard.index', [
        '$scope', 'abp.services.app.vehicle','abp.services.app.limoTrip', 'abp.services.app.limoTripSearch', '$uibModal',
        function ($scope, vehicleService,tripService, tripSearchService,$uibModal) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
           
            vm.vehiclesSummary = null;
           
            vm.permissions = {
                vehicles: abp.auth.hasPermission('Pages.Tenant.Vehicles'),
            };

            vm.masterFilters = {
                ownership: null,
                vehicleType: null
            };

            vm.ownershipFilterChanged = function () {
                init();
            };

            vm.vehiclePieChart = {};
            vm.vehiclePieChart.type = "PieChart";
            vm.vehiclePieChart.data = {
                "cols": [
                    { id: "t", label: "Topping", type: "string" },
                    { id: "s", label: "Slices", type: "number" }
                ],
                "rows": []
            };

            vm.vehiclePieChart.options = {
                'legend': { position: 'none' },
                width: 120,
                height: 120,
                chartArea: { left: 10, top: 10, bottom: 10, right: 10, height: "100%" },
                colors: ['#36c6d3', '#F1C40F', '#ED6B75', '#1733ed', '#777777', '#FF91F0']
            };

            vm.getlocalDate = function (date) {
                if (date == null)
                    return "";

                var localTime = moment.utc(date).toDate();
                return moment(localTime).format('YYYY-MM-DD');
            };

            vm.getVehiclesSummary = function () {
                vehicleService.getLimoVehiclesSummary(vm.masterFilters).success(function (result) {
                    vm.vehiclesSummary = result;
                   

                    //fill pie chart
                    vm.vehiclePieChart.data.rows.length = 0;
                    vm.vehiclePieChart.data.rows.push({ c: [{ v: app.localize('OnTrip') }, { v: vm.vehiclesSummary.onTrip }] });
                    vm.vehiclePieChart.data.rows.push({ c: [{ v: app.localize('OnNRM') }, { v: vm.vehiclesSummary.onNrm }] });
                    vm.vehiclePieChart.data.rows.push({ c: [{ v: app.localize('InWorkShop') }, { v: vm.vehiclesSummary.workShop }] });
                    vm.vehiclePieChart.data.rows.push({ c: [{ v: app.localize('ForSale') }, { v: vm.vehiclesSummary.forSale }] });
                    vm.vehiclePieChart.data.rows.push({ c: [{ v: app.localize('TotalLoss') }, { v: vm.vehiclesSummary.totalLoss }] });
                    vm.vehiclePieChart.data.rows.push({ c: [{ v: app.localize('Idle') }, { v: vm.vehiclesSummary.idle }] });

                });
            };

            vm.getTripsSummary = function () {
                tripSearchService.getTripsSummary(
                    {
                        todayFromTime: moment().startOf('day'),
                        todayToTime: moment().endOf('day'),
                    }).success(function (result) {
                        vm.tripsSummary = result;
                    });
            };

            vm.getVehicleSummaryNrm = function () {
                vehicleService.getVehicleSummaryNrm(vm.masterFilters)
                    .success(function (result) {
                        vm.vehicleSummaryNrm = result;
                    });
            };

            vm.getVehicleSummaryWorkShop = function () {
                vehicleService.getVehicleSummaryWorkShop(vm.masterFilters)
                    .success(function (result) {
                        vm.vehicleSummaryWorkShop = result;
                    });
            };

            vm.selectVehilceHandler = function (status, statusId, subStatus, fleetType,subStatuses, locationId) {
                //var subStatus = null;
                openListVehicleModal(status, statusId, subStatus, fleetType, subStatuses, locationId);
            };
            
            function openListVehicleModal(status, statusId, subStatus, fleetType, subStatuses, locationId) {
                vm.loading = true;
                var modalInstance = $uibModal.open({
                    animation: true,
                    templateUrl: '~/App/tenant/views/crs/vehicles/listModal.cshtml',
                    controller: 'tenant.views.crs.vehicles.listModal as vm',
                    backdrop: 'static',
                    size: 'xl',
                    resolve: {
                        options: function () {
                            return {
                                status: status,
                                statusId: statusId,
                                subStatus: subStatus,
                                ownerShip: vm.masterFilters.ownership,
                                fleetType: fleetType,
                                subStatuses: subStatuses == null && fleetType == null ? [1, 2, 5, 6, 7, 8] : [],
                                locationId: locationId,
                                DashboardName: "limo",
                            };
                        },
                    }
                });
            }
           
            function init() {
                vm.getTripsSummary();
                if (vm.permissions.vehicles) {
                    vm.getVehiclesSummary();
                }
                vm.getVehicleSummaryNrm();
                vm.getVehicleSummaryWorkShop();
                //vm.getTripsSummary();
                //vm.getVehiclesSummaryIdle();
            };

            init();
        }
    ]);
})();;
