            //    return vehicleService.searchVehicles({ plateNo: $select.search, statusId: 'IDL', tariffGroupId: vm.otherGroupsVehiclePermission && vm.searchOtherGroupsVehicle ? null : vm.trip.tariffGroupId }).then(function (response) {
