                            if (vm.limo.invoiceTo.taxCodeId > 0) {
                                vm.limo.taxPercent = vm.limo.invoiceTo.taxCode.taxPercent;
                            }
                            else {
                                if (vm.branchTaxPercentage)
                                    vm.limo.taxPercent = vm.branchTaxPercentage;
                            }
