(function () {
    appModule.controller('tenant.views.crs.limousine.trips.updateChargesModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'options', 'abp.services.app.limoTrip','utilities',
    function ($scope, $uibModal, $uibModalInstance, options, tripService, utilities) {

        var vm = this;
        vm.saving = false;
        vm.isEditMod = false;
        vm.dateFormat = abp.setting.get("App.General.DateFormat");
        vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
        vm.cancel = function () {
            $uibModalInstance.dismiss();
        };
        vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
        vm.getlocalDateTime = function (date) {
            if (date != null) {
                var localTime = moment.utc(date).toDate();
                return moment(localTime).format(vm.dateTimeFormat);
            }
            else {
                return "";
            }
        };
        //vm.sumCharges = function () {
        //    if (!vm.trip)
        //        return '';
        //    var totalCharges = 0.0;
        //    for (var i = 0; i < vm.trip.tripCharges.length; i++) {
        //        if (vm.trip.tripCharges[i].charges > 0) {
        //            totalCharges += parseFloat(vm.trip.tripCharges[i].charges);
        //        }
        //    }
        //    vm.trip.charges = totalCharges;
        //    return totalCharges;

        //};

        vm.sumCharges = function () {
            if (vm.trip == null) return { totalCharges: 0, totalTax: 0, totalWithTax: 0};
            
            var totalCharges = 0.0;
            var totalTax = 0.0;

            for (var i = 0; i < vm.trip.tripCharges.length; i++) {
                if (vm.trip.tripCharges[i].charges > 0) {
                    var tax = 0;
                    if (vm.trip.tripCharges[i].taxable && vm.trip.taxPercent > 0) {
                        if (vm.isTaxInclusive) {   // prices are with tax. extract include tax amount which will not be added in 
                            //equation solved from following formula... 
                            //chargesWithoutTax + chargesWithoutTax * (taxPercent/100) = chargesWithTax
                            var chargesWithoutTax = (vm.trip.tripCharges[i].charges * 100) / (100 + vm.trip.taxPercent);
                            tax = utilities.round(vm.trip.tripCharges[i].charges - chargesWithoutTax, 2);
                            vm.trip.tripCharges[i].tax = tax;
                            totalTax += utilities.round(tax, 2);
                        } else {
                            tax = utilities.round(vm.trip.tripCharges[i].charges * vm.trip.taxPercent / 100, 2);
                            vm.trip.tripCharges[i].tax = tax;
                            totalTax += utilities.round(tax, 2);

                        }
                    }

                    totalCharges += parseFloat(vm.trip.tripCharges[i].charges);
                    //  totalCharges += parseFloat(totalTax);
                }
                else {
                    vm.trip.tripCharges[i].tax = 0;
                }
            }

            //vm.trip.charges = utilities.round(totalCharges, 2);
            vm.trip.charges = vm.isTaxInclusive ? utilities.round(totalCharges, 2) : (utilities.round(totalCharges, 2) + utilities.round(totalTax, 2)) / 1
            vm.trip.charges = utilities.round(vm.trip.charges, 2);
            vm.trip.tax = utilities.round(totalTax, 2);

            //return totalCharges;
            return { totalCharges: utilities.round(totalCharges, 2), totalTax: utilities.round(totalTax, 2), totalWithTax: (utilities.round(totalCharges, 2) + utilities.round(totalTax, 2)) / 1 };

        };
        vm.localize = function (input) {
            return app.localize(input);
        };

        function init() {
            vm.loading = true;
            tripService.getTripForEdit({ id: options.tripId }).success(function (data) {
                vm.trip = data;
            }).finally(function () {
                vm.loading = false;
            });

        }
        init();
        vm.save = function () {
            vm.saving = true;
            tripService.updateCharges({
                trip: vm.trip,
            }).success(function () {
                abp.notify.info(app.localize('SavedSuccessfully'));
                $uibModalInstance.close();
            }).finally(function () {
                vm.saving = false;
            });
        }
    }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.limousine.trips.updateVehicleModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.vehicleModel', 'abp.services.app.directory', 'abp.services.app.googleMapAPI', '$sce',
        'abp.services.app.commonLookup', 'abp.services.app.limoTrip', 'abp.services.app.tripType', 'abp.services.app.vehicle', 'utilities', 'abp.services.app.invoice', 'appSession', 'trip',
        function ($scope, $uibModal, $uibModalInstance, vehicleModelService, directoryService,
            mapService, $sce, commonLookupService, tripService, tripTypeService, vehicleService, utilities, invoiceService, appSession, trip) {

            var vm = this;
            vm.trip = trip;
            vm.vehicle = trip.vehicle;
            vm.saving = false;

            vm.searchVehicles = function ($select) {
                if ($select.search == "") {
                    vm.vehicles = null; return null;
                }
                return vehicleService.searchVehicles({ plateNo: $select.search, tariffGroupId: trip.tariffGroupId }).then(function (response) {
                    vm.vehicles = response.data.items;
                });
            };

            vm.searchVehiclePopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/vehicles/searchVehicleModal.cshtml',
                    controller: 'tenant.views.crs.vehicles.searchVehicleModal as vm',
                    backdrop: 'static',
                    resolve: {
                        options: function () {
                            return {
                                tariffGroupId: trip.tariffGroupId,
                                allSelectable: true
                            };
                        }
                    }
                }).result.then(function (vehicle) {
                    if (vehicle != null) {
                        vm.vehicle = vehicle;
                    }
                });
            };

            vm.clearVehicle = () => {
                vm.vehicle = null;
            }

            vm.save = () => {
                vm.saving = true;
                tripService
                    .updateVehicle({ tripId: trip.id, vehicleId: vm.vehicle.id })
                    .success(() => {
                        $uibModalInstance.close({ tripId: trip.id, vehicle: vm.vehicle });
                    })
                    .finally(() => {
                        vm.saving = false;
                    });
            }

            vm.cancel = () => {
                $uibModalInstance.close();
            }

            function init() {
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.limousine.trips.uploadDocumentsModal', [
        '$scope', 'appSession', '$uibModalInstance', 'FileUploader',
        function ($scope, appSession, $uibModalInstance, fileUploader) {

            var vm = this;
            vm.loading = false;
            vm.uploadedFileName = null;
            vm.uploadedFileUrl = null;

            vm.uploadHeader = function () {
                return app.localize("Document")
            };

            function guid() {
                function _p8(s) {
                    var p = (Math.random().toString(16) + "000000000").substr(2, 8);
                    return s ? "-" + p.substr(0, 4) + "-" + p.substr(4, 4) : p;
                }
                return _p8() + _p8(true) + _p8(true) + _p8();
            }
            var getGUID = guid();
            vm.uploader = new fileUploader({
                url: abp.appPath + 'Document/UploadDocument/' + getGUID,
                queueLimit: 1,
                autoUpload: true,
                removeAfterUpload: true,
                filters: [{
                    name: 'filter',
                    fn: function (item, options) {
                        //File type check
                        //var type = '|' + item.type.slice(item.type.lastIndexOf('/') + 1) + '|';
                        //if ('|jpg|jpeg|png|'.indexOf(type) === -1) {
                        //    abp.message.warn(app.localize('ProfilePicture_Warn_FileType'));
                        //    return false;
                        //}

                        //File size check
                        if (item.size > 5242880 * 5) //5MB
                        {
                            abp.message.warn(app.localize('Document_Warn_SizeLimit'));
                            return false;
                        }

                        return true;
                    }
                }]
            });

            vm.uploader.onSuccessItem = function (fileItem, response, status, headers) {
                vm.loading = true;
                if (response.success) {
                    vm.uploadedFileName = response.result.fileName;
                    vm.uploadedFileUrl = response.result.url;
                    vm.loading = false;
                    $uibModalInstance.close({ guid: getGUID, name: response.result.fileName, url: response.result.url, urlWithToken: response.result.url + response.result.token });

                } else {
                    abp.message.error(response.error.message);
                }

            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
        }
    ]);
})();;
