(function () {
    appModule.controller('tenant.views.crs.rental.masterAgreements.masterAgreementModal', ['$uibModal', '$uibModalInstance', 'utilities',
        'abp.services.app.directory', 'abp.services.app.vehicleModel', 'abp.services.app.costSetting', 'abp.services.app.chargesSetting', '$filter', 'abp.services.app.rentalMasterAgreement', 'abp.services.app.costParameter', 'agreementId',
        function ($uibModal, $uibModalInstance, utilities, directoryService, vehicleModelService, costSettingService, chargesSettingService, $filter, masterAgreementService, costParameterService, agreementId) {
            var vm = this;

            vm.customers = [];
            vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
            vm.taxPercentage = abp.setting.get("App.General.TaxPercentage");
            vm.isSaleOrderEnabled = abp.features.isEnabled("CRS.Vouchers.SaleOrders");
            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };

            vm.localize = function (input) {
                return app.localize(input);
            };
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getAgreementStatus = function (id) {
                if (id === 1)
                    return "Open";
                else if (id === 2)
                    return "Closed";
                else if (id === 3)
                    return "Cancelled";
            };

            vm.lineWiseMonthsList = function (row, line) {
                var monthsArray = [];
                if (line.amount1Year)
                    monthsArray.push(12);
                if (line.amount2Year)
                    monthsArray.push(24);
                if (line.amount3Year)
                    monthsArray.push(36);
                if (line.amount4Year)
                    monthsArray.push(48);
                if (line.amount5Year)
                    monthsArray.push(60);

                if (!row.agreementId && !row.kMs) {
                    row.kMs = monthsArray[0];
                    vm.periodChanged(row, line);
                }
                return monthsArray;
            };

            function getChargesSettings() {
                vm.loading = true;
                var module = 1;

                chargesSettingService.getChargesSettings({ module: module }).success(function (data) {
                    vm.chargesSettings = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            }

            vm.openViewAgreementModal = function (schedule) {
                openViewAgreementModal(schedule.agreementId);
            };

            function openViewAgreementModal(agreementId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/agreements/viewModal.cshtml',
                    controller: 'tenant.views.crs.agreements.viewModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        agreementId: function () {
                            return agreementId;
                        }
                    }
                });
            }

            vm.periodChanged = function (row, line) {
                if (row.kMs > 0 && row.kMs <= 12)
                    row.rentRate = line.amount1Year ? line.amount1Year : 0;

                else if (row.kMs > 12 && row.kMs <= 24)
                    row.rentRate = line.amount2Year ? line.amount2Year : 0;

                else if (row.kMs > 0 && row.kMs <= 36)
                    row.rentRate = line.amount3Year ? line.amount3Year : 0;

                else if (row.kMs > 0 && row.kMs <= 48)
                    row.rentRate = line.amount4Year ? line.amount4Year : 0;

                else if (row.kMs > 0 && row.kMs <= 60)
                    row.rentRate = line.amount5Year ? line.amount5Year : 0;
                else
                    row.rentRate = 0;
            };

            function getTaxAmount(amount) {
                var taxAmount = amount / (1 + (vm.taxPercentage / 100));
                return taxAmount;
            }

            vm.addAgreementUnderMasterAgreement = function (schedule, quotationLine) {
                openCreateOrEditRentalAgreementModal(schedule, quotationLine);
            };

            function openCreateOrEditRentalAgreementModal(schedule, quotationLine) {

                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/agreements/createOrEditModalForMaster.cshtml',
                    controller: 'tenant.views.crs.agreements.createOrEditModalForMaster as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        options: function () {
                            return {
                                chargesSettings: vm.chargesSettings,
                                quotationRates: quotationLine.extrasLines,
                                masterAgreementId: vm.masterAgreement.id,
                                date: moment().utc(),
                                noOfMonths: schedule.kMs,
                                customer: vm.masterAgreement.quotation.customer,
                                customerId: vm.masterAgreement.quotation.customerId,
                                vehicleType: quotationLine.vehicleType,
                                saleOrderToPass: vm.masterAgreement.saleOrderMasterAgreement,
                                notes: quotationLine.descToPass,
                                vehicleModel: quotationLine.vehicleModel,
                                customerPoNo: vm.masterAgreement.poNo,
                                rateType: vm.masterAgreement.quotation.type,
                                taxPercent: vm.masterAgreement.quotation.taxPercent,
                                skipTariff: true
                            };
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    if (result) {
                        schedule.agreementId = result;
                    }
                    updateScheduleLine(schedule);
                });
            }
            function updateScheduleLine(schedule) {
                masterAgreementService.updateScheduleLine(schedule)
                    .success(function () {
                        init();
                    })
                    .finally(function () {
                        vm.loading = false;
                    });
            }

            vm.save = function () {
                vm.loading = true;
                masterAgreementService.createOrUpdateMasterRentalAgreement({ masterAgreement: vm.masterAgreement })
                    .success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    })
                    .finally(function () {
                        vm.loading = false;
                    });
            };
            function init() {
                vm.loading = true;

                vm.unitLines = [];

                masterAgreementService.getMasterAgreementForView({ id: agreementId })
                    .success(function (data) {
                        vm.loading = false;
                        vm.masterAgreement = data;

                        vm.masterAgreement.quotation.quotationLines.forEach(function (value, index) {

                            for (let i = 0; i < value.quantity; i++) {
                                var amount = 0;

                                value.extrasLines.forEach(function (val, line) {
                                    amount = amount + val.rate;
                                });

                                //vm.unitLines.push({ quotationLine: angular.copy(value), index: i + 1, rate: amount });

                                vm.masterAgreement.schedule.forEach(row => {
                                    if (row.vehicleTypeId == value.vehicleTypeId) {
                                        row.rate = amount;
                                    }
                                });
                            }

                                //var makeName = value.vehicleModel.make.name;
                                //var modelName = value.vehicleModel.name;
                                //var title = value.vehicleType.title;
                                var description = value.description;

                            value.descToPass = description;

                            
                        });

                        vm.masterAgreement.quotation.quotationLines.forEach(line => {
                            var looping = 1;
                            vm.masterAgreement.schedule.forEach(row => {
                                if (row.vehicleTypeId == line.vehicleTypeId) {
                                    row.unitNo = looping++;
                                }
                            });
                        });

                        getChargesSettings();

                    }).finally(function () {

                    });
            }

            init();

        }]);
})();;
(function () {
    appModule.controller('tenant.views.rental.masterAgreements.printModal', ['$scope', '$sce', 'appSession', '$stateParams', 'utilities', 'abp.services.app.leaseClause', 'abp.services.app.rentalMasterAgreement',
        function ($scope, sce, appSession, $stateParams, utilities, leaseClauseService, masterAgreementService) {
            var vm = this;
            vm.loading = false;
            vm.tenantName = appSession.tenant.name;
            vm.tenancyName = appSession.tenant.tenancyName;
            vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
            vm.currency = abp.setting.get("App.General.CurrencyCode");
            //vm.trafficFineSurCharge = abp.setting.get("App.General.TrafficFineSurCharge");
            vm.trafficFineSurCharge = parseFloat(abp.setting.get("App.General.TrafficFineSurCharge"));
            vm.tollSurcharge = parseFloat(abp.setting.get("App.General.TollsSurCharge"));
            vm.fineSurchargeType = abp.setting.get("App.General.FineSurchargeType");
            vm.tollsSurCharge = abp.setting.get("App.General.TollsSurCharge");
            vm.taxPercent = parseFloat(abp.setting.get("App.General.TaxPercentage"));
            vm.termsAndConditions = sce.trustAsHtml(app.localize('RentalTermsAndConditions'));
            vm.fileName = vm.tenancyName.toLowerCase() + '-' + 'header.png';
            vm.showSignatureButton = true;
            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };
            vm.clauseTypeDataName = null;
            //if pop-up print
            if ($scope.$parent != null) {
                if (!isNaN($scope.$parent.vmMain.masterAgreementId))
                    masterAgreementId = $scope.$parent.vmMain.masterAgreementId;
            }
            //if through url print
            if (masterAgreementId == 0 && !isNaN($stateParams.query)) {
                masterAgreementId = $stateParams.query;
            }
            vm.onImageError = function () { vm.imgError = true; };
            vm.localize = function (input) {
                if (input == null)
                    return "";

                return app.localize(input);
            };
            vm.getClauses = function (id) {
                vm.loading = true;
                vm.clauseTypeDataName = null;
                leaseClauseService.getClausesForEdit({
                    id: id
                }).success(function (data) {
                    vm.clauseTypeDataName = data.name
                    return vm.clauseTypeDataName;
                }).finally(function () {
                    vm.loading = false;
                });
            };
            vm.getCustomerId = function (documents) {
                var customerDocuments = "";
                if (documents != null) {
                    var nationalId = documents.filter(e => e.identityDocumentType == 3);
                    if (nationalId != null) {
                        customerDocuments = nationalId[0];
                    }
                    else {
                        var passportId = documents.filter(e => e.identityDocumentType == 2);
                        if (passportId != null) {
                            customerDocuments = passportId[0];
                        }
                    }
                    return customerDocuments;
                }
            }

            vm.getAllowedCharges = function (charges) {
                if (charges != null) {
                    var result = charges.filter(e => e.chargesTypeId == 5);
                    if (result != null) {
                        return result[0];
                    }
                }
            };
            vm.getlocalDateTime = function (date, format) {
                if (date == null)
                    return "";

                var localTime = moment.utc(date).toDate();
                return moment(localTime).format(format);
            };
            vm.getFuelLevel = function (value) {
                if (value == null)
                    return "";

                if (value == 0) {
                    return "0/8";
                } else if (value > 0 && value <= 0.125) {
                    return "1/8";
                } else if (value > 0.125 && value <= 0.25) {
                    return "2/8";
                } else if (value > 0.25 && value <= 0.375) {
                    return "3/8";
                } else if (value > 0.375 && value <= 0.5) {
                    return "4/8";
                } else if (value > 0.5 && value <= 0.625) {
                    return "5/8";
                } else if (value > 0.625 && value <= 0.75) {
                    return "6/8";
                } else if (value > 0.75 && value <= 0.875) {
                    return "7/8";
                } else if (value > 0.875 && value <= 1) {
                    return "8/8";
                } else {
                    return "";
                }

            };
            vm.init = function () {
                vm.loading = true;
                masterAgreementService.getMasterAgreementRentalForPrint({ id: masterAgreementId })
                    .success(function (result) {
                        vm.masterAgreement = result;
                        vm.linesToIterate = [];
                        var srNo = 1;
                        vm.masterAgreement.quotation.quotationLines.forEach(line => {
                            line.printQuantity = true;
                            vm.masterAgreement.schedule.forEach(schedule => {
                                if (schedule.agreement) {
                                    if (line.vehicleTypeId == schedule.vehicleTypeId && schedule.vehicleModelId == line.vehicleModelId && schedule.agreement.vehicle.customField3)
                                        line.printQuantity = false;
                                }
                                if (schedule.agreement) {
                                    if (line.vehicleTypeId == schedule.vehicleTypeId && line.vehicleModelId == schedule.agreement.vehicle.modelId) {
                                        obj = new Object();
                                        obj.srNo = srNo;
                                        obj.plateNo = schedule.agreement.vehicle.plateNo;
                                        obj.description = line.description;
                                        obj.closingLocationName = schedule.agreement.closingLocation?.name;

                                        obj.vehicleModel = line.vehicleModel.make.name + ' ' +
                                            +' ' + line.vehicleModel.name + ' ' + (line.vehicleType.title)

                                        line.closingLocationName = schedule.agreement.closingLocation?.name;
                                        srNo++;
                                        vm.linesToIterate.push(obj);
                                    }
                                } else {
                                    if (line.vehicleTypeId == schedule.vehicleTypeId && line.vehicleModelId == schedule.vehicleModelId) {
                                        obj = new Object();
                                        obj.srNo = srNo;
                                        
                                        obj.description = line.description;
                                        
                                        obj.vehicleModel = line.vehicleModel.make.name + ' ' +
                                            +' ' + line.vehicleModel.name + ' ' + (line.vehicleType.title)

                                       
                                        srNo++;
                                        vm.linesToIterate.push(obj);
                                    }
                                }
                                 
                                


                            });
                        });
                        masterAgreementService.getMasterAgreementForView({ id: masterAgreementId })
                            .success(function (result) {
                                vm.masterAgreementView = result;

                            }).finally(function () {
                                vm.loading = false;
                            });
                    }).finally(function () {
                        vm.loading = false;
                });
            };
        }]);
})();;
