                    vm.periodsday.push({ fromDay: 31, toDay: 60 });
                    vm.periodsday.push({ fromDay: 61, toDay: 90 });
                    vm.periodsday.push({ fromDay: 91, toDay: 120 });
                    vm.periodsday.push({ fromDay: 121, toDay: 150 });
