(function () {
    appModule.controller('tenant.views.crs.reports.reconcileDarbTolls.index', [
        '$scope', 'abp.services.app.toll', 'abp.services.app.salikAccount', 'chromeExtDownloader',
        function ($scope, tollService, salikAccountService, chromeExtDownloader) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.salikTolls = [];
            vm.salikAccounts = [];
            vm.selectedSalikAccounts = [];

            vm.tollsCountLoading = false;
            vm.totalOnlineCount = 0;
            vm.totalDownloadedCount = 0;
            vm.totalDifference = 0;

            vm.tollStatus = {
                dubai: {},
                abuDhabi: {}
            };

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.tollDownloader = {
                dubai: {},
                abuDhabi: {
                    isDownloading: false,
                    progress: 0,
                    status: '',
                    error: null
                }
            };

            vm.isRecoRun = false;
            vm.getSalikReconciliation = function () {

                if (vm.isRecoRun) return;
                vm.isRecoRun = true;

                var accountWithCount = [];
                vm.tollsCountLoading = true;

                if (vm.salikAccounts.AccountWiseCounts)
                    angular.forEach(vm.salikTolls.AccountWiseCounts, function (v, k) {
                        accountWithCount.push({ key: v.username, value: v.tollsCount });
                    });
                else { //MV3
                    vm.selectedSalikAccounts.forEach(x => {
                        accountWithCount.push({ key: x.username, value: 0 });
                    })
                }

                var tollsReqToDate = vm.filters.toDate;
                if (tollsReqToDate > moment())
                    tollsReqToDate = moment();

                var reqData = {
                    accountWithCount: accountWithCount,
                    fromDate: vm.filters.fromDate,
                    toDate: tollsReqToDate,
                    servers: 2
                };

                tollService.getReconcileToll(reqData)
                    .success(function (result) {
                        vm.accountReconcileDetails = result.items;

                        vm.totalOnlineCount = 0;
                        vm.totalDownloadedCount = 0;
                        vm.totalDifference = 0;

                        angular.forEach(vm.accountReconcileDetails, function (v, k) {
                            v.onlineCount = v.downloadedCount;
                            v.difference = 0;

                            vm.totalDownloadedCount += v.downloadedCount;
                            vm.totalOnlineCount += v.onlineCount;
                            vm.totalDifference += v.difference;
                        });

                        if (vm.downloadTolls)
                            vm.downloadingTolls = false;
                        vm.tollStatus.abuDhabi.isDownloading = false;
                    })
                    .error(function (reason) {
                        abp.notify.error(reason);
                    })
                    .finally(function () {
                        vm.tollsCountLoading = false;
                        vm.isRecoRun = false;
                    });
            };

            vm.downloadTollsV3 = function (getOnlyCount) {
                //var req = {
                //    fromDate: vm.filters.fromDate.format('YYYY-MM-DD'),
                //    toDate: vm.filters.toDate.format('YYYY-MM-DD'),
                //    tollAccounts: vm.selectedSalikAccounts.length > 0 ? vm.selectedSalikAccounts : vm.salikAccounts,
                //    isEtoll: true
                //};

                ////const nonReconciledAccounts = vm.accountReconcileDetails.filter(x => x.difference);
                //vm.tollAccountsDownloadingRes = {
                //    request: req,
                //    getOnlyCount: true,
                //    tollAccounts: req.tollAccounts
                //};

                chromeExtDownloader.downloadTollsV3(vm, false);
            };

            vm.getTollsCount = function () {
                debugger;
                vm.filters.fromDate = moment(vm.filters.monthYear).startOf('month');
                vm.filters.toDate = moment(vm.filters.monthYear).endOf('month').endOf('day');

                var tollsReqToDate = vm.filters.toDate;
                if (tollsReqToDate > moment())
                    tollsReqToDate = moment();

                vm.tollsCountLoading = true;
                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    vm.tollAccountsDownloadingRes = {
                        request: {
                            fromDate: vm.filters.fromDate.format('YYYY-MM-DD'),
                            toDate: vm.filters.toDate.format('YYYY-MM-DD')
                        },
                        getOnlyCount: false,
                        tollAccounts: vm.selectedSalikAccounts,
                        dateSlabs: []
                    };

                    vm.callbackOnComplete = () => { vm.getSalikReconciliation(); }
                    vm.tollStatus.abuDhabi.isDownloading = true;
                    vm.downloadTolls = true;
                    chromeExtDownloader.initV3(vm, vm.downloadTollsV3)
                }
                else
                    getSalikCount({
                        fromDate: vm.filters.fromDate.format('YYYY-MM-DD'),
                        toDate: tollsReqToDate.format('YYYY-MM-DD'),
                        salikAccounts: vm.selectedSalikAccounts.length > 0 ? vm.selectedSalikAccounts : vm.salikAccounts
                    });
            };

            vm.downloadTolls = function () {
                vm.downloadingTolls = true;
                vm.tollStatus.abuDhabi.error = '';

                //if reconcile accounts have 0 toll difference from web then don't include in downloading
                //vm.salikAccounts = vm.salikAccounts.filter(x =>
                //    vm.accountReconcileDetails.find(y => y.accountName === x.username && y.amount > 0));

                var tollsReqToDate = vm.filters.toDate;
                if (tollsReqToDate > moment())
                    tollsReqToDate = moment();

                var req = {
                    fromDate: vm.filters.fromDate.format('YYYY-MM-DD'),
                    toDate: tollsReqToDate.format('YYYY-MM-DD'),
                    salikAccounts: vm.selectedSalikAccounts.length > 0 ? vm.selectedSalikAccounts : vm.salikAccounts,
                    isEtoll: true
                };

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    vm.tollDownloader.abuDhabi.isDownloading = true;
                    vm.callbackOnComplete = () => { vm.getSalikReconciliation(); }
                    vm.tollAccountsDownloadingRes.getOnlyCount = false;
                    chromeExtDownloader.initV3(vm, vm.downloadTollsV3);
                }
                else {
                    var funcNode = document.getElementById('speedExtReportingSalik');
                    if (funcNode) {
                        funcNode.parentElement.removeChild(funcNode);
                    }

                    chromeExtDownloader.downloadTolls(
                        req,
                        function () {
                            debugger;
                        },
                        function error(e) {

                            vm.downloadTolls = false;

                            if (!$scope.$$phase)
                                $scope.$digest();

                            abp.message.error(e.error, null, true);
                        });
                }
            };

            vm.cancel = function () {
                chromeExtDownloader.closeAllTabs({});
            };

            function getSalikCount(reqeust) {

                vm.tollStatus.abuDhabi.countError = '';

                var funcNode = document.getElementById('speedExtReportingSalikCount');
                if (funcNode) {
                    funcNode.parentElement.removeChild(funcNode);
                }

                var script1 = document.createElement('script');
                script1.id = 'speedExtReportingSalik';
                script1.appendChild(document.createTextNode(`function reportStatus(status) {
                            var $scope = angular.element(document.querySelectorAll('[ng-controller]')[1]).scope();
                            if(status.error){
                                $scope.vm.tollsCountLoading = false;
                            }

                            if (!$scope.vm.tollStatus.abuDhabi)
                                $scope.vm.tollStatus.abuDhabi = {};

                            if (status.isComplated || status.error) {
                                $scope.vm.downloadingTolls = false;

                                if (!status.error)
                                    $scope.vm.getSalikReconciliation();

                                $scope.vm.tollStatus.abuDhabi.error = status.error;
                                $scope.vm.tollStatus.abuDhabi.status = status.status;

                            }
                            else {
                                $scope.vm.downloadingTolls = true;
                                $scope.vm.tollStatus.abuDhabi.error = '';

                                $scope.vm.tollStatus.abuDhabi.progress = status.progress;
                                $scope.vm.tollStatus.abuDhabi.status = status.status;
                            }

                            if (!$scope.$$phase) {
                                $scope.$digest();
                            }
                        }`));
                (document.body || document.head || document.documentElement).appendChild(script1);

                var script = document.createElement('script');
                script.id = 'speedExtReportingSalikCount';
                script.appendChild(document.createTextNode(
                    `function reportSalikCountStatus(status) {
                        var $scope = angular.element(document.querySelectorAll('[ng-controller]')[1]).scope();

                        if (status.reportCount) {
                            $scope.vm.salikTolls.TotalCount = status.requestData.totalTolls;
                            $scope.vm.salikTolls.AccountWiseCounts = status.requestData.salikAccounts;
                            $scope.vm.tollsCountLoading = false;
                            $scope.vm.getSalikReconciliation();
                        }
                        else if (status.showCaptchaMessage) {
                            if(!$scope.vm.tollStatus.abuDhabi) $scope.vm.tollStatus.abuDhabi = {};
                            $scope.vm.tollStatus.abuDhabi.status = 'Fill Captcha on site...';
                        }
                        else if (status.error) {
                            $scope.vm.tollsCountLoading = false;
                            $scope.vm.tollStatus.abuDhabi.countError = status.error;
                        }

                        if (!$scope.$$phase) {
                            $scope.$digest();
                        }
                    }`
                ));

                (document.body || document.head || document.documentElement).appendChild(script);

                chromeExtDownloader.getSalikCount(
                    reqeust,
                    null,
                    function error(e) {

                        vm.tollsCountLoading = false;

                        if (!$scope.$$phase)
                            $scope.$digest();

                        abp.message.error(e.error, null, true);
                    }
                );
            }

            vm.showError = function (error) {
                abp.message.error(error);
            };

            (function () {
                salikAccountService.getSalikAccountsForExtension({ id: 2 })
                    .success(function (data) {
                        vm.salikAccounts = data.items;
                    });
            })();

        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.reports.reconcileTolls.index', [
        '$scope', 'abp.services.app.toll', 'abp.services.app.salikAccount', 'chromeExtDownloader',
        function ($scope, tollService, salikAccountService, chromeExtDownloader) {
            var vm = this;

            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().format(abp.setting.get("App.General.DateFormat"));
            let downloadUnchargedSalikTolls = abp.setting.get("App.General.Salik.DownloadUnchargedSalikTolls") == 'True' ? true : false;

            vm.dateRangeCountBreakup = [];

            vm.salikTolls = [];
            vm.salikTolls.TotalCount = null;
            vm.salikAccounts = [];
            vm.selectedSalikAccounts = [];
            vm.daysToReconcile = [];
            vm.filters = {};
            vm.totalCount = 0;
            vm.totalLiveCount = 0;

            vm.tollStatus = { isDownloading: false };

            vm.tollStatus = {
                abuDhabi: {},
                dubai: {
                    isDownloading: false,
                    progress: 0,
                    status: '',
                    error: null
                }
            };

            vm.tollCountError = '';

            var salikFeatureEnabled = abp.features.isEnabled('CRS.Tolls.Salik');

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.dateRangeModelChanged = function () {
                vm.filters.fromDate = moment(vm.dateRangeModel.startDate).startOf('day');
                vm.filters.toDate = moment(vm.dateRangeModel.endDate).endOf('day');
            };

            vm.applyLiveCount = function () {
                tollService.getTollsCountBreakupDateWise(vm.filters)
                    .success(function (data) {
                        debugger;
                        console.log('applying live count');
                        vm.totalCount = 0;
                        vm.totalLiveCount = 0;

                        $scope.vm.tollsCountBreakup.forEach(x => {
                            let a = data.items.find(y => y.day == x.day);
                            x.count = a.count;
                            vm.totalCount += x.count;
                            vm.totalLiveCount += x.liveCount;

                            if (x.count == x.liveCount)
                                x.shoulReconcile = null;
                        });

                        if (!$scope.$$phase) {
                            $scope.$digest();
                        }
                    });

            };

            vm.downloadTolls = function () {
                vm.tollStatus.dubai.isDownloading = true;
                vm.tollStatus.dubai.error = null;

                vm.filters.fromDate = moment(vm.dateRangeModel.startDate).startOf('day');
                vm.filters.toDate = moment(vm.dateRangeModel.endDate).endOf('day');

                var req = {
                    fromDate: vm.filters.fromDate.format('YYYY-MM-DD'),
                    toDate: vm.filters.toDate.format('YYYY-MM-DD'),
                    tagNo: [],
                    salikAccounts: [],
                    isEtoll: false,
                    forReconciliation: true
                };

                req.salikAccounts = vm.tollAccounts.filter(a => a.id == vm.singleSeletedAccount);
                req.salikAccounts[0].daysToReconcile = vm.daysToReconcile;
                req.downloadUnchargedSalikTolls = downloadUnchargedSalikTolls;

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    chromeExtDownloader.initV3(vm, vm.downloadTollsV3);
                    return;
                }

                chromeExtDownloader.downloadTolls(
                    req,
                    `function reportStatus(status) {
						var $scope = angular.element('#appController').scope();
						if (!$scope) return;

						if (!$scope.vm.tollStatus.dubai)
							$scope.vm.tollStatus.dubai = {};

						if (status.isComplated || status.error) {

							$scope.vm.tollStatus.dubai.isDownloading = false;

							//if (!status.error) {
								$scope.vm.applyLiveCount();
							//}
							
							$scope.vm.daysToReconcile = [];
							$scope.vm.tollsCountBreakup.forEach(x => { x.processing = false; });
							$scope.vm.tollStatus.dubai.error = status.error;
							$scope.vm.tollStatus.dubai.status = status.status;

						}
						else if (status.isSlabCompleted) {
							debugger;
							let o = $scope.vm.tollsCountBreakup.find(y => y.day == status.slabProcessing + 'T00:00:00Z');
							o.processing = false;
							$scope.vm.daysToReconcile.splice($scope.vm.daysToReconcile.indexOf(o.day), 1);
							$scope.vm.applyLiveCount();
						}
						else {
							$scope.vm.tollStatus.dubai.isDownloading = true;
							$scope.vm.tollStatus.dubai.error = '';

							$scope.vm.tollStatus.dubai.progress = status.progress;
							$scope.vm.tollStatus.dubai.status = status.status;
							if ($scope.vm.tollsCountBreakup.length && status.slabProcessing)
								$scope.vm.tollsCountBreakup.find(y => y.day == status.slabProcessing + 'T00:00:00Z').processing = true;
 
						}

						if (!$scope.$$phase) {
							$scope.$digest();
						}
					}`,
                    function error(e) {
                        vm.tollStatus.dubai.isDownloading = false;

                        if (!$scope.$$phase)
                            $scope.$digest();

                        abp.message.error(e.error, null, true);
                    });

            };

            vm.search = function () {
                vm.tollStatus.dubai.isCheckingCount = true;
                vm.tollStatus.dubai.error = null;

                vm.filters.fromDate = moment(vm.dateRangeModel.startDate).startOf('day');
                vm.filters.toDate = moment(vm.dateRangeModel.endDate).endOf('day');
                vm.filters.salikAccountId = vm.singleSeletedAccount;
                vm.tollsCountBreakup = [];
                var diffDays = Math.ceil(Math.abs((new Date(vm.filters.toDate)) - (new Date(vm.filters.fromDate))) / (1000 * 60 * 60 * 24));
                if (diffDays > 31) {
                    vm.loading = false;
                    abp.message.error("Date Range's difference cannot be more than 31 days.");
                    return;
                }

                tollService.getTollsCountBreakupDateWise(vm.filters)
                    .success(function (data) {
                        vm.tollsCountBreakup = data.items;
                    }).finally(function () {
                        let accs = vm.tollAccounts.filter(x => x.id == vm.singleSeletedAccount);
                        getSalikCount({
                            fromDate: vm.filters.fromDate.format('YYYY-MM-DD'),
                            toDate: vm.filters.toDate.format('YYYY-MM-DD'),
                            salikAccounts: accs,
                            downloadUnchargedSalikTolls: downloadUnchargedSalikTolls,
                            isEtoll: false
                        });
                    });
            };

            vm.enableDebugging = true;
            vm.downloadTollsV3 = function () {
                vm.downloadingResponse = [];
                //function defination
                function getReconciliationSummary(preserveOnlineCount, callback) {
                    vm.filters.fromDate = moment(vm.dateRangeModel.startDate).startOf('day');
                    vm.filters.toDate = moment(vm.dateRangeModel.endDate).endOf('day');
                    vm.filters.salikAccountId = vm.singleSeletedAccount;

                    if (!preserveOnlineCount)
                        vm.tollsCountBreakup = [];

                    var diffDays = Math.ceil(Math.abs((new Date(vm.filters.toDate)) - (new Date(vm.filters.fromDate))) / (1000 * 60 * 60 * 24));
                    if (diffDays > 31) {
                        vm.loading = false;
                        abp.message.error("Date Range's difference cannot be more than 31 days.");
                        return;
                    }

                    tollService.getTollsCountBreakupDateWise(vm.filters)
                        .success(function (data) {
                            debugger;
                            vm.totalLiveCount = 0;
                            vm.totalCount = 0;

                            if (!preserveOnlineCount) {
                                vm.tollsCountBreakup = data.items;
                                data.items.forEach(x => {
                                    vm.totalCount += x.count;
                                    vm.totalLiveCount += (x.liveCount ? x.liveCount : 0);
                                });
                            }
                            else
                                vm.tollsCountBreakup.forEach(x => {
                                    x.processing = false;
                                    const o = data.items.find(d => d.day == x.day);
                                    x.count = o.count;
                                    vm.totalCount += o.count;
                                    vm.totalLiveCount += (x.liveCount ? x.liveCount : 0);
                                });

                        }).finally(() => callback && callback());
                }

                vm.isLoading = false;
                vm.callbackOnComplete = function () {
                    if (vm.isLoading) return;
                    console.info('callbackOnComplete code run.');
                    vm.isLoading = true;
                    getReconciliationSummary(true, () => {
                        vm.tollStatus.dubai.isDownloading = false;
                        vm.tollStatus.dubai.isCheckingCount = false;
                        vm.isLoading = false;

                        if (!$scope.$$phase)
                            $scope.$digest();
                    });
                };

                vm.reponseCallback = function (res) { //reponse received from extension to show progress
                    console.info('reponseCallback code run.');
                };

                debugger;

                //calling the function
                if (vm.tollStatus.dubai.isCheckingCount)
                    getReconciliationSummary(false, function () {
                        const accounts = vm.tollAccounts.filter(x => x.id == vm.filters.salikAccountId);
                        vm.tollAccountsDownloadingRes = {
                            request: {},
                            getOnlyCount: true,
                            fromDate: null,
                            toDate: null,
                            tollAccounts: accounts,
                            dateSlabs: []
                        };

                        for (var i in vm.tollsCountBreakup) {
                            const val = vm.tollsCountBreakup[i];
                            vm.tollAccountsDownloadingRes.dateSlabs.push({ fromDate: val.day.split('T')[0], downloadedCount: val.count, tollsCountOnSite: 0 });
                        }

                        chromeExtDownloader.downloadTollsV3(vm, false);
                    });
                else {
                    vm.tollAccountsDownloadingRes.dateSlabs = undefined;
                    vm.tollStatus.dubai.isDownloading = true;
                    chromeExtDownloader.downloadTollsV3(vm, false);
                }
            };

            function getSalikCount(reqeust) {

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    reqeust.getOnlyCount = true;
                    chromeExtDownloader.initV3(vm, vm.downloadTollsV3);
                    return;
                }

                chromeExtDownloader.getSalikCount(
                    reqeust,
                    `function reportSalikCountStatus(status) {
						var $scope = angular.element('#appController').scope();
						if (status.reportCount && status.requestData.salikAccount) {
							debugger;
							$scope.vm.daysToReconcile = [];
							$scope.vm.tollCountError = '';
							$scope.vm.tollsCountBreakup.forEach(x => {
								let a = status.requestData.salikAccount.tollsDateList.find(y => y.day == x.day.split('T')[0]);

								if (a) {
									x.liveCount = a.count;
									if (a.count > x.count) {
										$scope.vm.daysToReconcile.push(x.day);
										x.shoulReconcile = true;
									}
								}
							});

							$scope.vm.tollStatus.dubai.isCheckingCount = false;
						}
						else if (status.isComplated && status.error) {
							$scope.vm.tollsCountBreakup.forEach(x => { x.liveCount = 0; });
							$scope.vm.tollStatus.dubai.isCheckingCount = false;
							$scope.vm.tollStatus.dubai.isDownloading = false;
							$scope.vm.salikTolls.TotalCount = 0;
							$scope.vm.tollCountError = status.error;
						}

						if (!$scope.$$phase) {
							$scope.$digest();
						}
					}

						`,
                    function error(e) {

                        $scope.vm.tollStatus.dubai.isCheckingCount = false;
                        $scope.vm.tollStatus.dubai.isDownloading = false;

                        if (!$scope.$$phase)
                            $scope.$digest();

                        abp.message.error(e.error, null, true);
                    }
                );
            }

            vm.cancelAll = function () {
                chromeExtDownloader.closeAllTollsTabs();
                vm.tollStatus.dubai.isCheckingCount = false;
            };

            (function () {
                debugger;
                if (!salikFeatureEnabled) {
                    abp.message.error('', 'One of the Features Salik should be Enabled.');
                }
                else {
                    salikAccountService.getSalikAccountsForExtension({ id: 1 })
                        .success(function (data) {
                            vm.tollAccounts = data.items;
                        });
                }
            })();

            vm.showError = function (error) {
                if (error)
                    abp.message.error(error);
            };

        }
    ]);
})();;
