(function () {
    appModule.controller('tenant.views.crs.transportation.agreements.report', ['$scope', '$stateParams', 'abp.services.app.transAgreement',
        function ($scope, $stateParams, transAgreementService) {

            var vm = this;

            vm.filters = null;

            if ($scope.$parent !== null) {
                if ($scope.$parent.vmMain !== null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters === null)
                vm.filters = $stateParams.filters;

            if (vm.filters.agreementNo) {
                vm.filters.plateNo = null;
                vm.filters.startDate = null;
                vm.filters.endDate = null;
                vm.filters.customerId = null;
                vm.filters.customer = null;
                vm.filters.driver = null;
                vm.filters.driverId = null;
                vm.filters.status = null;
            }
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.getStatuses = function () {
                if (!vm.filters.status) return '';
                if (vm.filters.status == 1)
                    return app.localize("Open");
                else if (vm.filters.status == 2)
                    return app.localize("Closed");
            };

            vm.getlocalizedString = function (agreementStatus) {
                if (agreementStatus == 1)
                    return app.localize("Open");
                if (agreementStatus == 2)
                    return app.localize("Closed");
            };

            function init() {
                vm.loading = true;
                transAgreementService.getTransAgreementsReport(vm.filters).success(function (data) {
                    vm.agreementReportData = data.items;
                    angular.forEach(vm.agreementReportData, function (value, key) {
                        vm.totalAmount += value.amount;
                    });
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }]);
})();;
(function () {

    appModule.controller('tenant.views.crs.transportation.agreements.viewModal', [
        '$scope','$uibModalInstance','agreementId','abp.services.app.transAgreement',
        function ($scope, $uibModalInstance,agreementId, transAgreementService) {
            var vm = this;
            vm.loading = false;

            vm.localizeWeekDays = function (weekDay) {
                //if (!weekDay) return '';
                if (weekDay == 0) return app.localize('Sunday');
                else if (weekDay == 1) return app.localize('Monday');
                else if (weekDay == 2) return app.localize('Tuesday');
                else if (weekDay == 3) return app.localize('Wednesday');
                else if (weekDay == 4) return app.localize('Thursday');
                else if (weekDay == 5) return app.localize('Friday');
                else if (weekDay == 6) return app.localize('Saturday');

            }

            vm.localize = function (input) {
                return app.localize(input);
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM-DD HH:mm:ss');
                }
                else {
                    return "";
                }
            };

            vm.getlocalTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('HH:mm');
                }
                else {
                    return "";
                }
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.loading = true;
                transAgreementService.getTransAgreementForEdit({ id: agreementId }).success(function (data) {
                    vm.transAgreement = data;
                }).finally(function () {
                    vm.loading = false;
                });

            }

            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.transportation.agreements.print', [
        '$scope', 'appSession',
        function ($scope, appSession) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.getTemplateUrl = function () {
         
                var template = abp.features.getValue('CRS.Transportation.Agreements.PrintTemplate').toLowerCase();
                if (template == undefined || template == '')
                    template = 'standard';

                if (template == 'custom')
                    return '~/App/tenant/views/crs/transportation/agreements/printtemplates/tenants/' + appSession.tenant.tenancyName.toLowerCase() + '.cshtml';
                else if (template == 'englisharabic')
                    return '~/App/tenant/views/crs/transportation/agreements/printtemplates/englisharabic.cshtml';
                else
                    return '~/App/tenant/views/crs/transportation/agreements/printtemplates/' + template + '.cshtml';
            };
        }
    ]);
})();;
