(function () {
    appModule.controller('tenant.views.crs.vehicles.defleetModal', [
        '$scope', '$uibModalInstance', 'abp.services.app.vehicle', 'vehicleId',
        function ($scope, $uibModalInstance, vehicleService, vehicleId) {

            var vm = this;
            vm.saving = false;
            vm.isEditMod = false;

            vm.filters = {
                name: '',
                makeId: null
            };
            vm.save = function () {
                vm.saving = true;
                vehicleService.defleetVehicle({
                    vehicleId: vm.vehicle.id,
                    defleetDate: vm.vehicle.deFleetDate,
                    deFleetReason: vm.vehicle.deFleetReason,
                }).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vehicleService.getVehicleForEdit({
                    id: vehicleId
                }).success(function (result) {
                    vm.vehicle = result;
                    if (vm.vehicle.id > 0) {
                        vm.isEditMod = true;
                    } else {
                        vm.isEditMod = false;
                    }
                });
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.vehicles.detailReport', ['$scope', '$stateParams', 'abp.services.app.vehicle', 'abp.services.app.commonLookup', 'abp.services.app.vehicleStatus', 'utilities',
        function ($scope, $stateParams, vehicleService, commonLookupService, vehicleStatusService, utilities) {

            var vm = this;
            vm.filters = null;
            vm.replacementOfMakeAndModelInGridForVehicles = utilities.parseBoolean(abp.setting.get('App.Speed.Common.ReplacementOfMakeAndModelInGridForVehicles'));
            vm.fuelAverageforPettyCashPayment = utilities.parseBoolean(abp.setting.get("App.General.FuelAverageUsingPettyCashPayment"));
            vm.showMortgageInVehicle = utilities.parseBoolean(abp.setting.get("App.Speed.Common.ShowMortgageInVehicle"));

            if ($scope.$parent !== null) {
                if ($scope.$parent.vmMain !== null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters === null)
                vm.filters = $stateParams.filters;

            vm.localize = function (text) {
                return app.localize(text);
            };

            if (!vm.filters.ownership) {
                vm.filters.startDate = null;
                vm.filters.endDate = null;
            }
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.getFuelLevel = function (value) {
                return utilities.getFuelLevel(value);
            };

            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };
            vm.getMortgageName = function (id) {
                if (id == 0)
                    return app.localize("NonMortgage")
                if (id == 1)
                    return app.localize("Mortgage")
            };
            function getLocationName() {
                if (!vm.locations || !vm.filters.locationId)
                    return;
                angular.forEach(vm.locations, function (value, key) {
                    if (value.id == vm.filters.locationId) {
                        vm.locationName = value.name;
                        return;
                    }
                });
            };

            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    getLocationName();
                });
            }
            function getStatusName() {
                if (!vm.statuses || !vm.filters.statusId)
                    return null;
                angular.forEach(vm.statuses, function (value, key) {
                    if (value.id == vm.filters.statusId) {
                        vm.statusName = value.name;
                        return;
                    }
                });
            };
            function getVehicleStatuses() {
                vm.loading = true;
                vehicleStatusService.getVehicleStatuses({}).success(function (data) {
                    vm.statuses = data.items;
                    getStatusName();
                }).finally(function () {
                    vm.loading = false;
                });
            };
            function init() {
                getLocations();

                if (vm.filters.statusId == 'ADFL') {
                    var tempStatusId = vm.filters.statusId;
                    vm.filters.allActive = true;
                    vm.filters.statusId = '';
                } else
                    vm.filters.allActive = false;
                if (vm.showMortgageInVehicle) {
                    if (vm.filters.mortgage === 1) {
                        vm.filters.isMortgage = true;
                    } else if (vm.filters.mortgage === 2) {
                        vm.filters.isMortgage = false;
                    } else {
                        vm.filters.isMortgage = null; // important!
                    }
                }
                //getVehicleStatuses();
                vm.loading = true;
                if (vm.filters.statusId == 'BKD') {
                    vm.filters.dontPaginate = true;
                    vehicleService.getBookedVehicles(vm.filters).success(function (data) {
                        vm.vehicleReportData = data.items;
                        console.log(data.items);
                    }).finally(function () {
                        vm.loading = false;
                    });
                } else {
                    vehicleService.getVehiclesDetailReport(vm.filters).success(function (data) {
                        if (vm.filters.allActive) {

                            vm.filters.statusId = tempStatusId;
                        }
                        vm.vehicleReportData = data.items;
                        console.log(data.items);
                    }).finally(function () {
                        vm.loading = false;
                    });
                }
            }
            init();
        }]);
})();;
(function () {
    appModule.controller('tenant.views.crs.vehicles.importServiceModel', [
        '$scope', '$uibModal', '$uibModalInstance', 'fileName', '$filter', 'abp.services.app.vehicleService', 'abp.services.app.vehicleServiceLog',
    function ($scope, $uibModal, $uibModalInstance, fileName, $filter, vehicleService, vehicleServiceLogService) {
        var vm = this;
        vm.saving = false;
        
        vm.cancel = function () {
            if (vm.importedOpeningBalances)
                $uibModalInstance.close();
            else
                $uibModalInstance.dismiss();
        };
       
        // extended search using search customer popup
        vm.getlocalDateTime = function (date) {
            if (date != null) {
                var localTime = moment.utc(date).toDate();
                return moment(localTime).format('YYYY-MM-DD HH:mm:ss');
            }
            else {
                return "";
            }
        };

        function init() {
            vm.loading = true;
            
            vehicleService.importServicesFromExcel(fileName)
            .success(function (result) {
                vm.data = result;
            })
            .error(function (response) {
                abp.message.error(response.error);
            })
            .finally(function () {
                vm.importing = false;
                vm.loading = false;
            });
        }

        var pageNo = 1;
        var pageSize = 50;

        vm.importedOpeningBalances = false;
        vm.totalServices = 0;
        vm.duplicateOpeningBalance = 0;
        vm.errorServices = 0;
        vm.totalGeneratedServices = 0;
        
        init();
        
        vm.generateImportedServiceLogs = function () {
            
            var servicesToImport = [];
            var startIndex = 1 + ((pageNo - 1) * pageSize);
            var endIndex = pageNo * pageSize;

            if (endIndex > vm.data.length) {
                endIndex = vm.data.length;
            }
            
            var i = 1;
            for (i = startIndex; i <= endIndex; i++) {
                servicesToImport.push(vm.data[i-1]);
            }

        
            if (servicesToImport.length == 0) {
                vm.saving = false;
                vm.importedOpeningBalances = true;
                return;
            }
            
            vm.saving = true;
            vehicleServiceLogService.generateImportedServiceLogs({ workShopMovements: servicesToImport })
                .success(function(data) {
                    vm.generatedService = data;
                    vm.totalServices += data.length;
                    vm.errorServices += (data.length - $filter('filter')(data, {
                        error: null
                    }, true).length);

                    vm.totalGeneratedServices += ($filter('filter')(data, {
                        error: null,
                        notesDuplicate: null,
                    }, true).length);

                    //vm.duplicateOpeningBalance = vm.totalServices - vm.errorServices - vm.totalGeneratedServices;
                    angular.forEach(vm.generatedService, function(generatedTrip) {

                        var foundLines = $filter('filter')(vm.data, {
                            serialNo: generatedTrip.srNo,
                        }, true);
                        if (foundLines.length) {
                            foundLines[0].error = generatedTrip.error;
                            foundLines[0].notesDuplicate = generatedTrip.notesDuplicate;
                            foundLines[0].isGenerated = generatedTrip.isGenerated;

                        }
                    });

                    pageNo += 1;

                    if (vm.generatedService.length > 0)
                        vm.generateImportedServiceLogs();
                    else {
                        vm.saving = false;
                        vm.importedOpeningBalances = true;
                    }
                    
                }).error(function (response) {
                    abp.message.error(response.error);
                    vm.saving = false;

                }).finally(function () {
                    //vm.saving = false;
                });
        };

        vm.exportToExcel = function () {
            var tab_text = "<table border='1px'><tr>";
            var textRange; var j = 0;
            var tab1 = document.getElementById('importServiceTable'); // id of table
            for (j = 0 ; j < tab1.rows.length ; j++) {

                tab_text = tab_text;
                tab_text = tab_text + tab1.rows[j].innerHTML.toUpperCase() + "</tr>";
            }
            tab_text = tab_text + "</table>";

            var blob = b64toBlob(btoa(tab_text), "application/vnd.ms-excel");
            var blobUrl = URL.createObjectURL(blob);
            window.open(blobUrl, "_blank");
        }

        function b64toBlob(b64Data, contentType, sliceSize) {
            contentType = contentType || '';
            sliceSize = sliceSize || 512;

            var byteCharacters = atob(b64Data);
            var byteArrays = [];

            for (var offset = 0; offset < byteCharacters.length; offset += sliceSize) {
                var slice = byteCharacters.slice(offset, offset + sliceSize);

                var byteNumbers = new Array(slice.length);
                for (var i = 0; i < slice.length; i++) {
                    byteNumbers[i] = slice.charCodeAt(i);
                }

                var byteArray = new Uint8Array(byteNumbers);

                byteArrays.push(byteArray);
            }

            var blob = new Blob(byteArrays, { type: contentType });
            return blob;
        }
    }
    ]);
})();;
