(function () {
    appModule.controller('tenant.views.crs.vehicles.viewServicesModal', [
        '$scope', '$uibModal', '$uibModalInstance', 'abp.services.app.vehicleService', 'abp.services.app.serviceItem', 'vehicleServiceId', 'abp.services.app.designation',
        function ($scope, $uibModal, $uibModalInstance, serviceService, serviceItemService, vehicleServiceId, designationAppService) {


            var vm = this;
            vm.isWorkshopfeatureEnabled = abp.features.isEnabled("WORKSHOP");

        vm.serviceItems = [];
        vm.service = null;

        vm.cancel = function () {
            $uibModalInstance.dismiss();
        };

        function getServiceItems() {
            serviceItemService.getServiceItems({})
            .success(function (result) {
                vm.serviceItems = result;
            });
        }

        function getDesignations() {
            vm.loading = true;
            designationAppService.getDesignations()
                .success(function (result) {
                    vm.designations = result.items;
                    vm.loading = false;

                })
                .error(function () {
                    vm.loading = false;
                });
        }
        function init() {
            vm.loading = true;
            getServiceItems();
            getDesignations();
            serviceService.getVehicleServiceForEdit({ id: vehicleServiceId })
            .success(function (result) {
                vm.service = result;
                if (vm.service.dueOnMonths == 0)
                    vm.service.dueOnMonths = null;
                vm.loading = false;
            })
            .error(function () {
                vm.loading = false;
            });
        }

        init();
    }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.crs.vehicles.printPreview', [
        '$scope', 'appSession', 'vehicleId','$uibModalInstance',
        function ($scope, appSession, vehicleId, $uibModalInstance) {

            var vm = this;
            vm.vehicleId = vehicleId;
            
            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getTemplateUrl = function () {

                var template = abp.features.getValue('Core.Vehicles.PrintTemplate').toLowerCase();
                if (template == undefined || template == '')
                    template = 'standardVehicle';

                if (template == 'custom')
                    return '~/App/tenant/views/crs/vehicles/printtemplates/tenants/' + appSession.tenant.tenancyName.toLowerCase() + '.cshtml';
                else if (template == 'englisharabic')
                    return '~/App/tenant/views/crs/vehicles/printtemplates/englisharabic.cshtml';
                else
                    return '~/App/tenant/views/crs/vehicles/printtemplates/' + template + '.cshtml';
               
            };
        }
    ]);
})();;
