(function () {
    appModule.controller('tenant.views.crs.vehicles.serviceItems.serviceItemsSelectorModal', [
        '$scope', '$uibModalInstance', 'abp.services.app.serviceItem', 'serviceItemsSelectedList',
        function ($scope, $uibModalInstance, serviceItemService, serviceItemsSelectedList) {

            var vm = this;
            vm.saving = false;
            vm.serviceItems = null;
            vm.allSelected = false;

            vm.selectionCommit = function () {
                var list = [];
                for (var i in vm.serviceItems) {
                    if (vm.serviceItems[i].isSelected)
                        list.push(vm.serviceItems[i]);
                }

                $uibModalInstance.close(list);
            };

            vm.selectAllChange = function () {
                if (vm.serviceItems) {
                    
                    for (var x in vm.serviceItems) {
                        vm.serviceItems[x].isSelected = vm.allSelected;
                    }
                }
            };

            vm.removeSelectedItems = function () {
                if (vm.serviceItems)
                    for (var i = 0; i < vm.serviceItems.length; i++) {
                        for (var j = 0; j < serviceItemsSelectedList.items.length; j++) {
                            if (vm.serviceItems[i].id == serviceItemsSelectedList.items[j].id) {
                                vm.serviceItems.splice(i, 1);
                                i--;
                                break;
                            }
                        }
                    }
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.loading = true;
                serviceItemService.getServiceItems()
                    .success(function (result) {
                        vm.serviceItems = result.items;
                        vm.removeSelectedItems();
                        vm.loading = false;
                    })
                    .error(function () {
                        vm.loading = false;
                    });
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.vehicles.snagReport.createOrEditModal', [
        '$uibModal', '$uibModalInstance', 'snagReportId', 'isViewModal', 'abp.services.app.snagReport', 'abp.services.app.vehicle',
        function ($uibModal,$uibModalInstance, snagReportId, isViewModal, snagReportService, vehicleService) {

            var vm = this;
            vm.isViewModal = isViewModal;

            vm.saving = false;
            vm.snagReport = null;
            vm.isEditMod = false;



            vm.snagStatuses = [
                {
                    id: 1, name: app.localize("New")
                },
                {
                    id: 2, name: app.localize("In-Progress")
                },
                {
                    id: 3, name: app.localize("Closed")
                },

            ];


            vm.getStatuses = function (status) {
                if (status == 1)
                    return app.localize("New");
                if (status == 2)
                    return app.localize("In-Progress");
                if (status == 3)
                    return app.localize("Closed");
                return '';
            };


            vm.searchVehicles = function ($select) {
                if ($select.search == "") { vm.vehicles = null; return null; }
                return vehicleService.searchVehicles({ plateNo: $select.search }).then(function (response) {
                    vm.vehicles = response.data.items;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.searchVehiclePopup = function () {
                openSearchVehicleModal();
            };

            function openSearchVehicleModal() {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/vehicles/searchVehicleModal.cshtml',
                    controller: 'tenant.views.crs.vehicles.searchVehicleModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        options: {
                        }
                    }

                });

                modalInstance.result.then(function (result) {
                    if (result !== null) {
                        vm.snagReport.vehicle = result;
                    }
                });
            }

            vm.save = function () {

                vm.saving = true;
                snagReportService.createOrUpdateSnagReport({
                    snagReport: vm.snagReport
                }).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });

            };

            function init() {

                snagReportService.getSnagReportForEdit({
                    id: snagReportId
                }).success(function (result) {
                    vm.snagReport = result;

                    if (!vm.snagReport.status) {
                        vm.snagReport.status = 1;   // Default "New" for create case
                    }
                    if (vm.snagReport.vehicleId) {
                        vehicleService.getVehicleForSelect({ id: vm.snagReport.vehicleId }).success(function (vehicleResult) {
                            vm.snagReport.vehicle = vehicleResult;
                            vm.vehicles = [vehicleResult];
                        });
                    }
                });

            }

            init();
        }
    ]);
})();;
