(function () {
    appModule.controller('tenant.views.crs.vouchers.cashWithdrawals.createOrEditModal', [
        'appSession', 'abp.services.app.billingMethod', 'utilities', 'abp.services.app.commonLookup', '$uibModalInstance',
        'abp.services.app.cashWithdrawal', 'cashWithdrawalId', 'abp.services.app.cashWithdrawalSearch',
        function (appSession, billingMethodService, utilities, commonLookupService, $uibModalInstance, cashWithdrawalService, cashWithdrawalId, cashWithdrawalSearchService) {

            var vm = this;
            vm.locations = [];

            vm.autoCalculateAmountInWords = abp.setting.get("App.General.AutoCalculateAmountInWords");
            vm.isPostDatedChequeDirectlyToBankEnabled = utilities.parseBoolean(abp.setting.get("App.General.EnablePostDatedChequeDirectlyToBank"));

            vm.isMultiCurrencyEnabled = abp.features.isEnabled('Core.MultiCurrency');
            vm.isAccountsEnabled = abp.features.isEnabled("CRS.Accounts");
            
            vm.fromPaymentMethods = [];
            vm.toPaymentMethods = [];
            vm.bankAccounts = [];

            var currencyName = null;
            var decimalName = null;

            vm.loading = false;
            vm.isCurrentDateBigger = false;

            vm.currentDate = moment().endOf('day');

            function getBankAccounts() {
                commonLookupService.getBankAccountsForSelection().success(function (data) {
                    vm.bankAccounts = data.items;
                });
            }
            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                });
            };
            function getFromPaymentMethods() {
                vm.loading = true;
                billingMethodService.getBillingMethods({ type: 4 }).success(function (data) {
                    vm.fromPaymentMethods = data.items.filter(i => i.isActive && (i.locationId == null || i.locationId === appSession.user.locationId) && (i.userId == null || i.userId === appSession.user.id));
                }).finally(function () {
                    vm.loading = false;
                });
            };

            function getToPaymentMethods() {
                vm.loading = true;
                billingMethodService.getBillingMethods({ type: 1 }).success(function (data) {
                    vm.toPaymentMethods = data.items.filter(i => i.isActive && (i.locationId == null || i.locationId === appSession.user.locationId) && (i.userId == null || i.userId === appSession.user.id));
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.amountChanged = function () {
                if (vm.cashWithdrawal.amount == 0 || angular.isUndefined(vm.cashWithdrawal.amount)) {
                    if (vm.autoCalculateAmountInWords == "true")
                        vm.cashWithdrawal.amountInWords = '';
                    return;
                }
                vm.cashWithdrawal.amount = utilities.round(vm.cashWithdrawal.amount, 2);
                if (vm.autoCalculateAmountInWords == "true") {
                    if (vm.isMultiCurrencyEnabled && vm.cashWithdrawal.contact) {
                        currencyName = vm.cashWithdrawal.contact.currencyDto ? vm.cashWithdrawal.contact.currencyDto.name : null;
                        decimalName = vm.cashWithdrawal.contact.currencyDto ? vm.cashWithdrawal.contact.currencyDto.decimalName : null;
                    }
                    vm.cashWithdrawal.amountInWords = utilities.toWords(vm.cashWithdrawal.amount, currencyName, decimalName);
                }
            };

            vm.checkCurrentDate = function () {
                if (vm.currentDate >= vm.cashWithdrawal.fromPaymentMethod.cheque.chequeDate) {
                    vm.isCurrentDateBigger = true;
                } else {
                    vm.isCurrentDateBigger = false;
                }
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.dateNullOrNot = function () {
                if (vm.cashWithdrawal.fromPaymentMethod.cheque.chequeDate == false) {
                    vm.cashWithdrawal.fromPaymentMethod.cheque.chequeDate = "";
                }
                if (vm.cashWithdrawal.date == false) {
                    vm.cashWithdrawal.date = "";
                }
            }

            vm.save = function () {

                vm.saving = true;

                if (vm.cashWithdrawal.locationId == null || vm.cashWithdrawal.locationId == 0) {
                    if (appSession.user.locationId != null)
                        vm.cashWithdrawal.locationId = appSession.user.locationId;
                    else if (vm.locations.length == 1)
                        vm.cashWithdrawal.locationId = vm.locations[0].id;
                }

                var date = new Date(vm.cashWithdrawal.date);
                date.setHours(0);
                date.setMinutes(0);
                date.setSeconds(0);
                vm.cashWithdrawal.date = date;

                vm.cashWithdrawal.fromPaymentMethod.creditCard = null;
                if (vm.isPostDatedChequeDirectlyToBankEnabled && vm.isCurrentDateBigger)
                    vm.cashWithdrawal.fromPaymentMethod.bankAccountId = vm.cashWithdrawal.fromPaymentMethod.bankAccount.id;
                else
                    vm.cashWithdrawal.fromPaymentMethod.bankAccountId = null;

                vm.cashWithdrawal.fromPaymentMethod.cheque.chequeDate = moment(vm.cashWithdrawal.fromPaymentMethod.cheque.chequeDate).startOf('day');
                vm.cashWithdrawal.fromPaymentMethod.cheque.status = 1;
                
                vm.cashWithdrawal.billingDetail = vm.cashWithdrawal.fromPaymentMethod;
                vm.cashWithdrawal.billingDetail.billingMethod = vm.cashWithdrawal.toPaymentMethod.billingMethod;
                vm.cashWithdrawal.billingDetail.billingMethodId = vm.cashWithdrawal.toPaymentMethod.billingMethod.id;

                vm.cashWithdrawal.billingDetail.bankAccount.chequePrintTemplate = null;
                
                cashWithdrawalService.createOrUpdateCashWithdrawal(vm.cashWithdrawal).success(function (result) {
                    
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    vm.cashWithdrawal.id = result;
                    $uibModalInstance.close();

                }).finally(function () {

                    vm.saving = false;

                });
            };

            function init() {
                vm.loading = true;
                getLocations();

                cashWithdrawalSearchService.getCashWithdrawalForEdit({
                    id: cashWithdrawalId
                }).success(function (result) {
                    vm.cashWithdrawal = result;
                    vm.cashWithdrawal.fromPaymentMethod = vm.cashWithdrawal.billingDetail;
                    vm.cashWithdrawal.fromPaymentMethod.cheque.chequeNo = vm.cashWithdrawal.billingDetail.cheque.chequeNo;
                    vm.cashWithdrawal.fromPaymentMethod.cheque.bankName = vm.cashWithdrawal.billingDetail.cheque.bankName;
                    vm.cashWithdrawal.fromPaymentMethod.cheque.chequeDate = vm.cashWithdrawal.billingDetail.cheque.chequeDate;
                    vm.cashWithdrawal.fromPaymentMethod.bankAccount = vm.cashWithdrawal.billingDetail.bankAccount;
                    vm.cashWithdrawal.fromPaymentMethod.bankAccount.id = vm.cashWithdrawal.billingDetail.bankAccountId;
                    vm.cashWithdrawal.toPaymentMethod = vm.cashWithdrawal.billingDetail;
                    vm.cashWithdrawal.toPaymentMethod.billingMethod = vm.cashWithdrawal.billingDetail.billingMethod;
                    vm.cashWithdrawal.toPaymentMethod.billingMethod.id = vm.cashWithdrawal.billingDetail.billingMethodId;
                    vm.isEditMod = true;
                }).finally(function () {
                    vm.loading = false;
                });
            }

            function initializeFilters() {
                getFromPaymentMethods();
                getToPaymentMethods();

                if (vm.isAccountsEnabled) {
                    getBankAccounts();
                }
            }

            init();
            initializeFilters();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.crs.vouchers.cashWithdrawals.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.cashWithdrawalSearch', 'abp.services.app.billingMethod', 'utilities', 'abp.services.app.cashWithdrawal',
        function ($scope, $uibModal, uiGridConstants, cashWithdrawalSearchService, billingMethodService, utilities, cashWithdrawalService) {
            var vm = this;
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.isMultiCurrencyEnabled = abp.features.isEnabled('Core.MultiCurrency');

            //Filters 
            vm.filters = {
                enableDateRange: true,
                agreementNo: null,
                voucherNo: null,
                fromDate: null,
                toDate: null,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
            };

            //Permissions 
            vm.permissions = {
                create: abp.auth.hasPermission('Pages.Tenant.Vouchers.CashWithDrawals.Addnew'),
                edit: abp.auth.hasPermission('Pages.Tenant.Vouchers.CashWithDrawals.Edit'),
                delete: abp.auth.hasPermission('Pages.Tenant.Vouchers.CashWithDrawals.Delete'),
                view: abp.auth.hasPermission('Pages.Tenant.Vouchers.CashWithDrawals.View'),
                isJournalEnabled: abp.auth.hasPermission('Pages.Tenant.Accounts.Journal'),
            };

            vm.roundingforView = function (value) {
                var roundedValue = utilities.roundforView(value, 2);
                return roundedValue.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            };

            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: 120,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.view" ng-click="grid.appScope.viewCashWithdrawal(row.entity)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.edit" ng-click="grid.appScope.editCashWithdrawal(row.entity.id)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.delete" ng-click="grid.appScope.deleteCashWithdrawal(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.isJournalEnabled" ng-click="grid.appScope.openJournalViewModal(row.entity)">' + app.localize('Journal') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('VoucherNo'),
                        field: 'voucherNo',
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '{{row.entity.voucherNo}}' +
                            '</div>'
                    },
                    {
                        name: app.localize('Date'),
                        field: 'date',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.date)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('ChequeDate'),
                        field: 'date',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.billingDetail.cheque.chequeDate)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Bank'),
                        field: 'billingDetail.bankAccount.bankName',
                    },
                    {
                        name: app.localize('Amount'),
                        field: 'amount',
                        type: 'number',
                        cellTemplate:
                            '<div class=\"ui-grid-cell pull-right\">' +
                            '<div class=\"ui-grid-cell-contents\"><span ng-if=\"grid.appScope.isMultiCurrencyEnabled && row.entity.currency\">{{row.entity.currency.code}}</span> {{grid.appScope.roundingforView(row.entity.amount)}}</div>' +
                            '</div>'
                    }
                ],

                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = null;
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }

                        vm.getCashWithdrawal();
                    });

                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getCashWithdrawal();
                    });
                },
                data: []
            };

            vm.createCashWithdrawal = function () {
                openCreateOrEditCashWithdrawalModal(null);
            };

            vm.editCashWithdrawal = function (cashWithdrawalId) {
                openCreateOrEditCashWithdrawalModal(cashWithdrawalId);
            };

            vm.viewCashWithdrawal = function (cashWithdrawal) {
                openViewCashWithdrawalModal(cashWithdrawal.id);
            };

            vm.deleteCashWithdrawal = function (cashWithdrawal) {
                openDeleteCashWithdrawalModal(cashWithdrawal);
            };


            // functions 
            function openCreateOrEditCashWithdrawalModal(cashWithdrawalId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/vouchers/cashWithdrawals/createOrEditModal.cshtml',
                    controller: 'tenant.views.crs.vouchers.cashWithdrawals.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'full',
                    resolve: {
                        cashWithdrawalId: function () {
                            return cashWithdrawalId;
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getCashWithdrawal();
                });
            }

            function openViewCashWithdrawalModal(cashWithdrawalId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/vouchers/cashWithdrawals/viewModal.cshtml',
                    controller: 'tenant.views.crs.vouchers.cashWithdrawals.viewModal as vm',
                    backdrop: 'static',
                    size: 'full',
                    resolve: {
                        cashWithdrawalId: function () {
                            return cashWithdrawalId;
                        }
                    }
                });
            }

            function openDeleteCashWithdrawalModal(cashWithdrawal) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', cashWithdrawal.voucherNo),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            cashWithdrawalService.deleteCashWithdrawal({
                                id: cashWithdrawal.id
                            }).success(function () {
                                vm.getCashWithdrawal();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };


            vm.openJournalViewModal = function (cashWithdrawal) {
                openJournalViewModal(cashWithdrawal);
            }

            openJournalViewModal = function (cashWithdrawal) {

                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/accounting/journal/viewModal.cshtml',
                    controller: 'tenant.views.crs.accounting.journal.viewModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        voucherId: function () {
                            return cashWithdrawal.id;
                        },
                        voucherNo: function () {
                            return cashWithdrawal.voucherNo;
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getCashWithdrawal();
                });
            }


            function initDate() {
                vm.dateRangeModel = {
                    startDate: moment().add(-29, 'days').startOf('day'),
                    endDate: moment().endOf('day')
                };
            }

            function getBillingMethods() {
                vm.loading = true;
                billingMethodService.getBillingMethods({ category: 1 }).success(function (data) {
                    vm.billingMethods = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };

            vm.dateRangeCheck = function () {
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.dateRangeModelChanged = function () {
                vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            vm.CurrencyFormate = function (amount) {
                if (amount == null) return null;
                return amount.toLocaleString('en');
            };

            vm.getCashWithdrawal = function () {
                vm.loading = true;
                vm.dateRangeCheck();
                
                cashWithdrawalSearchService.getCashWithdrawal(vm.filters)
                    .success(function (data) {
                        if (vm.dateRangeModel.startDate == null && vm.dateRangeModel.endDate == null)
                            initDate();
                        vm.gridOptions.totalItems = data.totalCount;
                        vm.gridOptions.data = data.items;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            // init
            function init() {
                initDate();
                getBillingMethods();
                vm.getCashWithdrawal();
            }

            init();
        }])

}
)();;
(function () {
    appModule.controller('tenant.views.crs.vouchers.cashWithdrawals.viewModal', [
        'cashWithdrawalId', 'abp.services.app.cashWithdrawalSearch', '$uibModalInstance','utilities',
        function (cashWithdrawalId, cashWithdrawalSearchService, $uibModalInstance,utilities) {

            var vm = this;
            vm.cashWithdrawal = null;
            vm.saving = false;
            vm.isEditMod = false;
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm:ss';
            vm.currentDate = moment().endOf('day');

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.roundingforView = function (value) {
                var roundedValue = utilities.roundforView(value, 2);
                return roundedValue.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            };


            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            function getCurrencies() {
                commonLookupService.getCurrencies({}).success(function (data) {
                    vm.currencies = data.items;
                });
            };

            function init() {
                vm.loading = true;
                cashWithdrawalSearchService.getCashWithdrawalForView({
                    id: cashWithdrawalId
                }).success(function (result) {
                    vm.cashWithdrawal = result;
                    vm.isEditMod = true;
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();


