(function () {

    appModule.controller('tenant.views.crs.vouchers.invoices.addMissingFineModal',
        ['$uibModal', '$uibModalInstance', 'abp.services.app.vehicle', 'abp.services.app.trafficFine', 'abp.services.app.customer', 'abp.services.app.directory', 'utilities',
            function ($uibModal, $uibModalInstance, vehicleService,
                trafficFineAppService, customerService, directoryService, utilities) {
                var vm = this;
                vm.isVipCustomer = utilities.parseBoolean(abp.setting.get("App.General.IsVipCustomer"));
                vm.isShowCustomerInMissingFines = abp.features.isEnabled('CRS.CustomFeatures.ShowCustomerInMissingFines');

                vm.clearCustomer = function () {
                    vm.trafficFine.contact = null;
                    vm.trafficFine.contactId = null;
                };
                vm.searchVehicles = function ($select) {
                    if ($select.search == "") { vm.vehicles = null; return null; }
                    return vehicleService.searchVehicles({ plateNo: $select.search, includeDefleeted: true }).then(function (response) {
                        vm.vehicles = response.data.items;
                        vm.vehicles.forEach((v) => {
                            if (v.deFleetDate) {
                                v.label = `${v.plateNo} (Defleet)`;
                            } else {
                                v.label = v.plateNo;
                            }
                        });
                    });
                };

                vm.vehicleChanged = function () {
                    if (vm.trafficFine.vehicle) {
                        vm.loading = true;
                        trafficFineAppService.getMovementOnVehicle(vm.trafficFine).success(
                            function (result) {
                                vm.vehicleMovement = result;
                                if (vm.vehicleMovement) {
                                    vm.vehicleMovementType = getMovementType(vm.vehicleMovement.movementTypeId);
                                    if (vm.vehicleMovement.movementTypeId == 1) {
                                        vm.vehicleMovementLabel = vm.localize("AgreementNo");
                                        vm.vehicleMovementId = vm.vehicleMovement.refNo;
                                        vm.vehicleMovementContactLabel = vm.localize("Customer");
                                        vm.vehicleMovementContact = vm.vehicleMovement.contact.name;
                                    }
                                    else {
                                        vm.vehicleMovementLabel = vm.localize("MovementNo");
                                        vm.vehicleMovementId = vm.vehicleMovement.id;
                                        vm.vehicleMovementContactLabel = vm.localize("Staff");
                                        vm.vehicleMovementContact = vm.vehicleMovement.contact.name;
                                    }
                                }

                                if (vm.vehicleMovement) {
                                    customerService.getSurcharge(vm.vehicleMovement.contactId)
                                        .success((d) => {
                                            debugger;
                                            if (d?.fineSurchargeType === 1) {
                                                vm.surcharge = d.fineSurcharge;
                                            } else if (d?.fineSurchargeType === 2) {
                                                vm.surcharge = vm.trafficFine.amount / 100 * d.fineSurcharge;
                                            } else {
                                                vm.surcharge = parseFloat(abp.setting.get("App.General.TrafficFineSurCharge"));
                                            }
                                        })
                                        .finally(() => {
                                            vm.loading = false;
                                        });
                                }
                            }).finally(() => {
                                if (!vm.vehicleMovement) {
                                    vm.loading = false;
                                }
                            });
                    }
                };

                function getMovementType(movementTypeId) {
                    if (movementTypeId == 1)
                        return vm.localize("Agreement");
                    if (movementTypeId == 2)
                        return vm.localize("StaffMove");
                    if (movementTypeId == 3)
                        return vm.localize("Garage");
                    if (movementTypeId == 4)
                        return vm.localize("Delivery");
                    if (movementTypeId == 5)
                        return vm.localize("Collection");
                }

                vm.localize = function (input) {
                    if (input == null)
                        return "";
                    return app.localize(input);
                };
                vm.searchCustomers = function ($select) {

                    //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                    return directoryService.search({ keyword: $select.search, contactType: 2, contactCategory: vm.contactCategory, activeOnly: true }).then(function (response) {
                        vm.customers = response.data.items;
                    });
                };
                vm.searchCustomerPopoup = function () {
                    $uibModal.open({
                        templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                        controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                        backdrop: 'static',
                        resolve: {
                            category: function () {
                                return null;
                            },
                            type: function () {
                                return 2;
                            }
                        }
                    }).result.then(function (contact) {
                        if (contact != null) {
                            vm.trafficFine.contact = contact;
                            vm.trafficFine.contactId = contact.id;
                        }
                    });
                };
                vm.save = function () {
                    debugger;
                    vm.saving = true;
                    vm.trafficFine.vehicleId = vm.trafficFine.vehicle.id;
                    vm.trafficFine.surcharge = vm.surcharge;
                    if (vm.vehicleMovement) {
                        vm.trafficFine.agreementId = vm.vehicleMovement.agreementId;
                        vm.trafficFine.movementId = vm.vehicleMovement.id;
                    }
                    //vm.trafficFine.fineDateTime = moment.utc(vm.trafficFine.fineDateTime, 'YYYY-MM-DD hh:mm').local().format('YYYY-MM-DD hh:mm A');
                    vm.trafficFine.isAddedManually = true;

                    trafficFineAppService.createOrUpdateTrafficFine({ trafficFine: vm.trafficFine }).success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                    });
                };

                vm.cancel = function () {
                    $uibModalInstance.dismiss();
                };

                function init() {
                    
                }

                init();
            }]);
})();;
(function () {
    appModule.controller('tenant.views.crs.vouchers.invoices.advanceTaxAllocationModal', ['$uibModalInstance', 'abp.services.app.invoice', 'abp.services.app.allocation', 'invoice', 'utilities',
        function ($uibModalInstance, invoiceService, allocationService, invoice, utilities) {

            var vm = this;
            vm.loading = false;
            vm.advanceTaxInvoice = invoice;
            vm.deleteATIReversal = utilities.parseBoolean(abp.setting.get("App.General.DeleteATIReversal"));
            vm.alreadyAllocated = 0;
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.rounding = function (value) {

                return utilities.round(value, 2);
            };
            vm.customRound = function (amount, allocated) {
                var rAmount = amount - allocated;
                return utilities.round(rAmount, 2);
            };
            vm.localize = function (value) {

                return app.localize(value);
            };


            vm.getInvoiceTypeById = function (voucherSubTypeId) {
                if (voucherSubTypeId == 1) return app.localize("RentalInvoice");
                else if (voucherSubTypeId == 8) return app.localize("SalikInvoice");
                else if (voucherSubTypeId == 7) return app.localize("FineInvoice");
                else if (voucherSubTypeId == 2) return app.localize("LimousineInvoice");
                else if (voucherSubTypeId == 14) return app.localize("LeaseInvoice");
                else if (voucherSubTypeId == 16) return app.localize('TransportationInvoice');
                else if (voucherSubTypeId == 17) return app.localize("AssetSaleInvoice");
                else if (voucherSubTypeId == 9) return app.localize("MiscellaneousInvoice");
                else if (voucherSubTypeId == 24) return app.localize("AdditionalChargesInvoice");
                else if (voucherSubTypeId == 29) return app.localize("FuelInvoice");
                else if (voucherSubTypeId == 30) return app.localize("DamageInvoice");
                else if (voucherSubTypeId == 33) return app.localize("FleetAssignmentInvoice");
                else if (voucherSubTypeId == 34) return app.localize("ChauffeurInvoice");
                else if (voucherSubTypeId == 37) return app.localize("WorkshopInvoice");
                else if (voucherSubTypeId == 46) return app.localize("EquipmentInvoice");
                else if (voucherSubTypeId == 55) return app.localize("AccessoriesInvoice");
                else if (voucherSubTypeId == 57) return app.localize("ExcessChargesInvoice");
                else if (voucherSubTypeId == 60) return app.localize("ExcessKMsInvoice");
                else if (voucherSubTypeId == 63) return app.localize('DarbTollInvoice');
                else if (voucherSubTypeId == 65) return app.localize('AdvanceTaxInvoice');
                // else if (voucherSubTypeId == 47) return app.localize("EquipmentLeaseInvoice");
                else return "";
            };

            vm.sumAmount = function () {
                if (vm.invoicesToAllocate == null)
                    return 0;

                if (vm.invoicesToAllocate.length == 0)
                    return 0;

                var amount = 0;
                angular.forEach(vm.invoicesToAllocate, function (value, key) {

                    if (value.allocatedNow > 0)
                        amount = amount + value.allocatedNow;
                });

                vm.totalAllocated = utilities.round(amount, 2);
            };

            vm.save = function () {
                vm.saving = true;
                vm.loading = true;
                var invoicesToBeAllocated = vm.invoicesToAllocate.filter(e => e.allocatedNow > 0);
                invoiceService.allocateInvoicesToAdvanceTaxInvoice({ advanceTaxInvoiceId: vm.advanceTaxInvoice.id, allocations: invoicesToBeAllocated, allocatingVoucherAmount: vm.totalAllocated })
                    .success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                        vm.loading = false;
                    });
            };


            vm.deleteReversal = function (row) {
                abp.message.confirm(
                    "Are you sure you want to delete this allocation?",
                    "Confirm Delete",
                    function (isConfirmed) {
                        if (isConfirmed) {
                            invoiceService.deleteAdvanceTaxInvoiceAllocation({
                                advanceTaxInvoiceId: invoice.id,
                                reversalVoucherId: row.id
                            }).then(function () {
                                abp.notify.success("Allocation deleted successfully.");

                                loadAlreadyAllocatedInvoices();
                                loadAllocations();
                            });
                        }
                    }
                );
            };

            function loadAlreadyAllocatedInvoices() {
                vm.loading = true;
                vm.invoicesToAllocate = undefined;
                invoiceService.getAlreadyAllocatedDetails({ id: vm.advanceTaxInvoice.id }).success(function (result) {
                    vm.alreadyAllocated = result.alreadyAllocatedAmount;
                    vm.alreadyAllocatedDetails = result.detail;

                    if (vm.alreadyAllocated < vm.advanceTaxInvoice.amount)
                        loadAllocations();

                }).finally(function () {
                    vm.loading = false;
                });
            }

            function loadAllocations() {
                vm.loading = true;
                allocationService.getAllocationsForEdit({ contactId: vm.advanceTaxInvoice.contact.id, voucherCategory: 2 }).success(function (result) {
                    vm.invoicesToAllocate = result.allocations;



                }).finally(function () {
                    vm.loading = false;
                });
            }

            function init() {
                loadAlreadyAllocatedInvoices();
            }

            init();
        }
    ]);
})();;
