                //                tax = utilities.round(row.amount - credit, 2);
                //            } else {
                //                //tax = utilities.round(row.amount * vm.invoice.taxPercent / 100, 2);
                //                credit = (row.amount * 100) / (100 + vm.invoice.taxPercent);
                //                tax = utilities.round(row.amount - credit, 2);
