            vm.agreementStatus = [{ id: null, name: 'All' }, { id: 1, name: 'Open' }, { id: 2, name: 'Closed' }];
            vm.invoiceDueDate = [{ id: null, name: '' }, { id: 1, name: 'Due Date' }, { id: 2, name: 'Over Due' }];
            vm.dateRangeOptions = app.createDateRangePickerOptions();
