                    templateUrl: '~/App/tenant/views/crs/vouchers/payments/printtemplates/printPreview.cshtml',
                    controller: 'tenant.views.crs.vouchers.payments.printTemplates.printPreview as vmMain',
                    backdrop: 'static',
