                    vm.payment.contact = null;
                    vm.accountCategory = null;
                    vm.payment.voucherLines = [];
                    vm.allocationData = null;
                    vm.closedAgreements = false;
                    vm.payment.tds = null;
                    vm.payment.amount = null;
                    vm.payment.amountInWords = null;
