                vm.agreementTypes.push({ type: "Weekly", id: 2 });
            vm.agreementTypes.push({ type: "Monthly", id: 3 });

            vm.permissions = {
                canBulkGenerateForAnyAsOfDate: abp.auth.hasPermission('Pages.Tenant.Vouchers.Invoices.Addnew.CanBulkGenerateForAnyAsOfDate')            
            };
                       
