(function () {
    appModule.controller('tenant.views.crs.vouchers.stockAdjustment.printModal',
        ['$stateParams', '$scope', 'appSession', 'abp.services.app.commonLookup', 'abp.services.app.stockAdjustment', 'utilities',
            function ($stateParams, $scope, appSession, commonLookupService, StockAdjustmentService, utilities) {

                var vm = this;
                var JVId = 0;
                vm.tenantName = appSession.tenant.name;
                vm.tenancyName = appSession.tenant.tenancyName;
                vm.currency = abp.setting.get("App.General.CurrencyCode");
                vm.currencyName = abp.setting.get("App.General.CurrencyName");
                vm.dateFormat = abp.setting.get("App.General.DateFormat");
                vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
                //vm.userName = appSession.user.name;
                vm.userName = '';
                vm.fileName = vm.tenancyName.toLowerCase() + '-' + 'header.png';
                vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
                vm.taxPercent = parseFloat(abp.setting.get("App.General.TaxPercentage"));


                var recordsPerPage = 10;
                if ($scope.$parent != null) {
                    if (!isNaN($scope.$parent.vmMain.JVId))
                        JVId = $scope.$parent.vmMain.JVId;
                }


                vm.currencyAndRounding = function (value) {
                    if (value == null) return null;

                    return value.toLocaleString('en', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
                };


                //if through url print
                if (JVId == 0 && !isNaN($stateParams.query)) {
                    JVId = $stateParams.query;
                }

                $scope.$on('$viewContentLoaded', function () {
                    App.initAjax();
                });
                vm.rounding = function (value) {
                    return utilities.round(value, 2);
                };
                vm.getlocalDateTime = function (date, format) {
                    if (date != null) {
                        if (format == null) format = vm.dateFormat;

                        var localTime = moment.utc(date).toDate();
                        return moment(localTime).format(format);
                    }
                    else {
                        return "";
                    }
                };

                vm.getUserName = function (userId) {
                    commonLookupService.getUser({
                        id: userId
                    }).success(function (result) {
                        vm.userName = result.name + ' ' + result.surname;
                    });
                };
                vm.currencyAndRoundingWithThree = function (value) {
                    if (value == null) return null;

                    return value.toLocaleString('en', { minimumFractionDigits: 3, maximumFractionDigits: 3 })
                };
                function customizePagesData() {
                    var customArray = [];
                    var customArray = vm.voucherLines;
                    customArray = vm.stockAdjustment.voucherLines.filter(v => !v.hidden);
                    var arrayLength = customArray.length;
                    var noOfPages = arrayLength / recordsPerPage;
                    vm.pagesData = [];
                    for (var i = 0; i < noOfPages; i++) {
                        var subArray = [];
                        var start = i * recordsPerPage;
                        var end = start + recordsPerPage;
                        subArray = customArray.slice(start, end);
                        vm.pagesData.push({
                            pageNo: i + 1,
                            voucherLinesdataToIterate: subArray
                        })
                    }
                }

                function init() {
                    vm.loading = true;
                    StockAdjustmentService.getStockAdjustmentForEdit({
                        id: JVId
                    }).success(function (result) {
                        vm.stockAdjustment = result;
                        vm.voucherLine = result.voucherLines;
                        vm.voucherLines = result;
                        vm.debitAmount = 0.0;
                        vm.creditAmount = 0.0;
                        if (vm.tenancyName && vm.tenancyName.toLowerCase() === 'fixera') {
                            vm.stockAdjustment.voucherLines = vm.stockAdjustment.voucherLines.filter(v => !v.hidden);
                        }

                        vm.stockAdjustment.voucherLines.forEach(function (value) {
                            if (value.debit > 0) {
                                if (vm.tenancyName && vm.tenancyName.toLowerCase() === 'fixera') {
                                    if (!value.hidden) {
                                        vm.debitAmount += parseFloat(value.debit);
                                    }
                                }
                                else {

                                    vm.debitAmount += parseFloat(value.debit);
                                }
                            }
                            if (value.credit > 0) {
                                vm.creditAmount += parseFloat(value.credit);
                            } else {
                                value.taxable = false;
                            }
                        });

                        customizePagesData();
                    }).finally(function () {
                        vm.loading = false;
                    });
                }

                init();
            }
        ])
})();;
(function () {
    appModule.controller('tenant.views.crs.vouchers.stockAdjustment.report', ['$scope', 'abp.services.app.stockAdjustment', '$stateParams', 'abp.services.app.commonLookup', 'utilities',
        function ($scope, StockAdjustmentService, $stateParams, commonLookupService, utilities) {

            var vm = this;
            vm.locationName = '';
            vm.totalAmount = 0;
            vm.totalCredit = 0;
            vm.totalDebit = 0;
            vm.filters = null;

            if ($scope.$parent != null) {
                if ($scope.$parent.vmMain != null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters == null)
                vm.filters = $stateParams.filters;

            if (vm.filters.voucherNo) {
                vm.filters.locationId = null;
                vm.filters.fromDate = null;
                vm.filters.toDate = null;
            }
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.CurrencyFormate = function (amount) {
                if (amount == null) return null;
                return amount.toLocaleString('en');
            };

            vm.roundingforView = function (value) {
                var roundedValue = utilities.roundforView(value, 2);
                return roundedValue.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            };


            vm.TotalAmountFunc = function () {
                var val = vm.CurrencyFormate(parseFloat(vm.totalAmount));
                return val;
            }
            vm.TotalCreditFunc = function () {
                var val = vm.CurrencyFormate(parseFloat(vm.totalCredit));
                return val;
            };
            vm.TotalDebitFunc = function () {
                var val1 = vm.CurrencyFormate(parseFloat(vm.totalDebit));
                return val1;
            }

            function getLocationName() {
                if (!vm.locations || !vm.filters.locationId)
                    return null;
                angular.forEach(vm.locations, function (value, key) {
                    if (value.id == vm.filters.locationId) {
                        vm.locationName = value.name;
                        return;
                    }
                });
            };
            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    getLocationName();
                });
            }
            function init() {
                getLocations();
                vm.loading = true;
                StockAdjustmentService.getStockAdjustmentReport(vm.filters).success(function (data) {
                    vm.totalCredit = 0;
                    vm.totalDebit = 0;
                    vm.reportData = data.items;
                    debugger;
                    angular.forEach(vm.reportData, function (voucher, key) {
                        angular.forEach(voucher.voucherLines, function (voucherLine, key) {
                            if (!voucherLine.hidden) {
                                if (voucherLine.credit > 0)
                                    vm.totalCredit += voucherLine.credit;
                                if (voucherLine.debit > 0)
                                    vm.totalDebit += voucherLine.debit;
                            }
                        });
                    });
                }).finally(function () {
                    vm.loading = false;
                });
            }
            init();
        }]);
})();;
