            //    var modalInstance = $uibModal.open({
            //        templateUrl: '~/App/tenant/views/common/documents/uploadImageModal.cshtml',
            //        controller: 'tenant.views.common.documents.uploadImageModal as vm',
            //        backdrop: 'static',
            //        resolve: {
