(function () {
    appModule.controller('tenant.views.ers.deliveries.printModal', [
        '$scope', 'appSession', '$stateParams', 'abp.services.app.equipmentDeliverySearch', 'abp.services.app.commonLookup', 'utilities',
        function ($scope, appSession, $stateParams, equipmentDeliverySearchService, commonLookupService, utilities) {

            var vm = this;

            vm.tenantName = appSession.tenant.name;
            vm.fileName = appSession.tenant.tenancyName.toLowerCase() + '-' + 'header.png';
            vm.userName = '';
            vm.currency = abp.setting.get("App.General.CurrencyCode");
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.locationId = appSession.user.locationId;
            //if pop-up print
            if ($scope.$parent != null) {
                if (!isNaN($scope.$parent.vmMain.deliveryId))
                    deliveryId = $scope.$parent.vmMain.deliveryId;
            }

            //if through url print
            if (deliveryId == 0 && !isNaN($stateParams.query)) {
                deliveryId = $stateParams.query;
            }

            vm.getlocalDateTime = function (date, format) {
                if (date != null) {
                    if (format == null) format = vm.dateFormat;

                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(format);
                }
                else {
                    return "";
                }
            };

            vm.rounding = function (value) {
                return utilities.round(value, 2);
            };

            vm.currencyFormate = function (amount) {
                if (amount == null) return null;
                return amount.toLocaleString('en');
            };
            vm.getAgreementTypeName = function (id) {
                if (id == 0) {
                    return 'NA';
                }
                else if (id == 1) {
                    return 'Daily';
                }
                else if (id == 2) {
                    return 'Weekly';
                }
                else if (id == 3) {
                    return 'Monthly';
                }
                else if (id == 4) {
                    return 'Lease';
                }
                else if (id == 5) {
                    return 'LeaseToOwn';
                }
            };

            vm.localize = function (input) {
                if (input == null)
                    return "";

                return app.localize(input);
            };




            vm.getAgreementType = function (id) {
                if (id == 1)
                    return vm.localize("Daily")
                if (id == 2)
                    return vm.localize("Weekly")
                if (id == 3)
                    return vm.localize("Monthly")
                if (id == 4)
                    return vm.localize("Lease")
                if (id == 5)
                    return vm.localize("LeaseToOwn")
            }


            vm.getlocalDateTimeYearMonth = function (date, format) {
                if (date != null) {
                    if (format == null) format = 'YYYY/MM';

                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(format);
                }
                else {
                    return "";
                }
            };

            vm.getUserName = function (userId) {
                commonLookupService.getUser({
                    id: userId
                }).success(function (result) {
                    vm.userName = result.name;
                });
            };

            vm.getRateType = function (id) {
                if (id == 1) {
                    return 'PerDay';
                }
                else if (id == 2) {
                    return 'PerWeek';
                }
                else if (id == 3) {
                    return 'PerMonth';
                }
                else if (id == 4) {
                    return 'PerLiter';
                }
                else if (id == 5) {
                    return 'PerKM';
                }
                else if (id == 6) {
                    return 'OneTime';
                }
                else if (id == 7) {
                    return 'PerHour';
                }
                else if (id == 8) {
                    return 'PerHalfDay';
                }
                else if (id == 14) {
                    return 'PerYear';
                }
                else if (id == 15) {
                    return 'PercentPerYear';
                }
            };


            function init() {
                vm.loading = true;
                equipmentDeliverySearchService.getEquipmentRentalAgreementForPrint({
                    id: deliveryId
                }).success(function (result) {
                    debugger;
                    vm.Agreement = result;
                  //  vm.outCheckList = vm.Agreement.movements[0].outCheckList.map(e => e.name);
                }).finally(function () {
                    vm.loading = false;
                });
            };

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.ers.deliveries.replaceEquipmentModal', ['abp.services.app.vehicle', 'options', '$uibModal',
        'abp.services.app.equipmentAgreementReplacement', 'abp.services.app.commonAgreement', '$uibModalInstance', 'abp.services.app.commonLookup',
        function (vehicleService, options, $uibModal, equipmentAgreementReplacementService, commonAgreementService, $uibModalInstance, commonLookupService) {

            var vm = this;
            vm.loading = false;
            vm.agreement = null;
            vm.inMovement = null;
            vm.outMovement = null;
            vm.locations = [];
            var isValid = true;
            var errorMessage = {};

            vm.searchVehicles = function ($select) {
                if ($select.search == "") {
                    vm.vehicles = null;
                    return null;
                }
                var subStatuses = [1, 7];//1: Avialable, 7: Ready To Go
                return vehicleService.searchVehicles({
                    plateNo: $select.search, statusId: 'IDL', subStatuses: subStatuses,
                    ownership: vm.outMovement.vehicle.ownership
                }).then(function (response) {
                    vm.vehicles = response.data.items;
                });
            };

            vm.getAgreementTypeName = function (agreementType) {
                if (agreementType == null)
                    return "";

                if (agreementType == 1) {
                    return "Daily";
                } else if (agreementType == 2) {
                    return "Weekly";
                } else if (agreementType == 3) {
                    return "Monthly";
                } else {
                    return "";
                }
            };

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };


            vm.vehicleSelected = function () {
                vm.outMovement.vehicleId = vm.outMovement.vehicle.id;
                vm.outMovement.outDetail.fuelLevel = vm.outMovement.vehicle.fuelLevel;
                vm.outMovement.outDetail.km = vm.outMovement.vehicle.kMs;
                vm.outMovement.outDetail_LocationId = vm.outMovement.vehicle.locationId;
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function validate() {
                errorMessage = '';
                errorMessage = 'Replacement Can Not Be Saved Due To Following Issues: \n';
                if (isValid == false) {
                    isValid = true;
                }

                
                var localTime = moment.utc(vm.inMovement.outDetail.dateTime).toDate();
                var dateOutLocal = moment(localTime);

                if (dateOutLocal > moment(vm.inMovement.inDetail.dateTime)) {
                    isValid = false;
                    errorMessage = errorMessage + '\n In Date can not be less than Out Date ';
                }

                if (vm.inMovement.outDetail.km > vm.inMovement.inDetail.km) {
                    isValid = false;
                    errorMessage = errorMessage + '\n ODO IN can not be less than ODO OUT ';
                }

                //if (vm.getlocalDateTime(vm.inMovement.inDetail.dateTime) > vm.getlocalDateTime(vm.outMovement.outDetail.dateTime)) {
                if (moment(vm.inMovement.inDetail.dateTime) > moment(vm.outMovement.outDetail.dateTime)) {
                    isValid = false;
                    errorMessage = errorMessage + '\n Replace Equipment Out Date can not be less than In Date ';
                }
            }

            vm.save = function () {
                vm.saving = true;

                validate();
                if (isValid) {
                    if (vm.locations.length == 1)
                        vm.inMovement.inDetail_LocationId = vm.locations[0].id;

                    vm.inMovement.outDetail.fuelLevel = 0;
                    equipmentAgreementReplacementService.replaceEquipment({
                        agreementId: vm.agreement.id,
                        inMovement: vm.inMovement,
                        outMovement: vm.outMovement,
                        deliveryMovementId: vm.deliveryMovementId,
                        isPermanentVehicle: vm.isPermanentVehicle,
                        isReplacementForService: vm.isReplacementForService
                    }).success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                    });
                } else {
                    abp.message.info(app.localize(errorMessage));
                    vm.saving = false;
                }
            };

            vm.searchVehiclePopup = function () {
                openSearchVehicleModal();
            };

            function openSearchVehicleModal() {

                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/vehicles/searchVehicleModal.cshtml',
                    controller: 'tenant.views.crs.vehicles.searchVehicleModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        options: function () {
                            return {
                                fromDateTime: moment(vm.agreement.movements[0].outDetail.dateTime ? vm.agreement.movements[0].outDetail.dateTime : moment().startOf('day')).utc(),
                                toDateTime: moment(vm.agreement.endDate ? vm.agreement.endDate : moment().endOf('day')).utc(),
                                tariffGroup: vm.searchOtherGroupsVehicle ? null : vm.tariffGroup,
                                tariffGroupId: vm.searchOtherGroupsVehicle ? null : vm.tariffGroupId,
                                statusId: 'IDL',
                                subStatuses: [1, 7], //1: Available, 7: Ready to go
                                source: 'openagreement',
                                selectable: true
                            };
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    if (result != null) {
                        vm.agreement.vehicle = result;
                        vm.vehicleSelected();
                    }
                });
            }

            vm.addExternalEquipmentPopup = function () {
                openAddExternalEquipmentModal();
            };

            function openAddExternalEquipmentModal() {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/vehicles/addExternalVehicle.cshtml',
                    controller: 'tenant.views.crs.vehicles.addExternalVehicle as vm',
                    backdrop: 'static',
                    size: 'sm'
                });
                modalInstance.result.then(function (vehicle) {
                    vm.outMovement.vehicle = vehicle;
                    vm.outMovement.vehicle.ownership = 2; // External vehicle
                });
            }

            function getReplacementReasons() {
                commonLookupService.getReplacementReasons().success(function (result) {
                    vm.replacementReasons = result.items;
                })
            };

            function init() {
                vm.loading = true;
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                });
                commonAgreementService.getAgreement({
                    id: options.agreementId,
                    includeMovements: true,
                    includeVehicle: true,
                    isMobile: false
                }).success(function (result) {
                    vm.deliveryMovementId = options.deliveryMovementId;

                    vm.agreement = result;
                    vm.inMovement = vm.agreement.movements.filter(row => !row.isComplete)[0];
                    //vm.inMovement = vm.agreement.movements[vm.agreement.movements.length - 1];
                    vm.isLeaseAgreement = vm.agreement.agreementCategory == 2;
                    vm.isMonthlyAgreement = vm.agreement.agreementType == 3;
                    //initialize new out movement
                    vm.outMovement = angular.copy(vm.inMovement);
                    vm.outMovement.id = 0;
                    vm.outMovement.outDetail.dateTime = null;
                    vm.outMovement.outDetail.fuelLevel = 0;
                    vm.outMovement.inDetail.fuelLevel = 0;
                    vm.outMovement.outDetail.km = null;
                    vm.outMovement.vehicle = { ownership: 1 };
                    vm.outMovement.vehicleId = null;
                    vm.outMovement.outDetail_LocationId = null;
                    vm.outMovement.outDetail_Location = null;
                    vm.outMovement.contact = null;
                    if (vm.deliveryMovementId) {
                        vm.outMovement.vehicle = options.vehicle;
                        vm.outMovement.vehicleId = options.vehicle.id;
                        vm.outMovement.outDetail_LocationId = options.vehicle.locationId;
                    }
                    getReplacementReasons();
                }).finally(function () {
                    vm.loading = false;
                });
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.ers.deliveries.replaceOperatorModal', ['abp.services.app.vehicle', 'agreementId', 'abp.services.app.agreement',
        'abp.services.app.equipmentAgreementReplacement', 'abp.services.app.commonAgreement', '$uibModalInstance', 'abp.services.app.commonLookup', 'abp.services.app.directory',
        'abp.services.app.designation',
        function (vehicleService, agreementId, agreementService, agreementReplacementService, commonAgreementService, $uibModalInstance, commonLookupService, directoryService,
            designationService) {

            var vm = this;
            vm.loading = false;
            vm.agreement = null;
            vm.inMovement = null;
            vm.outMovement = null;
            vm.outAgreement = {
                operator1Type: 2,
                operator2Type: 2
            }
            vm.locations = [];
            var isValid = true;
            var errorMessage = {};

            function searchOperators() {
                return designationService.getDesignations().then(function (response) {
                    vm.operators = response.data.items;
                });
            };

            vm.searchSupplier = function ($select) {
                if (!$select.search) return;
                return directoryService.search({ keyword: $select.search, contactType: 3 }).then(function (response) {
                    vm.suppliers = response.data.items;
                });
            };

            vm.searchVehicles = function ($select) {
                if ($select.search == "") {
                    vm.vehicles = null;
                    return null;
                }
                return vehicleService.searchVehicles({ plateNo: $select.search, statusId: 'IDL' }).then(function (response) {
                    vm.vehicles = response.data.items;
                });
            };

            vm.getAgreementTypeName = function (agreementType) {
                if (agreementType == null)
                    return "";

                if (agreementType == 1) {
                    return "Daily";
                } else if (agreementType == 2) {
                    return "Weekly";
                } else if (agreementType == 3) {
                    return "Monthly";
                } else {
                    return "";
                }
            };

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };


            vm.vehicleSelected = function () {
                vm.outMovement.vehicleId = vm.outMovement.vehicle.id;
                vm.outMovement.outDetail.fuelLevel = vm.outMovement.vehicle.fuelLevel;
                vm.outMovement.outDetail.km = vm.outMovement.vehicle.kMs;
                vm.outMovement.outDetail_LocationId = vm.outMovement.vehicle.locationId;
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.save = function () {
                vm.saving = true;

                //validate();
                if (isValid) {
                    vm.outAgreement.id = agreementId;
                    agreementReplacementService.replaceOperator({
                        agreement: vm.outAgreement
                    }).success(function () {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    }).finally(function () {
                        vm.saving = false;
                    });
                } else {
                    abp.message.info(app.localize(errorMessage));
                    vm.saving = false;
                }
            };

            function init() {
                vm.loading = true;
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                });

                commonAgreementService.getAgreementForOperatorReplacement({
                    id: agreementId
                }).success(function (result) {
                    vm.inAgreement = result;
                    //vm.inDriver = vm.agreement.driverLogs[vm.agreement.driverLogs.length - 1];
                    //vm.isLeaseAgreement = vm.agreement.agreementCategory == 2;
                    
                    //vm.outDriver = null;

                }).finally(function () {
                    vm.loading = false;
                });
            }

            searchOperators();
            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.ers.deliveries.report', ['$scope', '$stateParams', 'abp.services.app.equipmentRentalAgreementSearch', 
        '$stateParams', 'abp.services.app.commonLookup', 'utilities',
        function ($scope, $stateParams, equipmentRentalAgreementSearchService, $stateParams, commonLookupService, utilities) {

            var vm = this;
            vm.enableManualAgreementNo = utilities.parseBoolean(abp.setting.get("App.General.EnableManualAgreementNo"));

            vm.filters = null;

            if ($scope.$parent !== null) {
                if ($scope.$parent.vmMain !== null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters === null )
                vm.filters = $stateParams.filters;
            
            if (vm.filters.agreementNo) {
                vm.filters.manualAgreementNo = null;
                vm.filters.plateNo = null;
                vm.filters.startDate = null;
                vm.filters.endDate = null;
                vm.filters.locationId = null;
                vm.filters.agreementType = null;
                vm.filters.status = null;
                vm.filters.customer = null;
            }
            else if (vm.filters.manualAgreementNo) {
                vm.filters.plateNo = null;
                vm.filters.startDate = null;
                vm.filters.endDate = null;
                vm.filters.locationId = null;
                vm.filters.agreementType = null;
                vm.filters.status = null;
                vm.filters.customer = null;
            }
            else if (vm.filters.plateNo) {
                vm.filters.startDate = null;
                vm.filters.endDate = null;
                vm.filters.locationId = null;
                vm.filters.agreementType = null;
                vm.filters.status = null;
                vm.filters.customer = null;
            }
            vm.agreementType = '';
            vm.locationName = '';


            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };
            function getAgreementTypes() {
                if (!vm.filters.agreementType) return '';
                if (vm.filters.agreementType == 4) vm.agreementType = app.localize('Lease');
                if (vm.filters.agreementType == 5) vm.agreementType = app.localize('LeaseToOwn');
            };
            vm.getStatuses = function () {
                if (!vm.filters.status) return '';
                if (vm.filters.status == 1)
                    return app.localize("Open");
                else if (vm.filters.status == 2)
                    return app.localize("Closed");
            };

            vm.getStatusString = function (status) {
                if (!status) return '';
                if (status == 1)
                    return app.localize("Open");
                else if (status == 2)
                    return app.localize("Closed");
            };

            vm.getlocalizedString = function (agreementStatus) {
                return app.localize(agreementStatus);
            };


            function getLocationName() {
                if (!vm.locations || !vm.filters.locationId)
                    return null;
                angular.forEach(vm.locations, function (value, key) {
                    if (value.id == vm.filters.locationId) {
                        vm.locationName = value.name;
                        return;
                    }
                });
            };
            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    getLocationName();
                });
            }
            function init() {
                getLocations();
                vm.loading = true;
                if (vm.filters.agreementType)
                    getAgreementTypes();
                equipmentRentalAgreementSearchService.getAgreementsReport(vm.filters).success(function (data) {
                    vm.agreementReportData = data;
                    vm.isLeaseAgreement = vm.agreementReportData[0].agreementCategory == 2;
                    angular.forEach(vm.agreementReportData, function (value, key) {
                        vm.totalAmount += value.amount;
                    });
                }).finally(function () {
                    vm.loading = false;
                });
            }
            init();
        }]);
})();;
(function () {
    appModule.controller('tenant.views.ers.deliveries.viewModal', [
        'utilities', '$uibModalInstance', '$uibModal', 'abp.services.app.equipmentDeliverySearch', 'agreementId', '$filter', 'abp.services.app.designation', 'abp.services.app.synch',
        function (utilities, $uibModalInstance, $uibModal, equipmentDeliverySearchService, agreementId, $filter, designationService, synchAppService) {

            var vm = this;

            vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
            vm.isTaxOptional = utilities.parseBoolean(abp.setting.get("App.General.IsTaxOptional"));
            vm.taxPercent = parseFloat(abp.setting.get("App.General.TaxPercentage"));
            vm.manualAgreementNo = utilities.parseBoolean(abp.setting.get("App.General.ManualAgreementNo"));
            vm.enableManualAgreementNo = utilities.parseBoolean(abp.setting.get("App.General.EnableManualAgreementNo"));
            vm.enableAdditionalNotes = utilities.parseBoolean(abp.setting.get("App.General.EnableAdditionalNotes"));
            vm.isWeeklyMonthlyEnabled = utilities.parseBoolean(abp.setting.get("App.General.WeeklyMonthlyRental"));
            vm.isUserWiseDiscountEnable = abp.features.isEnabled("CRS.UserWiseDiscount");
            vm.isTariffCardExplicitSelection = utilities.parseBoolean(abp.setting.get("App.General.TariffCardExplicitSelection"));
            vm.isTariffCardEnable = abp.features.isEnabled("CRS.Tariff.TariffCards");
            vm.isDeliveryMovementEnable = abp.features.isEnabled("CRS.DeliveryAndCollectionMovements");
            vm.IsInsuranceCompanyAndClaimNoRequired = utilities.parseBoolean(abp.setting.get("App.General.IsInsuranceCompanyAndClaimNoRequired"));
            vm.isSaleOrderEnabled = abp.features.isEnabled("CRS.Vouchers.SaleOrders");
            vm.isTotalDaysAndHrs = false;
            vm.invoiceBasedOnAgreedRent = utilities.parseBoolean(abp.setting.get("App.General.InvoiceBasedOnAgreedRent"));
            vm.isIndividualCustomerRadio = true;
            vm.loading = false;
            vm.locations = [];
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date == null)
                    return "";

                var localTime = moment.utc(date).toDate();
                return moment(localTime).format(vm.dateTimeFormat);
            };

            vm.localize = function (input) {
                return app.localize(input);
            };

            vm.agreementTypes = [
                { type: "Daily", id: 1 },
                { type: "Weekly", id: 2 },
                { type: "Monthly", id: 3 },
                { type: "Lease", id: 4 },
                { type: "LeaseToOwn", id: 5 },
            ];

            vm.getAgreementStatus = function (id) {
                if (id == 1)
                    return vm.localize("Delivered");
                else if (id == 2)
                    return vm.localize("Closed");
                else if (id == 3)
                    return vm.localize("Cancelled");
                else if (id == 4)
                    return vm.localize("Approval1Pending");
                else if (id == 5)
                    return vm.localize("Approval2Pending");
                else if (id == 6)
                    return vm.localize("DeliveryPending");
                else
                    return vm.localize("NA");
            }
            var rateTypes = {
                perDay: { id: 1, name: '/Day' },
                perWeek: { id: 2, name: '/Week' },
                perMonth: { id: 3, name: '/Month' },
            };

            vm.getAgreementType = function (type) {
                if (type == 1) {
                    return app.localize("Daily");
                }
                else if (type == 2) {
                    return app.localize("Weekly");
                }
                else if (type == 3) {
                    return app.localize("Monthly");
                }
                else if (type == 4) {
                    return app.localize("Lease");
                }
                else if (type == 5) {
                    return app.localize("LeaseToOwn");
                }
            }


            function openCustomerViewModal(personId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/viewModel.cshtml',
                    controller: 'tenant.views.crs.contacts.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        personId: function () {
                            return personId;
                        },
                        isFromSearchScreen: function () {
                            return false;
                        }
                    }
                });
            }

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.totalDaysAndTime = function () {
                var startDate = moment(vm.agreement.movements[0].outDetail.dateTime);
                var endDate = moment(vm.agreement.movements[vm.agreement.movements.length - 1].inDetail.dateTime);

                vm.totalDays = moment(endDate.format("LLLL")).diff(moment(startDate.format("LLLL")), 'days');
                var totalHrs = moment(endDate.format("LLLL")).diff(moment(startDate.format("LLLL")), 'hours');
                vm.remainingHrs = totalHrs - (vm.totalDays * 24);

                var startDateForEndDate = moment(vm.agreement.movements[0].outDetail.dateTime);
                var endDateForEndDate = moment(vm.agreement.endDate);

                vm.totalDaysForEndDate = moment(endDateForEndDate.format("LLLL")).diff(moment(startDateForEndDate.format("LLLL")), 'days');
                var totalHrsForEndDate = moment(endDateForEndDate.format("LLLL")).diff(moment(startDateForEndDate.format("LLLL")), 'hours');
                vm.remainingHrsForEndDate = totalHrsForEndDate - (vm.totalDaysForEndDate * 24);
            };

            function designationDetails() {
                designationService.getDesignations().success(function (result) {
                    vm.operators = result.items;
                });
            };
            function getAllChecklistItems() {
                vm.loading = true;
                synchAppService.getAllCheckListItems()
                    .success(function (result) {
                        vm.checklistItems = result;
                        vm.checklistItems.forEach(e => {
                            vm.agreement.movements[0].outCheckList.forEach(a => {
                                if (e.id == a.id) {
                                e.isSelected = true;
                                }
                            });
                        });
                    }).finally(function () { vm.loading = false; });
            }

            function init() {
                vm.loading = true;

                equipmentDeliverySearchService.getEquipmentRentalAgreementForView({
                    id: agreementId
                }).success(function (result) {
                    vm.agreement = result;
                    vm.agreement.vehicle.makeAndModel = vm.agreement.vehicle.make + ' ' + vm.agreement.vehicle.model;
                    //vm.agreement.agreementType = 1;

                    if (vm.agreement && vm.agreement.charges) {
                        var foundLines = $filter('filter')(vm.agreement.charges, {
                            chargesTypeId: 1
                        }, true);
                        if (foundLines.length == 1) {
                            if (foundLines[0].discountPercent > 0) {

                                foundLines[0].discountedRate = utilities.round(foundLines[0].rate - (foundLines[0].rate * (foundLines[0].discountPercent / 100)), 2);
                            }
                        }
                    }

                    var mobilizationRow = vm.agreement.charges.filter(e => e.chargesTypeId == 26)[0];
                    vm.includeMobilization = mobilizationRow.accepted;

                    getAllChecklistItems();
                }).finally(function () {
                    vm.loading = false;
                });
            }

            designationDetails();
            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.ers.deliveries.printTemplates.printPreview', [
        '$scope', 'appSession', 'deliveryId', '$uibModalInstance',
        function ($scope, appSession, deliveryId, $uibModalInstance) {
            
            var vm = this;
            vm.deliveryId = deliveryId;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getTemplateUrl = function () {
               // var template = abp.features.getValue('CRS.Vouchers.Receipts.PrintTemplate').toLowerCase();
                var template = abp.features.getValue('ERS.EquipmentDelivery.PrintTemplate');

                if (template == undefined || template == '')
                    template = 'standard';

                if (template == 'custom')
                    return '~/App/tenant/views/ers/deliveries/printTemplates/tenants/' + appSession.tenant.tenancyName.toLowerCase() + '.cshtml';
                else if (template == 'englisharabic')
                    return '~/App/tenant/views/ers/deliveries/printTemplates/englisharabic.cshtml';
                else
                    return '~/App/tenant/views/ers/deliveries/printTemplates/' + template + '.cshtml';
            };
        }
    ]);
})();;
