(function () {

    appModule.controller('tenant.views.externalLogin.vehicleServiceBooking.createOrEditModal', [
        '$scope', 'utilities', '$uibModal', '$uibModalInstance', 'abp.services.app.vehicleServiceBookingExternal', 'serviceBooking',
        function ($scope, utilities, $uibModal, $uibModalInstance, vehicleServiceBookingExternalService, serviceBooking) {

            var vm = this;


            vm.saveAndPrint = false;
            vm.loading = false;
            vm.agreements = [];
            vm.serviceBooking = {};
            vm.filters = {};
            vm.serviceBooking = serviceBooking;

            vm.isUserWiseDiscountEnable = abp.features.isEnabled("CRS.UserWiseDiscount");
            vm.isDepositsEnable = abp.features.isEnabled("CRS.Vouchers.Deposits");
            vm.isSaleOrderEnabled = abp.features.isEnabled("CRS.Vouchers.SaleOrders");

            vm.canChangeAdvanceAmount = abp.auth.hasPermission('Pages.Tenant.Agreements.CanChangeAdvanceAmount');

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.serviceBookingItems = [
                { item: 1, title: app.localize("ServiceAndRoutineMaintenance") }, { item: 2, title: app.localize("CheckBrake") },
                { item: 3, title: app.localize("CheckAirConditionOrAC") }, { item: 4, title: app.localize("CheckTiresAndPressures") },
                { item: 5, title: app.localize("ChangeWiperBlade") }, { item: 6, title: app.localize("CheckAllLights") },
                { item: 7, title: app.localize("SteeringWheelAlignment") }, { item: 8, title: app.localize("Vibration") },
                { item: 9, title: app.localize("BatteryChecking") }, { item: 10, title: app.localize("WarningLightsOnTheDashboard") },
                { item: 11, title: app.localize("RenewalOfRegistrationOrIstimara") }, { item: 12, title: app.localize("OtherServiceBookingItem") },
            ];

            vm.serviceBookingItemsName = function (item) {
                if (item === 1)
                    return app.localize("ServiceAndRoutineMaintenance");
                else if (item === 2)
                    return app.localize("CheckBrake");
                else if (item === 3)
                    return app.localize("CheckAirConditionOrAC");
                else if (item === 4)
                    return app.localize("CheckTiresAndPressures");
                else if (item === 5)
                    return app.localize("ChangeWiperBlade");
                else if (item === 6)
                    return app.localize("CheckAllLights");
                else if (item === 7)
                    return app.localize("SteeringWheelAlignment");
                else if (item === 8)
                    return app.localize("Vibration");
                else if (item === 9)
                    return app.localize("BatteryChecking");
                else if (item === 10)
                    return app.localize("WarningLightsOnTheDashboard");
                else if (item === 11)
                    return app.localize("RenewalOfRegistrationOrIstimara");
                else if (item === 12)
                    return app.localize("OtherServiceBookingItem");
                else
                    return item;
            };

            vm.agreementChanged = function () {
                vm.serviceBooking = {};
                vm.serviceBooking.plateNo = vm.filters.agreement.plateNo;
                vm.serviceBooking.makeAndModel = vm.filters.agreement.makeAndModel;
                vm.serviceBooking.serviceDate = vm.filters.agreement.serviceDate;
                //vm.serviceBooking.notes = vm.filters.agreement.notes;
                vm.serviceBooking.vehicleId = vm.filters.agreement.vehicleId;
                if (!vm.serviceBooking.items)
                    vm.serviceBooking.items = vm.serviceBookingItems;
            }

            vm.save = function () {
                vm.loading = true;
                vm.serviceBooking.agreementId = vm.filters.agreement.id;
                vehicleServiceBookingExternalService.createOrUpdateVehicleServiceBooking(
                    vm.serviceBooking
                ).success(function (result) {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function init() {
                vm.loading = true;
                if (serviceBooking && serviceBooking.id) {
                    vehicleServiceBookingExternalService.getVehicleServiceBookingForEdit({
                        id: serviceBooking.id
                    }).success(function (result) {
                        vm.serviceBooking = result;
                        vm.serviceBooking.plateNo = vm.serviceBooking.plateNo;
                        vm.serviceBooking.makeAndModel = vm.serviceBooking.makeAndModel;
                        vm.serviceBooking.serviceDate = vm.serviceBooking.serviceDate;
                        vm.serviceBooking.notes = vm.serviceBooking.notes;
                        vm.serviceBooking.vehicleId = vm.serviceBooking.VehicleId;
                        vm.serviceBooking.items = vm.serviceBooking.items;
                        if (vm.serviceBooking.agreement)
                            vm.serviceBooking.agreement.plateNo = vm.serviceBooking.plateNo;
                        vm.openAgreements = [];
                        vm.openAgreements.push(vm.serviceBooking.agreement);
                        vm.filters.agreement = vm.serviceBooking.agreement;
                    }).finally(function () {
                        vm.loading = false;
                    });
                } else {
                    vehicleServiceBookingExternalService.getOpenAgreements()
                        .success(function (data) {
                            vm.openAgreements = data.items;
                            vm.serviceBooking = {};
                            vm.serviceBooking.items = vm.serviceBookingItems;
                        }).finally(function () {
                            vm.loading = false;
                        });
                }

            }

            init();

        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.externalLogin.vehicleServiceBooking.index', [
        '$scope', 'abp.services.app.vehicleServiceBookingExternal','$uibModal',
        function ($scope, vehicleServiceBookingExternalService, $uibModal) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';

            vm.permissions = {
                create: abp.auth.hasPermission('Page.ExternaLogin.VehicleServiceBooking.Add'),
                edit: abp.auth.hasPermission('Page.ExternaLogin.VehicleServiceBooking.Edit'),
                'delete': abp.auth.hasPermission('Page.ExternaLogin.VehicleServiceBooking.Delete'),
                'cancel': abp.auth.hasPermission('Page.ExternaLogin.VehicleServiceBooking.Cancel')
            };

            vm.filters = {
                enableDateRange: false,
                statuses: [{ "id": 1, "name": app.localize("Pending") }, { "id": 2, "name": app.localize("Confirmed") }]
            };

            function getStatuses() {
                vm.statuses = [{ id: 1, name: app.localize("Pending") }, { id: 2, name: app.localize("Confirmed") }, { id: 3, name: app.localize("Closed") }, { id: 4, name: app.localize("Cancel") }];
            };

            //vm.statusChanged = function () {
            //    vm.filters.enableDateRange = true;
            //};

            function initDate() {
                vm.dateRangeModel = {
                    startDate: moment().add(-29, 'days').startOf('day'),
                    endDate: moment().endOf('day')
                };
            }

            //vm.dateRangeModel = {
            //    startDate: moment().add(-29, 'days').startOf('day'),
            //    endDate: moment().endOf('day')
            //};
            vm.dateRangeModelChanged = function () {
                vm.filters.startDate = vm.dateRangeModel.startDate;
                vm.filters.endDate = vm.dateRangeModel.endDate;
            };
            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getStatus = function (status) {
                if (status === 1)
                    return "Pending";
                else if (status === 2)
                    return "Confirmed";
                else if (status === 3)
                    return "Closed";
                else if (status === 4)
                    return "Cancel";
                else
                    return status;
            };

            function openCreateVehicleServiceBookingModal(booking) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/externalLogin/vehicleServiceBooking/createOrEditModal.cshtml',
                    controller: 'tenant.views.externalLogin.vehicleServiceBooking.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        serviceBooking: function () {
                            return booking;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getOpenServiceRequests();
                });
            }

            vm.createVehicleServiceBooking = function () {
                openCreateVehicleServiceBookingModal(null);
            };

            vm.updateVehicleServiceBooking = function (booking) {
                openCreateVehicleServiceBookingModal(booking);
            };

            vm.updateNotesServiceBooking = function (booking) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/externalLogin/vehicleServiceBooking/createNotesServiceBookingModal.cshtml',
                    controller: 'tenant.views.externalLogin.vehicleServiceBooking.createNotesServiceBookingModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        serviceBooking: function () {
                            return booking;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getOpenServiceRequests();
                });
            };


            vm.deleteVehicleServiceBooking = function (row) {
                abp.message.confirm(
                    app.localize('PressYesToDeleteVehicleServiceBooking'), app.localize('DeleteVehicleServiceBooking'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            vehicleServiceBookingExternalService.deleteVehicleServiceBooking({
                                id: row.id
                            }).success(function () {
                                vm.getOpenServiceRequests();
                                abp.notify.success(app.localize('SuccessfullyDeleteVehicleServiceBooking'));
                            });
                        }
                    }
                );
            };


            vm.cancelVehicleServiceBooking = function (booking) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/externalLogin/vehicleServiceBooking/cancelVehicleServiceBookingModal.cshtml',
                    controller: 'tenant.views.externalLogin.vehicleServiceBooking.cancelVehicleServiceBookingModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        serviceBooking: function () {
                            return booking;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getOpenServiceRequests();
                });
            };

            vm.getOpenServiceRequests = function () {
                vm.loading = true;
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate !== null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                    vm.filters.toDate = vm.dateRangeModel.endDate !== null ? vm.dateRangeModel.endDate : moment().endOf('day');
                }
                else {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
                vm.filters.status = [];
                angular.forEach(vm.filters.statuses, function (value) {
                    vm.filters.status.push(value.id);
                });
                vehicleServiceBookingExternalService.getOpenServiceRequests(vm.filters)
                    .success(function (data) {
                        if (vm.dateRangeModel.startDate === null && vm.dateRangeModel.endDate === null) {
                            initDate();
                        }
                        vm.openServiceRequests = data.items;
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            vm.showVehicleServiceBookingLogs = function (row) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/externalLogin/vehicleServiceBooking/serviceBookingLogsModel.cshtml',
                    controller: 'tenant.views.externalLogin.vehicleServiceBooking.serviceBookingLogsModel as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        serviceBooking: function () {
                            return row;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    //vm.getOpenServiceRequests();
                });
            }

            vm.init = function () {
                initDate();
                vm.getOpenServiceRequests();
                getStatuses();
            }

            vm.init();
        }]);
})();;
(function () {

    appModule.controller('tenant.views.externalLogin.vehicleServiceBooking.serviceBookingLogsModel', [
        '$scope', 'utilities', '$uibModal', '$uibModalInstance', 'abp.services.app.serviceBookings','serviceBooking',
        function ($scope, utilities, $uibModal, $uibModalInstance, serviceBookingsService, serviceBooking) {

            var vm = this;
            
            vm.saveAndPrint = false;
            vm.loading = false;
            vm.agreements = [];
            vm.serviceBooking = {};
            vm.filters = {};
            vm.serviceBooking = serviceBooking;

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.localize = function (string) {
                return app.localize(string)
            };

            vm.getStatus = function (status) {
                if (status === 1)
                    return "Pending";
                else if (status === 2)
                    return "Confirmed";
                else if (status === 3)
                    return "Closed";
                else if (status === 4)
                    return "Cancel";
                else
                    return status;
            }

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            
            function init() {
                if (serviceBooking && serviceBooking.id) {
                    vm.loading = true;
                    serviceBookingsService.getVehicleServiceBookingLogs({
                        id: serviceBooking.id
                    }).success(function (result) {
                        vm.serviceBookingLogs = result;
                    }).finally(function () {
                        vm.loading = false;
                    });
                }
            }

            init();

        }
    ]);
})();;
