(function () {
    appModule.controller('tenant.views.externalVehiclesControlPanel.rental.bookings.listModal', [
        '$scope', '$uibModalInstance', 'uiGridConstants', 'abp.services.app.externalBookingSearch', 'vehicleStatus', 'vehicleOwnership', 'vehicleType',
        function ($scope, $uibModalInstance, uiGridConstants, externalBookingSearchService, bookingStatus, vehicleOwnership, vehicleType) {

            var vm = this;
            vm.date = moment();

            vm.subTitle = function () {
                var result = "";
                if (bookingStatus == 'Due') { result = "DueToCheck-Out"; }
                else if (bookingStatus == 'OverDue') { result = "OverDueCheck-Out"; }
                else if (bookingStatus == 'Opened') { result = "OpenedToday"; }
                else result = bookingStatus;
                return app.localize(result);
            };

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.filters = {
                bookingStatus: bookingStatus,
                vehicleOwnership: vehicleOwnership,
                vehicleType: vehicleType,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.DueToCloseCalender = function () {
                vm.loading = true;

                externalBookingSearchService.getDueBookings(
                    {
                        fromDate: moment(vm.date).startOf('day'),
                        toDate: moment(vm.date).endOf('day'),
                        vehicleOwnership: vehicleOwnership
                    }).success(function (data) {
                        vm.gridOptions.totalItems = data.totalCount;

                        vm.gridOptions.data = data.items;
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM-DD HH:mm');
                }
                else {
                    return "";
                }
            };

            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize('No'),
                        field: 'agreementNo',
                        type: 'number',
                        //width: 80
                        minWidth: 130
                    },
                    {
                        name: app.localize('VehicleNo'),
                        field: 'vehicle.plateNo',
                        minWidth: 120
                    },
                    {
                        name: app.localize('MakeAndModel'),
                        field: 'vehicle.makeAndModel',
                        minWidth: 120
                    },
                    {
                        name: app.localize('Customer'),
                        field: 'customer.name',
                        minWidth: 140
                    },
                    {
                        name: app.localize('PickupDate'),
                        field: 'startDate',
                        minWidth: 120,
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.startDate)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('ReturnDate'),
                        field: 'endDate',
                        minWidth: 120,
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.endDate)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('PickupLocation'),
                        field: 'location.name',
                        minWidth: 140,
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div ng-if="row.entity.pickupLocationId" class=\"ui-grid-cell-contents\">{{row.entity.pickupLocation.title}}</div>' +
                            '<div ng-if="!row.entity.pickupLocationId" class=\"ui-grid-cell-contents\">{{row.entity.location}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Branch'),
                        field: 'location',
                        minWidth: 120
                    },
                    {
                        name: app.localize('VehicleType'),
                        field: 'tariffGroup',
                        minWidth: 120
                    },

                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = null;
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }
                        vm.getBookings();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getBookings();
                    });
                },
                data: []
            };

            vm.getBookings = function () {
                vm.loading = true;

                if (vm.filters.bookingStatus == 'Due') {
                    vm.DueToCloseCalender();
                }
                else if (vm.filters.bookingStatus == 'OverDue') {


                    vm.filters.fromDate = moment().startOf('day');
                    vm.filters.toDate = moment().endOf('day')
                    externalBookingSearchService.getOverDueBookings(
                        vm.filters).success(function (data) {
                            vm.gridOptions.totalItems = data.totalCount;
                            vm.gridOptions.data = data.items;

                        }).finally(function () {
                            vm.loading = false;
                        });
                }
                else {

                    externalBookingSearchService.getBookings(vm.filters).success(function (data) {
                        vm.gridOptions.totalItems = data.totalCount;
                        vm.gridOptions.data = data.items;

                    }).finally(function () {
                        vm.loading = false;
                    });
                }
            };

            function init() {
                vm.getBookings();
            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.externalVehiclesControlPanel.rental.bookings.report',
        ['$scope', '$stateParams', 'abp.services.app.externalBookingSearch', 'abp.services.app.commonLookup', 'utilities',
        function ($scope, $stateParams, externalBookingSearchService, commonLookupService, utilities) {

            var vm = this;

            if ($scope.$parent != null) {
                if ($scope.$parent.vmMain != null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters == null)
                vm.filters = $stateParams.filters;

            if (vm.filters.bookingNo) {
                vm.filters.fromDate = null;
                vm.filters.toDate = null;
                vm.filters.locationId = null;
                vm.filters.bookingStatus = null;
                vm.filters.customer = null;
                vm.filters.durationType = 1;
            }

            vm.localize = function (input) {
                return app.localize(input);
            };
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.enableManualBookingNo = utilities.parseBoolean(abp.setting.get("App.General.EnableManualBookingNo"));


            vm.agreementType = '';
            vm.locationName = '';
            vm.roundingforView = function (value) {
                var roundedValue = utilities.roundforView(value, 2);
                return roundedValue.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            };
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            function getAgreementTypes() {
                if (!vm.filters.agreementType) return '';
                if (vm.filters.agreementType == 1) vm.agreementType = 'Daily';
                if (vm.filters.agreementType == 2) vm.agreementType = 'Weekly';
                if (vm.filters.agreementType == 3) vm.agreementType = 'Monthly';
            };
            vm.getStatuses = function () {
                if (!vm.filters.bookingStatus) return '';
                if (vm.filters.bookingStatus == 1)
                    return app.localize("New");
                else if (vm.filters.bookingStatus == 2)
                    return app.localize("Confirmed");
                else if (vm.filters.bookingStatus == 3)
                    return app.localize("Cancelled");
                else if (vm.filters.bookingStatus == 4)
                    return app.localize("Closed");
            };
            vm.getlocalizedString = function (status) {
                return app.localize(status);
            };
            function getLocationName() {
                if (!vm.locations || !vm.filters.locationId)
                    return null;
                angular.forEach(vm.locations, function (value, key) {
                    if (value.id == vm.filters.locationId) {
                        vm.locationName = value.name;
                        return;
                    }
                });
            };
            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    getLocationName();
                });
            }
            function init() {
                getLocations();
                vm.loading = true;
                if (vm.filters.agreementType)
                    getAgreementTypes();
                externalBookingSearchService.getBookingsReport(vm.filters).success(function (data) {
                    vm.bookingReportData = data.items;
                    console.clear(); console.log(vm.bookingReportData);
                }).finally(function () {
                    vm.loading = false;
                });
            }
            init();
        }]);
})();;
(function () {
    appModule.controller('tenant.views.externalVehiclesControlPanel.rental.bookings.viewModal', [
        '$scope', '$uibModal', 'utilities', '$uibModalInstance', 'bookingId', 'abp.services.app.booking', 'abp.services.app.externalBookingSearch', 'tariffHelper', '$filter',
        function ($scope, $uibModal, utilities, $uibModalInstance, bookingId, bookingAppService, externalBookingSearchService, tariffHelper, $filter) {

            var vm = this;

            vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
            vm.isTaxOptional = utilities.parseBoolean(abp.setting.get("App.General.IsTaxOptional"));
            vm.taxPercent = parseFloat(abp.setting.get("App.General.TaxPercentage"));
            vm.enableManualBookingNo = utilities.parseBoolean(abp.setting.get("App.General.EnableManualBookingNo"));
            vm.taxAccepted = false;
            vm.isWeeklyMonthlyEnabled = utilities.parseBoolean(abp.setting.get("App.General.WeeklyMonthlyRental"));
            vm.loading = false;
            vm.documents = [];
            vm.isTariffCardExplicitSelection = utilities.parseBoolean(abp.setting.get("App.General.TariffCardExplicitSelection"));
            vm.isTariffCardEnable = abp.features.isEnabled("CRS.Tariff.TariffCards");
            vm.documentsForBookings = abp.features.isEnabled("CRS.CustomFeatures.DocumentsForBookings");
            vm.isUserWiseDiscountEnable = abp.features.isEnabled("CRS.UserWiseDiscount");
            vm.invoiceBasedOnAgreedRent = utilities.parseBoolean(abp.setting.get("App.General.InvoiceBasedOnAgreedRent"));
            var isValid = true;
            var isTariffEnabled = abp.features.isEnabled("CRS.Tariff");
            vm.agreementTypes = [
                { type: "Daily", id: 1 },
                { type: "Weekly", id: 2 },
                { type: "Monthly", id: 3 }
            ];
            vm.rounding = function (value) {
                if (!value) return;
                return utilities.round(value, 2);
            };
            vm.roundingforView = function (value) {
                var roundedValue = utilities.roundforView(value, 2);
                return roundedValue.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
            };
            vm.localize = function (input) {
                return app.localize(input);
            };

            vm.disableRate = function (chargesRow) {
                if (chargesRow.tariff.length > 1) {
                    var foundLines = $filter('filter')(chargesRow.tariff, {
                        included: chargesRow.included,
                        rate: chargesRow.rate,
                        excessRate: chargesRow.excessRate,
                        limit: chargesRow.limit
                    }, true);
                    if (foundLines.length > 0) {
                        return foundLines[0].rate > 0;
                    }
                    else {
                        return false;
                    }
                }
                return chargesRow.tariff[0].rate > 0;
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getOriginalName = function (doc) {
                var originalName = doc.name.replace("_" + doc.guid, "");
                return originalName;
            };

            vm.uploadDocument = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/bookings/uploadDocumentsModal.cshtml',
                    controller: 'tenant.views.crs.bookings.uploadDocumentsModal as vm',
                    backdrop: 'static'

                });
                modalInstance.result.then(function (result) {
                    vm.documents.push(result);
                });
            };

            vm.totalDaysAndTime = function () {
                var startDate = moment(vm.agreement.startDate, "DD/MM/YYYY hh:mm");
                var endDate = moment(vm.agreement.endDate, "DD/MM/YYYY hh:mm");

                if (startDate.isValid() && endDate.isValid()) {

                    var duration = moment.duration(moment(endDate.format("LLLL")).diff(moment(startDate.format("LLLL"))));
                    vm.totalDays = moment(endDate.format("LLLL")).diff(moment(startDate.format("LLLL")), 'days');
                    vm.remainingHrs = utilities.round(duration.hours() + (duration.minutes() / 60), 2);
                }
                else {
                    var startDate = moment(vm.agreement.startDate);
                    var endDate = moment(vm.agreement.endDate);

                    if (startDate.isValid() && endDate.isValid()) {
                        vm.totalDays = moment(endDate.format("LLLL")).diff(moment(startDate.format("LLLL")), 'days');
                        var totalHrs = moment(endDate.format("LLLL")).diff(moment(startDate.format("LLLL")), 'hours');
                        vm.remainingHrs = totalHrs - (vm.totalDays * 24);
                    }

                }
            };

            function init() {
                vm.loading = true;
                externalBookingSearchService.getBookingForView({
                    id: bookingId
                }).success(function (result) {
                    vm.agreement = result;
                    vm.documents = vm.agreement.documents;
                    if (vm.agreement.vehicle)
                        vm.vehicleMakeAndModel = vm.agreement.vehicle.make + " " + vm.agreement.vehicle.model.name;
                    if (vm.agreement && vm.agreement.charges) {
                        var foundLines = $filter('filter')(vm.agreement.charges, {
                            chargesTypeId: 1
                        }, true);
                        if (foundLines.length == 1) {
                            if (foundLines[0].discountPercent > 0) {
                                foundLines[0].discountedRate = vm.roundingforView(foundLines[0].rate - (foundLines[0].rate * (foundLines[0].discountPercent / 100)));
                            }
                        }
                    }
                    //in edit mod load tariff for vehicle. which will be used if some parameter is changed like dates etc.
                    var groupId = vm.agreement.tariffGroup.id;
                    if (groupId == null) groupId = -1;

                    //if (isTariffEnabled) {
                    //    //load tariff
                    //    tariffHelper.loadTariff(groupId, function () {
                    //        //don't apply
                    //    });
                    //}
                    vm.totalDaysAndTime();
                    vm.taxAccepted = vm.agreement.taxPercent > 0 ? true : false;
                }).finally(function () {
                    vm.loading = false;
                });


            }

            init();
        }
    ]);
})();;
