                        { id: 2, name: app.localize("ReplacementDelivery"), movementSubType: 9 },
                        { id: 2, name: app.localize("NRM_CustomerMovement"), movementSubType: 13 },
                        { id: 2, name: app.localize("NRM_AgreementCollection"), movementSubType: 11 }
