(function () {

    appModule.controller('tenant.views.fuel.dataSharing.sharingMapping', [
        'utilities', '$scope', '$uibModal', 'uiGridConstants', '$stateParams', 'abp.services.app.dataSharingMapping',
        function (utilities, $scope, $uibModal, uiGridConstants, $stateParams, dataSharingMappingService) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
         
            vm.loading = false;
            vm.filters = {
                code: '',
                name: '',
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize
            };


            vm.getDataType = function () {
                vm.filters.dataType = $stateParams.dataType;
                if ($stateParams.dataType == 5)
                    return app.localize('E-Fuel');
             
            };

            vm.fields = [];
            function getFields() {
                vm.fields.push("PlateNo_Mapped");
               // vm.fields.push("State_Mapped");
               // vm.fields.push("PlateCode_Mapped");
               // vm.fields.push("Description_Mapped");
               // vm.fields.push("Location_Mapped");
               // vm.fields.push("Authority_Mapped");
                //vm.fields.push("Vehicle No");
            }

            vm.statuses = [];
            function getStatuses() {
                vm.statuses.push("Mapped");
                vm.statuses.push("Un-Mapped");
            }

            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                useExternalPagination: true,
                appScopeProvider: vm,
                enableSorting: true,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: '10%',
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a  ng-click="grid.appScope.openCreateOrEditDataSharingMappingModal(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a  ng-click="grid.appScope.deleteMapping(row.entity.id)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Input') + ' ' + app.localize('Value'),
                        field: 'inputValue'
                    },
                    {
                        name: app.localize('Output') + ' ' + app.localize('Value'),
                        field: 'outputValue'
                    },
                    {
                        name: 'State',
                        field: 'parentValue'
                    }

                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = "inputValue desc";
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }

                        vm.getMappings();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getMappings();
                    });
                },
                data: []
            };

            vm.getDateFormat = function (date) {
                if (date !== null) {
                    return moment.utc(date).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.openCreateOrEditDataSharingMappingModal = function (mapping) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/fuel/dataSharing/createOrEditSharingMapping.cshtml',
                    controller: 'tenant.views.fuel.dataSharing.createOrEditSharingMapping as vm',
                    backdrop: 'static',
                    size: '450',
                    resolve: {
                        mapping: function () {
                            if (mapping != null) {
                                return mapping;
                            }
                            else {
                                return { id: null, dataType: vm.filters.dataType, field: vm.filters.field };
                            }
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getMappings();
                });
            };


            vm.deleteMapping = function (id) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', ''),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            dataSharingMappingService.deleteMapping({
                                id: id
                            }).success(function () {
                                vm.getMappings();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            function hideOrShowStateColumn() {
                var pos = vm.gridOptions.columnDefs.map(function (e) { return e.name; }).indexOf('State');
                if (vm.filters.field == "PlateCode_Mapped") {
                    vm.gridOptions.columnDefs[pos].visible = true;
                } else {
                    vm.gridOptions.columnDefs[pos].visible = false;
                }
            }


            vm.getMappings = function () {
                hideOrShowStateColumn();
                if (vm.filters.field) {
                    vm.loading = true;
                    dataSharingMappingService.getMappings(vm.filters).success(function (data) {
                        vm.gridOptions.totalItems = data.totalCount;
                        vm.gridOptions.data = data.items;
                    }).finally(function () {
                        vm.loading = false;
                    });
                }
                else {
                    vm.gridOptions.totalItems = 0;
                    vm.gridOptions.data = [];
                }
            }

            hideOrShowStateColumn();
            vm.getDataType();
            getFields();
            getStatuses();
            vm.getMappings();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.fuel.downloading.downloadEnoc', [
        '$scope', 'abp.services.app.uaeFuelTransactions', 'chromeExtDownloader',
        function ($scope, uaeFuelTransactions, chromeExtDownloader) {
            var vm = this;
            vm.fuelAccounts = [];
            var dateFormat = abp.setting.get("App.General.DateFormat");
            if (!dateFormat) dateFormat = 'dd/MM/yyyy';


            vm.getDate = function (date) {
                if (date) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(dateFormat);
                } else {
                    return '';
                }
            };

            vm.getFuelAccountsForDownload = function () {
                vm.loading = true;
                uaeFuelTransactions.getFuelAccountsForDownload()
                    .success(function (result) {
                        vm.fuelAccounts = result.filter(x => x.type == 1);
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            function sendCaptcha(d) {
                const o = {
                    captchaText: d.captchaTxt, fuelAccount: d.fuelAccount, type: 'processCaptcha'
                };

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    o.captchaTxt = d.captchaTxt;
                    o.capthaTabId = d.capthaTabId; //apply script on this tab
                    chromeExtDownloader.sendCaptchaMv3(o)
                }
                else {
                    var event = new CustomEvent('startFuelDownloadingENOC', {
                        detail: JSON.stringify(o)
                    });

                    event.initEvent('startFuelDownloadingENOC');
                    document.dispatchEvent(event);
                }
            }

            vm.captchaKeyPress = function (keyEvent, acc) {
                if (keyEvent.which === 13) {
                    sendCaptcha({ type: "applyCaptcha", captchaTxt: acc.captchaTxt, account: acc, capthaTabId: acc.capthaTabId });
                }
            };

            vm.downloadFuelTransV3 = function () {
                chromeExtDownloader.downloadFuelV3(vm, false);
            };

            vm.downloadByAccount = function (fuelAccount) {

                debugger;
                //abp.message.info('Temporary disabled, please contact Sales for new module');

                fuelAccount.isDownloading = true;
                vm.isDownloading = true;

                fuelAccount.enocVIPEnabled = abp.features.isEnabled("FuelDataMangement.DownloadENOCTransactions.Vip");
                fuelAccount.enocMainEnabled = false; // abp.features.isEnabled("FuelDataMangement.DownloadENOCTransactions.Enoc");

                if (!fuelAccount.enocVIPEnabled &&
                    !fuelAccount.enocMainEnabled) {
                    abp.message.info('VIP || MAIN one of the features need to enable.');
                    return;
                }

                fuelAccount.error = '';
                fuelAccount.status = '';

                let fuelRequest = {};
                fuelRequest.fromDate = moment().add('month', -1).startOf('month').format("DD/MM/YYYY");
                fuelRequest.toDate = moment().add('month', -1).endOf('month').format("DD/MM/YYYY");
                fuelRequest.type = fuelAccount.type;
                fuelRequest.fuelTransAccounts = [];
                fuelRequest.fuelTransAccounts.push(fuelAccount);

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {

                    vm.callbackOnComplete = function () {
                        vm.getFuelAccountsForDownload();
                    };

                    vm.fuelRequest = {
                        request: fuelRequest,
                        fuelAccounts: fuelRequest.fuelTransAccounts
                    };

                    chromeExtDownloader.initV3(vm, vm.downloadFuelTransV3);

                    return;
                }

                var funcNode = document.getElementById('speedExtReporting');
                if (funcNode) {
                    funcNode.parentElement.removeChild(funcNode);
                }

                let fnc = `function processCaptcha(msg) {
					let $scope = angular.element(document.querySelectorAll('[ng-controller]')[1]).scope();
					let fuelAccount = $scope.vm.fuelAccounts.find(x => x.id === msg.fuelAccount.id);
					fuelAccount.captchaSrc = msg.captcha;
					fuelAccount.captchaTxt = '';

					if (!$scope.$$phase) {
						$scope.$digest();
					}
				}

				function reportFuelStatus(status) {
					var $scope = angular.element('#appController').scope();
                    debugger;
					if (status.isComplated || (status.error && !status.error === {})) {
						
						$scope.vm.isDownloading = false;

						if (status.isCancled) {
							let acc = $scope.vm.fuelAccounts.find(x => x.isDownloading);
							acc.progress = null;
							acc.status = null;
							acc.error = "Cancled";
							acc.isCompleted = true;
							acc.isDownloading = false;
							acc.captcha = '';
							acc.cls = 'badge badge-danger';
						}
						else if (status.fuelAccount) {
							var acc = $scope.vm.fuelAccounts.find(x => x.id == status.fuelAccount.id);
							acc.progress = status.progress;
							acc.status = status.status;
							acc.status = status.error ? status.error : '';
							acc.isCompleted = true;
							acc.captcha = '';
							acc.isDownloading = false;
							acc.cls = 'badge badge-success';

							$scope.vm.getFuelAccountsForDownload();
						}
					}
					else {
						$scope.vm.isDownloading = true;

						if (status.fuelAccount) {
							var acc = $scope.vm.fuelAccounts.find(x => x.id == status.fuelAccount.id);
							acc.progress = status.progress;
							acc.captcha = status.captcha;
							acc.status = status.status;
							acc.isComplated = status.isComplated;
							acc.error = status.error;
							acc.cls = 'badge badge-info';
						}
					}

					if (!$scope.$$phase) {
						$scope.$digest();
					}
				} `;


                chromeExtDownloader.downloadFuelTrans(
                    fuelRequest,
                    fnc,
                    function error(e) {

                        vm.isDownloading = false;

                        if (!$scope.$$phase)
                            $scope.$digest();

                        abp.message.error(e.error);
                    });
            };

            vm.round = function (value) {
                return Math.round(value, 2);
            };

            function init() {
                vm.getFuelAccountsForDownload();
            }

            init();
        }
    ]);
})();;
(function () {

	appModule.controller('tenant.views.fuel.downloading.index', [
		'$scope', 'abp.services.app.uaeFuelTransactions', 'chromeExtDownloader',
		function ($scope, uaeFuelTransactions, chromeExtDownloader) {
			var vm = this;
			vm.fuelAccounts = [];
			var dateFormat = abp.setting.get("App.General.DateFormat");
			if (!dateFormat) dateFormat = 'dd/MM/yyyy';


			vm.getDate = function (date) {
				if (date) {
					var localTime = moment.utc(date).toDate();
					return moment(localTime).format(dateFormat);
				} else {
					return '';
				}
			};

			vm.downloadFuelTransV3 = function () {
				chromeExtDownloader.downloadFuelV3(vm, false);
			};

			vm.getFuelAccountsForDownload = function () {
				vm.loading = true;
				uaeFuelTransactions.getFuelAccountsForDownload()
					.success(function (result) {
						vm.fuelAccounts = result.filter(x => x.type == 2);
					}).finally(function () {
						vm.loading = false;

						if (!$scope.$$phase)
							$scope.$digest();
					});
			};

			vm.downloadByAccount = function (fuelAccount) {
				fuelAccount.isDownloading = true;
				vm.isDownloading = true;

				fuelAccount.smartEnabled = abp.features.isEnabled("FuelDataMangementDownlaod.ADNOCTransactions.Smart");
				fuelAccount.smartPlusEnabled = abp.features.isEnabled("FuelDataMangement.DownlaodADNOCTransactions.SmartPlus");
				fuelAccount.rahalEnabled = abp.features.isEnabled("FuelDataMangement.DownlaodADNOCTransactions.Rahal");
				fuelAccount.downloadAdnocfromInvoiceLink = abp.setting.getBoolean('App.General.Fuel.DownloadAdnocSmartTransactionsfromInvoiceLink');

				if (!fuelAccount.smartEnabled &&
					!fuelAccount.smartPlusEnabled &&
					!fuelAccount.rahalEnabled) {
					abp.message.info('Smart || Plus || Rahal one of the features need to enable.');
					return;
				}

				fuelAccount.error = '';
				fuelAccount.status = '';

				let fuelRequest = {};
				fuelRequest.fromDate = fuelAccount.lastDownloadDate ?
					moment(fuelAccount.lastDownloadDate).format("DD/MM/YYYY") : moment().format("DD/MM/YYYY");
				fuelRequest.toDate = moment().format("DD/MM/YYYY");
				fuelRequest.type = fuelAccount.type;
				fuelRequest.fuelTransAccounts = [];
				fuelRequest.fuelTransAccounts.push(fuelAccount);

				//temporary date adjustment only for 2 months
				fuelRequest.fromDate = moment().add('month', -1).startOf('month').format("DD/MM/YYYY");

				if (chromeExtDownloader.isMv3ExtensionAvailable()) {

					vm.callbackOnComplete = function () {
						console.log('callbackOnComplete run');
						vm.isDownloading = false;
						vm.getFuelAccountsForDownload();
					};

					vm.fuelRequest = {
						request: fuelRequest,
						fuelAccounts: fuelRequest.fuelTransAccounts
					};

					chromeExtDownloader.initV3(vm, vm.downloadFuelTransV3);

					return;
				}

				var funcNode = document.getElementById('speedExtReporting');
				if (funcNode) {
					funcNode.parentElement.removeChild(funcNode);
				}

				let fnc = `function reportFuelStatus(status) {
					var $scope = angular.element('#appController').scope();
					if (status.isComplated || (status.error && !status.error === {})) {
						debugger;
						$scope.vm.isDownloading = false;

						if (status.isCancled) {
							let acc = $scope.vm.fuelAccounts.find(x => x.isDownloading);
							acc.progress = null;
							acc.status = null;
							acc.error = "Cancled";
							acc.isCompleted = true;
							acc.isDownloading = false;
							acc.cls = 'badge badge-danger';
						}
						else if (status.account) {
							var acc = $scope.vm.fuelAccounts.find(x => x.id == status.account.id);
							acc.progress = status.progress;
							acc.status = status.status;
							acc.status = status.error ? status.error : '';
							acc.isCompleted = true;
							acc.isDownloading = false;
							acc.cls = 'badge badge-success';

							$scope.vm.getFuelAccountsForDownload();
						}
					}
					else {
						$scope.vm.isDownloading = true;

						if (status.account) {
							var acc = $scope.vm.fuelAccounts.find(x => x.id == status.account.id);
							acc.progress = status.progress;
							acc.status = status.status;
							acc.isComplated = status.isComplated;
							acc.error = status.error;
							acc.cls = 'badge badge-info';
						}
					}

					if (!$scope.$$phase) {
						$scope.$digest();
					}
				} `;

				chromeExtDownloader.downloadFuelTrans(
					fuelRequest,
					fnc,
					function error(e) {

						vm.isDownloading = false;

						if (!$scope.$$phase)
							$scope.$digest();

						abp.message.error(e.error);
					});
			};

			vm.round = function (value) {
				return Math.round(value, 2);
			};

			vm.showError = function (acc) {
				abp.message.error(acc.error);
			};

			function init() {
				vm.getFuelAccountsForDownload();
			}

			init();
		}
	]);
})();;
