(function () {
    appModule.controller('tenant.views.fuel.importEPPCOData.index', [
        '$scope', 'abp.services.app.ePPCOImportData',
        function ($scope, eppcoImportDataService) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.isFuelEnabled = abp.features.isEnabled("FuelDataMangement");
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.loading = false;
            vm.processing = false;
            var currentPage = 1;
            var maxCountToProcessInOneRequest = 100;
            vm.dateOptions = {
                format: vm.dateFormat
            };
            vm.filters = {
                skipCount: 0,
                maxResultCount: maxCountToProcessInOneRequest
            };

            vm.permissions = {
                create: vm.isFuelEnabled
            };

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    //var localTime = moment.utc(date).toDate();
                    //return moment(localTime).format(vm.dateTimeFormat);
                    return moment(date).utc().format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalDate = function (date) {
                if (date !== null) {
                    return moment(date).utc().format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            //start
            $scope.selectedFile = null;
            vm.response = {
                processed: 0,
                unProcessed: 0,
                total: 0
            };

            $scope.loadFile = function (files) {
                $scope.$apply(function () {
                    $scope.selectedFile = files[0];
                });
            };

            vm.save = function () {
                vm.loading = true;
                var file = $scope.selectedFile;
                if (file && ['xlsx', 'xls'].indexOf(file.name.split('.').pop().toLowerCase()) > -1) {
                    vm.response = {
                        processed: 0,
                        unProcessed: 0,
                        total: 0
                    };
                    var reader = new FileReader();
                    reader.onload = function (e) {
                        var data = e.target.result;
                        var workbook = XLSX.read(data, { type: 'binary', cellDates: true, cellNF: false, cellText: false });
                        var first_sheet_name = workbook.SheetNames[0];

                        var dataObjects = XLSX.utils.sheet_to_json(workbook.Sheets[first_sheet_name], { raw: true, dateNF: 'MM-DD-YYYY HH:mm:ss' });

                        if (dataObjects.length > 0) {

                            //if VIP Export File detacted
                            if (dataObjects[0]['SITE'] !== undefined) {
                                var fileDataList = [];
                                angular.forEach(dataObjects, function (value) {

                                    fileDataList.push({
                                        amount: value['AMOUNT'],
                                        amountWithoutVat: value['VDET ACTUALAMOUNT'],
                                        batchNo: value['BATCH NO'],
                                        cardNo: value['CARDOFFSET'],//value['VID NUMBER'],
                                        cardOffset: value['CARDOFFSET'],
                                        odoMeter: value['ODOMETER'],
                                        product: value['PRODUCT'],
                                        quantity: value['QUANTITY'],
                                        site: value['SITE'],
                                        source: 1,
                                        transactionDateTime: value['TRANSACTIONDATE'],
                                        unitPrice: value['UNIT PRICE'],
                                        vatAmount: value['VDET VATAMOUNT'],
                                        vatRate: value['VDET VATRATE'],
                                        vehicleInfo: value['PLATECODE'],
                                        voucherNo: value['VOUCHERNO']
                                    });

                                });
                                vm.importDataFuelTransaction(fileDataList);
                            } else if (dataObjects[0]['INT BATCH NO'] !== undefined) {
                                //If ENOC Data File Detected
                                fileDataList = [];
                                angular.forEach(dataObjects, function (value) {
                                    fileDataList.push({//change value names
                                        amount: value['AMOUNT'],
                                        amountWithoutVat: value['ACTUAL AMOUNT WITHOUT VAT'],
                                        batchNo: value['INT BATCH NO'],
                                        cardNo: value['VID NUMBER'],
                                        cardOffset: value['CARDOFFSET'],
                                        odoMeter: value['ODOMETER'],
                                        product: value['PRODUCT'],
                                        quantity: value['QUANTITY'],
                                        site: value['SITE NO'],
                                        source: 2,
                                        transactionDateTime: value['TRANSACTIONDATE'],
                                        unitPrice: value['UNIT PRICE'],
                                        vatAmount: value['VDET ACTUALAMOUNT'],
                                        vatRate: value['VDET VATAMOUNT'],
                                        vehicleInfo: value['VEHICLE NUMBER'],
                                        voucherNo: null
                                    });
                                });
                                vm.importDataFuelTransaction(fileDataList);
                            } else {
                                abp.message.warn("Please select Valid file to upload !", "Unknown File");
                                vm.loading = false;
                            }

                        } else {
                            console.log("Error : Something Wrong Or File is empty !");
                            abp.message.warn("Error : Something Wrong Or File is empty !", "Error");
                            vm.loading = false;
                        }
                    };
                    reader.onerror = function (ex) {
                        console.log(ex);
                        vm.loading = false;
                        abp.message.warn(
                            app.localize(ex),
                            'Unknown File'
                        );
                    };
                    reader.readAsBinaryString(file);
                } else {
                    abp.message.warn("Please select Valid file to upload !", "Unknown File");
                    vm.loading = false;
                }
            };

            vm.importDataFuelTransaction = function (data) {
                vm.loading = true;
                vm.response = {
                    processed: 0,
                    unProcessed: 0,
                    total: 0
                };
                eppcoImportDataService.importDataFuelTransaction({ fuelTransactionList: data })
                    .success(function (result) {
                        vm.response = result;
                        vm.autoProcess(vm.response);
                        abp.notify.success("Saved");
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            vm.refresh = function () {
                vm.response = {
                    processed: 0,
                    unProcessed: 0,
                    total: 0
                };
                angular.element('#fileMobile').val(null);
                $scope.selectedFile = null;
            };

            vm.autoProcess = function (par) {
                if (par.minDate)
                    vm.filters.fromDate = moment(par.minDate).utc().toJSON();
                if (par.maxDate)
                    vm.filters.toDate = moment(par.maxDate).utc().toJSON();

                vm.filters.fromDate = moment(vm.filters.fromDate).startOf('day');
                vm.filters.toDate = moment(vm.filters.toDate).startOf('day').endOf('day');
                
                vm.filters.count = par.count;
                vm.filters.skipCount = 0;
                currentPage = 1;
                moreDataToProcess = true;

                vm.response = {
                    processed: 0,
                    unProcessed: 0,
                    total: 0
                };

                vm.process();
            };

            vm.process = function () {
                if (vm.filters.fromDate > vm.filters.toDate) return;
                vm.processing = true;

                var filters = {};
                filters = vm.filters;

                eppcoImportDataService.processEPPCOData(filters)
                    .success(function (result) {

                        moreDataToProcess = (result.total > 0);
                        if (moreDataToProcess) {

                            //vm.response = result;
                            vm.response.processed += result.processed;
                            vm.response.unProcessed += result.unProcessed;
                            vm.response.total += result.total;

                            vm.filters.skipCount = currentPage * maxCountToProcessInOneRequest;
                            currentPage += 1;
                            vm.process();
                        } else {
                            vm.processing = false;
                        }
                    }).finally(function () {
                        //vm.processing = false;
                    });

            };

            vm.nextProcess = function () {
                vm.filters.skipCount = 0;
                currentPage = 1;
                moreDataToProcess = true;
                vm.response = {
                    processed: 0,
                    unProcessed: 0,
                    total: 0
                };

                vm.filters.fromDate = moment(vm.filters.fromDate).utc().startOf('day');
                vm.filters.toDate = moment(vm.filters.toDate).utc().startOf('day').endOf('day');

                vm.process();
            };
        }
    ]);

})();;
(function () {
    appModule.controller('tenant.views.fuel.sharing.index', [
        '$scope', 'abp.services.app.dataSharingSetting',
        function ($scope, dataSharingSettingService) {
            var vm = this;
            vm.saving = false;
            vm.loading = false;
            vm.fields = [];
            vm.shareFileFormat = abp.features.getValue("FuelDataMangement.ShareFuel_FileFormat");
            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });


            vm.setting = {
                dataToShare: 5,
                sharingFormat: 0,
                configuration: {
                    sftpConfiguration: {},
                    fieldMappings: []
                }
            }

            function getSharingFormat() {
                if (vm.shareFileFormat === "CSV") {
                    vm.sharingFormat = 1;
                    vm.shareAs = app.localize('CSV');
                }
                else if (vm.shareFileFormat === "MsSql") {
                    vm.sharingFormat = 2;
                    vm.shareAs = app.localize('MsSql');
                }
                else if (vm.shareFileFormat === "Oracle") {
                    vm.sharingFormat = 7;
                    vm.shareAs = app.localize('Oracle');
                }
            }


            vm.addcustomRow = function () {
                if (vm.dataToShare == 5)
                    vm.fuelTransaction.configuration.sharedDBs.push(customsettings());

            };

            vm.getlocalDate = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.fieldtypechange = function (row) {
                if (row.fieldType !== 1)
                    row.maxLength = null;
                if (row.inputField !== "N/A")
                    row.defaultValue = null;
                if (row.filedType !== 3)
                    row.defaultValue = null;
            };

            vm.save = function () {
                vm.saving = true;
                vm.loading = true;
                vm.setting.dataToShare = vm.dataToShare;
                debugger;
                vm.setting.sharingFormat = vm.sharingFormat;
                vm.setting.isActive = 1;
                vm.setting.configuration.sharingStartDate = moment(vm.setting.configuration.sharingStartDate).startOf('day');
                dataSharingSettingService.updateAllSettings(vm.setting).success(function (result) {
                    vm.loading = false;
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    getAllSettings();
                }).finally(function () {
                    vm.saving = false;
                });
            };

            vm.sortOfSettingsChanged = function (event, ui) {
                vm.loading = true;
                var obj = JSON.parse(ui.item.attr('data-id'));
                var updatedIndex = ui.item.index();

                var row = obj.row;


                if (updatedIndex === 0) {

                    row.order = (vm.settings.configuration.fieldMappings[0].order) / 2;
                    var element = row;
                    vm.settings.configuration.fieldMappings.splice(obj.rowIndex, 1);
                    vm.settings.configuration.fieldMappings.splice(updatedIndex, 0, element);
                }
                else if (updatedIndex === (vm.settings.configuration.fieldMappings.length - 1)) {
                    row.order = (vm.settings.configuration.fieldMappings[updatedIndex].order + vm.settings.configuration.fieldMappings[updatedIndex].order + 1) / 2;
                    element = row;
                    vm.settings.configuration.fieldMappings.splice(obj.rowIndex, 1);
                    vm.settings.configuration.fieldMappings.splice(updatedIndex, 0, element);
                }
                else {
                    if (updatedIndex > obj.rowIndex)
                        row.order = (vm.settings.configuration.fieldMappings[updatedIndex + 1].order + vm.settings.configuration.fieldMappings[updatedIndex].order) / 2;
                    else if (updatedIndex < obj.rowIndex)
                        row.order = (vm.settings.configuration.fieldMappings[updatedIndex - 1].order + vm.settings.configuration.fieldMappings[updatedIndex].order) / 2;
                    element = row;
                    vm.settings.configuration.fieldMappings.splice(obj.rowIndex, 1);
                    vm.settings.configuration.fieldMappings.splice(updatedIndex, 0, element);
                }
                vm.loading = false;
                $scope.$apply();
            };

            vm.removerow = function (row) {
                if (vm.dataToShare == 5) {
                    let index = vm.setting.configuration.fieldMappings.indexOf(row);
                    vm.setting.configuration.fieldMappings.splice(index, 1);
                }
            };

            vm.dataSharingfieldtypes = [
                { key: 1, value: "Text" }, { key: 2, value: "Numeric" }, { key: 3, value: "DateTime" }, { key: 4, value: "Decimal" }, { key: 5, value: "Boolean" }];

            function getinputfields() {
                dataSharingSettingService.getInputFieldsFuelTransactions().success(function (result) {
                    vm.inputfields = result;
                });
            }

            vm.addRow = function () {
                debugger;

                vm.setting.configuration.fieldMappings.push({
                    order: vm.setting.configuration.fieldMappings.length < 1 ? 1 :
                        vm.setting.configuration.fieldMappings[vm.setting.configuration.fieldMappings.length - 1].order + 1,
                    inputfield: null,
                    outputfield: null,
                    fieldtype: null,
                    format: null,
                    defaultvalue: null,
                    maxlength: null
                });
            };

            function getAllSettings() {
                vm.loading = true;
                dataSharingSettingService.getAllSettingsFuel().success(function (result) {
                    vm.setting = result.find(x => x.dataToShare == 5);
                }).finally(function () {
                    vm.loading = false;
                });
            }

            function init() {
                getAllSettings();
                getSharingFormat();
                getinputfields();
                vm.dataToShare = 5;
            }
            init();
        }
    ]);

})();;
