(function () {

    appModule.controller('tenant.views.hrm.shift.createOrEditModal', [
        '$uibModalInstance', '$uibModal', 'abp.services.app.directory', 'abp.services.app.designation', 'abp.services.app.shift', 'abp.services.app.commonLookup', 'abp.services.app.department', 'options',
        function ($uibModalInstance, $uibModal, directoryService, designationService, shiftService, commonLookupService, staffDepartmentService, options) {


            var vm = this;
            vm.loading = false;
            vm.shiftTypes = [];
            vm.locations = [];
            vm.isDesignationFeatureEnabled = abp.features.isEnabled("Core.Staff.Designations");
            var shiftId = options.id;
            //vm.weekendDays = [               
            //    { dayOfWeek: 'Monday' },
            //    { dayOfWeek: 'Tuesday' },
            //    { dayOfWeek: 'Wednesday' },
            //    { dayOfWeek: 'Thursday' },
            //    { dayOfWeek: 'Friday' },
            //    { dayOfWeek: 'Saturday' },
            //    { dayOfWeek: 'Sunday' },
            //];
            vm.weekendDays = [
                { dayOfWeek: 1, dayValue: 'Monday' },
                { dayOfWeek: 2, dayValue: 'Tuesday' },
                { dayOfWeek: 3, dayValue: 'Wednesday' },
                { dayOfWeek: 4, dayValue: 'Thursday' },
                { dayOfWeek: 5, dayValue: 'Friday' },
                { dayOfWeek: 6, dayValue: 'Saturday' },
                { dayOfWeek: 7, dayValue: 'Sunday' },
            ];
            function mapNumberToDay(number) {
                switch (number) {
                    case 1:
                        return 'Monday';
                    case 2:
                        return 'Tuesday';
                    case 3:
                        return 'Wednesday';
                    case 4:
                        return 'Thursday';
                    case 5:
                        return 'Friday';
                    case 6:
                        return 'Saturday';
                    case 7:
                        return 'Sunday';
                    default:
                        return 'Unknown Day';
                }
            }
            //functions
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };


            function getLocations() {

                commonLookupService.getLocations({
                }).success(function (data) {
                    vm.locations = data.items;
                });
            };
            function getStaffDepartments() {
                staffDepartmentService.getDepartment({}).success(function (data) {
                    vm.staffDepartments = data.items
                }).finally(function () {
                    vm.loading = false;
                });
            };
            var designationDetails = function () {
                designationService.getDesignations().success(function (result) {
                    vm.designationDetails = result.items;
                    //console.log(test);
                });
            };
            vm.searchStaff = function ($select) {
                //whereas contactType: 1 (staff) 
                return directoryService.search({ keyword: $select.search, activeOnly: true, contactType: 1 }).then(function (response) {
                    vm.customers = response.data.items;
                });
            };

            vm.searchStaffPopoup = function () {

                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return 1;
                        }
                    }
                }).result.then(function (result) {
                    if (result != null) {
                        vm.onStaffSelect(result);
                    }
                });
            };

            vm.onStaffSelect = function (customer) {
                vm.shift.staffId = customer.id;
                vm.shift.staff = customer;
            };
            vm.resetTotalHours = function () {
                if (vm.shift.isFlexible) {
                    vm.shift.startTime = null;
                    vm.shift.endTime = null;
                    vm.shift.totalHours = null;
                }
                else {
                    vm.shift.totalHours = null;

                }
            }
            vm.calculateTotalHours = function () {
                // Check if both start and end time are defined
                if (vm.shift.startTime && vm.shift.endTime) {
                    // Calculate the time difference in milliseconds
                    var timeDiff = vm.shift.endTime - vm.shift.startTime;

                    // Convert the time difference to hours
                    var totalHours = Math.round(timeDiff / (1000 * 60 * 60) * 100) / 100;
                    //timeDiff / (1000 * 60 * 60);

                    // Update vm.shift.totalHours
                    vm.shift.totalHours = totalHours;
                } else {
                    // If start or end time is not defined, set totalHours to null
                    vm.shift.totalHours = null;
                }
            }
            vm.save = function () {
                vm.saving = true;
                shiftService.createOrUpdateShift({ shift: vm.shift }
                ).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });
            };

            //init 
            function init() {
                //getLocations();
                //getStaffDepartments();
                //if (vm.isDesignationFeatureEnabled)
                //    designationDetails();
                if (shiftId != null && shiftId != '' && shiftId != undefined) {
                    vm.loading = true;
                    shiftService.getShiftForEdit({ id: shiftId }).success(
                        function (result) {
                            vm.shift = result;
                            var mappedWeekendDays = vm.shift.weekendDays.map(function (weekendDay) {
                                return {
                                    dayOfWeek: weekendDay.dayOfWeek,
                                    dayValue: mapNumberToDay(weekendDay.dayOfWeek),
                                };
                            });
                            console.log(mappedWeekendDays);
                            vm.shift.weekendDays = mappedWeekendDays;
                        }).finally(function () {
                            vm.loading = false;
                        });
                }

            }

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.common.hrm.shift.index', [
        '$scope', '$uibModal', 'abp.services.app.directory', 'uiGridConstants', 'abp.services.app.shift',
        function ($scope, $uibModal, directoryService, uiGridConstants,  shiftService) {

            var vm = this;

            vm.loading = false;

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.timeFormat = "HH:mm";

            vm.permissions = {
                view: abp.auth.hasPermission('Pages.HRM.Shift.View'),
                create: abp.auth.hasPermission('Pages.HRM.Shift.AddNew'),
                edit: abp.auth.hasPermission('Pages.HRM.Shift.Edit'),
                delete: abp.auth.hasPermission('Pages.HRM.Shift.Delete')
            };

            vm.filters = {
                enableDateRange: true,
                startDate: null,
                endDate: null,
                staffId: null,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
            };

            vm.statuses = null;
            vm.types = null;
            vm.staffs = [];

            //functions
            vm.getShifts = function () {
                vm.loading = true;

                if (vm.filters.enableDateRange) {
                    vm.filters.startDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.endDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }

                if (vm.filters.staff != null) {
                    vm.filters.staffId = vm.filters.staff.id;
                }

                if (!vm.filters.enableDateRange) {
                    vm.filters.startDate = null;
                    vm.filters.endDate = null;
                }

                shiftService.getShifts(vm.filters).success(function (data) {

                    vm.gridOptions.totalItems = data.totalCount;
                    vm.gridOptions.data = data.items;

                }).finally(function () {
                    vm.loading = false;
                });

            };

            vm.dateRangeModelChanged = function () {
                vm.filters.startDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                vm.filters.endDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            function initDate() {
                vm.dateRangeModel = {
                    startDate: moment().add(-29, 'days').startOf('day'),
                    endDate: moment().endOf('day')
                };
            }

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.timeFormat);
                }
                else {
                    return "";
                }
            };
            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format('YYYY-MM-DD');
                }
                else {
                    return "";
                }
            };

            vm.clearStaff = function () {
                vm.filters.staff = null;
                vm.filters.staffId = null;
            };

            vm.searchStaff = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customers). get customers
                return directoryService.search({ keyword: $select.search, contactType: 1, activeOnly: true }).then(function (response) {
                    vm.staffs = response.data.items;
                });
            };

            vm.searchStaffPopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return 1;
                        }
                    }
                }).result.then(function (staff) {
                    if (staff != null) {
                        vm.filters.staff = staff;
                    }
                });
            };

            vm.createShift = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/hrm/shift/createOrEditModal.cshtml',
                    controller: 'tenant.views.hrm.shift.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return {
                                id: null
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getShifts();
                });
            };

            vm.editShift = function (shift) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/hrm/shift/createOrEditModal.cshtml',
                    controller: 'tenant.views.hrm.shift.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return {
                                id: shift.id
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getShifts();
                });
            };

            vm.viewShift = function (shift) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/hrm/shift/viewModal.cshtml',
                    controller: 'tenant.views.hrm.shift.viewModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        options: function () {
                            return {
                                id: shift.id
                            }
                        }
                    }
                });
                modalInstance.result.then(function (result) {
                    vm.getShifts();
                });
            };

            vm.deleteShift = function (shift) {
                abp.message.confirm(
                    app.localize('DeleteShiftMessage'),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            shiftService.deleteShift({
                                id: shift.id
                            }).success(function () {
                                vm.getShifts();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };

            vm.getStatus = function (status) {
                if (status == 0) {
                    return app.localize("Not Completed");
                } else if (status == 1) {
                    return app.localize("Completed");
                } else {
                    return "";
                }
            };

          

            //init
            function init() {
                initDate();
                vm.getShifts();
            }

            init();

            //grid 
            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize(' '),
                        enableSorting: false,
                        width: 55,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown " uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize(' ') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.view" ng-click="grid.appScope.viewShift(row.entity)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.edit"  ng-click="grid.appScope.editShift(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.delete" ng-click="grid.appScope.deleteShift(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Name'),
                        field: 'name',
                    },
                    {
                        name: app.localize('TotalHours'),
                        field: 'totalHours',
                    },
                    {
                        name: app.localize('CreationDate'),
                        field: 'creationDate',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.creationTime)}}</div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('ShiftTime'),
                        field: 'shiftTime',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div ng-if="!row.entity.isFlexible" class=\"ui-grid-cell-contents\">({{grid.appScope.getlocalTime(row.entity.startTime)}} - {{grid.appScope.getlocalTime(row.entity.endTime)}})</div>' +
                            '</div>'
                    },
                    //{
                    //    name: app.localize('EndDate'),
                    //    field: 'creationTime',
                    //    cellTemplate:
                    //        '<div class=\"ui-grid-cell\">' +
                    //        '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.creationTime)}}</div>' +
                    //        '</div>'
                    //},
                    //{
                    //    name: app.localize('Staff'),
                    //    field: 'staff.name',
                    //},
                    //{
                    //    name: app.localize('Designation'),
                    //    field: 'designation.name',
                    //},
                    
                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getShifts();
                    });
                },
                data: []
            };
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.hrm.shift.viewModal', [
        '$uibModalInstance', 'abp.services.app.directory', 'abp.services.app.shift', 'options',
        function ($uibModalInstance, directoryService, shiftService, options) {

            var vm = this;
            vm.loading = false;

            var shiftId = options.id;

            //functions
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            function mapNumberToDay(number) {
                switch (number) {
                    case 1:
                        return 'Monday';
                    case 2:
                        return 'Tuesday';
                    case 3:
                        return 'Wednesday';
                    case 4:
                        return 'Thursday';
                    case 5:
                        return 'Friday';
                    case 6:
                        return 'Saturday';
                    case 7:
                        return 'Sunday';
                    default:
                        return 'Unknown Day';
                }
            }
            //vm.getTypeOfShift = function (type) {
            //    if (type == 1) {
            //        return app.localize("Loan Shift");
            //    } else {
            //        return "";
            //    }
            //};

            //init 
            function init() {
                vm.loading = true;
                shiftService.getShiftForView({ id: shiftId }).success(
                    function (result) {
                        vm.shift = result;
                        var mappedWeekendDays = vm.shift.weekendDays.map(function (weekendDay) {
                            return {
                                dayOfWeek: weekendDay.dayOfWeek,
                                dayValue: mapNumberToDay(weekendDay.dayOfWeek),
                            };
                        });
                        console.log(mappedWeekendDays);
                        vm.shift.weekendDays = mappedWeekendDays;
                        /*vm.shift.type = vm.getTypeOfShift(vm.shift.type);*/

                    }).finally(function () {
                        vm.loading = false;
                    });
            }

            init();
        }
    ]);
})();;
