(function () {

    appModule.controller('tenant.views.hrm.sponsorship.index', [
        '$scope', '$uibModal', 'uiGridConstants', '$stateParams', 'abp.services.app.sponsorship', 'abp.services.app.user', 'appSession',
        function ($scope, $uibModal, uiGridConstants, $stateParams, sponsorship, userService, appSession) {

            var vm = this;

            vm.isCrsEnabled = abp.features.isEnabled("CRS");
            vm.currentUserId = appSession.user.id;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.loading = false;
            vm.type = $stateParams.type;

            vm.filters = {
                searchName: '',
                InActive: '',
            };

            vm.permissions = {
                create: abp.auth.hasPermission('Pages.HRM.Sponsorship.Addnew'),
                edit: abp.auth.hasPermission('Pages.HRM.Sponsorship.Edit'),
                'delete': abp.auth.hasPermission('Pages.HRM.Sponsorship.Delete'),
            };

            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: 80,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-if="grid.appScope.permissions.edit" ng-click="grid.appScope.editSponsorships(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="grid.appScope.permissions.delete" ng-click="grid.appScope.deleteSponsorships(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Name'),
                        field: 'name'
                    },
                    {
                        name: app.localize('Notes'),
                        field: 'notes'
                    },

                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = null;
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }

                        vm.getSponsorships();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getSponsorships();
                    });
                },
                data: []
            };

            vm.getSponsorships = function () {
                vm.loading = true;
                sponsorship.getSponsorships(vm.filters).success(function (data) {
                    vm.gridOptions.totalItems = data.totalCount;
                    vm.gridOptions.data = data;
                }).finally(function () {
                    vm.loading = false;
                });
            };

            function openCreateOrEditSponsorshipsModal(sponsorshipsEdit) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/hrm/sponsorship/createOrEditModal.cshtml',
                    controller: 'tenant.views.hrm.sponsorship.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        sponsorshipsEdit: function () {
                            return sponsorshipsEdit;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getSponsorships();
                });
            }

            vm.createSponsorships = function () {
                openCreateOrEditSponsorshipsModal(null);
            };

            vm.editSponsorships = function (sponsorshipsEdit) {
                openCreateOrEditSponsorshipsModal(sponsorshipsEdit);
            };

            vm.deleteSponsorships = function (obj) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', ''),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            sponsorship.deleteSponsorships({
                                id: obj.id
                            }).success(function () {
                                vm.getSponsorships();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            }).error(function (data) {
                                if (data) {
                                    setTimeout(() => abp.message.info(data.message), 300);
                                }

                            });
                        }
                    }
                );
            };
            vm.getSponsorships();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.hrm.staffOvertime.index', [
            'abp.services.app.employeeOvertime', 'utilities', '$stateParams', '$uibModal', 'abp.services.app.directory',
        function (employeeOvertimeService, utilities, $stateParams, $uibModal, directoryService) {
            var vm = this;
            vm.invalidForm = false;

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';

            // search from dropdown
            vm.searchCustomers = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get staff
                return directoryService.searchStaff({ keyword: $select.search, contactType: $stateParams.contactType }).then(function (response) {
                    vm.customers = response.data.items;
                });
            };

            // extended search using search customer popup
            vm.searchCustomerPopoup = function () {
                $uibModal.open({
                    templateUrl: '~/App/tenant/views/crs/contacts/searchContactStaffModal.cshtml',
                    controller: 'tenant.views.crs.contacts.searchContactStaffModal as vm',
                    backdrop: 'static',
                    resolve: {
                        category: function () {
                            return null;
                        },
                        type: function () {
                            return $stateParams.contactType;
                        }
                    }
                }).result.then(function (customer) {
                    if (customer != null) {
                        vm.employee = customer;
                    }
                });
            };

            //vm.getlocalDateTime = function (date) {
            //    if (date != null) {
            //        var localTime = moment.utc(date).toDate();
            //        return moment(localTime).format(vm.dateFormat);
            //    }
            //    else {
            //        return "";
            //    }
            //};

            //vm.getlocalTime = function (date) {
            //    if (date != null) {
            //        var localTime = moment.utc(date).toDate();
            //        return moment(localTime).format('HH:mm');
            //    }
            //    else {
            //        return "";
            //    }
            //};

            //$scope.onFocusChange = function ($event) {
            //    setTimeout(function () {
            //        $event.target.select();
            //    }, 200);
            //}

            vm.changeAmountandMinutes = function () {
                vm.invalidForm = false;
                angular.forEach(vm.employStaffOvertime.overtimes, function (elem, index) {
                    if (!(elem.overtimeMinutes == null || elem.overtimeMinutes == '') && (elem.amount == null || elem.amount == '')) {
                        vm.invalidForm = true;
                    }
                    //if (!(elem.amount == null || elem.amount == '') && (elem.overtimeMinutes == null || elem.overtimeMinutes == '')) {
                    //    vm.invalidForm = true;
                    //}
                });
            };

            vm.changeEmptyToNull = function () {
                angular.forEach(vm.employStaffOvertime.overtimes, function (elem, index) {
                    if (elem.overtimeMinutes == '') {
                        elem.overtimeMinutes = null;
                    }
                    if (elem.amount == '') {
                        elem.amount = null;
                    }
                });
            };

            vm.save = function () {
                vm.loading = true;
                vm.changeEmptyToNull();
                employeeOvertimeService.saveEmployeeOvertime(vm.employStaffOvertime).success(function (data) {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                }).finally(function () {
                    vm.loading = false;
                });
            };

            vm.getStaffOvertime = function () {
                vm.loading = true;
                vm.filters.startDate = moment(vm.filters.monthYear).startOf('month');
                vm.filters.endDate = moment(vm.filters.monthYear).endOf('month').endOf('day');
                vm.filters.employeeId = vm.employee.id;
                employeeOvertimeService.getStaffOvertime(vm.filters).success(function (data) {
                    vm.employStaffOvertime = data;
                    vm.changeAmountandMinutes();
                }).finally(function () {
                    vm.loading = false;
                });
            };
        }
    ]);
})();;
