            vm.getDriverMinutes = function (row) {
                if (!row ||
                    !row.outDetail_DateTime ||
                    !row.inDetail_DateTime) {
                    return '';
                }

                var outTime = moment(row.outDetail_DateTime);
                var inTime = moment(row.inDetail_DateTime);

                var minutes = inTime.diff(outTime, 'minutes');

                return minutes >= 0 ? minutes : '';
            };

