(function () {
    appModule.controller('tenant.views.pos.order.viewModal', [
        '$scope', '$uibModalInstance', 'abp.services.app.product', 'productId',
        function ($scope, $uibModalInstance, productService, productId) {
            var vm = this;
            vm.loading = false;
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };
            vm.getProductsList = function () {
                localStorage.setItem("productlist", JSON.stringify(vm.product));
            };
            function init() {
                vm.loading = true;
                productService.getProductForView({
                    id: productId
                }).success(function (result) {
                    vm.product = result;
                    vm.loading = false;
                    vm.getProductsList();
                });
            }
            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.pos.product.createOrEditModal', [
        '$scope', '$uibModalInstance', 'abp.services.app.product', 'abp.services.app.unitOfMeasure', 'productId',
        function ($scope, $uibModalInstance, productService, unitOfMeasureService, productId) {

            var vm = this;
            vm.saving = false;
            vm.loading = false;

            vm.isposEnabled = abp.features.isEnabled("POS");
            vm.product = {
                productUnitOfMeasures: []
            };
            var productPrices = [];

            vm.save = function () {
                vm.saving = true;

                var arr = Array.from(new Set(vm.product.productUnitOfMeasures.map(x => x.unitOfMeasureId)));

                if (arr.length !== vm.product.productUnitOfMeasures.length) {
                    abp.message.info('Duplication in Unit Of Measure Id');
                    vm.saving = false;
                    return;
                }

                productService.createOrUpdateProduct({
                    product: vm.product
                }).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            function unitOfMeasuresLineObject() {
                var line = new Object();
                line.productId = null;
                line.unitOfMeasureId = null;
                line.isDefault = false;
                line.productPrices = angular.copy(productPrices);
                return line;

            }

            //Add Row
            vm.addRow = function (line) {
                line = unitOfMeasuresLineObject();
                vm.product.productUnitOfMeasures.push(line);
                $('#unitOfMeasureIdItemsSelectionCombobox').selectpicker('refresh');

            };

            vm.isDefaultChanged = function (val) {
                if (!val.isDefault)
                    return;
                var ObjectIndex = vm.product.productUnitOfMeasures.indexOf(val);
                vm.product.productUnitOfMeasures.forEach(function (valueNested, index) {
                    if (ObjectIndex !== index)
                        valueNested.isDefault = false;
                });
            };

            //Remove row
            vm.removeRow = function (obj) {
                var index = vm.product.productUnitOfMeasures.indexOf(obj);
                if (index > -1 && vm.product.productUnitOfMeasures.length > 1) {
                    vm.product.productUnitOfMeasures.splice(index, 1);
                }
            };

            unitOfMeasureIdItems = function () {
                unitOfMeasureService.getUnitOfMeasures().success(function (result) {
                    vm.unitOfMeasureIdItems = result.items;
                    angular.forEach(vm.unitOfMeasureIdItems, function (value) {
                        value.title = value.name + " (" + value.nameLang + ")";
                    });
                });
            };
            vm.unitOfMeasureChange = function (index) {

                //row.unitOfMeasureId = row.unitOfMeasure.id;

                setTimeout(function () {
                    $('#unitOfMeasureIdItemsSelectionCombobox' + index).selectpicker('refresh');
                }, 0);
            };
            vm.getProductsList = function () {
                localStorage.setItem("productlist", JSON.stringify(vm.product));
            };
            function init() {
                vm.loading = true;
                unitOfMeasureIdItems();
                productService.getProductForEdit({
                    id: productId
                }).success(function (result) {
                    vm.product = result;
                    console.log(vm.product);
                    productPrices = angular.copy(result.productUnitOfMeasures[0].productPrices);
                    productPrices.forEach(function (value) {
                        value.id = 0;
                        value.price = 0;
                    });
                    setTimeout(function () {
                        $('#unitOfMeasureIdItemsSelectionCombobox').selectpicker('refresh');
                    }, 0);
                    vm.loading = false;
                    vm.getProductsList();
                });
            }
            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.pos.product.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.product',
        function ($scope, $uibModal, uiGridConstants, productService) {

            var vm = this;

            vm.isposEnabled = abp.features.isEnabled("POS");

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.loading = false;

            vm.permissions = {
                create: true
                //create: abp.auth.hasPermission('Pages.Tenant.Locations.Addnew'),
                //edit: abp.auth.hasPermission('Pages.Tenant.Locations.Edit'),
                //'delete': abp.auth.hasPermission('Pages.Tenant.Locations.Delete')
            };
            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                appScopeProvider: vm,
                enableSorting: false,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        width: 120,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-click="grid.appScope.viewProduct(row.entity)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-click="grid.appScope.editProduct(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-click="grid.appScope.deleteProduct(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Code'),
                        field: 'code'
                    },

                    {
                        name: app.localize('ProductName'),
                        field: 'name'
                    },
                    {
                        name: app.localize('ProductNameLang'),
                        field: 'nameLang'
                    },
                    ],
                data: []
            };
            vm.getProducts = function () {
                vm.loading = true;
                productService.getProducts().success(function (data) {
                    vm.gridOptions.data = data.items;
                }).finally(function () {
                    vm.loading = false;
                    vm.getProductsList();
                    });
            };

            vm.getProductsList = function ()
            {
                localStorage.setItem("productlist", JSON.stringify(vm.gridOptions.data));
            };
            function openCreateOrEditProductModal(Id) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/pos/product/createOrEditModal.cshtml',
                    controller: 'tenant.views.pos.product.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        productId: function () {
                            return Id;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getProducts();
                });
            }

            vm.createProduct = function () {
                openCreateOrEditProductModal(null);
            };
            vm.editProduct = function (Product) {
                openCreateOrEditProductModal(Product.id);
            };

            vm.viewProduct = function (Product) {
                openViewModal(Product.id);
            };

            function openViewModal(id) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/pos/product/viewModal.cshtml',
                    controller: 'tenant.views.pos.product.viewModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        productId: function () {
                            return id;
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getProducts();
                });
            }
            
            vm.deleteProduct = function (Product) {
                //debugger;
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', Product.Id),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            productService.deleteProduct({
                                Id: Product.id
                            }).success(function () {
                                vm.getProducts();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };
            vm.getProducts();
        }
    ]);
})();;
