                        field: 'cost',
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.utilities.round(row.entity.stockValue,2)}}</div>' +
                            '</div>'
