(function () {

    appModule.controller('tenant.views.stock.requisitions.printModal',
        ['abp.services.app.commonLookup', 'utilities', 'appSession', 'abp.services.app.grn', '$scope', '$stateParams', 'abp.services.app.purchaseOrder', 'abp.services.app.itemRequisition',
           
            function (commonLookupService,
                utilities, appSession, grnService, $scope, $stateParams, purchaseOrdersService, itemRequisitionService) {
                var vm = this;
                vm.tenantName = appSession.tenant.name;
                vm.tenancyName = appSession.tenant.tenancyName;
                var requisitionId = 0;
                vm.currency = abp.setting.get("App.General.CurrencyCode");
                vm.currencyName = abp.setting.get("App.General.CurrencyName");

                vm.dateFormat = abp.setting.get("App.General.DateFormat");
                vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
                //vm.userName = appSession.user.name;
                vm.userName = '';
                vm.fileName = vm.tenancyName.toLowerCase() + '-' + 'header.png';
                vm.isTaxInclusive = utilities.parseBoolean(abp.setting.get("App.General.TaxInclusive"));
                vm.taxPercent = parseFloat(abp.setting.get("App.General.TaxPercentage"));
                var recordsPerPage = 10;
                //if pop-up print
                if ($scope.$parent != null) {
                    if (!isNaN($scope.$parent.vmMain.requisitionId))
                        requisitionId = $scope.$parent.vmMain.requisitionId;
                }


                vm.currencyAndRounding = function (value) {
                    if (value == null) return null;

                    return value.toLocaleString('en', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
                };


                //if through url print
                if (requisitionId == 0 && !isNaN($stateParams.query)) {
                    requisitionId = $stateParams.query;
                }

                $scope.$on('$viewContentLoaded', function () {
                    App.initAjax();
                });
                vm.rounding = function (value) {
                    return utilities.round(value, 2);
                };
                vm.getlocalDateTime = function (date, format) {
                    if (date != null) {
                        if (format == null) format = vm.dateFormat;

                        var localTime = moment.utc(date).toDate();
                        return moment(localTime).format(format);
                    }
                    else {
                        return "";
                    }
                };

                vm.getUserName = function (userId) {
                    commonLookupService.getUser({
                        id: userId
                    }).success(function (result) {
                        vm.userName = result.name + ' ' + result.surname;
                    });
                };
                vm.getAllTotalAmount = function () {
                    var amount = 0;
                    angular.forEach(vm.itemRequisition.voucherLines, function (line) {
                        line.product.unitOfMeasure = line.unitOfMeasure;
                        line.product.unitOfMeasureId = line.unitOfMeasureId;
                        if (line.product.price)
                            amount += line.product.price;
                    });
                    return amount;
                };

                vm.getlocalDateTimeForEngAr = function (date, format) {
                    if (date != null) {
                        if (format == null) format = vm.dateFormat;

                        var localTime = moment.utc(date).toDate();
                        return moment(localTime).format(format);
                    }
                    else {
                        return "";
                    }
                };
           

                function customizePagesData() {
                    var customArray = [];
                    customArray = vm.grn.voucherLines.filter(v => !v.hidden);
                    var arrayLength = customArray.length;
                    var noOfPages = arrayLength / recordsPerPage;
                    vm.pagesData = [];
                    for (var i = 0; i < noOfPages; i++) {
                        var subArray = [];
                        var start = i * recordsPerPage;
                        var end = start + recordsPerPage;
                        subArray = customArray.slice(start, end);
                        vm.pagesData.push({
                            pageNo: i + 1,
                            voucherLinesdataToIterate: subArray
                        })
                    }
                }



                vm.calculateQtyAlreadyReceived = function (VoucherLine, value = 0) {
                    vm.loading = true;
                    vm.qtyAlreadyReceived = [];
                    grnService.getGrnByParentVoucherId({ id: vm.grn.parentVoucherId }).success(function (result) {
                        vm.qtyAlreadyReceived = result;
                        vm.qtyAlreadyReceived.forEach(function (voucher) {
                            voucher.voucherLines.forEach(function (voucherline) {
                                if (voucherline.productId === VoucherLine.productId) {
                                    if (!VoucherLine.quantityAlreadyReceived)
                                        VoucherLine.quantityAlreadyReceived = 0;
                                    VoucherLine.quantityAlreadyReceived += voucherline.quantity;
                                };
                            });
                        });

                    }).finally(function () {
                        vm.loading = false;
                    });
                };

                vm.calculateQtyOrdered = function (VoucherLine, value = 0) {
                    vm.loading = true;
                    vm.qtyOrdered = [];
                    purchaseOrdersService.getPOById(vm.grn.parentVoucherId).success(function (result) {
                        vm.parentVoucher = result;
                    }).finally(function () {
                        VoucherLine.quantityOrdered = 0;
                        vm.parentVoucher.voucherLines.forEach(function (voucherline) {
                            if (voucherline.productId === VoucherLine.productId) {
                                VoucherLine.quantityOrdered += voucherline.quantity;
                            };
                        });
                        if (value === 0)
                            vm.loading = false;
                    });

                }
                vm.totalAmount = 0;
                function init() {
                    {
                        vm.loading = true;
                        itemRequisitionService.getItemRequisitionForEdit({
                            id: requisitionId
                        }).success(function (result) {
                            if (result) {
                                vm.itemRequisition = result;
                               
                                if (vm.itemRequisition)
                                vm.getUserName(vm.itemRequisition.creatorUserId);
                                if (requisitionId > 0)
                                    vm.itemRequisition.job.jobType = vm.itemRequisition.jobType;

                                angular.forEach(result.voucherLines, function (line) {
                                    line.product.unitOfMeasure = line.unitOfMeasure;
                                    line.product.unitOfMeasureId = line.unitOfMeasureId;
                                    if(line.product.price)
                                       vm.totalAmount += line.product.price;
                                });
                            }
                        });
                        vm.loading = false;
                       
                    }
                }

                init();

                
            }
        ])
})();;
(function () {
    appModule.controller('tenant.views.stock.requisitions.report', ['$scope', 'abp.services.app.itemRequisition', '$stateParams', 'abp.services.app.commonLookup',
        function ($scope, itemRequisitionService, $stateParams, commonLookupService) {

            var vm = this;


            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';

            vm.filters = null;

            if ($scope.$parent != null) {
                if ($scope.$parent.vmMain != null)
                    vm.filters = $scope.$parent.vmMain.filters;
            }

            if (vm.filters == null)
                vm.filters = $stateParams.filters;
            if (vm.filters.voucherNo) {
                vm.filters.jobId = null;
                vm.filters.fromDate = null;
                vm.filters.toDate = null;
            }

            vm.getlocalDate = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

        
            function init() {

            vm.loading = true;

            if (vm.filters.locationId)
                getLocations();

                itemRequisitionService.getReport(vm.filters).success(function (data) {
                   // alert(JSON.stringify(data));
                vm.reportData = data;

            }).finally(function () {
                vm.loading = false;
            });
        };
            init();
        }]);
})();;
(function () {

    appModule.controller('tenant.views.stock.requisitions.printPreview', [
        '$scope', 'appSession', 'requisitionId', '$uibModalInstance',
        function ($scope, appSession, requisitionId, $uibModalInstance) {

            var vm = this;
            vm.requisitionId = requisitionId;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.getTemplateUrl = function () {
                var template = abp.features.getValue('CRS.Vouchers.GRNs.PrintTemplate').toLowerCase();
                if (template == undefined || template == '')
                    template = 'standard';

                if (template == 'custom')
                    return '~/App/tenant/views/stock/requisitions/printTemplates/tenants/' + appSession.tenant.tenancyName.toLowerCase() + '.cshtml';
                else if (template == 'englisharabic')
                    return '~/App/tenant/views/stock/requisitions/printTemplates/englisharabic.cshtml';
                else
                    return '~/App/tenant/views/stock/requisitions/printTemplates/' + template + '.cshtml';
            };
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.stock.stockTransfer.createOrEditModal', [
        '$uibModalInstance', 'abp.services.app.item', 'options', 'abp.services.app.stockTransfer', 'abp.services.app.commonLookup', 'utilities', 'appSession',
        function ($uibModalInstance, itemAppService, options, stockTransferService, commonLookupService, utilities, appSession) {

            var vm = this;
            vm.loading = false;

            vm.autoCalculateAmountInWords = abp.setting.get("App.General.AutoCalculateAmountInWords");

            vm.userBranch = "";
            vm.branchTo = "";

            vm.stockTransfer = {
                voucherLines: []
            };

            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.filters = {};

            function stockTransferObject() {
                var line = new Object();
                line.productId = null;
                line.quantity = null;
                //line.locationId = null;
                vm.getBranchTo();
                return line;
            }

            vm.clearModelData = function () {
                vm.models = null;
                vm.item.model = null;
                vm.modelId = null;
            };

            vm.productSelected = function (line) {
                line.productId = line.product.id;
                line.unitOfMeasureId = line.product.unitOfMeasureId;
            };

            //Add row
            vm.addRow = function (line) {
                if (line == undefined)
                    item = stockTransferObject();

                vm.stockTransfer.voucherLines.push(item);
            };

            //Remove row
            vm.removeRow = function (obj) {
                var index = vm.stockTransfer.voucherLines.indexOf(obj);
                vm.stockTransfer.voucherLines.splice(index, 1);

            };

            vm.searchItems = function ($select) {
                if ($select.search == "") { vm.items = null; return null; }
                return itemAppService.searchItems({ name: $select.search }).then(function (response) {
                    vm.items = response.data.items;
                });
            };

            function getLocations() {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    vm.userBranch = vm.locations.find(e => e.id == appSession.user.locationId).name;
                    vm.locations = vm.locations.filter(e => e.id != appSession.user.locationId);
                });
            }
            vm.getBranchTo = function () {
                commonLookupService.getLocations({}).success(function (data) {
                    vm.locations = data.items;
                    vm.locations = vm.locations.filter(e => e.id != appSession.user.locationId);
                    var selectedBranch = vm.locations.find(e => e.id == vm.branchTo);

                    // ✅ if branch selected, apply it to all rows
                    if (selectedBranch && vm.stockTransfer && vm.stockTransfer.voucherLines) {
                        vm.stockTransfer.voucherLines.forEach(function (line) {
                            line.locationId = selectedBranch.id;
                        });
                    }
                });
            };


            vm.save = function () {

                if (!appSession.user.locationId)
                    abp.message.info("Attach branch with user");

                vm.loading = true;

                if ([...new Set(vm.stockTransfer.voucherLines.map(e => e.productId))].length != vm.stockTransfer.voucherLines.length) {
                    abp.message.info("Cannot save items are duplicated!");
                    vm.loading = false;
                    return;
                }

                if (vm.stockTransfer.voucherLines.some(e => e.quantity > e.product.quantity)) {
                    abp.message.info("Cannot save transfer quantity is greater than available quantity!");
                    vm.loading = false;
                    return;
                }

                vm.stockTransfer.voucherLines.forEach(e => {
                    e.debit = e.quantity * e.product.cost;
                    e.credit = 0;
                });

                var voucherLinesCopy = JSON.parse(JSON.stringify(vm.stockTransfer.voucherLines));

                voucherLinesCopy.forEach((row) => {
                    vm.stockTransfer.voucherLines.push({
                        productId: row.productId,
                        product: row.product,
                        quantity: row.quantity,
                        debit: 0,
                        credit: row.debit,
                        locationId: appSession.user.locationId,
                        hidden:true
                    });
                });



                stockTransferService.createOrUpdateStockTransfer({ stockTransfer: vm.stockTransfer })
                    .success(function (result) {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                        $uibModalInstance.close();
                    }).error(function (result) {
                        abp.notify.error(app.localize('RecordNotSaved.'));
                    }).finally(function () {
                        vm.loading = false;
                    });
            };

            init();
            getLocations();

            function init() {
                vm.loading = true;
                stockTransferService.getStockTransferForEdit({
                    id: options.id
                }).success(function (result) {
                    if (result) {
                        vm.stockTransfer = result;
                        vm.stockTransfer.date = result.date;
                        angular.forEach(result.voucherLines, function (line) {
                            line.product.unitOfMeasure = line.unitOfMeasure;
                            line.product.unitOfMeasureId = line.unitOfMeasureId;
                        });
                    }
                })
                    .finally(function () {
                        vm.loading = false;
                    });
            }
        }

    ]);
})();;
(function () {

    appModule.controller('tenant.views.stock.stockTransfer.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.stockTransfer', 
        function ($scope, $uibModal, uiGridConstants, stockTransferService ) {

            var vm = this;

            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateFormat = abp.setting.get("App.General.DateFormat");

            vm.loading = false;

            vm.filters = {
                enableDateRange: true,
                fromDate: null,
                toDate: null,
                voucherNo: null,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
            };

            vm.dateRangeModelChanged = function () {
                vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment().add(-29, 'days').startOf('day');
                vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            function initDate() {
                vm.dateRangeModel = {
                    startDate: moment().add(-29, 'days').startOf('day'),
                    endDate: moment().endOf('day')
                };
            };

            vm.dateRangeCheck = function () {

                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format(abp.setting.get("App.General.DateFormat"))).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                }
            };

            vm.getlocalDateTime = function (date) {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
         
            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                paginationPageSize: app.consts.grid.defaultPageSize,
                useExternalPagination: true,
                appScopeProvider: vm,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: 120,
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a ng-click="grid.appScope.openViewModal(row.entity.id)">' + app.localize('View') + '</a></li>' +
                            '      <li><a ng-if="row.entity.job.status == 1" ng-click="grid.appScope.openCreateOrEditModel(row.entity.id)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a ng-if="row.entity.job.status == 1" ng-click="grid.appScope.deleteItem(row.entity)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('StockTransfer') + " " + app.localize('No'),
                        field: 'voucherNo',
                        minWidth: 100
                    },
                    {
                        name: app.localize('Date'),
                        field: 'date',
                        minWidth: 100,
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.date)}}</div>' +
                            '</div>'
                    },
                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = null;
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }
                        vm.getStockTransfers();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getStockTransfers();
                    });
                },
                data: []
            };

            vm.openCreateOrEditModel = function (stockTransferId) {

                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/stock/stockTransfer/createOrEditModal.cshtml',
                    controller: 'tenant.views.stock.stockTransfer.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        options: function () {
                            return { id: stockTransferId };
                        }               

                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getStockTransfers();
                });
            };

            vm.openViewModal = function (stockTransferId) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/stock/stockTransfer/viewModal.cshtml',
                    controller: 'tenant.views.stock.stockTransfer.createOrEditModal as vm',
                    backdrop: 'static',
                    size: 'lg',
                    resolve: {
                        options: function () {
                            return { id: stockTransferId };
                        }

                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getStockTransfers();
                });
            };

           
            vm.deleteItem = function (item) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', item.name),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            vm.loading = true;
                            itemIssueService.deleteItemIssue({ id: item.id })
                                .success(function (result) {
                                    abp.notify.info(app.localize('DeletedSuccessfully'));
                                    vm.getItemIssues();
                                }).error(function (result) {
                                    abp.notify.error(app.localize('Error'));
                                }).finally(function () {
                                    vm.loading = false;
                                });
                        }
                    }
                );
            };

            vm.getStockTransfers = function () {
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate !== null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate !== null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
                }
                vm.loading = true;
                stockTransferService.getStockTransfers(vm.filters)
                    .success(function (data) {
                        if (vm.dateRangeModel.startDate == null && vm.dateRangeModel.endDate == null)
                            initDate();

                        vm.gridOptions.totalItems = data.totalCount;
                        vm.gridOptions.data = data.items;
                    }).finally(function () {
                        vm.loading = false;
                    });
            };


            function init() {
                initDate();
                vm.getStockTransfers();
            }

            init();

        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.tfms.attachDetails.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.uaeFine', 'abp.services.app.vehicle', 'abp.services.app.directory',
        function ($scope, $uibModal, uiGridConstants, finesService, vehicleService, directoryService) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.isEnableFMS = abp.features.isEnabled("TFMS");
            vm.isEnableCRS = abp.features.isEnabled("CRS");
            vm.isEnableUpdateFines = abp.auth.hasPermission('Pages.TFMS.Update.Fines');
            vm.isEnableEmail = abp.auth.hasPermission('Pages.TFMS.Email.Fines');
            vm.finesUpdateEmailDetail = abp.features.isEnabled("TFMS.Fines.Update.And.Email.Detail");

            vm.loading = false;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.customers = [];
            vm.selectedVehicle = null;
            vm.vehicleNo = [];
            vm.trafficFileId = [];
            vm.server = [];
            vm.plateNos = null;
            vm.selectedFinesCount = 0;
            vm.isDisableEmailbtn = true;

            vm.filters = {
                enableDateRange: true,
                name: "",
                agreementNo: null,
                vehicleId: null,
                plateTagNo: null,
                customerId: null,
                fromDate: null,
                fromTime: null,
                toDate: null,
                toTime: null,
                amount: null,
                trafficFileId: null,
                vehicleNo: null,
                enableWithAgreement: false,
                enableWithOutAgreement: false,
                enableInvoiced: false,
                enableIgnored: false,
                enableUnIgnored: false,
                enableUnInvoiced: false,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                finesWithFailedVehicleMappings: false,

                plateNo: [],
                durationType: 1,
                trafficFileIdEN: [],
                vehicleNoEN: [],
                server: null,
                vehicleNoArr: [],
                movementType: null,
                emailStatus: null
            };

            vm.dateRangeModel = {
                startDate: moment(moment().format('YYYY-MM-DD')).utc(),
                endDate: moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc(),
            };

            vm.dateRangeModelChanged = function () {
                vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            vm.dateRangeCheck = function () {
                if (vm.filters.enableDateRange) {
                    vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                    vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment().endOf('day');
                    vm.filters.fromTime = moment(new Date()).startOf('day').utc();
                    vm.filters.toTime = moment(new Date()).endOf('day').utc();
                }
                if (!vm.filters.enableDateRange) {
                    vm.filters.fromDate = null;
                    vm.filters.toDate = null;
                    vm.filters.fromTime = null;
                    vm.filters.toTime = null;
                }
            };

            vm.movementType = [
                { type: "Agreement (Customer)", id: 1 },
                { type: "NRM (Staff)", id: 2 },
                { type: "Un-Identified", id: 3 }

            ];

            vm.emailStatus = [
                { name: "Yes", id: 1 },
                { name: "No", id: 0 }

            ];

            function getFiltersData() {
                finesService.getFiltersData().success(function (data) {
                    angular.forEach(data.trafficFileId, function (value, key) {
                        vm.trafficFileId.push({ name: value.name, id: value.id });
                    });
                    angular.forEach(data.server, function (value, key) {
                        vm.server.push({ name: value.name, id: value.name });
                    });
                });
            };


            vm.searchPlateNo = function ($select) {
                if ($select.search) {
                    vm.filters.name = $select.search;
                    return finesService.getSearchPlateNo(vm.filters).then(function (response) {
                        vm.plateNos = response.data.items;
                    });
                }
            };

            vm.searchCustomers = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                if (!$select.search) return null;
                return directoryService.search({ keyword: $select.search, contactType: 2, activeOnly: true }).then(function (response) {
                    vm.customers = response.data.items;
                });
            };

            vm.CurrencyFormate = function (amount) {
                if (amount == null) return null;
                return amount.toLocaleString('en');
            };

            vm.getFinesReport = function () {
                vm.loading = true;
                vm.filters.fromDate = moment(vm.filters.fromDate) !== null ? moment(new Date(vm.filters.fromDate._d.getFullYear(), vm.filters.fromDate._d.getMonth(), vm.filters.fromDate._d.getDate(), vm.filters.fromTime._d.getHours(), vm.filters.fromTime._d.getMinutes(), '00', '000')).utc() : moment(moment().format('YYYY-MM-DD HH:mm')).utc();
                vm.filters.toDate = moment(vm.filters.toDate) !== null ? moment(new Date(vm.filters.toDate._d.getFullYear(), vm.filters.toDate._d.getMonth(), vm.filters.toDate._d.getDate(), vm.filters.toTime._d.getHours(), vm.filters.toTime._d.getMinutes(), '59', '999')).utc() : moment(moment().format('YYYY-MM-DD HH:mm')).utc();
                if (vm.filters.fromDate > vm.filters.toDate) return;
                vm.filters.trafficFileIdArr = [];
                vm.filters.serverArr = [];
                vm.filters.vehicleNo = vm.filters.plateNo;
                if (vm.filters.trafficFileIdEN.length > 0) {
                    angular.forEach(vm.filters.trafficFileIdEN, function (value) {
                        vm.filters.trafficFileIdArr.push(value.name);
                    });
                }
                finesService.getFinesReportForReport(vm.filters).success(function (data) {
                    vm.fines = data;
                }).finally(function () {
                    vm.allfineReports = false;
                    vm.fineReportChecked();
                    vm.loading = false;
                    vm.isDisableEmailbtn = true;
                });
            };

            function getStatuses() {
                vm.statuses = [{ id: 1, name: 'With Agreement' }, { id: 2, name: 'Without Agreement' }];
            }

            vm.statusChanged = function () {

                if (vm.filters.status == 1) {
                    vm.filters.enableWithAgreement = true;
                    vm.filters.enableWithOutAgreement = false;

                }
                else if (vm.filters.status == 2) {
                    vm.filters.enableWithOutAgreement = true;
                    vm.filters.enableWithAgreement = false;
                }
                else {
                    vm.filters.enableWithAgreement = false;
                    vm.filters.enableWithOutAgreement = false;
                }
            };
            function getInvoiceStatuses() {
                vm.invoiceStatuses = [{ id: 1, name: 'Invoiced' }, { id: 2, name: 'Un-Invoiced' }];
            }

            function getFineStatuses() {
                vm.fineStatuses = [{ id: 1, name: 'Ignored' }, { id: 2, name: 'Un-Ignored' }];
            }

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getlocalDate = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.allFineReportsChecked = function () {
                angular.forEach(vm.fines, function (value, key) {
                    if (vm.allfineReports) {
                        value.selected = true;
                    } else {
                        value.selected = false;
                    }
                });
                vm.fineReportChecked();
            };

            vm.fineReportChecked = function () {
                vm.selectedFinesCount = 0;
                angular.forEach(vm.fines, function (value, key) {
                    if (value.selected) {
                        vm.selectedFinesCount++;
                    }
                });
            }

            function openAttachDetailModal(selectedFinesDetail) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/tfms/attachDetails/updateModal.cshtml',
                    controller: 'tenant.views.tfms.attachDetails.updateModal as vm',
                    backdrop: 'static',
                    size: 'xs',
                    resolve: {
                        SelectedFinesDetail: function () {
                            return selectedFinesDetail;
                        }
                    }
                });
                modalInstance.result.then(function () {
                    vm.getFinesReport();
                });
            }
            vm.isEmailSent = function (value) {
                if (value) {
                    return "Yes";
                } else {
                    return "No";
                }

            };
            vm.attachDetail = function () {
                var selectedFinesDetail = new Object();
                selectedFinesDetail.finesId = [];
                selectedFinesDetail.selectedCount = vm.selectedFinesCount;
                angular.forEach(vm.fines, function (value) {
                    if (value.selected) {
                        selectedFinesDetail.finesId.push(value.id);
                    }
                });
                openAttachDetailModal(selectedFinesDetail);
            };

            vm.emailFines = function () {
                if (!vm.isDisableEmailbtn && vm.isEnableEmail) {
                    vm.loading = true;
                    vm.filters.finesId = [];
                    angular.forEach(vm.fines, function (value) {
                        if (value.selected) {
                            vm.filters.finesId.push(value.id);
                        }
                    });

                    vm.filters.customerEmail = vm.fines.filter(f => f.selected)[0].movementContact.email;
                    vm.filters.customerType = vm.fines.filter(f => f.selected)[0].movementContact.contactType;

                    finesService.emailFines(vm.filters).success(function (data) {
                        abp.notify.success("Email Sent");
                    }).finally(function () {
                        vm.allfineReports = false;
                        vm.fineReportChecked();
                        vm.loading = false;
                        vm.getFinesReport();
                    });
                }
                
            };

            vm.isDisableEmailbtnChange = function () {
                if (vm.selectedFinesCount > 0 && vm.isEnableEmail && !(vm.fines === null || vm.fines === undefined)) {

                    angular.forEach(vm.fines, function (value) {
                        if (value.selected) {
                            if ((value.movementContact !== null && value.movementContact.email !== null)) {

                                vm.isDisableEmailbtn = false;
                                //check if different emails are selected
                                var duplicationEmail = vm.fines.filter(f => f.movementContact !== null && f.movementContact.email !== value.movementContact.email && f.selected);
                                if (duplicationEmail.length > 0) {
                                    vm.isDisableEmailbtn = true;
                                }
                            } else {
                                vm.isDisableEmailbtn = true;
                            }
                        }
                    });

                    //check if empty contact
                    var emptyContact = vm.fines.filter(f => (f.movementContact === null || f.movementContact.email === null || f.movementContact === undefined || f.movementContact.email === undefined) && f.selected);
                    if (emptyContact.length > 0) {
                        vm.isDisableEmailbtn = true;
                    }

                    //check if empty contactType are employee and staff
                    var customerContact = vm.fines.filter(f => (f.movementContact === null || f.movementContact.contactType === 2) && f.selected);
                    var staffContact = vm.fines.filter(f => (f.movementContact === null || f.movementContact.contactType === 1) && f.selected);
                    if (customerContact.length > 0 && staffContact.length > 0) {
                        vm.isDisableEmailbtn = true;
                    }

                } else {
                    vm.isDisableEmailbtn = true;
                }
            };

            vm.dateRangeCheck();
            vm.getFinesReport();
            getStatuses();
            getInvoiceStatuses();
            getFineStatuses();
            getFiltersData();

        }
    ]);
})();;
