(function () {
    appModule.controller('tenant.views.tfms.downloadFineDescription', [
        '$scope', 'abp.services.app.uaeFine', 'chromeExtDownloader',
        function ($scope, fineService, chromeExtDownloader) {

            var vm = this;
            vm.fines = [];
            vm.allSelected = false;
            vm.downloading = false;

            var isAbuDhabiFinesEnabled = abp.features.isEnabled("TFMS.Fines.AbuDhabiPolice");
            var isDubaiFinesEnabled = abp.features.isEnabled("TFMS.Fines.DubaiPolice");

            vm.isDownloading = false;
            vm.finesCount = 0;

            vm.init = function () {
                vm.loading = true;
                vm.processedFines = 0;
                vm.fines = [];
                vm.finesCount = 0;

                const newobj = { id: true }

                fineService.getFineNosForUpdateFineDescription(newobj)
                    .success(function (r) {
                        var filteredFines = r.items; //.filter(x => !x.authority.startsWith('INTEGRATED TRANSPORT CENTER'));
                        //filteredFines = filteredFines.filter(x => !x.authority.startsWith('Department of Transportation Abu Dhabi'));
                        vm.fines = filteredFines;

                        //vm.dubaiAuthorityFineAvailable = vm.fines.filter(x => x.authority.toUpperCase().indexOf("DUBAI") > -1).length > 0;
                        vm.loading = false;
                        vm.downloading = false;
                    });
            }

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm:ss';

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.selectedFines = [];
            vm.downloadFineDescription = function () {

                vm.downloading = true;

                vm.selectedFines = vm.fines.filter(x => x.selected);
                vm.finesCount = vm.selectedFines.length;

                if (vm.selectedFines) {
                    if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                        //fineDetails array will be filled and sent to MV3 extension
                        //extension will render the fines one by one and give status msgs to enable disbale the processing
                        //once all done downloading will send the succes status to stop processing and refresh the fines list

                        vm.downloadFineDescriptionOnly = true;
                        vm.fineDetails = vm.selectedFines;
                        chromeExtDownloader.initV3(vm, () => chromeExtDownloader.downloadFinesV3(vm));

                    }
                    else
                        chromeExtDownloader.downlaodFinesDescription(
                            vm.selectedFines,
                            `function reportFineStatus(msg) {
							var $scope = angular.element(document.querySelector('#appController')).scope();
							if (!msg.fineDetail) return;

							var fineDetail = $scope.vm.selectedFines.find(x => x.fineNo === msg.fineDetail.fineNo);
							fineDetail.progress = msg.progress;
							fineDetail.error = msg.error;
							fineDetail.status = msg.status;

							if (fineDetail.error) {
								fineDetail.isComplete = true;
								fineDetail.downloadClass = "badge-danger";
								$scope.vm.selectedFines.splice(fineDetail, 1);
							}
							else if (msg.isComplated) {
								fineDetail.isComplete = msg.isComplated;

								fineDetail.downloadClass = "badge-success";

								$scope.vm.fines.splice($scope.vm.fines.find(x => x.fineNo == msg.fineDetail.fineNo), 1);
								$scope.vm.selectedFines.splice(fineDetail, 1);
								console.log("remaining items",$scope.vm.selectedFines.length);
								$scope.vm.finesCount && $scope.vm.finesCount--;
							}

							if ($scope.vm.selectedFines.length == 0) {
								$scope.vm.downloading = false;
							}

							if (!$scope.$$phase) {
								$scope.$digest();
							}
						}`,
                            function error(e) {
                                abp.message.error(e.error);
                            }
                        );
                }
                else { vm.loading = false; vm.downloading = false; }

            };

            vm.selectedCount = function () { return vm.fines.filter(x => x.selected).length; };

            vm.selectAll = function () {
                if (vm.allSelected) {
                    if (vm.fines)
                        for (let i in vm.fines) {
                            vm.fines[i].selected = true;

                        }
                }
                else {
                    if (vm.fines)
                        for (let i in vm.fines) {
                            vm.fines[i].selected = false;
                        }
                }
            };


            var fineIds = [];
            vm.updateDuabiFinesDescription = function () {
                fineIds = [];
                vm.downloading = true;
                vm.processedFines = 0;

                let dubaiFines = vm.fines.filter(x => x.selected && x.authority.toUpperCase().indexOf("DUBAI") > -1);
                for (var i in dubaiFines) {
                    fineIds.push(dubaiFines[i].id);
                }

                console.log(dubaiFines.length);
                vm.finesCount = dubaiFines.length;

                vm.processedFines = 0;
                errorStr = "";
                totalBatch = Math.ceil(vm.finesCount / batchSize);
                var nextBatch = iterator(dubaiFines, batchSize);
                processBatchDP(1, nextBatch);
            };

            var batchSize = 5;
            var totalBatch = 0;
            var errorStr = "";
            vm.processedFines = 0;

            var iterator = function (list, n) {
                var current = 0,
                    l = list.length;
                return function () {
                    end = current + n;
                    var part = list.slice(current, end);
                    current = end < l ? end : 0;
                    let ids = [];
                    for (var i in part) {
                        ids.push(part[i].id);
                    }
                    return ids;
                };
            };

            function processBatchDP(currentBatch, nb) {
                let ids = nb();
                fineService.updateDuabiFinesDescription(ids)
                    .success(function (r) {
                        let e = r.items;

                        for (let i in e) {
                            errorStr += e[i] + '\n';
                        }

                        for (let i in ids) {
                            let ind = vm.fines.indexOf(vm.fines.find(x => x.id === ids[i]));
                            vm.fines.splice(ind, 1);
                        }

                        currentBatch++;
                        vm.processedFines += 5;

                        if (currentBatch > totalBatch) {
                            vm.downloading = false;

                            if (errorStr)
                                abp.message.error(errorStr);

                            init();
                            return;
                        }
                        else
                            processBatchDP(currentBatch, nb);
                    });
            }

            vm.init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.tfms.downloadFines', [
        '$scope', 'abp.services.app.trafficFile', 'chromeExtDownloader', 'abp.services.app.uaeFine',
        function ($scope, trafficFileAppService, chromeExtDownloader, uaeFineAppService) {

            var vm = this;

            var isAbuDhabiFinesEnabled = abp.features.isEnabled("TFMS.Fines.AbuDhabiPolice");
            vm.isDubaiFinesEnabled = abp.features.isEnabled("TFMS.Fines.DubaiPolice");
            var isQatarFinesEnabled = abp.features.isEnabled("TFMS.Fines.Qatar");
            vm.isDownloadConfiscationChargesEnabled = abp.features.isEnabled("TFMS.Fines.DownloadConfiscationCharges");
            vm.isEmailingThroughFinesReceiptEnabled = abp.features.isEnabled("TFMS.Fines.EmailingThroughFinesReceipt");

            //let tammAccountsSetting = []; //{userId:0 , uaePass:''}

            vm.trafficFiles = [];
            vm.selectedTrafficFiles = [];
            vm.selected = 'all';

            vm.isDownloading = false;

            function getTrafficFiles() {
                trafficFileAppService.getTrafficFiles().success(function (data) {

                    angular.forEach(data.items, function (value, key) {
                        if (
                            (value.state === 'Dubai' && vm.isDubaiFinesEnabled) ||
                            (value.state === 'Abu Dhabi' && isAbuDhabiFinesEnabled) ||
                            (value.state === 'Qatar' && isQatarFinesEnabled)
                        ) {
                            vm.trafficFiles.push(value);
                        }
                    });
                });
            }

            vm.downloadFines = function () {

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    chromeExtDownloader.initV3(vm, vm.downloadFinesV3);
                    return;
                }

                const trafficFiles = vm.selected === 'all' ? vm.trafficFiles : vm.selectedTrafficFiles;

                chromeExtDownloader.checkAndDownload(
                    function () {
                        vm.downloaderReq.trafficFileIds = null;
                        debugger;
                        vm.downloadingFines = true;
                        vm.downloaderReq.trafficFileIds = trafficFiles;
                        //const hasAbuDhabiFile = trafficFiles.find(x => x.state == 'Abu Dhabi');

                        ////if there is no uae pass configured for current user then use first one else use current user uae pass
                        //if (hasAbuDhabiFile && tammAccountsSetting.length) {
                        //    const tas = tammAccountsSetting.find(x => x.userId == abp.session.userId);
                        //    vm.downloaderReq.uaePass = tas ? tas.uaePass : tammAccountsSetting[0].uaePass;
                        //}
                        //else vm.downloaderReq.uaePass = null;

                        //for progress reporing on UI
                        vm.traffFilesDownloadingRes = [];
                        for (var i in trafficFiles) {
                            vm.traffFilesDownloadingRes.push({
                                isComplete: false,
                                status: '',
                                progress: 0,
                                error: '',
                                trafficFile: trafficFiles[i]
                            });
                        }

                        if (!$scope.$$phase)
                            $scope.$digest();

                        startDownloading();

                    },
                    function (content) {
                        abp.message.error(content, null, true);
                    });
            };

            vm.selectFilesOnly = function () {
                vm.selectedTrafficFiles = [];
                if (vm.selected == "onlyAbuDhabi") {
                    vm.selectedTrafficFiles = vm.trafficFiles.filter(x => x.state == 'Abu Dhabi');
                }
                else if (vm.selected == "onlyDubai") {
                    vm.selectedTrafficFiles = vm.trafficFiles.filter(x => x.state == 'Dubai');
                }
                else {
                    vm.selectedTrafficFiles = [];
                }
            }

            vm.downloadFinesV3 = function () {
                vm.downloadingResponse = [];
                vm.downloadingFines = true;

                let trafficFiles = vm.selected === 'all' ? vm.trafficFiles : vm.selectedTrafficFiles;
                vm.traffFilesDownloadingRes = [];

                for (var i in trafficFiles) {
                    vm.traffFilesDownloadingRes.push({
                        isComplete: false,
                        status: '',
                        progress: 0,
                        error: '',
                        trafficFile: trafficFiles[i]
                    });
                }

                vm.callbackOnComplete = function () {

                    if (vm.isDownloadConfiscationChargesEnabled) {
                        vm.downloadConfiscationCharges();
                    }

                    if (vm.processingEmailDetails && vm.isEmailingThroughFinesReceiptEnabled) {
                        vm.processFinesEmailDetails();
                    }
                };

                vm.reponseCallback = function (res) {
                    console.log('response from extension for progress.', res)
                };

                debugger;

                chromeExtDownloader.downloadFinesV3(vm, trafficFiles, false);

            };

            vm.showError = function (error) {
                var title = "FineDownloadingError";
                abp.message.error(
                    error, app.localize(title)
                );
            };

            // Fine Extension Code [Can copy and pase for other views]
            //=========================================================
            vm.downloaderReq = {
                tenantId: abp.session.tenantId,
                trafficFileIds: []
            };

            function startDownloading() {
                chromeExtDownloader.downloadFines(
                    vm.downloaderReq,
                    `function processCaptcha(msg) {
                        var $scope = angular.element(document.querySelectorAll('[ng-controller]')[1]).scope();
                        var trafficFile = $scope.vm.traffFilesDownloadingRes.find(x => x.trafficFile.fileId === msg.trafficFile.fileId && (msg.state.indexOf('Qatar') > -1 || msg.state.indexOf('Abu') > -1));
                        trafficFile.captchaSrc = msg.captcha;
                        trafficFile.captchaTxt = '';

                        if (!$scope.$$phase) {
                            $scope.$digest();
                        }
                    }

                    function reportFineStatus(msg) {
                        if (msg.scrapingInfo) {
                            console.error(JSON.stringify(msg.scrapingInfo.scrapingErrors));
                        }
                        var $scope = angular.element(document.querySelectorAll('[ng-controller]')[1]).scope();
                        var trafficFile = $scope.vm.traffFilesDownloadingRes.find(x => x.trafficFile.fileId === msg.trafficFile.fileId);
                        trafficFile.progress = msg.progress;
                        trafficFile.error = !trafficFile.error ? msg.error : trafficFile.error;

                        if(msg.status && msg.status.toUpperCase().indexOf('ACCEPT LOGIN FROM MOBILE APP') > -1){
                            trafficFile.showTammLoginImg = true;
                            trafficFile.status = 'Check Mobile...'
                        }
                        else{
                             trafficFile.status = msg.status;
                             trafficFile.showTammLoginImg = false;
                            }

                        if (trafficFile.error)
                            trafficFile.isComplete = true;
                        else
                            trafficFile.isComplete = msg.isComplated;

                        const allDone = $scope.vm.traffFilesDownloadingRes.filter(x=> x.isComplete == true).length == $scope.vm.traffFilesDownloadingRes.length;

                        if (allDone) {
                            $scope.vm.downloadingFines = false;

                            if ($scope.vm.isDownloadConfiscationChargesEnabled) {
                      
                                $scope.vm.downloadConfiscationCharges();
                            }

                            if (!$scope.vm.processingEmailDetails && $scope.vm.isEmailingThroughFinesReceiptEnabled) {
                                $scope.vm.processFinesEmailDetails();
                            }
                        }

                        if (!$scope.$$phase) {
                            $scope.$digest();
                        }
                    }`,
                    function error(e) {
                        abp.message.error(e.error);
                    });

            }

            vm.sendCaptcha = function (row) {

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    const captcahRequest = {
                        trafficFile: { id: row.trafficFile.id, fileId: row.trafficFile.fileId, server: row.trafficFile.state },
                        account: null,
                        tenantId: abp.session.tenantId,
                        captcahSelector: null,
                        buttonSelector: null,
                        captchaText: row.captchaTxt,
                        capthaTabId: row.capthaTabId
                    };

                    if (row.trafficFile.state == 'Qatar')
                    {
                        captcahRequest.buttonSelector = '#frmCpy button';
                        captcahRequest.captcahSelector = '#captchaResponseCompany';
                    }
                    else {
                        alert('captcah implementation is only for Qatar');
                        throw Error('captcah implementation is only for Qatar');
                    }

                    chromeExtDownloader.sendCaptchaMv3(captcahRequest);
                }
                else
                    chromeExtDownloader.sendCaptcha(row);
            };

            vm.focusWindow = function (r) {
                chromeExtDownloader.focusWindow({
                    type: 'fine',
                    trafficFileId: r.trafficFile.fileId
                });
            };

            //=========================================================

            vm.cancelAll = function () {
                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    chromeExtDownloader.downloadFinesV3(vm, (vm.selected === 'all' ? vm.trafficFiles : vm.selectedTrafficFiles), true);
                    return;
                }

                chromeExtDownloader.closeAllFinesTabs();
            };

            async function init() {
                getTrafficFiles();

                //if (abp.setting.get('App.General.Fine.DownloadingAuthorityType') == '1') {
                //    //Tamm based fines downloading enabled

                //    try {
                //        tammAccountsSetting = JSON.parse((await abp.services.app.tenantSettings.getAdvanceSetting({ token: 'App.General.Fine.UserUaePasses' })).value);
                //    } catch (e) {

                //    }
                //}
            }

            var lastIndex = -1;
            var toIndex = -1;
            vm.downloadConfiscationCharges = function () {
                debugger;

                if (vm.downloadingConfiscationFines || vm.traffFilesDownloadingRes.length != vm.traffFilesDownloadingRes.filter(x => x.isComplete || x.error).length)
                    return;

                vm.downloadingConfiscationFines = true;
                uaeFineAppService.getFinesForConfiscationDownloading()
                    .success(r => {
                        if (r.length > 0) {
                            vm.downloadingFines = true;

                            function downloadCCFQueue() {
                                let promisesArr = [];
                                toIndex = lastIndex + 5;
                                if (toIndex >= r.length)
                                    toIndex = r.length - 1;

                                for (var i = lastIndex + 1; i <= toIndex; i++) {
                                    promisesArr.push(new Promise((resolve, reject) => {
                                        uaeFineAppService.downloadConfiscationCharges({ id: [r[i].id] })
                                            .then(r => {
                                                if (r.items) {
                                                    reject(r);
                                                }
                                                else {
                                                    resolve();
                                                }
                                            });
                                    }));
                                }

                                lastIndex = toIndex;

                                Promise.all(promisesArr)
                                    .then(result => {
                                        if (lastIndex == r.length - 1) {
                                            vm.downloadingFines = false;
                                            vm.downloadingConfiscationFines = false;
                                            lastIndex = -1;
                                            toIndex = -1;

                                            if (!$scope.$$phase) {
                                                $scope.$digest();
                                            }
                                        }
                                        else {
                                            downloadCCFQueue();
                                        }
                                    })
                                    .catch(e => {
                                        console.log(e);
                                        abp.message.error(JSON.stringify(e));
                                        vm.downloadingFines = false;
                                        vm.downloadingConfiscationFines = false;
                                        lastIndex = -1;
                                        toIndex = -1;

                                        if (!$scope.$$phase) {
                                            $scope.$digest();
                                        }

                                    });
                            }

                            if (!$scope.$$phase) {
                                $scope.$digest();
                            }

                            downloadCCFQueue();
                        }
                        else {
                            vm.downloadingFines = false;
                            vm.downloadingConfiscationFines = false;
                            vm.processingEmailDetails = false;

                            if (!$scope.$$phase) {
                                $scope.$digest();
                            }
                        }
                    })
                    .catch(e => {
                        debugger;
                        vm.downloadingFines = false;
                        vm.downloadingConfiscationFines = false;
                        vm.processingEmailDetails = false;

                        if (!$scope.$$phase) {
                            $scope.$digest();
                        }

                        abp.message.error(e)
                    });
            };

            vm.processFinesEmailDetails = function () {
                vm.processingEmailDetails = true;

                uaeFineAppService.processEmailDetailsForEmailPendingFines({ id: '2022-10-01' })
                    .success(r => {
                        vm.processingEmailDetails = false;
                    })
                    .catch(e => {
                        vm.processingEmailDetails = false;
                        abp.message.error(e);
                    });
            };

            init();
        }
    ]);
})();;
(function () {
    appModule.controller('tenant.views.tfms.downloadOmanFines', [
        '$scope', 'abp.services.app.trafficFile', 'chromeExtDownloader',
        function ($scope, trafficFileAppService, chromeExtDownloader) {

            var vm = this;

            vm.trafficFiles = [];
            vm.selectedTrafficFiles = [];
            vm.selected = 'selected';

            vm.isDownloading = false;
            vm.isLatestVersion = false;

            function getTrafficFiles() {
                trafficFileAppService.getOmanTrafficFiles()
                    .success(function (data) {
                        vm.trafficFiles = data.items;
                    });
            }

            vm.downloadFinesV3 = function () {
                vm.downloadingResponse = [];
                vm.downloadingFines = true;

                let trafficFiles = vm.selected === 'all' ? vm.trafficFiles : vm.selectedTrafficFiles;
                vm.traffFilesDownloadingRes = [];

                for (var i in trafficFiles) {
                    vm.traffFilesDownloadingRes.push({
                        isComplete: false,
                        status: '',
                        progress: 0,
                        error: '',
                        trafficFile: trafficFiles[i]
                    });
                }

                vm.callbackOnComplete = function () {
                    if (vm.isDownloadConfiscationChargesEnabled && vm.isDownloadConfiscationChargesEnabled) {
                        vm.downloadConfiscationCharges();
                    }

                    if (vm.processingEmailDetails && vm.isEmailingThroughFinesReceiptEnabled) {
                        vm.processFinesEmailDetails();
                    }
                };

                vm.reponseCallback = function (res) { //reponse received from extension to show progress
                    //{fromDate: 'date', downloadedCount: int, tollsCountOnSite: int, isProcessing: false}; --response template

                };

                debugger;

                chromeExtDownloader.downloadFinesV3(vm, trafficFiles, false);

            };

            vm.downloadFines = function () {

                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    chromeExtDownloader.initV3(vm, vm.downloadFinesV3);
                    return;
                }

                vm.isLatestVersion = chromeExtDownloader.isLatestVersion();

                var trafficFiles = vm.selected === 'all' ? vm.trafficFiles : vm.selectedTrafficFiles;

                chromeExtDownloader.checkAndDownload(
                    function () {
                        vm.downloaderReq.trafficFileIds = null;

                        vm.downloadingFines = true;
                        vm.downloaderReq.trafficFileIds = trafficFiles;

                        //for progress reporing on UI
                        vm.traffFilesDownloadingRes = [];
                        for (var i in trafficFiles) {
                            vm.traffFilesDownloadingRes.push({
                                isComplete: false,
                                status: '',
                                progress: 0,
                                error: '',
                                trafficFile: trafficFiles[i],
                            });
                        }

                        if (!$scope.$$phase)
                            $scope.$digest();

                        startDownloading();

                    },
                    function (content) {
                        abp.message.error(content, null, true);
                    });
            };

            vm.showError = function (error) {
                var title = "FineDownloadingError";
                abp.message.error(
                    error, app.localize(title)
                );
            };

            // Fine Extension Code [Can copy and pase for other views]
            //=========================================================
            vm.downloaderReq = {
                tenantId: abp.session.tenantId,
                trafficFileIds: []
            };

            function startDownloading() {
                chromeExtDownloader.downloadFines(
                    vm.downloaderReq,
                    `function reportFineStatus(msg) {
                        var $scope = angular.element(document.querySelectorAll('[ng-controller]')[1]).scope();
                        var trafficFile = $scope.vm.traffFilesDownloadingRes.find(x => x.trafficFile.fileId === msg.trafficFile.fileId);
                        trafficFile.progress = msg.progress;
                        trafficFile.error = msg.error;
                        trafficFile.status = msg.status;

                        if (trafficFile.error)
                            trafficFile.isComplete = true;
                        else
                            trafficFile.isComplete = msg.isComplated;

                        if (trafficFile.isComplete || trafficFile.error)
                            $scope.vm.downloadingFines = false;

                        if (!$scope.$$phase) {
                            $scope.$digest();
                        }
                    }`,
                    function error(e) {
                        abp.message.error(e.error);
                    });

            }

            vm.sendCaptcha = function (row) {
                if (chromeExtDownloader.isMv3ExtensionAvailable()) {
                    const captcahRequest = {
                        trafficFile: { id: row.trafficFile.id, fileId: row.trafficFile.fileId, server: row.trafficFile.state },
                        account: null,
                        tenantId: abp.session.tenantId,
                        captcahSelector: null,
                        buttonSelector: null,
                        captchaText: row.captchaTxt,
                        capthaTabId: row.capthaTabId
                    };

                    captcahRequest.buttonSelector = '#ctl00_ContentPlaceHolder1_bntEnquire';
                    captcahRequest.captcahSelector = '#ctl00_ContentPlaceHolder1_CaptchaCodeTextBox';

                    chromeExtDownloader.sendCaptchaMv3(captcahRequest);
                }
                else
                    chromeExtDownloader.sendCaptcha(row);
            };

            vm.focusWindow = function (r) {
                chromeExtDownloader.focusWindow({
                    type: 'fine',
                    trafficFileId: r.trafficFile.fileId
                });
            };

            //=========================================================

            vm.cancelAll = function () {
                chromeExtDownloader.closeAllFinesTabs();
            };

            function init() {
                getTrafficFiles();
            }

            init();
        }
    ]);
})();;
(function () {
	appModule.controller('tenant.views.tfms.updateFineTimeAUH', [
		'$scope', 'abp.services.app.uaeFine', 'chromeExtDownloader',
		function ($scope, fineService, chromeExtDownloader) {

			var vm = this;
			vm.fines = [];
			vm.allSelected = false;
			vm.downloading = false;

			var isAbuDhabiFinesEnabled = abp.features.isEnabled("TFMS.Fines.AbuDhabiPolice");
			var isDubaiFinesEnabled = abp.features.isEnabled("TFMS.Fines.DubaiPolice");

			vm.isDownloading = false;

			function init() {
				vm.loading = true;
				fineService.getFineNosForUpdateFineTimeAUH()
					.success(function (r) {
						vm.fines = r.items;
						vm.loading = false;
					});
			}


			vm.dateFormat = abp.setting.get("App.General.DateFormat");
			vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm:ss';

			vm.getlocalDateTime = function (date) {
				if (date !== null) {
					var localTime = moment.utc(date).toDate();
					return moment(localTime).format(vm.dateTimeFormat);
				}
				else {
					return "";
				}
			};

			vm.selectedFines = [];
			vm.finesCount = 0;

			vm.updateFineTime = function () {

				vm.downloading = true;

				vm.selectedFines = vm.fines.filter(x => x.selected);
				vm.finesCount = vm.selectedFines.length;

				if (vm.selectedFines) {
					chromeExtDownloader.downlaodFinesDescription(
						vm.selectedFines,
						`function reportFineStatus(msg) {
							var $scope = angular.element(document.querySelector('#appController')).scope();
							if (!msg.fineDetail) return;

							var fineDetail = $scope.vm.selectedFines.find(x => x.fineNo === msg.fineDetail.fineNo);
							fineDetail.progress = msg.progress;
							fineDetail.error = msg.error;
							fineDetail.status = msg.status;

							if (fineDetail.error) {
								fineDetail.isComplete = true;
								fineDetail.downloadClass = "badge-danger";
								$scope.vm.selectedFines.splice(fineDetail, 1);
							}
							else if (msg.isComplated) {
								fineDetail.isComplete = msg.isComplated;

								fineDetail.downloadClass = "badge-success";

								$scope.vm.fines.splice($scope.vm.fines.find(x => x.fineNo == msg.fineDetail.fineNo), 1);
								$scope.vm.selectedFines.splice(fineDetail, 1);
								console.log("remaining items",$scope.vm.selectedFines.length);
								$scope.vm.finesCount && $scope.vm.finesCount--;
							}

							if ($scope.vm.selectedFines.length == 0) {
								$scope.vm.downloading = false;
							}

							if (!$scope.$$phase) {
								$scope.$digest();
							}
						}`,
						function error(e) {
							abp.message.error(e.error);
						}
					);

				}
				else { vm.loading = false; vm.downloading = false; }

			};

			vm.selectedCount = function () { return vm.fines.filter(x => x.selected).length; };

			vm.selectAll = function () {
				if (vm.allSelected) {
					if (vm.fines)
						for (let i in vm.fines) {
							vm.fines[i].selected = true;
							vm.fines[i].updateOnlyTime = true;
						}
				}
				else {
					if (vm.fines)
						for (let i in vm.fines) {
							vm.fines[i].selected = false;
							vm.fines[i].updateOnlyTime = true;
						}
				}
			};

			init();
		}
	]);
})();;
(function ()
{

    appModule.controller('tenant.views.tfms.finesSharingSetting.index', [
        '$scope', 'abp.services.app.dataSharingSetting', 'utilities',
        function ($scope, dataSharingSettingService, utilities)
        {

            var vm = this;
            vm.loading = false;
            vm.saving = false;
            vm.fields = [];
            vm.shareFileFormat = abp.features.getValue("TFMS.Fines.ShareFines.FileFormat");
            vm.reDownloadDiscountedAbuDhabiFines = abp.setting.get("App.Speed.Common.ReDownloadDiscountedAbuDhabiFines") == 'True' || 'true' ? true : false;

            $scope.$on('$viewContentLoaded', function ()
            {
                App.initAjax();
            });

            vm.settings = {
                dataToShare: 2,
                isActive: 1
            };

            function getSharingFormat()
            {
                if (vm.shareFileFormat == "CSV") {
                    vm.settings.sharingFormat = 1;
                    vm.shareAs = app.localize('CSV');
                }
                else if (vm.shareFileFormat == "MsSql") {
                    vm.settings.sharingFormat = 2;
                    vm.shareAs = app.localize('MsSql');
                }
                else if (vm.shareFileFormat == "MySql") {
                    vm.settings.sharingFormat = 3;
                    vm.shareAs = app.localize('MySql');
                }
                else if (vm.shareFileFormat == "Oracle") {
                    vm.settings.sharingFormat = 7;
                    vm.shareAs = app.localize('Oracle');
                }
                else if (vm.shareFileFormat == "E-Fines(Desktop)") {
                    vm.settings.sharingFormat = 10;
                    vm.shareAs = app.localize('E-Fines(Desktop)');
                }
                else if (vm.shareFileFormat == "CustomArenco") {
                    vm.settings.sharingFormat = 5;
                    vm.shareAs = app.localize('CustomArenco');
                }
                else if (vm.shareFileFormat == "RESTApi") {
                    vm.settings.sharingFormat = 11;
                    vm.shareAs = app.localize('RESTApi');
                }
            };

            vm.getlocalDate = function (date)
            {
                if (date != null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.fieldtypechange = function (row)
            {
                if (row.fieldType != 1)
                    row.maxLength = null;
                if (row.inputField != "N/A")
                    row.defaultValue = null;
                if (row.filedType != 3)
                    row.defaultValue = null;
            };

            vm.sortOfSettingsChanged = function (event, ui)
            {
                vm.loading = true;
                var obj = JSON.parse(ui.item.attr('data-id'));
                var updatedIndex = ui.item.index();

                var row = obj.row;


                if (updatedIndex == 0) {

                    row.order = (vm.settings.configuration.fieldMappings[0].order) / 2;
                    var element = row;
                    vm.settings.configuration.fieldMappings.splice(obj.rowIndex, 1);
                    vm.settings.configuration.fieldMappings.splice(updatedIndex, 0, element);
                }
                else if (updatedIndex == (vm.settings.configuration.fieldMappings.length - 1)) {
                    row.order = (vm.settings.configuration.fieldMappings[updatedIndex].order + vm.settings.configuration.fieldMappings[updatedIndex].order + 1) / 2;
                    var element = row;
                    vm.settings.configuration.fieldMappings.splice(obj.rowIndex, 1);
                    vm.settings.configuration.fieldMappings.splice(updatedIndex, 0, element);
                }
                else {
                    if (updatedIndex > obj.rowIndex)
                        row.order = (vm.settings.configuration.fieldMappings[updatedIndex + 1].order + vm.settings.configuration.fieldMappings[updatedIndex].order) / 2;
                    else if (updatedIndex < obj.rowIndex)
                        row.order = (vm.settings.configuration.fieldMappings[updatedIndex - 1].order + vm.settings.configuration.fieldMappings[updatedIndex].order) / 2;
                    var element = row;
                    vm.settings.configuration.fieldMappings.splice(obj.rowIndex, 1);
                    vm.settings.configuration.fieldMappings.splice(updatedIndex, 0, element);
                }
                vm.loading = false;
                $scope.$apply();
            };

            vm.addRow = function ()
            {
                if (vm.settings)
                    vm.settings.configuration.fieldMappings.push({
                        order: vm.settings.configuration.fieldMappings.length < 1 ? 1 :
                            vm.settings.configuration.fieldMappings[vm.settings.configuration.fieldMappings.length - 1].order + 1,
                        inputfield: null,
                        outputfield: null,
                        fieldtype: null,
                        format: null,
                        defaultvalue: null,
                        maxlength: null
                    });

            };
            function customsettings()
            {
                var line = new Object();
                line.companyCode = null;
                line.dbServer = null;
                line.dbName = null;
                line.user = null;
                line.password = null;
                return line;
            };

            vm.addcustomRow = function ()
            {
                debugger;
                vm.settings.configuration.sharedDBs.push(customsettings());

            };
            vm.removecustomrow = function (row)
            {
                var index = vm.settings.configuration.sharedDBs.indexOf(row);
                vm.settings.configuration.sharedDBs.splice(index, 1);
            };
            vm.removerow = function (row)
            {
                var index = vm.settings.configuration.fieldMappings.indexOf(row);
                vm.settings.configuration.fieldMappings.splice(index, 1);
            };

            vm.dataSharingfieldtypes = [
                { key: 1, value: "Text" }, { key: 2, value: "Numeric" }, { key: 3, value: "DateTime" }, { key: 4, value: "Decimal" }, { key: 5, value: "Boolean" }, { key: 6, value: "Time" }];


            //To give extra details to Input Mapping Fields to better understand the data nature.
            const inputFieldsNames = [
                { original: 'DownloadDateTime', modified: 'DownloadDateTime_UTC' },
                { original: 'FineDateTime', modified: 'FineDateTime_UTC' },
                { original: 'DiscountRate', modified: 'DiscountRate%' }
            ];

            function getinputfields()
            {
                dataSharingSettingService.getInputFieldsFines().success(function (result)
                {
                    debugger;
                    for (var i = 0; i < result.length; i++) {
                        const findVal = inputFieldsNames.find(x => x.original == result[i]);
                        result[i] = findVal ? findVal.modified : result[i];
                    }

                    if (result.filter(x => x == 'LateCharges').length == 0)
                        result.push('LateCharges');

                    vm.inputfields = result;
                });
            };

            function getallsettings()
            {
                vm.loading = true;
                dataSharingSettingService.getAllSettingsFines(vm.settings).success(function (result)
                {
                    debugger;
                    vm.settings = result;

                    for (var j = 0; j < vm.settings.configuration.fieldMappings.length; j++) {
                        const findVal = inputFieldsNames.find(x => x.original == vm.settings.configuration.fieldMappings[j].inputField);
                        vm.settings.configuration.fieldMappings[j].inputField = findVal ? findVal.modified : vm.settings.configuration.fieldMappings[j].inputField;
                    }

                    getSharingFormat();

                }).finally(function ()
                {
                    if (vm.settings.configuration.fieldMappings.length == 0)
                        vm.addRow();
                    if (vm.settings.configuration.sharedDBs.length === 0 || !vm.settings.configuration.fieldMappings)
                        vm.addcustomRow();
                    vm.loading = false;
                });
            };

            vm.save = function ()
            {
                vm.saving = true;
                vm.loading = true;
                vm.settings.dataToShare = 2;
                vm.settings.isActive = 1;
                getSharingFormat();
                vm.settings.configuration.sharingStartDate = moment(vm.settings.configuration.sharingStartDate).startOf('day');

                //---------------------------
                // Modify InputFields of mapping to remove extra strings i.e Utc, % etc.
                for (var j = 0; j < vm.settings.configuration.fieldMappings.length; j++) {
                    const findVal = inputFieldsNames.find(x => x.modified == vm.settings.configuration.fieldMappings[j].inputField);
                    vm.settings.configuration.fieldMappings[j].inputField = findVal ? findVal.original : vm.settings.configuration.fieldMappings[j].inputField;
                }
                //---------------------------

                dataSharingSettingService.updateAllSettings(vm.settings).success(function (result)
                {
                    vm.loading = false;
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    getallsettings();
                }).finally(function ()
                {
                    vm.saving = false;
                })
            }

            function init()
            {
                getinputfields();
                getallsettings();
            }


            init();
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.tms.attachDetails.index', [
        '$scope', '$uibModal', 'uiGridConstants', 'abp.services.app.toll', 'abp.services.app.vehicle', 'abp.services.app.directory', 'abp.services.app.salikAccount',
        function ($scope, $uibModal, uiGridConstants, tollsService, vehicleService, directoryService, salikAccountService) {
            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.isEnableCRS = abp.features.isEnabled("CRS");
            vm.isEnableTMS = abp.features.isEnabled("TMS");

            vm.loading = false;
            vm.dateRangeOptions = app.createDateRangePickerOptions();
            vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.dateTimeFormat = vm.dateFormat + ' HH:mm';
            vm.customers = [];
            vm.selectedVehicle = null;
            vm.vehicleNoEN = [];
            vm.plateTagNoEN = [];
            vm.selectedTollsCount = 0;

            vm.filters = {
                isAgreementClosing: false,
                enableDateRange: true,
                name: "",
                vehicleId: null,
                agreementNo: null,
                plateTagNo: null,
                customerId: null,
                fromDate: null,
                fromTime: null,
                toDate: null,
                toTime: null,
                amount: null,
                vehicleNo: null,
                enableWithAgreement: false,
                enableWithOutAgreement: false,
                enableInvoiced: false,
                enableUnInvoiced: false,
                enableCharged: true,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                ContactId: null,
                tmsAgreementNo: null,

                transactionNumber: null,
                plateTagNoEN: [],
                vehicleNoEN: [],
                location: null,
                direction: null,
                salikAccount: null,
                durationType: 1,
                vehicleNoArray: [],
                plateTagNoArray: []
            };
            function getFiltersDateForSAF() {
                vm.filters.fromDate = moment(moment().format('YYYY-MM-DD HH:mm')).utc();
                vm.filters.toDate = moment(moment().format('YYYY-MM-DD HH:mm')).add(1, 'days').add(-1, 'milliseconds').utc();
                vm.filters.fromTime = moment(new Date()).startOf('day').utc();
                vm.filters.toTime = moment(new Date()).endOf('day').utc();
            };

            vm.searchPlateNo = function ($select) {
                if (!$select.search) return;
                vm.filters.name = $select.search;
                return tollsService.getSearchPlateNo(vm.filters).then(function (response) {
                    vm.vehicleNoEN = response.data.items; //string list of plate numbers
                });
            };
            vm.searchTagNo = function ($select) {
                if (!$select.search) return;
                vm.filters.name = $select.search;
                return tollsService.getSearchTagNo(vm.filters).then(function (response) {
                    vm.plateTagNoEN = response.data.items; //string list of tag numbers
                });
            };

            vm.dateRangeModelChanged = function () {
                vm.filters.fromDate = vm.dateRangeModel.startDate !== null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
                vm.filters.toDate = vm.dateRangeModel.endDate !== null ? vm.dateRangeModel.endDate : moment().endOf('day');
            };

            vm.dateRangeModel = {
                startDate: moment(moment().format('YYYY-MM-DD')).utc(),
                endDate: moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc(),
            };

            vm.searchCustomers = function ($select) {
                //whereas contactType: 1 (staff) and contactType: 2 (customer). get customers
                return directoryService.search({ keyword: $select.search, contactType: 2, activeOnly: true }).then(function (response) {
                    vm.customers = response.data.items;
                });
            };

            vm.CurrencyFormate = function (amount) {
                if (amount === null) return null;
                return amount.toLocaleString('en');
            };

            vm.getTollsReport = function () {
                vm.loading = true;
                vm.filters.fromDate = moment(vm.filters.fromDate) !== null ? moment(new Date(vm.filters.fromDate._d.getFullYear(), vm.filters.fromDate._d.getMonth(), vm.filters.fromDate._d.getDate(), vm.filters.fromTime._d.getHours(), vm.filters.fromTime._d.getMinutes(), '00', '000')).utc() : moment(moment().format('YYYY-MM-DD HH:mm')).utc();
                vm.filters.toDate = moment(vm.filters.fromDate) !== null ? moment(new Date(vm.filters.toDate._d.getFullYear(), vm.filters.toDate._d.getMonth(), vm.filters.toDate._d.getDate(), vm.filters.toTime._d.getHours(), vm.filters.toTime._d.getMinutes(), '59', '999')).utc() : moment(moment().format('YYYY-MM-DD HH:mm')).utc();

                if (vm.filters.fromDate > vm.filters.toDate) return;
                if (vm.filters.durationType === null) vm.filters.durationType = 1;

                tollsService.getTollsReportForReport(vm.filters).success(function (data) {
                    vm.tolls = data;
                    vm.tolls.totalItems = data.length;
                }).finally(function () {
                    vm.loading = false;
                    vm.tollReportChecked();
                    vm.allTollReports = false;
                });
            };

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    return moment(date).utc().format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getServerName = function (server) {
                if (server == 1) {
                    return app.localize('Dubai');
                }
                else if (server == 2) {
                    return app.localize('AbuDhabi');
                }
            }

            vm.allTollReportsChecked = function () {
                angular.forEach(vm.tolls, function (value, key) {
                    if (vm.allTollReports) {
                        value.selected = true;
                    } else {
                        value.selected = false;
                    }
                    vm.tollReportChecked();
                });
            };

            vm.tollReportChecked = function () {
                vm.selectedTollsCount = 0;
                angular.forEach(vm.tolls, function (value, key) {
                    if (value.selected) {
                        vm.selectedTollsCount++;
                    }
                });
            }

            function openAttachAgreementDetailModal(selectedTollsDetail) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/tms/attachDetails/updateModal.cshtml',
                    controller: 'tenant.views.tms.attachDetails.updateModal as vm',
                    backdrop: 'static',
                    size: 'xs',
                    resolve: {
                        SelectedTollsDetail: function () {
                            return selectedTollsDetail;
                        }
                    }
                });
                modalInstance.result.then(function () {
                    vm.getTollsReport();
                });
            }

            vm.attachAgreementDetail = function () {
                var selectedTollsDetail = new Object();
                selectedTollsDetail.tollsId = [];
                selectedTollsDetail.selectedCount = vm.selectedTollsCount;
                angular.forEach(vm.tolls, function (value) {
                    if (value.selected) {
                        selectedTollsDetail.tollsId.push(value.id);
                    }
                });
                openAttachAgreementDetailModal(selectedTollsDetail);
            }

            function init() {
                getFiltersDateForSAF();
                vm.getTollsReport();
            };

            init();
        }
    ]);
})();;
