                        vm.totalCollectedAmount += parseFloat(vm.toFixeRound(value.collectedAmount));
                        vm.totalDueAmount += (parseFloat(vm.toFixeRound(value.chargedAmmount)) - parseFloat(vm.toFixeRound(value.collectedAmount)));
