(function () {

    appModule.controller('tenant.views.tms.dashboard.updateChargesModal', [
        '$scope', '$filter', '$uibModal', 'utilities', 'finesData', 'uiGridConstants', '$uibModalInstance', 'abp.services.app.uaeFine',
        function ($scope, $filter, $uibModal, utilities, finesData, uiGridConstants, $uibModalInstance, finesService) {

            var vm = this;
            vm.isEnableTFMS = abp.features.isEnabled("TFMS");

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });
            vm.filters = {
                name: null,
            }
            vm.loading = false;
            vm.fine = finesData;

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.isEnableUpdateChargedAmount = abp.auth.hasPermission('Pages.TFMS.Update.Charged.Amount');
            vm.isEnableUpdateCollectedAmount = abp.auth.hasPermission('Pages.TFMS.Update.Collected.Amount');
            vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';
            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateTimeFormat);
                }
                else {
                    return "";
                }
            };

            vm.getlocalDate = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };
            vm.cancel = function () {
                $uibModalInstance.dismiss(vm.fine);
            }
            vm.save = function () {
                vm.loading = true;
                if (vm.fine.agreementNo) {
                    vm.fine.refNo = vm.fine.agreementNo;
                }
                else {
                    vm.fine.refNo = vm.fine.movement ? vm.fine.movement.refNo : null ;
                }

                finesService.updateChargeAndCollection(vm.fine).success(function (data) {
                    if (data) {
                        abp.notify.info(app.localize('SavedSuccessfully'));
                    } else {
                        abp.notify.error(app.localize('Error'));
                    }
                    //abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close(vm.fine);
                }).finally(function () {
                    vm.loading = false;
                });
            }

            function initialize() {
                console.log(vm.fine);
            }
            initialize();
        }
    ]);
})();;
(function () {

	appModule.controller('tenant.views.tms.SharingLogs.index', [
		'$scope', '$stateParams', 'uiGridConstants', 'abp.services.app.dataSharingLog',
		function ($scope, $stateParams, uiGridConstants, dataSharingLogService) {

			$scope.$on('$viewContentLoaded', function () {
				App.initAjax();
			});

			var vm = this;
			vm.loading = false;
			vm.saving = false;

			vm.dateRangeOptions = app.createDateRangePickerOptions();
			vm.dateRangeOptions.max = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));
			vm.dateRangeOptions.maxDate = moment().add(3, 'year').format(abp.setting.get("App.General.DateFormat"));

			$scope.$on('$viewContentLoaded', function () {
				App.initAjax();
			});

			vm.filters = {
				dataToShare: null,
				skipCount: 0,
				enableDateRange: true,
				fromDate: null,
				toDate: null,
				maxResultCount: app.consts.grid.defaultPageSize,
				sorting: "date asc"
			};

			vm.getDataToShare = function () {
				vm.filters.dataToShare = $stateParams.dataToShare;
				if ($stateParams.dataToShare == 1)
					return app.localize('E-Salik') + app.localize('Tolls');
				if ($stateParams.dataToShare == 2)
					return app.localize('Fines');
				if ($stateParams.dataType == 3)
					return app.localize('E-Darb') + app.localize('Tolls');
				if ($stateParams.dataType == 8)
					return app.localize('E-Parking') + app.localize('Tolls');
			};

			vm.dateRangeModel = {
				startDate: moment(moment().format('YYYY-MM-DD')).utc(),
				endDate: moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc()
			};

			vm.dateFormat = abp.setting.get("App.General.DateFormat");
			vm.dateTimeFormat = vm.dateFormat + ' ' + 'HH:mm';


			vm.getlocalDateTime = function (date) {
				if (date != null) {
					var localTime = moment.utc(date).toDate();
					return moment(localTime).format(vm.dateTimeFormat);
				}
				else {
					return "";
				}
			};

			vm.dateRangeModelChanged = function () {
				vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
				vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
			};

			vm.gridOptions = {
				enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
				enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
				paginationPageSizes: app.consts.grid.defaultPageSizes,
				paginationPageSize: app.consts.grid.defaultPageSize,
				useExternalPagination: true,
				appScopeProvider: vm,
				enableSorting: true,
				columnDefs: [
					//{
					//    name: app.localize('Actions'),
					//    enableSorting: false,
					//    width: '8%',
					//    cellTemplate:
					//        '<div class=\"ui-grid-cell-contents\">' +
					//        '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
					//        '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
					//        //'    <ul uib-dropdown-menu>' +
					//        //'      <li><a  ng-click="grid.appScope.viewServiceLog(row.entity.id)">' + app.localize('View') + '</a></li>' +
					//        //'    </ul>' +
					//        '  </div>' +
					//        '</div>'
					//},
					{
						name: app.localize('Date'),
						field: 'date',
						cellTemplate:
							'<div class=\"ui-grid-cell\">' +
							'<div class=\"ui-grid-cell-contents\">{{grid.appScope.getlocalDateTime(row.entity.date)}}</div>' +
							'</div>',
						width: '20%',
					},
					{
						name: app.localize('Log'),
						field: 'log',
						width: '80%',
					}

				],
				onRegisterApi: function (gridApi) {
					$scope.gridApi = gridApi;
					$scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
						if (!sortColumns.length || !sortColumns[0].field) {
							vm.filters.sorting = "date desc";
						} else {
							vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
						}

						vm.getDataSharingLogs();
					});
					gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
						vm.filters.skipCount = (pageNumber - 1) * pageSize;
						vm.filters.maxResultCount = pageSize;

						vm.getDataSharingLogs();
					});
				},
				data: []
			};

			vm.exportToExcel = function () {
				vm.loading = true;

				if (vm.filters.enableDateRange) {
					vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
					vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
				}
				else {
					vm.filters.fromDate = null;
					vm.filters.toDate = null;
				}

				vm.filters.sorting = '';
				dataSharingLogService.exportToExcel(vm.filters).success(function (result) {
					app.downloadTempFile(result);
				}).finally(function () {
					vm.loading = false;
					vm.filters.sorting = "date desc";
				});
			};

			vm.clearSharingLog = function () {
				abp.message.confirm(
					app.localize('DeleteWarningMessage', ''),
					function (isConfirmed) {
						if (isConfirmed) {
							vm.loading = true;
							vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
							vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
							dataSharingLogService.clearSharingLog(vm.filters).success(function () {
								vm.getDataSharingLogs();
								vm.loading = false;
								abp.notify.success(app.localize('SuccessfullyDeleted'));
							});
						}
					}
				);
			}

			vm.getDataSharingLogs = function () {
				vm.loading = true;
				if (vm.filters.enableDateRange) {
					vm.filters.fromDate = vm.dateRangeModel.startDate != null ? vm.dateRangeModel.startDate : moment(moment().format('YYYY-MM-DD')).utc();
					vm.filters.toDate = vm.dateRangeModel.endDate != null ? vm.dateRangeModel.endDate : moment(moment().format('YYYY-MM-DD')).add(1, 'days').add(-1, 'milliseconds').utc();
				}
				else {
					vm.filters.fromDate = null;
					vm.filters.toDate = null;
				}
				dataSharingLogService.getDataSharingLog(vm.filters).success(function (data) {
					vm.gridOptions.totalItems = data.totalCount;
					vm.gridOptions.data = data.items;
				}).finally(function () {
					vm.loading = false;
				});
			};

			function init() {
				vm.getDataToShare();
				vm.getDataSharingLogs();
			}
			init();
		}
	]);
})();;
(function () {
    appModule.controller('tenant.views.tms.dataSharingMapping.createOrEditModal', [
        'utilities', '$scope', 'appSession', '$uibModalInstance', 'mapping', 'abp.services.app.dataSharingMapping',
        function (utilities, $scope, appSession, $uibModalInstance, mapping, dataSharingMappingService) {

            var vm = this;
            vm.saving = false;

            vm.tenant = appSession.tenant;
            vm.isEnableApplicableDate = abp.setting.get("App.DarbVehiclePlateNoMapped.EnableApplicableDate") === "True";
            vm.isInputFielEnabled = vm.tenant.tenancyName == 'SalikFines' || vm.tenant.tenancyName == 'Hertz' || vm.tenant.tenancyName == 'HertzUAE';
            vm.isArencoEnabled = abp.features.getValue("TMS.ShareTolls_FileFormat") == "CustomArenco";
            vm.cancel = function () {
                $uibModalInstance.dismiss();
            };

            vm.mapping = {
                id: mapping.id,
                dataType: mapping.dataType,
                field: mapping.field,
                inputValue: mapping.inputValue,
                outputValue: mapping.outputValue,
                parentValue: mapping.parentValue,
                applicableDate: mapping.applicableDate
            };

            vm.filters = {
                name: ''
            };

            vm.searchPlateCode = function ($select) {
                if (!$select.search) return;
                vm.filters.name = $select.search;

                if (vm.mapping.dataType == 2) {
                    return dataSharingMappingService.getSearchPlateCodeFines(vm.filters).then(function (response) {
                        vm.plateCodes = response.data.items; //string list of plate numbers
                    });
                }
                else
                    return dataSharingMappingService.getSearchPlateCode(vm.filters).then(function (response) {
                        vm.plateCodes = response.data.items; //string list of plate numbers
                    });
            };

            vm.save = function () {
                vm.saving = true;

                dataSharingMappingService.createOrEditMapping({
                    mapping: vm.mapping,
                }).success(function () {
                    abp.notify.info(app.localize('SavedSuccessfully'));
                    $uibModalInstance.close();
                }).finally(function () {
                    vm.saving = false;
                });
            };
        }
    ]);
})();;
(function () {

    appModule.controller('tenant.views.tms.dataSharingMapping.index', [
        'utilities', '$scope', '$uibModal', 'uiGridConstants', '$stateParams', 'abp.services.app.dataSharingMapping',
        function (utilities, $scope, $uibModal, uiGridConstants, $stateParams, dataSharingMappingService) {

            var vm = this;

            $scope.$on('$viewContentLoaded', function () {
                App.initAjax();
            });

            vm.dateFormat = abp.setting.get("App.General.DateFormat");
            vm.isEnableApplicableDate = abp.setting.get("App.DarbVehiclePlateNoMapped.EnableApplicableDate") === "True";

			vm.hasImportMappingsPermission = abp.auth.hasPermission("Pages.TMS.Tolls.ImportMappings") || abp.auth.hasPermission("Pages.TMS.Tolls.EDarb.ImportMappings");

            vm.loading = false;
            vm.filters = {
                code: '',
                name: '',
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize
            };


            vm.getDataType = function () {
                vm.filters.dataType = $stateParams.dataType;
                if ($stateParams.dataType == 1)
                    return app.localize('E-Salik') + app.localize('Tolls');
                if ($stateParams.dataType == 2)
                    return app.localize('Fines');
                if ($stateParams.dataType == 3)
                    return app.localize('E-Darb') + app.localize('Tolls');
            };

            vm.fields = [];
            function getFields() {
                vm.fields.push("PlateNo_Mapped");
                vm.fields.push("State_Mapped");
                vm.fields.push("PlateCode_Mapped");
                vm.fields.push("Description_Mapped");
                vm.fields.push("Location_Mapped");
                vm.fields.push("Authority_Mapped");
                //vm.fields.push("Vehicle No");
            }

            vm.statuses = [];
            function getStatuses() {
                vm.statuses.push("Mapped");
                vm.statuses.push("Un-Mapped");
            }

            vm.gridOptions = {
                enableHorizontalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                enableVerticalScrollbar: uiGridConstants.scrollbars.WHEN_NEEDED,
                paginationPageSizes: app.consts.grid.defaultPageSizes,
                useExternalPagination: true,
                appScopeProvider: vm,
                enableSorting: true,
                columnDefs: [
                    {
                        name: app.localize('Actions'),
                        enableSorting: false,
                        width: '10%',
                        cellTemplate:
                            '<div class=\"ui-grid-cell-contents\">' +
                            '  <div class="btn-group dropdown" uib-dropdown="" dropdown-append-to-body>' +
                            '    <button class="btn btn-xs btn-primary blue" uib-dropdown-toggle="" aria-haspopup="true" aria-expanded="false"><i class="fa fa-cog"></i> ' + app.localize('Actions') + ' <span class="caret"></span></button>' +
                            '    <ul uib-dropdown-menu>' +
                            '      <li><a  ng-click="grid.appScope.openCreateOrEditDataSharingMappingModal(row.entity)">' + app.localize('Edit') + '</a></li>' +
                            '      <li><a  ng-click="grid.appScope.deleteMapping(row.entity.id)">' + app.localize('Delete') + '</a></li>' +
                            '    </ul>' +
                            '  </div>' +
                            '</div>'
                    },
                    {
                        name: app.localize('Input') + ' ' + app.localize('Value'),
                        field: 'inputValue'
                    },
                    {
                        name: app.localize('Output') + ' ' + app.localize('Value'),
                        field: 'outputValue'
                    },
                    {
                        name: 'State',
                        field: 'parentValue'
                    },
                    {
                        name: 'ApplicableDate',
                        field: 'date',
                        minWidth: 150,
                        cellTemplate:
                            '<div class=\"ui-grid-cell\">' +
                            '<div class=\"ui-grid-cell-contents\">{{grid.appScope.getDateFormat(row.entity.applicableDate)}}</div>' +
                            '</div>'
                    }

                ],
                onRegisterApi: function (gridApi) {
                    $scope.gridApi = gridApi;
                    $scope.gridApi.core.on.sortChanged($scope, function (grid, sortColumns) {
                        if (!sortColumns.length || !sortColumns[0].field) {
                            vm.filters.sorting = "inputValue desc";
                        } else {
                            vm.filters.sorting = sortColumns[0].field + ' ' + sortColumns[0].sort.direction;
                        }

                        vm.getMappings();
                    });
                    gridApi.pagination.on.paginationChanged($scope, function (pageNumber, pageSize) {
                        vm.filters.skipCount = (pageNumber - 1) * pageSize;
                        vm.filters.maxResultCount = pageSize;

                        vm.getMappings();
                    });
                },
                data: []
            };

            vm.getDateFormat = function (date) {
                if (date !== null) {
                    return moment.utc(date).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            vm.openCreateOrEditDataSharingMappingModal = function (mapping) {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/tms/dataSharingMapping/createOrEditModal.cshtml',
                    controller: 'tenant.views.tms.dataSharingMapping.createOrEditModal as vm',
                    backdrop: 'static',
                    size: '450',
                    resolve: {
                        mapping: function () {
                            if (mapping != null) {
                                return mapping;
                            }
                            else {
                                return { id: null, dataType: vm.filters.dataType, field: vm.filters.field };
                            }
                        }
                    }
                });

                modalInstance.result.then(function (result) {
                    vm.getMappings();
                });
            };

            vm.openImportModal = function () {
                var modalInstance = $uibModal.open({
                    templateUrl: '~/App/tenant/views/tms/common/dataImportModal.cshtml',
                    controller: 'tenant.views.tms.common.dataImportModal as vm',
                    backdrop: 'static',
                    size: 'md',
                    resolve: {
                        dataType: $stateParams.dataType
                    }
                });

                modalInstance.closed.then(function (result) {
                    vm.getMappings();
                });
            };

            vm.deleteMapping = function (id) {
                abp.message.confirm(
                    app.localize('DeleteWarningMessage', ''),
                    function (isConfirmed) {
                        if (isConfirmed) {
                            dataSharingMappingService.deleteMapping({
                                id: id
                            }).success(function () {
                                vm.getMappings();
                                abp.notify.success(app.localize('SuccessfullyDeleted'));
                            });
                        }
                    }
                );
            };

            vm.getlocalDateTime = function (date) {
                if (date !== null) {
                    var localTime = moment.utc(date).toDate();
                    return moment(localTime).format(vm.dateFormat);
                }
                else {
                    return "";
                }
            };

            function hideOrShowStateColumn() {
                var pos = vm.gridOptions.columnDefs.map(function (e) { return e.name; }).indexOf('State');
                if (vm.filters.field == "PlateCode_Mapped") {
                    vm.gridOptions.columnDefs[pos].visible = true;
                } else {
                    vm.gridOptions.columnDefs[pos].visible = false;
                }
            }

            function hideOrShowApplicableDateColumn() {
                var pos = vm.gridOptions.columnDefs.map(function (e) { return e.name; }).indexOf('ApplicableDate');
                if (vm.filters.field === "PlateNo_Mapped" && vm.isEnableApplicableDate && vm.filters.dataType === 3) {
                    vm.gridOptions.columnDefs[pos].visible = true;
                } else {
                    vm.gridOptions.columnDefs[pos].visible = false;
                }
            }

            vm.getMappings = function () {
                hideOrShowApplicableDateColumn();
                hideOrShowStateColumn();
                if (vm.filters.field) {
                    vm.loading = true;
                    dataSharingMappingService.getMappings(vm.filters).success(function (data) {
                        vm.gridOptions.totalItems = data.totalCount;
                        vm.gridOptions.data = data.items;
                    }).finally(function () {
                        vm.loading = false;
                    });
                }
                else {
                    vm.gridOptions.totalItems = 0;
                    vm.gridOptions.data = [];
                }
            }
            hideOrShowApplicableDateColumn();
            hideOrShowStateColumn();
            vm.getDataType();
            getFields();
            getStatuses();
            //vm.getMappings();
        }
    ]);
})();;
