                amount: null,
                server: 2,
                enableCharged: false,
                skipCount: 0,
                maxResultCount: app.consts.grid.defaultPageSize,
                tollsShareStatus: null,
                plateTagNoEN: [],
                vehicleNoEN: [],
                location: null,
                direction: null,
                salikAccount: null,
