                    serviceNameWithoutSpace = additionalInfoObj.ServiceName.replace(/\s/g, '').toLowerCase();
                    var checkIfExists = vm.services.some(e => e.name.replace(/\s/g, '').toLowerCase() === serviceNameWithoutSpace);
